insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-canarias:1-5dff5cec94','aux-canarias',1,'¿Cuáles son los valores superiores del ordenamiento jurídico según la Constitución?','["La libertad, la justicia, la igualdad y el pluralismo político", "La libertad, la seguridad, la igualdad y la solidaridad", "La justicia, la paz, la igualdad y la democracia", "La libertad, la justicia, la dignidad y el pluralismo político"]'::jsonb,0,'Art. 1.1 CE','España propugna como valores superiores la libertad, la justicia, la igualdad y el pluralismo político.',null),
('aux-canarias:1-9977a4a04e','aux-canarias',1,'Según la Constitución, la soberanía nacional reside en:','["Las Cortes Generales", "El pueblo español", "El Rey", "La Nación y las Comunidades Autónomas"]'::jsonb,1,'Art. 1.2 CE','La soberanía nacional reside en el pueblo español, del que emanan los poderes del Estado.',null),
('aux-canarias:1-d2e96286bc','aux-canarias',1,'La forma política del Estado español es:','["La Monarquía constitucional", "El Estado autonómico", "La Monarquía parlamentaria", "La República federal"]'::jsonb,2,'Art. 1.3 CE','La forma política del Estado español es la Monarquía parlamentaria.',null),
('aux-canarias:1-b8fdb4cc03','aux-canarias',1,'Respecto al castellano, todos los españoles tienen:','["Solo el derecho a usarlo", "Solo el deber de conocerlo", "El derecho a conocerlo y el deber de usarlo", "El deber de conocerlo y el derecho a usarlo"]'::jsonb,3,'Art. 3.1 CE','Todos los españoles tienen el deber de conocer el castellano y el derecho a usarlo.',null),
('aux-canarias:1-51f294df53','aux-canarias',1,'¿Cómo es la bandera de España según la Constitución?','["Tres franjas horizontales roja, amarilla y roja, siendo la amarilla de doble anchura que cada roja", "Tres franjas horizontales roja, amarilla y roja, las tres de la misma anchura entre sí", "Tres franjas verticales roja, amarilla y roja, siendo la amarilla de doble anchura que cada roja", "Tres franjas horizontales amarilla, roja y amarilla, siendo la roja de doble anchura que cada amarilla"]'::jsonb,0,'Art. 4.1 CE','Tres franjas horizontales roja, amarilla y roja, siendo la amarilla de doble anchura que cada una de las rojas.',null),
('aux-canarias:1-45e58009d5','aux-canarias',1,'¿Cuál es la capital del Estado según la Constitución?','["La ciudad de Madrid y su área metropolitana", "La villa de Madrid", "La que determine una ley orgánica", "La sede del Gobierno, sea cual sea"]'::jsonb,1,'Art. 5 CE','La capital del Estado es la villa de Madrid.',null),
('aux-canarias:1-fd57cc4d5c','aux-canarias',1,'Según el art. 6, los partidos políticos:','["Son órganos del Estado", "Necesitan autorización administrativa previa", "Expresan el pluralismo político", "Pueden tener estructura interna no democrática"]'::jsonb,2,'Art. 6 CE','Los partidos expresan el pluralismo político y su estructura interna y funcionamiento deben ser democráticos.',null),
('aux-canarias:1-1058f470d5','aux-canarias',1,'¿Cuál de estos principios NO garantiza el art. 9.3 de la Constitución?','["La publicidad de las normas", "La jerarquía normativa", "La interdicción de la arbitrariedad de los poderes públicos", "La retroactividad de las disposiciones sancionadoras desfavorables"]'::jsonb,3,'Art. 9.3 CE','Se garantiza lo contrario: la irretroactividad de las disposiciones sancionadoras no favorables o restrictivas de derechos individuales.',null),
('aux-canarias:1-b9d3c67c0a','aux-canarias',1,'Las normas sobre derechos fundamentales se interpretan de conformidad con:','["La Declaración Universal de Derechos Humanos y los tratados ratificados por España", "La jurisprudencia del Tribunal Supremo y los tratados ratificados por España, en ese orden de prelación", "La Declaración Universal de Derechos Humanos y las leyes orgánicas que los desarrollen", "La doctrina del Tribunal Constitucional y los Estatutos de Autonomía vigentes"]'::jsonb,0,'Art. 10.2 CE','Se interpretan conforme a la Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales ratificados por España.',null),
('aux-canarias:1-042bab81ff','aux-canarias',1,'Según la Constitución, ¿puede un español de origen ser privado de su nacionalidad?','["Sí, por sentencia firme", "No, en ningún caso", "Sí, si adquiere otra nacionalidad", "Sí, por decisión del Gobierno"]'::jsonb,1,'Art. 11.2 CE','Ningún español de origen podrá ser privado de su nacionalidad.',null),
('aux-canarias:1-37b11936c7','aux-canarias',1,'¿A qué edad son mayores de edad los españoles según la Constitución?','["16 años", "21 años", "18 años", "La fija cada Comunidad Autónoma"]'::jsonb,2,'Art. 12 CE','Los españoles son mayores de edad a los dieciocho años.',null),
('aux-canarias:1-4818eecba1','aux-canarias',1,'Los extranjeros pueden ejercer el derecho de sufragio activo y pasivo:','["En las elecciones municipales y autonómicas, atendiendo a criterios de reciprocidad", "En las elecciones municipales, sin necesidad de criterios de reciprocidad", "En las elecciones municipales y europeas, siempre que residan en España", "En las elecciones municipales, atendiendo a criterios de reciprocidad"]'::jsonb,3,'Art. 13.2 CE','Solo los españoles son titulares del art. 23, salvo el sufragio activo y pasivo en las elecciones municipales con reciprocidad. Este apartado se reformó en 1992.',null),
('aux-canarias:1-961708e5ba','aux-canarias',1,'Según el art. 15 de la Constitución, la pena de muerte:','["Queda abolida, salvo lo que dispongan las leyes penales militares para tiempos de guerra", "Queda abolida, salvo para los delitos de terrorismo que determine una ley orgánica", "Queda abolida en todo caso, sin ninguna excepción en el texto constitucional", "Queda abolida, salvo lo que dispongan las leyes penales militares en estado de sitio"]'::jsonb,0,'Art. 15 CE','Queda abolida la pena de muerte, salvo lo que puedan disponer las leyes penales militares para tiempos de guerra.',null),
('aux-canarias:1-76fd5ff5f8','aux-canarias',1,'¿Cuánto puede durar como máximo la detención preventiva antes de poner al detenido en libertad o a disposición judicial?','["24 horas", "72 horas", "48 horas", "5 días"]'::jsonb,1,'Art. 17.2 CE','La detención preventiva no puede durar más de lo estrictamente necesario y, como máximo, 72 horas.',null),
('aux-canarias:1-af2e596818','aux-canarias',1,'¿Qué procedimiento regula la ley para la inmediata puesta a disposición judicial de toda persona detenida ilegalmente?','["El recurso de amparo", "El recurso de inconstitucionalidad", "El habeas corpus", "La cuestión prejudicial"]'::jsonb,2,'Art. 17.4 CE','La ley regula el procedimiento de habeas corpus.',null),
('aux-canarias:1-6931c53d26','aux-canarias',1,'¿En qué casos se puede entrar en un domicilio según la Constitución?','["Con consentimiento del titular, resolución judicial o autorización de la autoridad gubernativa", "Solo con resolución judicial o en caso de flagrante delito", "Con consentimiento del titular o resolución judicial, pero nunca sin ellos", "Con consentimiento del titular, resolución judicial o en caso de flagrante delito"]'::jsonb,3,'Art. 18.2 CE','Ninguna entrada o registro sin consentimiento del titular o resolución judicial, salvo flagrante delito.',null),
('aux-canarias:1-32aedf4516','aux-canarias',1,'El secuestro de publicaciones y otros medios de información solo puede acordarse:','["En virtud de resolución judicial", "Por orden del Ministerio del Interior", "Por acuerdo del Consejo de Ministros", "Por la autoridad gubernativa en casos urgentes"]'::jsonb,0,'Art. 20.5 CE','Solo podrá acordarse el secuestro en virtud de resolución judicial.',null),
('aux-canarias:1-7ff8116aaf','aux-canarias',1,'Para reuniones en lugares de tránsito público y manifestaciones se exige:','["Autorización previa de la autoridad", "Comunicación previa a la autoridad", "Autorización judicial", "Nada: son totalmente libres"]'::jsonb,1,'Art. 21.2 CE','Se da comunicación previa a la autoridad, que solo puede prohibirlas por razones fundadas de alteración del orden público.',null),
('aux-canarias:1-1aaf2f3520','aux-canarias',1,'¿Qué asociaciones prohíbe expresamente la Constitución?','["Las secretas y las que persigan fines políticos", "Las no inscritas en el registro y las de carácter paramilitar", "Las secretas y las de carácter paramilitar", "Las de carácter paramilitar y las formadas solo por extranjeros"]'::jsonb,2,'Art. 22.5 CE','Se prohíben las asociaciones secretas y las de carácter paramilitar.',null),
('aux-canarias:1-51906ec9a1','aux-canarias',1,'El art. 23.2 reconoce el derecho a acceder a las funciones y cargos públicos:','["En condiciones de igualdad, según el orden de antigüedad que fijen las leyes", "En condiciones de igualdad, siempre que se posea la nacionalidad española de origen", "Conforme a los méritos que libremente aprecie cada Administración", "En condiciones de igualdad, con los requisitos que señalen las leyes"]'::jsonb,3,'Art. 23.2 CE','Los ciudadanos tienen derecho a acceder en condiciones de igualdad a las funciones y cargos públicos, con los requisitos que señalen las leyes.',null),
('aux-canarias:1-9b3c013cf7','aux-canarias',1,'Según el art. 24.2, todos tienen derecho:','["Al Juez ordinario predeterminado por la ley", "A elegir el juez que les juzgue", "A ser juzgados por un jurado en todo caso", "A un tribunal especial según su profesión"]'::jsonb,0,'Art. 24.2 CE','Todos tienen derecho al Juez ordinario predeterminado por la ley, a la defensa y a la asistencia de letrado, entre otros.',null),
('aux-canarias:1-ff3c8b18af','aux-canarias',1,'La Administración civil puede imponer sanciones que impliquen privación de libertad:','["Sí, en casos graves", "No, en ningún caso", "Sí, con autorización judicial posterior", "Solo durante el estado de alarma"]'::jsonb,1,'Art. 25.3 CE','La Administración civil no podrá imponer sanciones que, directa o subsidiariamente, impliquen privación de libertad.',null),
('aux-canarias:1-ec4f29b6a2','aux-canarias',1,'Según la Constitución, la enseñanza básica es:','["Voluntaria y gratuita", "Obligatoria y de pago", "Obligatoria y gratuita", "Voluntaria y de pago"]'::jsonb,2,'Art. 27.4 CE','La enseñanza básica es obligatoria y gratuita.',null),
('aux-canarias:1-32601cfbc7','aux-canarias',1,'El derecho a la huelga de los trabajadores se reconoce en:','["El art. 37.2", "El art. 35.1", "El art. 7", "El art. 28.2"]'::jsonb,3,'Art. 28.2 CE','El art. 28.2 reconoce el derecho a la huelga de los trabajadores para la defensa de sus intereses.',null),
('aux-canarias:1-d55acc2e90','aux-canarias',1,'Según el art. 30.1, defender a España es para los españoles:','["Un derecho y un deber", "Solo un deber", "Solo un derecho", "Una obligación exclusiva de las Fuerzas Armadas"]'::jsonb,0,'Art. 30.1 CE','Los españoles tienen el derecho y el deber de defender a España.',null),
('aux-canarias:1-b51cc37e96','aux-canarias',1,'El art. 32.1 reconoce el derecho a contraer matrimonio:','["Al hombre y la mujer, a partir de la edad que fije cada Comunidad Autónoma", "Al hombre y la mujer, con plena igualdad jurídica", "Al hombre y la mujer, previa autorización del Registro Civil", "A los españoles mayores de edad, en forma civil o religiosa"]'::jsonb,1,'Art. 32.1 CE','El hombre y la mujer tienen derecho a contraer matrimonio con plena igualdad jurídica.',null),
('aux-canarias:1-05a3954d03','aux-canarias',1,'¿Qué artículo modificó la reforma constitucional de 2024?','["El art. 135, sobre estabilidad presupuestaria", "El art. 13.2, sobre el sufragio de los extranjeros en elecciones municipales", "El art. 49, sobre las personas con discapacidad", "El art. 69.3, sobre la elección de los senadores provinciales"]'::jsonb,2,'Art. 49 CE','La reforma de febrero de 2024 modificó el art. 49. Las anteriores fueron la de 1992 (art. 13.2) y la de 2011 (art. 135); la de mayo de 2026 modificó el art. 69.3.',null),
('aux-canarias:1-5a80a0d998','aux-canarias',1,'Según el art. 53.1, el ejercicio de los derechos del Capítulo II solo puede regularse:','["Por decreto-ley", "Por reglamento del Gobierno", "Por ley de las Comunidades Autónomas exclusivamente", "Por ley, que deberá respetar su contenido esencial"]'::jsonb,3,'Art. 53.1 CE','Vinculan a todos los poderes públicos y solo por ley, que respete su contenido esencial, podrá regularse su ejercicio.',null),
('aux-canarias:1-5c0066ba6f','aux-canarias',1,'¿Qué derechos pueden protegerse mediante recurso de amparo ante el Tribunal Constitucional?','["El art. 14, la Sección 1.ª del Capítulo II y la objeción de conciencia del art. 30", "Todos los derechos del Capítulo II del Título I, incluida su Sección 2.ª", "El art. 14 y los principios rectores del Capítulo III del Título I", "La Sección 1.ª del Capítulo II, pero no la igualdad del art. 14"]'::jsonb,0,'Art. 53.2 CE','Cabe amparo para el art. 14, la Sección 1.ª del Capítulo II y la objeción de conciencia del art. 30, en su caso tras acudir a los tribunales ordinarios.',null),
('aux-canarias:1-09a81868b0','aux-canarias',1,'El Defensor del Pueblo es:','["Alto comisionado del Gobierno, designado por el Consejo de Ministros", "Alto comisionado de las Cortes Generales, designado por estas", "Alto comisionado de las Cortes Generales, designado por el Rey", "Alto comisionado del Consejo General del Poder Judicial"]'::jsonb,1,'Art. 54 CE','Es alto comisionado de las Cortes Generales, designado por ellas para la defensa de los derechos del Título I.',null),
('aux-canarias:1-7028abb8d8','aux-canarias',1,'Según el art. 55.1, los derechos pueden suspenderse cuando se declare el estado de:','["Alarma", "Alarma, excepción o sitio", "Excepción o sitio", "Solo sitio"]'::jsonb,2,'Art. 55.1 CE','La suspensión general cabe en el estado de excepción o de sitio, no en el de alarma.',null),
('aux-canarias:1-4109852326','aux-canarias',1,'La suspensión individual de derechos para investigaciones sobre bandas armadas o terrorismo se regula mediante:','["Real decreto", "Ley ordinaria", "Orden ministerial", "Ley orgánica"]'::jsonb,3,'Art. 55.2 CE','Una ley orgánica puede determinar la suspensión individual de los derechos de los arts. 17.2 y 18.2 y 3 en esas investigaciones.',null),
('aux-canarias:1-07762f0eca','aux-canarias',1,'¿Qué principios garantiza el art. 9.3 de la Constitución en relación con las normas?','["La legalidad, la jerarquía normativa y la retroactividad de las normas favorables", "La legalidad, la competencia normativa y la publicidad de las normas", "La legalidad, la jerarquía normativa y la publicidad de las normas", "La seguridad jurídica, la reserva de ley y la jerarquía normativa"]'::jsonb,2,'Art. 9.3 CE','Garantiza, entre otros, el principio de legalidad, la jerarquía normativa y la publicidad de las normas.',null),
('aux-canarias:1-54172103dc','aux-canarias',1,'Según el art. 17.1, toda persona tiene derecho a:','["Una vivienda en propiedad", "La asistencia jurídica gratuita en cualquier caso", "La libertad y a la seguridad", "Un trabajo remunerado"]'::jsonb,2,'Art. 17.1 CE','Toda persona tiene derecho a la libertad y a la seguridad.',null),
('aux-canarias:1-a558190c80','aux-canarias',1,'Según el art. 31.2, la programación y ejecución del gasto público responden a los criterios de:','["Rentabilidad y beneficio", "Discrecionalidad política", "Prioridad territorial", "Eficiencia y economía"]'::jsonb,3,'Art. 31.2 CE','El gasto público realizará una asignación equitativa de los recursos públicos, y su programación y ejecución responderán a los criterios de eficiencia y economía.',null),
('aux-canarias:1-a77e6277f4','aux-canarias',1,'Según el art. 18.4, la ley limitará el uso de:','["El derecho de reunión y manifestación", "Los medios de comunicación social de titularidad pública", "La informática, para garantizar el honor y la intimidad", "Las armas de fuego, para garantizar la seguridad ciudadana"]'::jsonb,2,'Art. 18.4 CE','La ley limitará el uso de la informática para garantizar el honor y la intimidad personal y familiar.',null),
('aux-canarias:1-e4280bb170','aux-canarias',1,'El ejercicio de la libertad de expresión e información:','["Requiere autorización previa en los medios de titularidad pública", "No puede restringirse mediante ningún tipo de censura previa", "Puede someterse a censura previa en estados de alarma, excepción y sitio, por ley orgánica", "Solo se ejerce por periodistas"]'::jsonb,1,'Art. 20.2 CE','El ejercicio de estos derechos no puede restringirse mediante ningún tipo de censura previa.',null),
('aux-canarias:1-1924e9efcb','aux-canarias',1,'El secreto de las comunicaciones puede levantarse:','["Por decisión del Gobierno", "Mediante resolución judicial", "Por orden policial", "Nunca en ningún caso"]'::jsonb,1,'Art. 18.3 CE','Se garantiza el secreto de las comunicaciones, salvo resolución judicial.',null),
('aux-canarias:1-dda7baf908','aux-canarias',1,'Las demás lenguas españolas distintas del castellano:','["Solo son oficiales en el ámbito educativo de cada Comunidad Autónoma", "Son también oficiales en las respectivas Comunidades Autónomas de acuerdo con sus Estatutos", "Son oficiales en todo el territorio nacional, junto al castellano", "Son oficiales en las respectivas Comunidades Autónomas, pero solo cuando lo establezca una ley orgánica estatal"]'::jsonb,1,'Art. 3.2 CE','Son oficiales en sus Comunidades Autónomas de acuerdo con sus Estatutos.',null),
('aux-canarias:1-c3c5d34b13','aux-canarias',1,'Mediante ley podrán regularse los deberes de los ciudadanos en los casos de:','["Cambio de Gobierno o estado de alarma", "Grave riesgo, catástrofe o calamidad pública", "Huelga general", "Crisis económica grave declarada por el Gobierno"]'::jsonb,1,'Art. 30.4 CE','Podrán regularse los deberes de los ciudadanos en los casos de grave riesgo, catástrofe o calamidad pública.',null),
('aux-canarias:1-a8aa88a9ce','aux-canarias',1,'La libertad ideológica, religiosa y de culto tiene como única limitación en sus manifestaciones:','["La moral pública y las buenas costumbres, según determine la ley", "La autorización gubernativa previa", "La que fije cada confesión religiosa", "La necesaria para el mantenimiento del orden público protegido por la ley"]'::jsonb,3,'Art. 16.1 CE','Sin más limitación, en sus manifestaciones, que la necesaria para el mantenimiento del orden público protegido por la ley.',null),
('aux-canarias:1-38ad0eaa59','aux-canarias',1,'Según el art. 16.3, ¿alguna confesión tendrá carácter estatal?','["Sí, las que reconozca una ley orgánica", "No, ninguna confesión tendrá carácter estatal", "Sí, la católica", "Las que tengan más de un millón de fieles"]'::jsonb,1,'Art. 16.3 CE','Ninguna confesión tendrá carácter estatal, aunque los poderes públicos mantendrán relaciones de cooperación con la Iglesia Católica y las demás confesiones.',null),
('aux-canarias:1-73c6aed45b','aux-canarias',1,'Los principios del Capítulo III del Título I (principios rectores de la política social y económica):','["Son directamente exigibles ante el Tribunal Constitucional en recurso de amparo", "Informarán la legislación positiva, la práctica judicial y la actuación de los poderes públicos", "Informarán la legislación positiva, pero no la práctica judicial ni la actuación de la Administración", "Solo vinculan al Parlamento, y son directamente exigibles ante los tribunales ordinarios por cualquier ciudadano"]'::jsonb,1,'Art. 53.3 CE','Informarán la legislación positiva, la práctica judicial y la actuación de los poderes públicos; solo podrán alegarse ante la jurisdicción ordinaria según las leyes que los desarrollen.',null),
('aux-canarias:1-9215e65eee','aux-canarias',1,'El derecho a comunicar o recibir información, según el art. 20.1 d), se refiere a información:','["Veraz", "Oficial", "Gratuita", "Autorizada"]'::jsonb,0,'Art. 20.1 d) CE','Se reconoce el derecho a comunicar o recibir libremente información veraz por cualquier medio de difusión.',null),
('aux-canarias:1-f4a4f08777','aux-canarias',1,'Los poderes públicos garantizan el derecho de los padres a que sus hijos reciban:','["Educación en su lengua materna en todo caso", "La formación religiosa y moral que esté de acuerdo con sus propias convicciones", "La formación religiosa y moral de la confesión mayoritaria, salvo renuncia expresa de los padres o tutores", "Educación exclusivamente pública"]'::jsonb,1,'Art. 27.3 CE','Garantizan que los hijos reciban la formación religiosa y moral acorde con las convicciones de sus padres.',null),
('aux-canarias:1-b7fa1ab658','aux-canarias',1,'El principio de legalidad del art. 25.1 establece que nadie puede ser condenado o sancionado por acciones u omisiones que:','["En el momento de dictarse la resolución no constituyan delito, falta o infracción administrativa", "En el momento de producirse no constituyan delito, falta o infracción administrativa, según la legislación vigente", "En el momento de producirse no constituyan delito según la ley penal, aunque sí infracción según un reglamento", "Sean contrarias a la moral o hayan causado alarma social"]'::jsonb,1,'Art. 25.1 CE','Nadie puede ser condenado o sancionado por acciones u omisiones que, cuando se produjeron, no constituían delito, falta o infracción administrativa.',null),
('aux-canarias:1-c6cd03f488','aux-canarias',1,'Según el art. 14, los españoles son iguales ante la ley sin que pueda prevalecer discriminación por razón de:','["Nacimiento, raza, sexo, religión u opinión, sin incluir otras circunstancias", "Sexo, raza, nacionalidad, ideología y orientación sexual, pero no por cualquier otra condición o circunstancia personal o social", "Nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social", "Nacimiento, raza, sexo, religión, opinión o cualquier otra condición, salvo las circunstancias económicas y sociales, que regulan las leyes"]'::jsonb,2,'Art. 14 CE','No puede prevalecer discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.',null),
('aux-canarias:1-3a4e9e84f3','aux-canarias',1,'Son ilegales las asociaciones que:','["Reciban subvenciones públicas sin haberse inscrito previamente en el registro", "Persigan fines o utilicen medios tipificados como delito", "Tengan menos de diez socios fundadores", "No estén inscritas en un registro"]'::jsonb,1,'Art. 22.2 CE','Las asociaciones que persigan fines o utilicen medios tipificados como delito son ilegales.',null),
('aux-canarias:1-1a84bafaca','aux-canarias',1,'La nacionalidad española se adquiere, se conserva y se pierde:','["Solo por nacimiento o por residencia legal continuada", "Según lo que establezca cada Comunidad Autónoma en su Estatuto", "De acuerdo con lo establecido por la ley", "Por decisión del Gobierno, mediante real decreto acordado en Consejo de Ministros"]'::jsonb,2,'Art. 11.1 CE','Se adquiere, conserva y pierde de acuerdo con lo establecido por la ley.',null),
('aux-canarias:1-b9be27a279','aux-canarias',1,'El art. 40.2 encomienda a los poderes públicos garantizar el descanso necesario mediante:','["La jubilación anticipada y la reducción de la edad de jubilación", "La semana laboral de cuatro días y la jornada continua", "La limitación de la jornada laboral y las vacaciones periódicas retribuidas", "La limitación de la jornada laboral y los permisos retribuidos que fije cada convenio colectivo"]'::jsonb,2,'Art. 40.2 CE','Mediante la limitación de la jornada laboral, las vacaciones periódicas retribuidas y la promoción de centros adecuados.',null),
('aux-canarias:1-f2f2ac358e','aux-canarias',1,'El derecho de reunión pacífica y sin armas:','["No necesita autorización previa", "Requiere autorización judicial", "Requiere autorización del Delegado del Gobierno", "Solo se ejerce en locales cerrados"]'::jsonb,0,'Art. 21.1 CE','Se reconoce el derecho de reunión pacífica y sin armas, cuyo ejercicio no necesita autorización previa.',null),
('aux-canarias:1-0c7181ee7d','aux-canarias',1,'Según el art. 10.1, son fundamento del orden político y de la paz social:','["La monarquía parlamentaria, la soberanía nacional y la unidad de la Nación española", "La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás", "La dignidad de la persona, la soberanía popular, la economía social de mercado, la unidad de la Nación española y la solidaridad entre sus nacionalidades y regiones", "La unidad de mercado y la libertad de empresa"]'::jsonb,1,'Art. 10.1 CE','Lo son la dignidad de la persona, sus derechos inviolables, el libre desarrollo de la personalidad y el respeto a la ley y a los derechos de los demás.',null),
('aux-canarias:1-0bf26dfdb0','aux-canarias',1,'La estructura interna y el funcionamiento de los Colegios Profesionales deberán ser:','["Fijados por el Gobierno", "Secretos", "Democráticos", "Jerárquicos"]'::jsonb,2,'Art. 36 CE','La ley regulará los Colegios Profesionales, cuya estructura interna y funcionamiento deberán ser democráticos.',null),
('aux-canarias:1-a3e43947c6','aux-canarias',1,'Según el art. 7, los sindicatos de trabajadores y las asociaciones empresariales deben tener:','["Una estructura interna y un funcionamiento democráticos", "Un número mínimo de afiliados que fije la ley orgánica correspondiente", "Autorización administrativa previa", "Inscripción en el Registro de Partidos Políticos"]'::jsonb,0,'Art. 7 CE','Su estructura interna y funcionamiento deberán ser democráticos.',null),
('aux-canarias:1-558a271c99','aux-canarias',1,'La riqueza de las distintas modalidades lingüísticas de España es, según la Constitución:','["Un asunto de las Comunidades sin protección constitucional", "Un límite a la libertad de expresión", "Un patrimonio cultural objeto de especial respeto y protección", "Una competencia exclusiva del Estado"]'::jsonb,2,'Art. 3.3 CE','Es un patrimonio cultural que será objeto de especial respeto y protección.',null),
('aux-canarias:1-bb3559035b','aux-canarias',1,'La ley garantiza el derecho a la negociación colectiva laboral y:','["La prohibición de los convenios de empresa", "El arbitraje obligatorio", "La aprobación de los convenios por el Gobierno", "La fuerza vinculante de los convenios"]'::jsonb,3,'Art. 37.1 CE','La ley garantizará el derecho a la negociación colectiva laboral, así como la fuerza vinculante de los convenios.',null),
('aux-canarias:1-e9abaca3e4','aux-canarias',1,'Los extranjeros gozan en España de las libertades públicas del Título I:','["En ningún caso, salvo los derechos inherentes a la dignidad humana", "En igualdad absoluta con los españoles, incluido el derecho de sufragio en todas las elecciones", "Solo si residen legalmente más de cinco años", "En los términos que establezcan los tratados y la ley"]'::jsonb,3,'Art. 13.1 CE','Gozarán de las libertades públicas que garantiza el Título I en los términos que establezcan los tratados y la ley.',null),
('aux-canarias:1-76dbf6e964','aux-canarias',1,'Las libertades del art. 20 tienen su límite, especialmente, en:','["La opinión mayoritaria de la sociedad, los intereses económicos del Estado y las instrucciones del Gobierno sobre la información pública", "Las instrucciones del Gobierno en materia de comunicación", "La seguridad nacional, el orden público, los intereses económicos del Estado y las instrucciones del Gobierno en materia de comunicación", "El derecho al honor, a la intimidad, a la propia imagen y la protección de la juventud y de la infancia"]'::jsonb,3,'Art. 20.4 CE','Tienen su límite en los demás derechos del Título I y, especialmente, en el honor, la intimidad, la propia imagen y la protección de la juventud y la infancia.',null),
('aux-canarias:1-f02f8425c6','aux-canarias',1,'Las penas privativas de libertad y las medidas de seguridad están orientadas a:','["El trabajo obligatorio en beneficio de la comunidad y la compensación económica a la víctima del delito", "La compensación económica a la víctima y a la sociedad", "La reeducación y la reinserción social, y no pueden consistir en trabajos forzados", "La reeducación y la reinserción social, y pueden incluir trabajos forzados en los casos que prevea la ley"]'::jsonb,2,'Art. 25.2 CE','Están orientadas hacia la reeducación y reinserción social y no podrán consistir en trabajos forzados.',null),
('aux-canarias:1-63cb0e89a1','aux-canarias',1,'Las Fuerzas Armadas están constituidas, según la Constitución, por:','["El Ejército de Tierra y la Policía Nacional", "El Ejército de Tierra, la Armada y el Ejército del Aire", "Las Fuerzas y Cuerpos de Seguridad del Estado", "El Ejército de Tierra, la Guardia Civil y la Armada"]'::jsonb,1,'Art. 8.1 CE','Las constituyen el Ejército de Tierra, la Armada y el Ejército del Aire.',null),
('aux-canarias:1-9080c5cf2a','aux-canarias',1,'Según el art. 33.3, nadie podrá ser privado de sus bienes y derechos sino:','["Por deudas con particulares reconocidas en sentencia firme", "Por orden del alcalde", "Por causa justificada de utilidad pública o interés social, sin indemnización cuando así lo decida el Gobierno mediante real decreto", "Por causa justificada de utilidad pública o interés social, mediante la correspondiente indemnización y de conformidad con la ley"]'::jsonb,3,'Art. 33.3 CE','Solo por causa justificada de utilidad pública o interés social, con indemnización y conforme a la ley.',null),
('aux-canarias:1-64d6b73a0b','aux-canarias',1,'Según el art. 30.3, podrá establecerse:','["Un servicio civil para el cumplimiento de fines de interés general", "Un impuesto especial para la defensa nacional y la protección civil", "Un servicio militar universitario", "Una milicia en cada Comunidad Autónoma"]'::jsonb,0,'Art. 30.3 CE','Podrá establecerse un servicio civil para el cumplimiento de fines de interés general.',null),
('aux-canarias:1-a0814ee411','aux-canarias',1,'Según el art. 43.3, los poderes públicos fomentarán:','["El deporte profesional y de alto rendimiento, exclusivamente", "La medicina preventiva privada mediante conciertos con las mutuas sanitarias", "La educación sanitaria, la educación física y el deporte", "La educación física y el deporte escolar, pero no la educación sanitaria"]'::jsonb,2,'Art. 43.3 CE','Fomentarán la educación sanitaria, la educación física y el deporte, y facilitarán la adecuada utilización del ocio.',null),
('aux-canarias:1-8e7c64898c','aux-canarias',1,'Según el art. 33.1, se reconoce el derecho:','["A la herencia, pero solo entre cónyuges y descendientes", "A la propiedad privada y a la herencia", "A la propiedad privada y a una vivienda en propiedad para cada familia", "A una renta mínima garantizada"]'::jsonb,1,'Art. 33.1 CE','Se reconoce el derecho a la propiedad privada y a la herencia.',null),
('aux-canarias:1-e8f46be85b','aux-canarias',1,'Según el art. 38, se reconoce la libertad de empresa en el marco de:','["La economía de mercado", "La economía cooperativa exclusivamente", "La planificación central obligatoria", "El monopolio estatal"]'::jsonb,0,'Art. 38 CE','Se reconoce la libertad de empresa en el marco de la economía de mercado.',null),
('aux-canarias:1-8136eb10f3','aux-canarias',1,'Según el art. 35.1, todos los españoles tienen:','["Solo el derecho al trabajo", "El deber de trabajar y el derecho al trabajo", "Derecho a no trabajar sin consecuencias", "Derecho a un empleo público"]'::jsonb,1,'Art. 35.1 CE','Tienen el deber de trabajar y el derecho al trabajo, a la libre elección de profesión u oficio y a una remuneración suficiente.',null),
('aux-canarias:1-34a7a22d15','aux-canarias',1,'Según el art. 28.1, respecto a la libertad sindical:','["La afiliación es obligatoria para los funcionarios", "Nadie podrá ser obligado a afiliarse a un sindicato", "Solo pueden sindicarse los trabajadores fijos", "Los jueces pueden sindicarse sin límites"]'::jsonb,1,'Art. 28.1 CE','Todos tienen derecho a sindicarse libremente y nadie podrá ser obligado a afiliarse a un sindicato.',null),
('aux-canarias:1-0eb611146b','aux-canarias',1,'El derecho de petición, según el art. 29.1:','["Solo pueden ejercerlo las asociaciones", "Requiere abogado", "Es individual y colectivo, por escrito", "Solo es individual y verbal"]'::jsonb,2,'Art. 29.1 CE','Todos los españoles tienen el derecho de petición individual y colectiva, por escrito.',null),
('aux-canarias:1-e2332e3e6f','aux-canarias',1,'El art. 43 reconoce el derecho a:','["La asistencia sanitaria privada gratuita", "La protección de la salud", "La elección libre de médico en todo caso", "Un seguro de vida"]'::jsonb,1,'Art. 43.1 CE','Se reconoce el derecho a la protección de la salud.',null),
('aux-canarias:1-97cfb6326d','aux-canarias',1,'El art. 47 reconoce a todos los españoles el derecho a:','["Una ayuda pública al alquiler en todo caso, de cuantía fija", "Una vivienda en propiedad a precio tasado", "Disfrutar de una vivienda digna y adecuada", "Disfrutar de una vivienda digna, que los poderes públicos deben adjudicar directamente a quien la solicite"]'::jsonb,2,'Art. 47 CE','Todos los españoles tienen derecho a disfrutar de una vivienda digna y adecuada.',null),
('aux-canarias:1-9dbab76543','aux-canarias',1,'Los poderes públicos garantizarán la conservación y promoverán el enriquecimiento de:','["Las empresas públicas y su patrimonio", "El patrimonio histórico, cultural y artístico de los pueblos de España", "El patrimonio histórico, cultural y artístico de titularidad pública, pero no el de titularidad privada", "Los bienes de la Corona"]'::jsonb,1,'Art. 46 CE','Garantizarán la conservación y promoverán el enriquecimiento del patrimonio histórico, cultural y artístico.',null),
('aux-canarias:1-668962725d','aux-canarias',1,'Según el art. 24.1, todas las personas tienen derecho a obtener la tutela efectiva de los jueces y tribunales:','["Sin que, en ningún caso, pueda producirse indefensión", "Solo en asuntos penales y contencioso-administrativos", "Solo si están asistidas de abogado y procurador", "Previo pago de las tasas judiciales correspondientes"]'::jsonb,0,'Art. 24.1 CE','Tienen derecho a la tutela judicial efectiva sin que, en ningún caso, pueda producirse indefensión.',null),
('aux-canarias:1-f3c1026c89','aux-canarias',1,'¿Qué prohíbe el art. 26 de la Constitución?','["Los colegios profesionales con adscripción obligatoria", "Los jurados populares en el ámbito penal", "Los tribunales militares en tiempo de guerra y en los supuestos de estado de sitio declarados por el Congreso", "Los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales"]'::jsonb,3,'Art. 26 CE','Se prohíben los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales.',null),
('aux-canarias:1-a142d35069','aux-canarias',1,'El art. 18.1 garantiza el derecho:','["Al honor, a la intimidad personal y familiar y a la propia imagen", "A la propiedad privada y a la herencia", "A la libertad de empresa en el marco de la economía de mercado", "Al secreto de las comunicaciones"]'::jsonb,0,'Art. 18.1 CE','Garantiza el derecho al honor, a la intimidad personal y familiar y a la propia imagen.',null),
('aux-canarias:1-5a030869d0','aux-canarias',1,'El derecho de fundación se reconoce:','["Para fines de interés general, con arreglo a la ley", "Solo a las empresas y sociedades mercantiles", "Solo para fines religiosos o benéficos", "Para cualquier fin, incluido el lucrativo, con arreglo a la ley"]'::jsonb,0,'Art. 34.1 CE','Se reconoce el derecho de fundación para fines de interés general, con arreglo a la ley.',null),
('aux-canarias:1-555b0e1b2d','aux-canarias',1,'Según el art. 9.1, están sujetos a la Constitución y al resto del ordenamiento jurídico:','["Solo los ciudadanos españoles", "Solo los funcionarios y los poderes públicos", "Solo los poderes públicos y los funcionarios", "Los ciudadanos y los poderes públicos"]'::jsonb,3,'Art. 9.1 CE','Los ciudadanos y los poderes públicos están sujetos a la Constitución y al resto del ordenamiento jurídico.',null),
('aux-canarias:1-cf754e7588','aux-canarias',1,'Las prestaciones personales o patrimoniales de carácter público solo pueden establecerse:','["Con arreglo a la ley", "Por reglamento", "Por orden ministerial", "Por acuerdo municipal"]'::jsonb,0,'Art. 31.3 CE','Solo podrán establecerse prestaciones personales o patrimoniales de carácter público con arreglo a la ley.',null),
('aux-canarias:1-faa5937d98','aux-canarias',1,'Según el art. 44.2, los poderes públicos promoverán:','["La investigación militar y de defensa, y la cooperación científica con las Fuerzas Armadas aliadas", "Solo la investigación sanitaria y farmacéutica", "La investigación privada exclusivamente, mediante incentivos fiscales a las empresas", "La ciencia y la investigación científica y técnica en beneficio del interés general"]'::jsonb,3,'Art. 44.2 CE','Promoverán la ciencia y la investigación científica y técnica en beneficio del interés general.',null),
('aux-canarias:1-c942f0c342','aux-canarias',1,'¿Quién establece los términos en que extranjeros y apátridas pueden gozar del derecho de asilo?','["Los tratados exclusivamente", "La ley", "El Defensor del Pueblo", "El Ministerio del Interior por orden"]'::jsonb,1,'Art. 13.4 CE','La ley establecerá los términos en que los ciudadanos de otros países y los apátridas podrán gozar del derecho de asilo.',null),
('aux-canarias:1-6ab117283c','aux-canarias',1,'¿Qué regula la ley según el art. 20.3?','["La censura previa de los medios de comunicación privados", "Las tarifas publicitarias y el régimen de concesión de licencias de los medios de comunicación privados de ámbito estatal", "El control parlamentario de los medios de comunicación social dependientes del Estado o de cualquier ente público", "El control gubernamental de todos los medios de comunicación social, públicos y privados, a través de una autoridad independiente"]'::jsonb,2,'Art. 20.3 CE','La ley regulará la organización y el control parlamentario de los medios dependientes del Estado o de cualquier ente público.',null),
('aux-canarias:1-bbe81a4859','aux-canarias',1,'Respecto a la extradición, la Constitución establece que:','["No se consideran delitos políticos los actos de terrorismo", "Solo la concede el Gobierno, sin intervención judicial", "Se concede sin necesidad de tratado ni de ley, por reciprocidad", "Está prohibida en todo caso respecto de los nacionales"]'::jsonb,0,'Art. 13.3 CE','La extradición se concede en cumplimiento de un tratado o de la ley, atendiendo a la reciprocidad; los actos de terrorismo no se consideran delitos políticos.',null),
('aux-canarias:1-a153838ab4','aux-canarias',1,'Toda persona detenida debe ser informada:','["Solo si lo solicita su abogado o un familiar", "En el plazo máximo de 72 horas, una vez puesta a disposición judicial y en presencia de su abogado", "Solo cuando sea puesta a disposición judicial, en presencia de su abogado y en el plazo de setenta y dos horas", "De forma inmediata y comprensible de sus derechos y de las razones de su detención"]'::jsonb,3,'Art. 17.3 CE','Debe ser informada de forma inmediata, y de modo que le sea comprensible, de sus derechos y de las razones de su detención.',null),
('aux-canarias:1-43c8d813cf','aux-canarias',1,'Según la Constitución, ¿puede alguien ser obligado a declarar sobre su ideología, religión o creencias?','["No", "Sí, ante un juez", "Sí, en los censos oficiales", "Solo los funcionarios"]'::jsonb,0,'Art. 16.2 CE','Nadie podrá ser obligado a declarar sobre su ideología, religión o creencias.',null),
('aux-canarias:1-6ebd6b6995','aux-canarias',1,'Respecto al medio ambiente, el art. 45.1 reconoce:','["El derecho a disfrutar de un medio ambiente adecuado y el deber de conservarlo", "El derecho a disfrutar de un medio ambiente adecuado, sin establecer ningún deber de conservarlo", "El derecho a explotarlo libremente", "El deber de conservarlo, pero no el derecho a disfrutarlo, que se regula en los Estatutos"]'::jsonb,0,'Art. 45.1 CE','Todos tienen el derecho a disfrutar de un medio ambiente adecuado para el desarrollo de la persona, así como el deber de conservarlo.',null),
('aux-canarias:1-8a9e7e7cc3','aux-canarias',1,'Las banderas propias de las Comunidades Autónomas:','["Las aprueba el Gobierno de la Nación a propuesta de cada Comunidad", "Están prohibidas en los edificios públicos del Estado", "Sustituyen a la bandera de España en los edificios y actos oficiales de su territorio, si así lo dispone su Estatuto", "Pueden ser reconocidas por los Estatutos y se utilizan junto a la bandera de España en sus edificios y actos oficiales"]'::jsonb,3,'Art. 4.2 CE','Los Estatutos pueden reconocerlas; se usan junto a la bandera de España en sus edificios públicos y actos oficiales.',null),
('aux-canarias:1-2301c56eb2','aux-canarias',1,'Las asociaciones solo pueden ser disueltas o suspendidas en sus actividades:','["Por orden del Ministerio del Interior", "Por acuerdo del Consejo de Ministros", "En virtud de resolución judicial motivada", "Por decisión de la Delegación del Gobierno"]'::jsonb,2,'Art. 22.4 CE','Solo podrán ser disueltas o suspendidas en virtud de resolución judicial motivada.',null),
('aux-canarias:1-89e151a5c5','aux-canarias',1,'Según el art. 27.2, la educación tiene por objeto:','["El pleno desarrollo de la personalidad humana en el respeto a los principios democráticos y a los derechos fundamentales", "Preparar para el acceso al empleo y a la función pública", "La formación profesional exclusivamente", "El pleno desarrollo de la personalidad humana en el respeto a la religión mayoritaria y a las tradiciones de cada Comunidad Autónoma"]'::jsonb,0,'Art. 27.2 CE','Tiene por objeto el pleno desarrollo de la personalidad humana en el respeto a los principios democráticos de convivencia y a los derechos y libertades fundamentales.',null),
('aux-canarias:1-f31feb592f','aux-canarias',1,'Según el art. 2, la Constitución se fundamenta en:','["La indisoluble unidad de la Nación española, y reconoce el derecho a la autonomía de las nacionalidades y regiones", "La voluntad del Jefe del Estado", "La soberanía compartida del Estado y de las Comunidades Autónomas, y reconoce su derecho a la autodeterminación", "El pacto entre los territorios históricos"]'::jsonb,0,'Art. 2 CE','Se fundamenta en la indisoluble unidad de la Nación española y reconoce y garantiza el derecho a la autonomía de las nacionalidades y regiones y la solidaridad entre todas ellas.',null),
('aux-canarias:1-46cfa36c2e','aux-canarias',1,'¿Quién inspecciona y homologa el sistema educativo?','["Los poderes públicos", "Las universidades", "Los colegios profesionales", "Las asociaciones de padres"]'::jsonb,0,'Art. 27.8 CE','Los poderes públicos inspeccionarán y homologarán el sistema educativo para garantizar el cumplimiento de las leyes.',null),
('aux-canarias:1-0c3eb36e09','aux-canarias',1,'Según el art. 41, los poderes públicos mantendrán:','["Mutualidades profesionales obligatorias", "Un seguro médico solo para los trabajadores por cuenta ajena", "Un sistema privado de pensiones obligatorio", "Un régimen público de Seguridad Social para todos los ciudadanos"]'::jsonb,3,'Art. 41 CE','Mantendrán un régimen público de Seguridad Social para todos los ciudadanos.',null),
('aux-canarias:1-ff438fb55d','aux-canarias',1,'Según el art. 39.1, los poderes públicos aseguran:','["Una vivienda digna a cada familia", "La protección social, económica y jurídica de la familia", "La protección social, económica y jurídica de la familia, pero solo de la fundada en el matrimonio", "La educación obligatoria hasta los 25 años"]'::jsonb,1,'Art. 39.1 CE','Los poderes públicos aseguran la protección social, económica y jurídica de la familia.',null),
('aux-canarias:1-060ef796f4','aux-canarias',1,'Según el art. 50, los poderes públicos garantizarán a los ciudadanos durante la tercera edad:','["Una plaza en una residencia pública", "La gratuidad del transporte público", "Una pensión igual para todos, independientemente de lo cotizado", "Pensiones adecuadas y periódicamente actualizadas"]'::jsonb,3,'Art. 50 CE','Garantizarán, mediante pensiones adecuadas y periódicamente actualizadas, la suficiencia económica en la tercera edad.',null),
('aux-canarias:1-64f848cf3a','aux-canarias',1,'El sistema tributario, según el art. 31.1, debe ser justo, inspirado en la igualdad y la progresividad, y:','["Proporcional a la renta en todo caso", "Igual para todos los contribuyentes, con independencia de su renta", "En ningún caso tendrá alcance confiscatorio", "Exclusivamente estatal"]'::jsonb,2,'Art. 31.1 CE','Se basa en la igualdad y la progresividad, y en ningún caso tendrá alcance confiscatorio.',null),
('aux-canarias:1-5631c72632','aux-canarias',1,'Se reconoce a las personas físicas y jurídicas la libertad de:','["Expedir títulos oficiales sin necesidad de homologación", "Fijar libremente los planes de estudio oficiales", "Creación de centros docentes, dentro del respeto a los principios constitucionales", "Creación de centros docentes, que solo podrán impartir enseñanzas no regladas"]'::jsonb,2,'Art. 27.6 CE','Se reconoce la libertad de creación de centros docentes, dentro del respeto a los principios constitucionales.',null),
('aux-canarias:1-79f5440d0a','aux-canarias',1,'Según el art. 9.2, corresponde a los poderes públicos:','["Promover las condiciones para que la libertad y la igualdad sean reales y efectivas, y remover los obstáculos que lo impidan", "Regular la vida privada de los ciudadanos", "Limitar la participación política", "Garantizar la igualdad de resultados económicos entre todos los ciudadanos y territorios, y suprimir las diferencias de renta que lo impidan"]'::jsonb,0,'Art. 9.2 CE','Deben promover esas condiciones, remover los obstáculos y facilitar la participación de todos los ciudadanos.',null),
('aux-canarias:1-067ed9a473','aux-canarias',1,'¿Qué regula la ley según el art. 30.2?','["El servicio militar obligatorio, su duración y las causas de exención", "El ejército profesional exclusivamente", "La participación de España en organizaciones internacionales de defensa", "Las obligaciones militares de los españoles y la objeción de conciencia"]'::jsonb,3,'Art. 30.2 CE','La ley fijará las obligaciones militares de los españoles y regulará la objeción de conciencia.',null),
('aux-canarias:1-87d37044f5','aux-canarias',1,'Según el art. 42, el Estado orientará su política hacia el retorno de:','["Los trabajadores españoles en el extranjero", "Los capitales invertidos fuera", "Los funcionarios destinados en el exterior", "Los estudiantes de Erasmus"]'::jsonb,0,'Art. 42 CE','El Estado velará por los derechos de los trabajadores españoles en el extranjero y orientará su política hacia su retorno.',null),
('aux-canarias:1-4b9fddedff','aux-canarias',1,'El contenido del derecho de propiedad y de herencia lo delimita:','["Las ordenanzas fiscales de cada municipio", "La voluntad del propietario", "Su función social, de acuerdo con las leyes", "El Registro de la Propiedad"]'::jsonb,2,'Art. 33.2 CE','La función social de estos derechos delimitará su contenido, de acuerdo con las leyes.',null),
('aux-canarias:1-8ce1365534','aux-canarias',1,'Según el art. 23.1, los ciudadanos participan en los asuntos públicos:','["Solo por medio de los partidos políticos con representación parlamentaria", "Directamente o por medio de representantes elegidos en elecciones periódicas por sufragio censitario", "Por medio de representantes designados por las Cortes Generales y por los Parlamentos autonómicos", "Directamente o por medio de representantes libremente elegidos en elecciones periódicas por sufragio universal"]'::jsonb,3,'Art. 23.1 CE','Participan directamente o por medio de representantes libremente elegidos en elecciones periódicas por sufragio universal.',null),
('aux-canarias:1-5a2bb7111c','aux-canarias',1,'Las bases de la organización militar se regulan mediante:','["Un real decreto", "Una ley ordinaria", "Una ley orgánica", "Una orden del Ministerio de Defensa"]'::jsonb,2,'Art. 8.2 CE','Una ley orgánica regulará las bases de la organización militar.',null),
('aux-canarias:1-da5b9d8c8e','aux-canarias',1,'Según el art. 51.1, los poderes públicos garantizarán la defensa de:','["Los consumidores y usuarios, protegiendo mediante procedimientos eficaces su seguridad, salud e intereses económicos", "Los comerciantes minoristas exclusivamente", "Las empresas frente a la competencia desleal y los productores frente a las importaciones de terceros países", "Los productores agrarios"]'::jsonb,0,'Art. 51.1 CE','Garantizarán la defensa de los consumidores y usuarios mediante procedimientos eficaces.',null),
('aux-canarias:1-5ab4086072','aux-canarias',1,'En el control y la gestión de los centros sostenidos con fondos públicos intervienen:','["Solo la Administración educativa competente", "Los sindicatos más representativos y la Administración", "Solo el director del centro y el titular, en el caso de los centros concertados", "Los profesores, los padres y, en su caso, los alumnos"]'::jsonb,3,'Art. 27.7 CE','Intervienen los profesores, los padres y, en su caso, los alumnos, en los términos que la ley establezca.',null),
('aux-canarias:1-10333058b2','aux-canarias',1,'Según el art. 19, los españoles tienen derecho a:','["Una vivienda pública en su lugar de residencia", "Cambiar de nacionalidad libremente y entrar y salir de España sin requisitos", "Viajar sin pasaporte a cualquier país y residir en el extranjero sin requisitos", "Elegir libremente su residencia y a circular por el territorio nacional"]'::jsonb,3,'Art. 19 CE','Tienen derecho a elegir libremente su residencia y a circular por el territorio nacional.',null),
('aux-canarias:1-9a3e4d62bf','aux-canarias',1,'Según el art. 54 CE, el Defensor del Pueblo es:','["Alto comisionado del Gobierno, designado por el Consejo de Ministros para supervisar a la Administración", "Alto comisionado de las Cortes Generales, designado por estas para la defensa de los derechos del Título I", "Alto comisionado de las Cortes Generales, designado por el Rey a propuesta del Congreso", "Órgano del Poder Judicial encargado de la defensa de los derechos fundamentales"]'::jsonb,1,'Art. 54 CE','Puede supervisar la actividad de la Administración, dando cuenta a las Cortes Generales.',null),
('aux-canarias:1-a0b1607df8','aux-canarias',1,'La reforma del artículo 49 de la Constitución aprobada en 2024 sustituyó la expresión «disminuidos físicos, sensoriales y psíquicos» por:','["Personas con discapacidad", "Personas dependientes", "Personas con capacidades diferentes", "Personas con diversidad funcional"]'::jsonb,0,'Art. 49 CE (reforma de 17 de febrero de 2024)','Fue la tercera reforma de la Constitución, tras las de 1992 (art. 13.2) y 2011 (art. 135).',null),
('aux-canarias:2-5a79ffe05e','aux-canarias',2,'Según el art. 152.1 CE, el Tribunal Superior de Justicia:','["Culmina la organización judicial en el ámbito territorial de la Comunidad Autónoma, sin perjuicio de la jurisdicción del Tribunal Supremo", "Es el órgano jurisdiccional superior en todos los órdenes dentro de la Comunidad, sin que quepa recurso ante el Tribunal Supremo", "Es el órgano de gobierno de los jueces de la Comunidad Autónoma", "Depende del Gobierno autonómico, que nombra a su Presidente"]'::jsonb,0,'Art. 152.1 CE','Las sucesivas instancias procesales se agotan ante órganos radicados en el mismo territorio de la CA en que esté el órgano competente en primera instancia.',null),
('aux-canarias:2-813217ed97','aux-canarias',2,'Según el artículo 137 de la Constitución, el Estado se organiza territorialmente en:','["Provincias, Comunidades Autónomas y Ciudades Autónomas", "Municipios, islas y Comunidades Autónomas", "Municipios, provincias y Comunidades Autónomas", "Municipios, comarcas, provincias y regiones"]'::jsonb,2,'Art. 137 CE','Todas estas entidades gozan de autonomía para la gestión de sus respectivos intereses.',null),
('aux-canarias:2-975eb421e7','aux-canarias',2,'Según la Constitución, el gobierno y la administración de los municipios corresponde a:','["Las Diputaciones Provinciales, a través de sus delegaciones comarcales en cada municipio", "Los Delegados del Gobierno, con la colaboración de los Concejales elegidos por los vecinos", "Las asambleas vecinales abiertas, presididas por el Alcalde y el Secretario municipal", "Sus respectivos Ayuntamientos, integrados por los Alcaldes y los Concejales"]'::jsonb,3,'Art. 140 CE','Los Concejales son elegidos por los vecinos por sufragio universal, igual, libre, directo y secreto.',null),
('aux-canarias:2-37c44953c6','aux-canarias',2,'Según el artículo 140 de la Constitución, los Alcaldes serán elegidos:','["Por el Delegado del Gobierno, a propuesta de los Concejales", "Por el Pleno de la Diputación Provincial", "Por los Concejales o por los vecinos", "Siempre por sufragio universal directo de los vecinos"]'::jsonb,2,'Art. 140 CE','La ley regula las condiciones en las que procede el régimen del concejo abierto.',null),
('aux-canarias:2-187e04b18e','aux-canarias',2,'¿Qué tipo de ley es necesaria para alterar los límites provinciales?','["Una ley orgánica aprobada por las Cortes Generales", "Un real decreto del Consejo de Ministros", "Una ley ordinaria de las Cortes Generales, por mayoría absoluta", "Una ley de la Comunidad Autónoma afectada, previo informe estatal"]'::jsonb,0,'Art. 141.1 CE','La provincia es una entidad local con personalidad jurídica propia, agrupación de municipios y división territorial para el cumplimiento de las actividades del Estado.',null),
('aux-canarias:2-b2fb0d1b6f','aux-canarias',2,'En los archipiélagos, las islas tendrán además su administración propia en forma de:','["Diputaciones forales", "Cabildos o Consejos", "Juntas Generales", "Mancomunidades insulares"]'::jsonb,1,'Art. 141.4 CE','Los Cabildos existen en Canarias y los Consejos Insulares en Baleares.',null),
('aux-canarias:2-a76acbf024','aux-canarias',2,'Según el artículo 143.2 de la Constitución, la iniciativa del proceso autonómico corresponde a todas las Diputaciones interesadas o al órgano interinsular correspondiente y a:','["Los municipios que representen un tercio del censo electoral de la región histórica", "Las tres cuartas partes de los municipios que representen la mayoría absoluta de los electores", "La mitad de los municipios de cada provincia, sea cual sea su población", "Las dos terceras partes de los municipios cuya población represente, al menos, la mayoría del censo electoral de cada provincia o isla"]'::jsonb,3,'Art. 143.2 CE','Los requisitos deben cumplirse en el plazo de seis meses desde el primer acuerdo de una Corporación local.',null),
('aux-canarias:2-abffe64371','aux-canarias',2,'¿En qué plazo deben cumplirse los requisitos de iniciativa autonómica del artículo 143.2 de la Constitución?','["Dos años desde que se constituya la asamblea de parlamentarios", "Seis meses desde el primer acuerdo adoptado por alguna de las Corporaciones locales interesadas", "Tres meses desde el acuerdo de la última de las Diputaciones interesadas", "Un año desde la publicación de la Constitución en el Boletín Oficial del Estado y en los diarios oficiales"]'::jsonb,1,'Art. 143.2 CE','Si la iniciativa no prospera, solo puede reiterarse pasados cinco años.',null),
('aux-canarias:2-63ab67fd57','aux-canarias',2,'Si la iniciativa autonómica del artículo 143 no prospera:','["Podrá reiterarse pasados tres años", "Solo podrá reiterarse pasados cinco años", "Podrá reiterarse al año siguiente", "No podrá volver a plantearse nunca"]'::jsonb,1,'Art. 143.3 CE','Así lo dispone el artículo 143.3 de la Constitución.',null),
('aux-canarias:2-7c55b31439','aux-canarias',2,'Según el artículo 144 de la Constitución, las Cortes Generales, mediante ley orgánica y por motivos de interés nacional, podrán:','["Integrar dos Comunidades Autónomas limítrofes en una sola, sin necesidad de referéndum", "Disolver una Comunidad Autónoma que incumpla de forma grave las obligaciones que le imponen la Constitución u otras leyes", "Suspender la autonomía de una Comunidad Autónoma por un plazo máximo de seis meses", "Autorizar la constitución de una Comunidad Autónoma cuyo ámbito territorial no supere el de una provincia y no reúna las condiciones del artículo 143.1"]'::jsonb,3,'Art. 144 a) CE','El artículo 155 no permite disolver Comunidades, sino adoptar medidas para obligarlas a cumplir.',null),
('aux-canarias:2-87e0cabf95','aux-canarias',2,'¿Qué prohíbe el artículo 145 de la Constitución?','["Que una Comunidad Autónoma tenga varias provincias", "La federación de Comunidades Autónomas", "Los convenios entre Comunidades Autónomas", "Que las Comunidades Autónomas tengan himno propio"]'::jsonb,1,'Art. 145.1 CE','Sí se permiten convenios entre Comunidades para la gestión de servicios propios, que deben comunicarse a las Cortes Generales.',null),
('aux-canarias:2-9fb0855561','aux-canarias',2,'Los acuerdos de cooperación entre Comunidades Autónomas, distintos de los convenios para gestión de servicios propios, requieren:','["El dictamen del Consejo de Estado", "La aprobación del Consejo de Ministros", "La autorización de las Cortes Generales", "Una simple comunicación a las Cortes Generales"]'::jsonb,2,'Art. 145.2 CE','Los convenios para la gestión y prestación de servicios propios solo deben comunicarse a las Cortes.',null),
('aux-canarias:2-fb504bf285','aux-canarias',2,'Según el artículo 147 de la Constitución, el Estatuto de Autonomía es:','["Un tratado entre el Estado y la Comunidad Autónoma", "Un reglamento del Gobierno de la Nación para cada Comunidad", "La norma institucional básica de cada Comunidad Autónoma", "Una ley ordinaria aprobada por el Parlamento autonómico"]'::jsonb,2,'Art. 147.1 CE','El Estado lo reconoce y ampara como parte integrante de su ordenamiento jurídico.',null),
('aux-canarias:2-46c64ca846','aux-canarias',2,'¿Cuál de los siguientes contenidos NO exige la Constitución que figure en los Estatutos de Autonomía?','["La delimitación de su territorio", "La denominación de la Comunidad", "La lengua cooficial de la Comunidad", "Las competencias asumidas"]'::jsonb,2,'Art. 147.2 CE','El art. 147.2 exige denominación, delimitación del territorio, denominación, organización y sede de las instituciones propias y competencias asumidas.',null),
('aux-canarias:2-43b1bae131','aux-canarias',2,'La reforma de los Estatutos de Autonomía requiere, en todo caso:','["Un referéndum en todo el territorio nacional", "La aprobación por las Cortes Generales mediante ley orgánica", "El acuerdo del Senado por mayoría de tres quintos", "La aprobación por el Gobierno de la Nación mediante real decreto"]'::jsonb,1,'Art. 147.3 CE','El procedimiento lo fija cada Estatuto.',null),
('aux-canarias:2-e329be8f4c','aux-canarias',2,'Según el artículo 148.2 de la Constitución, las Comunidades Autónomas podían ampliar sucesivamente sus competencias transcurridos:','["Diez años", "Dos años", "Tres años", "Cinco años"]'::jsonb,3,'Art. 148.2 CE','Mediante la reforma de sus Estatutos, dentro del marco del artículo 149.',null),
('aux-canarias:2-bb43f6d555','aux-canarias',2,'Las materias no atribuidas expresamente al Estado por la Constitución podrán corresponder a las Comunidades Autónomas:','["Por acuerdo de la Conferencia de Presidentes", "Solo mediante ley de transferencia", "En virtud de sus respectivos Estatutos", "Siempre, de forma automática"]'::jsonb,2,'Art. 149.3 CE','Las no asumidas por los Estatutos corresponden al Estado, cuyo derecho es en todo caso supletorio del de las Comunidades Autónomas.',null),
('aux-canarias:2-cef9843825','aux-canarias',2,'En caso de conflicto, las normas del Estado prevalecen sobre las de las Comunidades Autónomas:','["En todo lo que no esté atribuido a la exclusiva competencia de estas", "Solo en materia de relaciones internacionales", "Solo si la norma estatal es posterior", "En todo caso, sin excepción alguna"]'::jsonb,0,'Art. 149.3 CE','Es la cláusula de prevalencia del derecho estatal.',null),
('aux-canarias:2-c6fa9f78b0','aux-canarias',2,'¿Qué leyes permiten a las Cortes atribuir a las Comunidades Autónomas la facultad de dictar normas legislativas en el marco de principios, bases y directrices fijados por una ley estatal?','["Las leyes de bases", "Las leyes marco", "Las leyes de armonización", "Las leyes orgánicas de transferencia"]'::jsonb,1,'Art. 150.1 CE','Las leyes de bases sirven para delegar en el Gobierno la elaboración de textos articulados.',null),
('aux-canarias:2-1deadce544','aux-canarias',2,'La transferencia o delegación a las Comunidades Autónomas de facultades de titularidad estatal se hace mediante:','["Ley ordinaria", "Real decreto legislativo", "Ley orgánica", "Ley marco"]'::jsonb,2,'Art. 150.2 CE','Debe prever la correspondiente transferencia de medios financieros y las formas de control que se reserve el Estado.',null),
('aux-canarias:2-a6decd5120','aux-canarias',2,'¿Quién aprecia la necesidad de dictar una ley de armonización?','["El Senado, por mayoría de dos tercios, a propuesta de la Comisión General de las CCAA", "El Tribunal Constitucional, a instancia del Gobierno o de cincuenta diputados", "Las Cortes Generales, por mayoría absoluta de cada Cámara", "El Gobierno de la Nación, previo dictamen favorable del Consejo de Estado"]'::jsonb,2,'Art. 150.3 CE','Lo exige el interés general, aunque se trate de materias atribuidas a la competencia de las Comunidades Autónomas.',null),
('aux-canarias:2-e466557fff','aux-canarias',2,'En la vía del artículo 151 de la Constitución, la iniciativa autonómica debía ratificarse mediante referéndum por:','["La mayoría absoluta de los votos válidos emitidos en el conjunto de toda España", "El voto afirmativo de la mayoría absoluta de los electores de cada provincia", "La mayoría simple de los votos emitidos en el conjunto del territorio de la futura Comunidad", "Dos tercios de los votantes de cada provincia"]'::jsonb,1,'Art. 151.1 CE','Además, la iniciativa debía acordarse por las Diputaciones y por las tres cuartas partes de los municipios de cada provincia.',null),
('aux-canarias:2-fa15375259','aux-canarias',2,'Según el artículo 152 de la Constitución, el Presidente de la Comunidad Autónoma es:','["Elegido por el Senado entre los senadores de la Comunidad", "Elegido directamente por los ciudadanos de la Comunidad en las elecciones autonómicas y nombrado por el Rey", "Nombrado por el Presidente del Gobierno, a propuesta de la Asamblea", "Elegido por la Asamblea Legislativa de entre sus miembros y nombrado por el Rey"]'::jsonb,3,'Art. 152.1 CE','Dirige el Consejo de Gobierno y ostenta la suprema representación de la Comunidad y la ordinaria del Estado en ella.',null),
('aux-canarias:2-4eb286cc34','aux-canarias',2,'El control económico y presupuestario de los órganos de las Comunidades Autónomas corresponde, según el artículo 153 de la Constitución, a:','["La jurisdicción contencioso-administrativa", "El Tribunal de Cuentas", "El Ministerio de Hacienda", "El Tribunal Constitucional"]'::jsonb,1,'Art. 153 d) CE','El TC controla las disposiciones con fuerza de ley y la jurisdicción contencioso-administrativa, la administración autónoma y sus reglamentos.',null),
('aux-canarias:2-1f8f06a0d8','aux-canarias',2,'¿Quién controla las funciones delegadas a las Comunidades Autónomas conforme al artículo 150.2 de la Constitución?','["El Tribunal de Cuentas, previo informe de la Intervención General", "El Tribunal Constitucional, previo recurso del Senado", "Los Tribunales Superiores de Justicia", "El Gobierno, previo dictamen del Consejo de Estado"]'::jsonb,3,'Art. 153 b) CE','Es una de las cuatro vías de control de la actividad autonómica que enumera el artículo 153.',null),
('aux-canarias:2-1c5c97f9de','aux-canarias',2,'Para aplicar las medidas del artículo 155 de la Constitución, el Gobierno necesita:','["Requerir previamente al Presidente de la Comunidad Autónoma y la aprobación de la mayoría absoluta del Senado", "La aprobación del Consejo de Estado y del Congreso", "La autorización del Congreso de los Diputados por mayoría de tres quintos", "Un dictamen favorable del Tribunal Constitucional"]'::jsonb,0,'Art. 155.1 CE','Se aplica si una Comunidad no cumple las obligaciones de la Constitución o las leyes o actúa contra el interés general de España.',null),
('aux-canarias:2-0f99be4b76','aux-canarias',2,'¿Qué fondo prevé el artículo 158.2 de la Constitución para corregir desequilibrios económicos interterritoriales?','["El Fondo de Suficiencia Global", "El Fondo de Compensación", "El Fondo de Garantía de Servicios Públicos Fundamentales", "El Fondo de Cohesión Territorial"]'::jsonb,1,'Art. 158.2 CE','Sus recursos se distribuyen por las Cortes Generales entre las Comunidades Autónomas y provincias.',null),
('aux-canarias:3-cb29a8fb89','aux-canarias',3,'¿Qué clases de competencias ejerce la Comunidad Autónoma de Canarias según su Estatuto?','["Exclusivas, de desarrollo legislativo y de ejecución, y ejecutivas", "Plenas, compartidas y residuales, según la cláusula de cierre del Estatuto", "Exclusivas, concurrentes y delegadas", "Exclusivas, compartidas con los cabildos, de ejecución y residuales asumidas por cláusula general"]'::jsonb,0,'Art. 94.1 EACan','La Comunidad Autónoma ejerce competencias exclusivas, de desarrollo legislativo y de ejecución y ejecutivas.',null),
('aux-canarias:3-006f6a5106','aux-canarias',3,'En el ámbito de sus competencias exclusivas, ¿qué potestades ejerce la Comunidad Autónoma de Canarias?','["La legislativa, la reglamentaria y la función ejecutiva, de forma íntegra", "Solo la reglamentaria y la ejecutiva, quedando la legislativa reservada al Estado", "La legislativa, en el marco de las bases estatales", "Solo la ejecutiva, salvo que una ley estatal le atribuya potestad reglamentaria"]'::jsonb,0,'Art. 95.1 EACan','En sus competencias exclusivas ejerce de forma íntegra la potestad legislativa, la reglamentaria y la función ejecutiva.',null),
('aux-canarias:3-2f53e683f5','aux-canarias',3,'En las competencias de desarrollo legislativo y de ejecución, ¿en qué marco actúa la Comunidad Autónoma de Canarias?','["Sin sujeción a ninguna norma estatal", "En el marco de las bases que fije el Estado", "En el marco de los acuerdos de la Comisión Bilateral de Cooperación con el Estado", "En el marco de los convenios con los cabildos"]'::jsonb,1,'Art. 96.1 EACan','Le corresponden la potestad legislativa, reglamentaria y ejecutiva en el marco de las bases que fije el Estado.',null),
('aux-canarias:3-ff2f4999c8','aux-canarias',3,'En el ámbito de las competencias ejecutivas, ¿qué potestad reglamentaria corresponde a Canarias?','["La aprobación de reglamentos ejecutivos de leyes estatales", "Ninguna potestad reglamentaria, que corresponde en exclusiva al Gobierno de Canarias", "Ninguna, porque la potestad reglamentaria se reserva al Estado en las competencias ejecutivas", "La aprobación de reglamentos internos de organización de los servicios"]'::jsonb,3,'Art. 97 b) EACan','En las competencias ejecutivas, la potestad reglamentaria comprende la aprobación de reglamentos internos de organización de los servicios.',null),
('aux-canarias:3-48aa80502b','aux-canarias',3,'¿Qué establece el principio de prevalencia del Estatuto de Autonomía de Canarias?','["Que el derecho propio en competencias exclusivas se aplica con preferencia a cualquier otro", "Que el derecho estatal prevalece siempre sobre el canario", "Que las ordenanzas insulares prevalecen sobre las leyes autonómicas", "Que la ley estatal posterior prevalece sobre la ley autonómica anterior"]'::jsonb,0,'Art. 98 EACan','El derecho propio de Canarias en materia de competencia exclusiva es aplicable en su territorio con preferencia a cualquier otro.',null),
('aux-canarias:3-b48af8858c','aux-canarias',3,'¿Cómo ejerce Canarias las competencias no contempladas expresamente en su Estatuto?','["Asumiéndolas automáticamente por cláusula residual", "En las materias que le sean transferidas o delegadas por el Estado", "Por acuerdo del Gobierno de Canarias, que las asume de forma provisional hasta su transferencia", "Mediante ley del Parlamento de Canarias aprobada por mayoría absoluta de la Cámara"]'::jsonb,1,'Art. 100.1 EACan','La Comunidad ejercerá las competencias no contempladas en el Estatuto en las materias que le sean transferidas o delegadas por el Estado.',null),
('aux-canarias:3-fa8de271d5','aux-canarias',3,'¿Qué debe tener en cuenta la normativa estatal según el artículo 101 del Estatuto de Canarias?','["La opinión vinculante del Parlamento de Canarias", "La previa conformidad del Gobierno de Canarias", "El informe previo de los cabildos insulares", "Las singularidades derivadas del carácter ultraperiférico de Canarias"]'::jsonb,3,'Art. 101 EACan','La normativa del Estado tendrá en cuenta las singularidades derivadas del carácter ultraperiférico de Canarias reconocidas por la Unión Europea.',null),
('aux-canarias:3-175e47c2c1','aux-canarias',3,'¿Qué carácter tiene la competencia de Canarias para establecer la organización y el régimen de funcionamiento de su Administración?','["Ejecutiva", "Exclusiva, sin perjuicio del artículo 149.1.18 de la Constitución", "Compartida con el Estado", "De desarrollo legislativo de las bases estatales"]'::jsonb,1,'Art. 104 EACan','Es competencia exclusiva, sin perjuicio del art. 149.1.18 CE, e incluye crear, modificar y suprimir órganos, unidades y entidades.',null),
('aux-canarias:3-4d71ef22ed','aux-canarias',3,'¿Qué circunstancias de Canarias deben tener en cuenta los poderes públicos al adaptar sus políticas, según el artículo 3 del Estatuto?','["La lejanía, la insularidad y la condición ultraperiférica", "La lengua, la cultura y la historia propias", "La densidad de población, el turismo y la escasez de recursos hídricos", "La riqueza de sus recursos naturales y la vocación atlántica de su economía"]'::jsonb,0,'Art. 3 EACan','Los poderes públicos tendrán en cuenta la lejanía, la insularidad y la condición ultraperiférica al adaptar sus políticas y decisiones.',null),
('aux-canarias:3-c8571c1448','aux-canarias',3,'¿Qué califica el Estatuto de Autonomía como norma institucional básica de Canarias?','["La Ley de Cabildos Insulares", "La Ley de Municipios de Canarias", "La Ley del Gobierno de Canarias", "El propio Estatuto de Autonomía"]'::jsonb,3,'Art. 2.1 EACan','Los poderes de la Comunidad emanan de la Constitución y del pueblo canario, en los términos del Estatuto, que es su norma institucional básica.',null),
('aux-canarias:3-e62f315e89','aux-canarias',3,'¿Qué órgano controla la constitucionalidad de las leyes del Parlamento de Canarias?','["La Audiencia de Cuentas de Canarias", "El Tribunal Superior de Justicia de Canarias", "El Tribunal Constitucional", "El Consejo Consultivo de Canarias"]'::jsonb,2,'Art. 47.2 EACan','El control de constitucionalidad de las leyes y normas con fuerza de ley de Canarias corresponde al Tribunal Constitucional.',null),
('aux-canarias:3-a408780120','aux-canarias',3,'¿Dónde deben publicarse las leyes del Parlamento de Canarias y en qué plazo?','["Solo en el BOE, en el plazo de un mes, sin necesidad de publicarla en el BOC", "En el BOC en 30 días, sin publicación en el BOE", "En el BOC en 15 días desde su promulgación, sin necesidad de publicarlas en el BOE", "En el BOC en 15 días desde su aprobación, y en el BOE"]'::jsonb,3,'Art. 47.1 EACan','Se publican en el BOC en 15 días desde su aprobación y en el BOE; la entrada en vigor se rige por la fecha del BOC.',null),
('aux-canarias:3-814e8cd20b','aux-canarias',3,'¿Dónde se publican, para su plena validez, las normas sin rango de ley de los órganos de la Comunidad Autónoma de Canarias?','["En el Boletín Oficial de Canarias", "En el Boletín Oficial del Estado", "En el boletín oficial del cabildo insular competente", "En el boletín de la provincia correspondiente"]'::jsonb,0,'Art. 63.2 EACan','Las normas sin rango de ley de los órganos de la Comunidad se publicarán, para su plena validez, en el BOC.',null),
('aux-canarias:4-2dd49332e4','aux-canarias',4,'Según el Estatuto de Autonomía de Canarias, ¿cómo ejerce Canarias el derecho al autogobierno?','["Como comunidad histórica foral", "Como nacionalidad", "Como región", "Como comunidad autónoma de régimen común sin la condición de nacionalidad"]'::jsonb,1,'Art. 1.1 EACan','Canarias ejerce el derecho al autogobierno como nacionalidad, constituyéndose en Comunidad Autónoma en el marco del Estado español.',null),
('aux-canarias:4-83bbd5eb7c','aux-canarias',4,'¿A través de qué órganos se ejercen los poderes de la Comunidad Autónoma de Canarias según su Estatuto?','["Del Parlamento, del Gobierno y de los cabildos insulares", "Del Parlamento, de la Presidencia y del Gobierno", "Del Parlamento, de la Presidencia, del Gobierno y de la Diputación del Común", "De la Presidencia, del Gobierno y del Consejo Consultivo"]'::jsonb,1,'Art. 2.2 EACan','Los poderes de la Comunidad Autónoma se ejercen a través del Parlamento, de la Presidencia y del Gobierno.',null),
('aux-canarias:4-4638c10a24','aux-canarias',4,'¿Qué carácter atribuye el Estatuto de Autonomía de Canarias a los cabildos insulares?','["Entidades locales sin carácter de institución autonómica", "Instituciones de la Comunidad Autónoma y órganos de gobierno de cada isla", "Corporaciones de derecho público con funciones delegadas por el Estado y por la Comunidad Autónoma", "Órganos desconcentrados del Gobierno de Canarias en cada una de las islas del archipiélago"]'::jsonb,1,'Art. 2.3 EACan','Los cabildos son, simultáneamente, instituciones de la Comunidad Autónoma y órganos de gobierno, administración y representación de cada isla.',null),
('aux-canarias:4-ebb4ff719a','aux-canarias',4,'¿Cuántas islas con administración propia integran el archipiélago canario según el Estatuto?','["Ocho", "Siete", "Nueve", "Seis"]'::jsonb,1,'Art. 4.1 EACan','Siete islas con administración propia: El Hierro, Fuerteventura, Gran Canaria, La Gomera, Lanzarote, La Palma y Tenerife, además de La Graciosa y los islotes.',null),
('aux-canarias:4-552080e1e8','aux-canarias',4,'¿Dónde tiene su sede el Parlamento de Canarias?','["En la isla cuya capital acoja la Presidencia durante la legislatura", "En Santa Cruz de Tenerife", "Alternativamente en ambas capitales por legislaturas", "En Las Palmas de Gran Canaria"]'::jsonb,1,'Art. 5.2 EACan','El Parlamento de Canarias tiene su sede en la ciudad de Santa Cruz de Tenerife.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-canarias:4-8450518b1e','aux-canarias',4,'¿Cómo se fija la sede de la Presidencia de Canarias?','["La fija cada Presidente al tomar posesión, mediante decreto publicado en el BOC", "Está siempre en Las Palmas de Gran Canaria", "Se fija por ley del Parlamento de Canarias aprobada por mayoría absoluta", "Alterna entre las dos capitales por periodos legislativos"]'::jsonb,3,'Art. 5.1 EACan','La sede de la Presidencia alterna entre Las Palmas de Gran Canaria y Santa Cruz de Tenerife por periodos legislativos; la Vicepresidencia se ubica en la otra capital.',null),
('aux-canarias:4-585abeb072','aux-canarias',4,'¿Quiénes gozan de la condición política de canarios?','["Los españoles que hayan residido al menos diez años en Canarias, aunque ya no tengan allí su vecindad", "Los españoles con vecindad administrativa en cualquier municipio de Canarias", "Los residentes en Canarias, sean o no españoles", "Los nacidos en Canarias, residan donde residan, y sus descendientes de primer grado"]'::jsonb,1,'Art. 6.1 EACan','Gozan de la condición política de canarios las personas con nacionalidad española que tengan vecindad administrativa en cualquier municipio de Canarias.',null),
('aux-canarias:4-45f1aab60e','aux-canarias',4,'¿Cuáles son los colores de la bandera de Canarias, a partir del asta?','["Blanco, amarillo y azul", "Blanco, azul y amarillo", "Amarillo, azul y blanco", "Azul, blanco y amarillo"]'::jsonb,1,'Art. 7.1 EACan','La bandera está formada por tres franjas verticales iguales: blanco, azul y amarillo, a partir del asta.',null),
('aux-canarias:4-9782a89059','aux-canarias',4,'¿Qué día celebra la Comunidad Autónoma de Canarias su festividad institucional?','["El 2 de febrero", "El 25 de julio", "El 12 de octubre", "El 30 de mayo"]'::jsonb,3,'Art. 7.4 EACan','La Comunidad Autónoma de Canarias celebra su festividad institucional el día 30 de mayo.',null),
('aux-canarias:4-9aec4d4731','aux-canarias',4,'¿Qué lema figura en el escudo de Canarias?','["Libertad", "Océano", "Atlántico", "Fortuna"]'::jsonb,1,'Art. 7.2 EACan','El escudo lleva como timbre una corona real con una cinta de plata con el lema Océano.',null),
('aux-canarias:4-6ef7cc0d94','aux-canarias',4,'¿Pueden los derechos del título I del Estatuto de Canarias crear títulos competenciales nuevos?','["Sí, cuando lo prevea una ley del Parlamento de Canarias", "Solo en materia de servicios sociales", "Sí, siempre que se trate de derechos sociales reconocidos expresamente en el Estatuto", "No, no alteran la distribución de competencias"]'::jsonb,3,'Art. 10.2 EACan','Los derechos, deberes y principios del título I no suponen alteración del régimen de competencias ni la creación de títulos competenciales nuevos.',null),
('aux-canarias:4-6c50e79a26','aux-canarias',4,'¿A quién puede dirigirse toda persona en defensa de sus derechos frente a lesiones imputables a las administraciones públicas de Canarias?','["A la Audiencia de Cuentas", "A la Diputación del Común", "Al Consejo Consultivo de Canarias", "Al Comisionado de Transparencia y Acceso a la Información Pública"]'::jsonb,1,'Art. 36.3 EACan','Sin perjuicio de las garantías constitucionales, toda persona puede dirigirse a la Diputación del Común en defensa de sus derechos.',null),
('aux-canarias:4-56ca5e067c','aux-canarias',4,'¿Qué derecho reconoce el Estatuto de Canarias a las personas en situación de exclusión social?','["El derecho a una vivienda gratuita", "El derecho a un empleo público adecuado a la formación de cada persona", "El derecho a una pensión no contributiva complementaria a cargo de los cabildos", "El derecho a acceder a una renta de ciudadanía"]'::jsonb,3,'Art. 24.1 EACan','Las personas en situación de exclusión social tienen derecho a acceder a una renta de ciudadanía en los términos que establezcan las leyes.',null),
('aux-canarias:4-516b2570e8','aux-canarias',4,'¿Cuál de estos derechos forma parte del derecho a una buena administración en el Estatuto de Canarias?','["La elección del funcionario que tramita el expediente", "La tramitación preferente de los asuntos presentados por vecinos de islas no capitalinas", "La gratuidad de todos los procedimientos administrativos", "La resolución de los asuntos en un plazo razonable"]'::jsonb,3,'Art. 32 c) EACan','El derecho a una buena administración incluye, entre otros, la resolución de los asuntos en un plazo razonable.',null),
('aux-canarias:4-60bb6be02e','aux-canarias',4,'¿Cómo define el Estatuto de Canarias el español de Canarias entre sus principios rectores?','["Como dialecto del español peninsular", "Como variedad lingüística del español atlántico", "Como modalidad lingüística protegida con rango de lengua propia de Canarias", "Como lengua cooficial de la Comunidad Autónoma"]'::jsonb,1,'Art. 37.7 EACan','Es principio rector la defensa, promoción y estudio del español de Canarias, como variedad lingüística del español atlántico.',null),
('aux-canarias:4-fa9bb6905b','aux-canarias',4,'¿A quién corresponde la iniciativa de la reforma del Estatuto de Autonomía de Canarias?','["Al Parlamento de Canarias a propuesta de la mayoría absoluta de sus diputados", "Al Gobierno o al Parlamento de Canarias a propuesta de al menos una quinta parte de sus diputados", "Al Gobierno de Canarias o a dos cabildos insulares", "A los cabildos insulares, actuando de forma conjunta, o a la quinta parte de los ayuntamientos canarios"]'::jsonb,1,'Art. 200.1 EACan','La iniciativa de reforma corresponde al Gobierno o al Parlamento de Canarias a propuesta de al menos una quinta parte de sus diputados.',null),
('aux-canarias:4-713d95168b','aux-canarias',4,'¿Qué mayoría del Parlamento de Canarias requiere la propuesta de reforma del Estatuto?','["Cuatro quintos de sus miembros", "Dos tercios de sus miembros", "Mayoría absoluta de sus miembros", "Tres quintos de sus miembros"]'::jsonb,3,'Art. 200.2 EACan','La propuesta requiere la aprobación del Parlamento por tres quintos, la de las Cortes mediante ley orgánica y referéndum de los electores.',null),
('aux-canarias:4-8b6e35bc5c','aux-canarias',4,'Aprobada la reforma del Estatuto por las Cortes, ¿en qué plazo puede el Gobierno de Canarias convocar el referéndum de ratificación?','["En el plazo de tres meses", "En el plazo de seis meses", "En el plazo de un mes", "En el plazo de dos meses"]'::jsonb,0,'Art. 200.4 EACan','La ley orgánica incluye la autorización del Estado para que el Gobierno de Canarias convoque el referéndum en el plazo de tres meses.',null),
('aux-canarias:4-f6044b5dc6','aux-canarias',4,'Si una propuesta de reforma del Estatuto de Canarias no es aprobada, ¿cuánto tiempo debe pasar para volver a debatirla en el Parlamento?','["Dos años", "Tres años", "Seis meses", "Un año"]'::jsonb,3,'Art. 200.5 EACan','No podrá someterse nuevamente a debate y votación del Parlamento hasta que haya transcurrido un año.',null),
('aux-canarias:4-b9399c764d','aux-canarias',4,'¿Cuándo puede seguirse el procedimiento abreviado de reforma del Estatuto de Canarias?','["Cuando la reforma afecte únicamente a la organización territorial de las islas", "Cuando la reforma afecte solo al capítulo II del título I", "Cuando la propuesta se apruebe por unanimidad", "Cuando la reforma afecte solo al título de competencias"]'::jsonb,1,'Art. 201 EACan','El procedimiento abreviado procede cuando la reforma afectare solo al capítulo II del título I del Estatuto.',null),
('aux-canarias:4-6a4c99e482','aux-canarias',4,'En el procedimiento abreviado de reforma del Estatuto de Canarias, ¿de qué plazo disponen las Cortes para declararse afectadas?','["Dos meses", "Quince días", "Tres meses", "Treinta días"]'::jsonb,3,'Art. 201 c) EACan','Si en treinta días desde la recepción de la consulta las Cortes no se declaran afectadas, la reforma se ratifica mediante ley orgánica.',null),
('aux-canarias:4-fc63264ad4','aux-canarias',4,'¿Qué trámite exige el Estatuto cuando la reforma altera la organización de los poderes de Canarias que afecta directamente a las islas?','["La aprobación de cada cabildo por mayoría absoluta", "La audiencia previa de los cabildos insulares", "El informe vinculante de la Conferencia de Presidentes", "El dictamen previo del Consejo de Estado"]'::jsonb,1,'Art. 202 EACan','Se requiere la audiencia previa de los cabildos insulares.',null),
('aux-canarias:5-ac67f81fb7','aux-canarias',5,'¿Cuál es la duración del mandato del Parlamento de Canarias?','["Cinco años", "Cuatro años", "Cinco años, salvo disolución anticipada", "Tres años"]'::jsonb,1,'Art. 38.3 EACan','La duración del mandato es de cuatro años, sin perjuicio de los supuestos de disolución anticipada.',null),
('aux-canarias:5-94b9b9ee82','aux-canarias',5,'¿Entre qué cifras debe estar el número de diputados del Parlamento de Canarias según el Estatuto?','["Entre sesenta y setenta", "Entre setenta y noventa", "Entre cincuenta y setenta y cinco", "Entre cuarenta y sesenta"]'::jsonb,2,'Art. 39.2 b) EACan','El número de diputados no será inferior a cincuenta ni superior a setenta y cinco.',null),
('aux-canarias:5-80d296b517','aux-canarias',5,'¿Qué mayoría exige el Estatuto para la ley electoral de Canarias?','["Cuatro quintos del Parlamento", "Dos tercios del Parlamento", "Mayoría absoluta del Parlamento", "Tres quintos del Parlamento"]'::jsonb,3,'Art. 39.2 EACan','La ley que regula el régimen electoral se aprueba por mayoría de tres quintos, a iniciativa de los miembros del Parlamento.',null),
('aux-canarias:5-288142a10e','aux-canarias',5,'¿Qué ámbito pueden tener las circunscripciones electorales para el Parlamento de Canarias?','["Provincial e insular", "Solo insular", "Autonómico, insular o ambos", "Autonómico, provincial o insular"]'::jsonb,2,'Art. 39.2 c) EACan','Las circunscripciones pueden ser de ámbito autonómico, insular o de ambas; cada isla con administración propia es una circunscripción.',null),
('aux-canarias:5-db048a0883','aux-canarias',5,'¿Cómo está compuesta la Mesa del Parlamento de Canarias?','["Una presidencia, dos vicepresidencias y dos secretarías", "Una presidencia, una vicepresidencia y tres secretarías", "Una presidencia, dos vicepresidencias y cuatro secretarías", "Una presidencia, tres vicepresidencias y una secretaría"]'::jsonb,0,'Art. 41.1 EACan','La Mesa está formada por una presidencia, dos vicepresidencias y dos secretarías.',null),
('aux-canarias:5-60714200a3','aux-canarias',5,'¿Por qué mayoría debe aprobarse el Reglamento del Parlamento de Canarias?','["Mayoría simple de los presentes", "Mayoría absoluta de sus miembros", "Dos tercios de sus miembros", "Tres quintos de sus miembros"]'::jsonb,1,'Art. 41.4 EACan','El Reglamento del Parlamento debe ser aprobado por mayoría absoluta de sus miembros.',null),
('aux-canarias:5-a9664c701c','aux-canarias',5,'¿A través de qué órgano participan los cabildos insulares en el Parlamento de Canarias?','["La Comisión de Asuntos Insulares del Gobierno", "La Conferencia de Presidentes", "El Consejo Municipal de Canarias", "La Comisión General de Cabildos Insulares"]'::jsonb,3,'Art. 41.5 EACan','Los cabildos participan a través de la Comisión General de Cabildos Insulares, cuyo informe es preceptivo en asuntos que les afecten.',null),
('aux-canarias:5-6be079453e','aux-canarias',5,'¿Qué ocurre si dos tercios de los diputados de una circunscripción insular se oponen motivadamente a un acuerdo por considerarlo perjudicial para la isla?','["Se somete a votación en la Comisión General de Cabildos", "El acuerdo queda rechazado definitivamente", "El asunto se pospone a la sesión plenaria siguiente", "Debe dictaminar el Consejo Consultivo"]'::jsonb,2,'Art. 41.6 EACan','Si al menos dos tercios de los diputados de una misma isla se oponen motivadamente, el asunto se pospone a la sesión plenaria siguiente.',null),
('aux-canarias:5-f640ff614b','aux-canarias',5,'¿Quién puede pedir la convocatoria de sesiones extraordinarias del Parlamento de Canarias fuera de los periodos de sesiones?','["La mayoría absoluta de los diputados o tres cabildos", "La Diputación Permanente, una cuarta parte de los diputados, dos grupos o el Gobierno", "Una décima parte de los diputados, un grupo parlamentario o cualquier cabildo insular", "Solo el Presidente de Canarias"]'::jsonb,1,'Art. 41.7 EACan','Las convoca la presidencia del Parlamento a petición de la Diputación Permanente, una cuarta parte de los diputados, dos grupos parlamentarios o el Gobierno.',null),
('aux-canarias:5-75309e871f','aux-canarias',5,'¿Corresponde a los cabildos insulares la iniciativa legislativa ante el Parlamento de Canarias?','["Sí, a cada uno de ellos", "Solo si actúan agrupados al menos tres cabildos", "No, solo al Gobierno y a los diputados", "Solo cuando la iniciativa sea conjunta de todos los cabildos"]'::jsonb,0,'Art. 44.2 EACan','La iniciativa legislativa corresponde también a cada uno de los cabildos insulares, en los términos del Reglamento del Parlamento.',null),
('aux-canarias:5-5f78aa1618','aux-canarias',5,'¿Qué leyes no puede delegar el Parlamento de Canarias en el Gobierno?','["Las que regulen materias de competencia exclusiva de la Comunidad Autónoma", "Las que regulen tributos propios", "Las del presupuesto y las de instituciones o que requieran mayoría cualificada", "Las de organización administrativa"]'::jsonb,2,'Art. 45.1 EACan','No cabe delegación legislativa en las leyes del presupuesto ni en las de instituciones autonómicas o que requieran mayoría cualificada.',null),
('aux-canarias:5-928008678e','aux-canarias',5,'¿En qué plazo deben convalidarse por el Parlamento de Canarias los decretos-leyes?','["Quince días naturales desde su publicación", "Treinta días naturales desde su publicación", "Treinta días hábiles desde su aprobación", "Un mes desde su aprobación por el Gobierno"]'::jsonb,1,'Art. 46.3 EACan','Los decretos-leyes deben convalidarse en el plazo de treinta días naturales contados desde su publicación.',null),
('aux-canarias:5-840423da49','aux-canarias',5,'En la investidura del Presidente de Canarias, si no se obtiene mayoría absoluta en primera votación, ¿qué ocurre?','["Se vota de nuevo pasadas 48 horas y basta la mayoría simple", "Se vota al día siguiente y se exige de nuevo mayoría absoluta", "Se repite la votación en el plazo de siete días exigiendo mayoría absoluta", "Queda disuelto el Parlamento"]'::jsonb,0,'Art. 48.3 EACan','Pasadas 48 horas se procede a una nueva votación y la confianza se entiende otorgada por mayoría simple.',null),
('aux-canarias:5-a6614772e6','aux-canarias',5,'¿Cuándo queda automáticamente disuelto el Parlamento de Canarias por falta de investidura?','["Tras tres votaciones fallidas", "Si tras cuatro votaciones ningún candidato obtiene la mayoría absoluta", "Si en un mes desde la constitución del Parlamento no hay Presidente", "Si en dos meses desde la primera votación ningún candidato obtiene la confianza"]'::jsonb,3,'Art. 48.4 EACan','Si transcurridos dos meses desde la primera votación de investidura ninguna candidatura obtiene la confianza, el Parlamento queda disuelto.',null),
('aux-canarias:5-434b688980','aux-canarias',5,'¿Quién nombra al Presidente de Canarias una vez elegido por el Parlamento?','["El Presidente del Parlamento de Canarias", "El Presidente del Tribunal Superior de Justicia de Canarias", "El Rey", "El Presidente del Gobierno de España"]'::jsonb,2,'Art. 48.5 EACan','Una vez elegida, la persona titular de la Presidencia es nombrada por el Rey.',null),
('aux-canarias:5-ff40c26ded','aux-canarias',5,'¿Qué requisito debe cumplir la persona titular de la Vicepresidencia de Canarias?','["Residir en la capital donde no esté la Presidencia", "Haber nacido en una isla distinta a la de la persona titular de la Presidencia", "Haber sido consejero en la legislatura anterior", "Ser miembro del Parlamento de Canarias"]'::jsonb,3,'Art. 49.5 EACan','La persona titular de la Vicepresidencia habrá de ser miembro del Parlamento y sustituye a la Presidencia en caso de vacancia, ausencia o enfermedad.',null),
('aux-canarias:5-8baca74338','aux-canarias',5,'¿Cómo responde el Gobierno de Canarias de su gestión política ante el Parlamento?','["Solo a través del Presidente", "Solidariamente", "Individualmente cada consejero", "Mancomunadamente con los cabildos insulares"]'::jsonb,1,'Art. 53 EACan','El Gobierno responde solidariamente de su gestión política ante el Parlamento; no puede exigirse responsabilidad política individual a sus miembros.',null),
('aux-canarias:5-a32b0e0070','aux-canarias',5,'¿Qué mayoría se exige para que el Parlamento de Canarias apruebe una moción de censura?','["Mayoría absoluta", "Dos tercios", "Mayoría simple", "Tres quintos"]'::jsonb,0,'Art. 55 EACan','La moción de censura se adopta por mayoría absoluta y debe incluir un candidato a la Presidencia.',null),
('aux-canarias:5-9460f9a9de','aux-canarias',5,'¿Qué porcentaje mínimo de diputados debe presentar una moción de censura en el Parlamento de Canarias?','["El veinticinco por ciento", "El diez por ciento", "El quince por ciento", "El veinte por ciento"]'::jsonb,2,'Art. 55 EACan','Toda moción de censura debe ser presentada, al menos, por el quince por ciento de los miembros del Parlamento.',null),
('aux-canarias:5-918b335a62','aux-canarias',5,'¿Con qué mayoría se entiende otorgada la cuestión de confianza en el Parlamento de Canarias?','["Mayoría absoluta de los miembros", "Tres quintos de los votos emitidos", "Mayoría absoluta de los votos emitidos", "Mayoría simple de los votos emitidos"]'::jsonb,3,'Art. 54 EACan','La confianza se entiende otorgada cuando el presidente obtiene la mayoría simple de los votos emitidos.',null),
('aux-canarias:5-aa62286fcc','aux-canarias',5,'¿Cuándo no puede el Presidente de Canarias disolver anticipadamente el Parlamento?','["Con una moción de censura presentada o durante el primer año de legislatura", "Mientras se tramiten los presupuestos generales de la comunidad autónoma en el Parlamento", "Durante el último año de legislatura o mientras se tramite una cuestión de confianza", "Durante los dos últimos años de legislatura"]'::jsonb,0,'Art. 56.2 EACan','La disolución no puede decretarse cuando se haya presentado una moción de censura ni durante el primer año de legislatura.',null),
('aux-canarias:5-69cc0dadf3','aux-canarias',5,'Tras su cese, ¿en qué plazo máximo debe tomar posesión el nuevo Gobierno de Canarias?','["Diez días desde la investidura", "Quince días desde el nombramiento del Presidente", "Un mes desde las elecciones", "Un mes desde el nombramiento del Presidente"]'::jsonb,1,'Art. 52.2 EACan','El Gobierno cesante continúa en funciones hasta la toma de posesión del nuevo, en el plazo máximo de quince días desde el nombramiento del Presidente.',null),
('aux-canarias:5-12b8b15d38','aux-canarias',5,'¿Por qué mayoría se elige a la persona titular de la Diputación del Común y para cuánto tiempo?','["Tres quintos del Parlamento, para cinco años", "Mayoría absoluta, para cuatro años", "Mayoría absoluta, para cinco años", "Dos tercios, para seis años"]'::jsonb,0,'Art. 57.3 EACan','Es elegida por tres quintas partes del Parlamento para un mandato de cinco años.',null),
('aux-canarias:5-8db769b46e','aux-canarias',5,'¿Qué es el Consejo Consultivo de Canarias?','["El órgano de asesoramiento jurídico del Parlamento", "El órgano de participación de los cabildos", "El órgano de fiscalización externa de las cuentas", "El supremo órgano consultivo de la Comunidad Autónoma"]'::jsonb,3,'Art. 58.1 EACan','Es el supremo órgano consultivo de la Comunidad, encargado de dictaminar sobre la adecuación a la Constitución y al Estatuto.',null),
('aux-canarias:5-fbe29e2cac','aux-canarias',5,'¿Qué órgano realiza la fiscalización externa de la gestión económica del sector público de Canarias?','["El Consejo Consultivo", "La Intervención General", "La Audiencia de Cuentas", "El Comisionado de Transparencia"]'::jsonb,2,'Art. 59.1 EACan','La Audiencia de Cuentas, dependiente del Parlamento, realiza la fiscalización externa, sin perjuicio de las competencias del Tribunal de Cuentas.',null),
('aux-canarias:5-15e69f9725','aux-canarias',5,'¿Por qué mayoría se elige al Comisionado de Transparencia y Acceso a la Información Pública de Canarias?','["Mayoría absoluta del Parlamento", "Tres quintas partes del Parlamento", "Mayoría simple del Parlamento", "Por el Gobierno, oído el Parlamento"]'::jsonb,1,'Art. 60.3 EACan','El Comisionado de Transparencia es elegido por mayoría de tres quintas partes del Parlamento.',null),
('aux-canarias:5-0a9ac4155c','aux-canarias',5,'¿Cuál de estas funciones corresponde al Parlamento de Canarias?','["Aprobar los reglamentos ejecutivos de las leyes aprobadas por el Parlamento de Canarias", "Ejercer el derecho de gracia respecto de los condenados por tribunales canarios", "Nombrar al Presidente del Tribunal Superior de Justicia", "Designar a los senadores representantes de la Comunidad Autónoma"]'::jsonb,3,'Art. 43 d) EACan','Entre las funciones del Parlamento está designar, para cada legislatura, a los senadores representantes de la Comunidad Autónoma.',null),
('aux-canarias:5-7f7cfacb8e','aux-canarias',5,'¿Quién compone el Gobierno de Canarias?','["La Presidencia, la Vicepresidencia y los consejeros", "La Presidencia y los presidentes de los cabildos", "La Presidencia, los consejeros y los viceconsejeros", "La Presidencia, la Vicepresidencia, los consejeros y los presidentes de los cabildos"]'::jsonb,0,'Art. 51.1 EACan','El Gobierno está compuesto por las personas titulares de la Presidencia y de la Vicepresidencia y por los consejeros o consejeras.',null),
('aux-canarias:6-e8ed456c73','aux-canarias',6,'¿Qué norma regula actualmente la Presidencia y el Gobierno de Canarias?','["La Ley 1/1983, de 14 de abril", "La Ley 4/2023, de 23 de marzo", "El Decreto 212/1991, de 11 de septiembre", "La Ley 14/1990, de 26 de julio"]'::jsonb,1,'Art. 1 Ley 4/2023 Canarias','La Ley 4/2023, de 23 de marzo, de la Presidencia y del Gobierno de Canarias, derogó la Ley 1/1983 con efectos desde el 4 de abril de 2023.',null),
('aux-canarias:6-bdd3629a3d','aux-canarias',6,'¿Qué requisito exige la Ley 4/2023 para ser presidente o presidenta de Canarias?','["Ser diputado o diputada del Parlamento de Canarias", "Haber nacido en Canarias y residir en el archipiélago al menos cinco años", "Haber sido miembro del Gobierno en una legislatura anterior", "Tener al menos cinco años de vecindad en Canarias"]'::jsonb,0,'Art. 3 Ley 4/2023 Canarias','Para ser presidente o presidenta de Canarias se requiere tener la condición de diputado o diputada del Parlamento de Canarias.',null),
('aux-canarias:6-2a38e1a84c','aux-canarias',6,'¿Qué es el Gobierno de Canarias según la Ley 4/2023?','["El órgano supremo consultivo de la comunidad autónoma", "El órgano de coordinación de los cabildos insulares y de los ayuntamientos del archipiélago con el Estado", "El órgano superior colegiado de dirección política de la comunidad autónoma y de su administración", "El órgano unipersonal que ostenta la más alta representación de la comunidad autónoma y la ordinaria del Estado"]'::jsonb,2,'Art. 20 Ley 4/2023 Canarias','El Gobierno es el órgano superior colegiado de dirección política de la comunidad y de su administración.',null),
('aux-canarias:6-29a9ecdf4e','aux-canarias',6,'¿Dónde tiene su sede el Gobierno de Canarias?','["En la capital donde resida la Presidencia en cada legislatura", "En Santa Cruz de Tenerife", "En Las Palmas de Gran Canaria", "Compartida entre las dos capitales de Canarias"]'::jsonb,3,'Art. 22 Ley 4/2023 Canarias','La sede del Gobierno y de sus comisiones delegadas es compartida entre las dos capitales, aunque puede reunirse en cualquier localidad.',null),
('aux-canarias:6-8920433371','aux-canarias',6,'¿Cómo funciona el Gobierno de Canarias según la Ley 4/2023?','["En Consejo de Gobierno y en la Conferencia de Consejeros y Viceconsejeros", "En Consejo de Gobierno y en comisiones delegadas del Gobierno", "Exclusivamente en Consejo de Gobierno", "En Pleno y en Comisión Permanente, presidida por el vicepresidente del Gobierno"]'::jsonb,1,'Art. 23 Ley 4/2023 Canarias','El Gobierno de Canarias funciona en Consejo de Gobierno y en comisiones delegadas del Gobierno.',null),
('aux-canarias:6-d1a2547d25','aux-canarias',6,'¿Qué límite establece la Ley 4/2023 para garantizar la presencia equilibrada de mujeres y hombres en el Gobierno de Canarias?','["Ningún sexo puede superar el 60 % ni bajar del 40 %", "Ningún sexo puede superar el 55 % ni bajar del 45 %", "Al menos un tercio de los consejeros deben ser mujeres", "Debe haber igual número de consejeras y consejeros"]'::jsonb,0,'Art. 24.2 Ley 4/2023 Canarias','El número de personas de cada sexo no puede superar el 60 % ni ser inferior al 40 % del total del órgano.',null),
('aux-canarias:6-1c4608fc62','aux-canarias',6,'¿Quién ejerce la Secretaría del Gobierno de Canarias?','["El consejero o consejera de menor edad del Gobierno", "El vicepresidente o vicepresidenta del Gobierno", "El consejero o consejera que designe el presidente o presidenta", "Un funcionario de carrera del subgrupo A1 nombrado por el Consejo"]'::jsonb,2,'Art. 25.1 Ley 4/2023 Canarias','La Secretaría del Gobierno la ejerce el consejero o consejera que designe el presidente; en su defecto la suple el de menor edad.',null),
('aux-canarias:6-a07d91e128','aux-canarias',6,'¿Qué quórum exige la Ley 4/2023 para la válida constitución del Consejo de Gobierno de Canarias?','["Todos sus miembros", "La mayoría de sus miembros, entre ellos el presidente o quien le supla", "Dos tercios de sus miembros, con presencia del vicepresidente", "La mitad de sus miembros, sin necesidad de la presencia del presidente"]'::jsonb,1,'Art. 34 Ley 4/2023 Canarias','Es necesaria la asistencia de la mayoría de sus miembros, entre los que estará el presidente o presidenta o quien le supla.',null),
('aux-canarias:6-3299ce6b5f','aux-canarias',6,'¿Cómo se adoptan las decisiones del Consejo de Gobierno de Canarias?','["Como expresión unitaria de su voluntad, sin votación formal", "Por unanimidad de los presentes, que se hace constar expresamente en el acta", "Por mayoría absoluta de sus miembros", "Por mayoría simple de los presentes, con voto dirimente del presidente"]'::jsonb,0,'Art. 37.1 Ley 4/2023 Canarias','Las decisiones constituyen la expresión unitaria de la voluntad del Consejo, obligan a todos sus miembros y no están sujetas a votación formal.',null),
('aux-canarias:6-80e6c492aa','aux-canarias',6,'¿Qué forma revisten las decisiones del Consejo de Gobierno de Canarias que aprueban disposiciones generales?','["La de orden", "La de acuerdo", "La de resolución", "La de decreto"]'::jsonb,3,'Art. 37.2 Ley 4/2023 Canarias','Revisten la forma de decreto cuando aprueban disposiciones generales; en otro caso, la de acuerdo.',null),
('aux-canarias:6-cabb718b7a','aux-canarias',6,'¿Qué carácter tienen las deliberaciones del Consejo de Gobierno de Canarias?','["Secreto únicamente en materia presupuestaria", "Reservado solo hasta el final de la legislatura", "Público, salvo acuerdo en contrario", "Reservado y secreto, también después del cese de sus miembros"]'::jsonb,3,'Art. 36.1 Ley 4/2023 Canarias','Las deliberaciones son reservadas y secretas y sus miembros deben mantener ese carácter aun después de cesar.',null),
('aux-canarias:6-f20cd2ba37','aux-canarias',6,'¿Quién firma las actas del Consejo de Gobierno de Canarias?','["El presidente o presidenta", "Todos los consejeros asistentes", "Quien desempeñe la Secretaría del Gobierno", "El vicepresidente o vicepresidenta"]'::jsonb,2,'Art. 38.2 Ley 4/2023 Canarias','Las actas son firmadas por quien desempeñe la Secretaría del Gobierno.',null),
('aux-canarias:6-b7d361d119','aux-canarias',6,'¿Puede reunirse el Consejo de Gobierno de Canarias sin convocatoria previa ni orden del día?','["Sí, si lo solicita al menos la mitad de los consejeros con un día de antelación", "Sí, si lo decide el presidente y están presentes todos sus integrantes", "No, en ningún caso, porque la convocatoria y el orden del día son siempre obligatorios", "Solo en periodo de Gobierno en funciones"]'::jsonb,1,'Art. 33.4 Ley 4/2023 Canarias','Puede reunirse sin convocatoria ni orden del día cuando lo decida el presidente y se hallen presentes todos los integrantes.',null),
('aux-canarias:6-d4aa5c5f64','aux-canarias',6,'¿A quién corresponde determinar el número, la denominación y las competencias de las consejerías del Gobierno de Canarias?','["Al presidente o presidenta", "Al Consejo de Gobierno a propuesta de la Vicepresidencia", "A la Comisión Preparatoria de Asuntos del Gobierno", "Al Parlamento de Canarias mediante ley"]'::jsonb,0,'Art. 13 i) Ley 4/2023 Canarias','Corresponde al presidente determinar el número, denominación, competencias y orden de precedencia de las consejerías.',null),
('aux-canarias:6-a9b9ede6c9','aux-canarias',6,'¿Quién resuelve los conflictos de atribuciones entre las consejerías del Gobierno de Canarias?','["La Secretaría del Gobierno", "El Consejo Consultivo de Canarias", "El presidente o presidenta", "El vicepresidente o vicepresidenta"]'::jsonb,2,'Art. 13 r) Ley 4/2023 Canarias','Corresponde al presidente coordinar la actividad de las consejerías y resolver los conflictos de atribuciones entre ellas.',null),
('aux-canarias:6-aed1d27c7f','aux-canarias',6,'¿Cómo se nombra y cesa a los consejeros y consejeras del Gobierno de Canarias?','["Por real decreto", "Por resolución del Parlamento a propuesta del presidente", "Por acuerdo del Consejo de Gobierno", "Por decreto del presidente o presidenta"]'::jsonb,3,'Art. 56.1 Ley 4/2023 Canarias','El nombramiento y cese de los consejeros se realiza por el presidente o presidenta mediante decreto.',null),
('aux-canarias:6-ddb5c958fc','aux-canarias',6,'¿En qué plazo deben tomar posesión los consejeros tras la publicación de su nombramiento en el BOC?','["Dentro de los cinco días naturales siguientes", "Dentro de los diez días hábiles siguientes", "En el mismo día de la publicación del decreto de nombramiento en el BOC", "Dentro de los quince días naturales siguientes"]'::jsonb,0,'Art. 56.2 Ley 4/2023 Canarias','La toma de posesión debe producirse dentro de los cinco días naturales siguientes a la publicación del nombramiento.',null),
('aux-canarias:6-b7b34b30db','aux-canarias',6,'¿Qué condición se exige para ser consejero o consejera del Gobierno de Canarias?','["Ser diputado del Parlamento de Canarias", "Tener la condición política de canario", "Haber residido diez años en Canarias", "Ser funcionario de carrera"]'::jsonb,1,'Art. 55.2 Ley 4/2023 Canarias','Se requiere tener la condición política de canario, los derechos de sufragio y no estar inhabilitado ni sancionado para ser cargo público.',null),
('aux-canarias:6-b10454e471','aux-canarias',6,'¿Qué forma adoptan las disposiciones generales de los consejeros y consejeras de Canarias?','["Orden", "Resolución", "Instrucción", "Decreto"]'::jsonb,0,'Art. 77.1 d) Ley 4/2023 Canarias','Las disposiciones generales del vicepresidente y de los consejeros adoptan la forma de orden; si afectan a varios departamentos, orden conjunta.',null),
('aux-canarias:6-4e9fceb7da','aux-canarias',6,'¿Qué forma revisten las disposiciones generales acordadas por las comisiones delegadas del Gobierno de Canarias?','["Acuerdos de Comisión", "Órdenes conjuntas", "Decretos de Comisión Delegada", "Resoluciones"]'::jsonb,2,'Art. 77.1 b) Ley 4/2023 Canarias','Las disposiciones generales acordadas por las comisiones delegadas adoptan la forma de decretos de Comisión Delegada.',null),
('aux-canarias:6-cff84f7116','aux-canarias',6,'¿Qué exige la entrada en vigor de las disposiciones reglamentarias del Gobierno de Canarias?','["Su publicación en extracto en el BOC", "Su íntegra publicación en el Boletín Oficial de Canarias", "Su comunicación al Parlamento de Canarias", "Su publicación en el BOE"]'::jsonb,1,'Art. 79 Ley 4/2023 Canarias','La entrada en vigor de las disposiciones reglamentarias exige su íntegra publicación en el BOC.',null),
('aux-canarias:6-468ece5fff','aux-canarias',6,'¿Dónde se ubica la sede de la Vicepresidencia del Gobierno de Canarias?','["En la misma capital que la Presidencia", "En la capital que elija el vicepresidente", "En Santa Cruz de Tenerife", "En capital distinta a la de la Presidencia"]'::jsonb,3,'Art. 51 Ley 4/2023 Canarias','La sede de la Vicepresidencia se ubica en capital distinta a la de la Presidencia.',null),
('aux-canarias:6-163f8e5a55','aux-canarias',6,'¿Puede el vicepresidente o vicepresidenta de Canarias ser titular de una consejería?','["Solo con autorización del Parlamento", "Solo de la consejería de Presidencia", "Sí, cuando así lo disponga el presidente o presidenta", "No, es incompatible con la titularidad de una consejería"]'::jsonb,2,'Art. 49.1 Ley 4/2023 Canarias','El vicepresidente es miembro del Gobierno y puede ostentar la titularidad de una consejería cuando así lo disponga el presidente.',null),
('aux-canarias:6-d006d39b3f','aux-canarias',6,'¿Quién sustituye al presidente o presidenta de Canarias en caso de fallecimiento?','["El consejero o consejera de mayor edad", "El consejero que designe el Consejo de Gobierno", "El presidente o presidenta del Parlamento de Canarias, de forma interina hasta la nueva investidura", "El vicepresidente o vicepresidenta y, en su defecto, el consejero que corresponda por orden de precedencia"]'::jsonb,3,'Art. 16.1 Ley 4/2023 Canarias','Le sustituye el vicepresidente y, en su defecto, el consejero que corresponda según el orden de precedencia.',null),
('aux-canarias:6-47c18e4347','aux-canarias',6,'¿Qué mayoría parlamentaria debe reconocer la notoria incapacidad permanente del presidente o presidenta de Canarias como causa de cese?','["Mayoría de tres quintos", "Mayoría absoluta", "Mayoría simple", "Mayoría de dos tercios"]'::jsonb,1,'Art. 15.2 Ley 4/2023 Canarias','La notoria incapacidad debe ser reconocida por el Parlamento de Canarias por mayoría absoluta.',null),
('aux-canarias:6-e56819812f','aux-canarias',6,'¿Cuántas comisiones delegadas puede constituir el Gobierno de Canarias y con qué carácter?','["Las que decida, de carácter permanente o temporal", "Solo una, de carácter permanente", "Las que autorice el Parlamento", "Hasta tres, siempre temporales"]'::jsonb,0,'Art. 40 Ley 4/2023 Canarias','El Gobierno puede constituir comisiones delegadas, de carácter permanente o temporal, para las funciones que se les atribuyan o deleguen.',null),
('aux-canarias:6-92276f88a8','aux-canarias',6,'¿Quién puede crear la Portavocía del Gobierno de Canarias?','["El Parlamento de Canarias", "El Consejo de Gobierno", "El presidente o presidenta", "La Secretaría del Gobierno"]'::jsonb,2,'Art. 46.1 Ley 4/2023 Canarias','El presidente o presidenta podrá crear la Portavocía del Gobierno, cuyo titular asiste a las reuniones con obligación de secreto.',null),
('aux-canarias:7-7b5d0a60eb','aux-canarias',7,'¿Cuáles son los órganos necesarios de los cabildos insulares según el Estatuto de Canarias?','["El pleno, la presidencia, la junta de portavoces y la comisión de reglamento", "El pleno, la presidencia, el consejo de gobierno y la comisión especial de cuentas", "El pleno, la presidencia, las vicepresidencias y el consejo de gobierno", "La presidencia, el consejo de gobierno y la comisión de cuentas"]'::jsonb,2,'Art. 67.2 EACan','Son órganos necesarios de los cabildos el pleno, la presidencia, las vicepresidencias y el consejo de gobierno.',null),
('aux-canarias:7-32b2de7c8e','aux-canarias',7,'¿Qué mayoría exige el Estatuto para la ley que regula la organización de los cabildos insulares?','["Mayoría simple", "Mayoría absoluta", "Dos tercios", "Tres quintos"]'::jsonb,1,'Art. 67.1 EACan','Una ley del Parlamento aprobada por mayoría absoluta regula la organización de los cabildos insulares.',null),
('aux-canarias:7-9af362f100','aux-canarias',7,'¿Cuál es la duración del mandato de los miembros de los plenos de los cabildos insulares?','["Seis años", "Cuatro años", "Tres años", "Cinco años"]'::jsonb,1,'Art. 68.2 EACan','La duración del mandato de los plenos de los cabildos es de cuatro años.',null),
('aux-canarias:7-175f13908a','aux-canarias',7,'¿Dónde está fijada la capital de la isla de Fuerteventura?','["En Antigua", "En Valverde", "En Puerto del Rosario", "En Arrecife"]'::jsonb,2,'Art. 66 EACan','La capital de cada isla está en la sede del cabildo: Fuerteventura en Puerto del Rosario, Lanzarote en Arrecife y El Hierro en Valverde.',null),
('aux-canarias:7-ae3d6d483a','aux-canarias',7,'¿A qué isla está agregada administrativamente La Graciosa?','["A Fuerteventura", "A Gran Canaria", "A Tenerife", "A Lanzarote"]'::jsonb,3,'Art. 65.1 EACan','La Graciosa está agregada administrativamente a Lanzarote, igual que Alegranza, Montaña Clara y los Roques; Lobos, a Fuerteventura.',null),
('aux-canarias:7-b3ca3c55b2','aux-canarias',7,'¿Qué es la Conferencia de Presidentes según el Estatuto de Canarias?','["Un foro de colaboración del Gobierno de Canarias y los cabildos insulares", "Una comisión del Parlamento con los presidentes de los grupos", "El órgano consultivo del Parlamento integrado por los presidentes de los cabildos y los alcaldes de las capitales", "El órgano de coordinación de los alcaldes canarios con la Federación Canaria de Municipios"]'::jsonb,0,'Art. 74.1 EACan','Es un foro institucional de colaboración del Gobierno de Canarias y los cabildos, integrado por los presidentes de Canarias y de las islas.',null),
('aux-canarias:7-0667e8a315','aux-canarias',7,'¿Qué órgano canaliza el parecer de los ayuntamientos en las iniciativas legislativas que afectan a su organización y competencias?','["La Federación Canaria de Municipios", "La Comisión Bilateral de Cooperación", "La Comisión General de Cabildos Insulares", "El Consejo Municipal de Canarias"]'::jsonb,3,'Art. 76 EACan','El Consejo Municipal de Canarias es el órgano de participación y colaboración de la Administración autonómica y los ayuntamientos.',null),
('aux-canarias:7-f5d66eabee','aux-canarias',7,'¿Quién coordina la actividad de los cabildos insulares cuando afecte directamente al interés general de Canarias?','["La Conferencia de Presidentes", "El Gobierno de Canarias", "El Parlamento de Canarias", "La Diputación del Común"]'::jsonb,1,'Art. 73 EACan','El Gobierno de Canarias coordina la actividad de los cabildos en cuanto afecte directamente al interés general de la Comunidad.',null),
('aux-canarias:7-e28c4c566c','aux-canarias',7,'¿Cuál de estos principios debe tenerse en cuenta al atribuir competencias a islas y municipios según el Estatuto?','["No duplicidad de competencias", "Jerarquía insular", "Uniformidad territorial", "Igualdad de servicios en todas las islas"]'::jsonb,0,'Art. 64.2 f) EACan','Los principios son garantía de autonomía local, equidad, eficacia, eficiencia, máxima proximidad, no duplicidad y estabilidad presupuestaria.',null),
('aux-canarias:7-5a3612f892','aux-canarias',7,'¿Qué carácter tienen los municipios según el Estatuto de Canarias?','["Órganos periféricos de la Comunidad Autónoma", "Agrupaciones de islas sin autonomía propia", "Entidades locales básicas con personalidad jurídica propia", "Entidades instrumentales de los cabildos"]'::jsonb,2,'Art. 75.1 EACan','Los municipios son las entidades locales básicas de Canarias, con personalidad jurídica propia y autonomía plena.',null),
('aux-canarias:7-d2d0de728e','aux-canarias',7,'¿Cuál de estas materias es una competencia ejecutiva insular de los cabildos según el Estatuto?','["Turismo", "Administración de Justicia", "Universidades", "Policía autonómica"]'::jsonb,0,'Art. 70.2 f) EACan','Entre las funciones ejecutivas insulares figuran el turismo, la ordenación del territorio, las carreteras o la asistencia social.',null),
('aux-canarias:7-363ecc0856','aux-canarias',7,'Según la Ley 8/2015 de Cabildos Insulares, ¿qué son los cabildos insulares?','["Entidades locales de segundo grado formadas por la agrupación obligatoria de los municipios de cada isla", "Mancomunidades obligatorias de los municipios de cada isla", "Órganos periféricos de la Administración autonómica en cada isla", "Instituciones de la Comunidad Autónoma y órganos de gobierno, administración y representación de cada isla"]'::jsonb,3,'Art. 2 Ley 8/2015 Canarias','Los cabildos son instituciones de la Comunidad Autónoma y órganos de gobierno, administración y representación de cada una de las siete islas.',null),
('aux-canarias:7-faa0347410','aux-canarias',7,'¿Pueden los cabildos insulares mancomunarse para la prestación conjunta de servicios propios o transferidos?','["No, y los actos que lo contravengan son nulos de pleno derecho", "Sí, si pertenecen a la misma provincia", "Solo para servicios de transporte interinsular", "Sí, con autorización del Gobierno de Canarias"]'::jsonb,0,'Art. 3 Ley 8/2015 Canarias','Los cabildos no pueden mancomunarse o federarse para la prestación conjunta de servicios; los actos contrarios son nulos de pleno derecho.',null),
('aux-canarias:7-5f0fd86eca','aux-canarias',7,'¿Qué plazo de audiencia a los cabildos establece la Ley 8/2015 cuando un anteproyecto de ley afecta a las materias que regula?','["Diez días", "Quince días", "Un mes", "Veinte días hábiles"]'::jsonb,1,'Art. 4 Ley 8/2015 Canarias','El Gobierno dará audiencia a los cabildos por un plazo de quince días antes de aprobar el anteproyecto o proyecto.',null),
('aux-canarias:7-07f938de0c','aux-canarias',7,'¿Qué servicios deben garantizar los cabildos en los municipios de menos de 1.000 habitantes?','["Los de abastecimiento de agua", "Los de recogida de residuos", "Los de policía local", "Los de secretaría e intervención"]'::jsonb,3,'Art. 8.1 b) Ley 8/2015 Canarias','En todo caso, el cabildo garantizará en los municipios de menos de 1.000 habitantes la prestación de los servicios de secretaría e intervención.',null),
('aux-canarias:7-6bef3e6544','aux-canarias',7,'¿En qué municipios asume el cabildo la prestación de prevención y extinción de incendios cuando estos no la presten?','["En los de menos de 20.000 habitantes", "En los de menos de 5.000 habitantes", "En todos los de la isla", "En los de menos de 50.000 habitantes"]'::jsonb,0,'Art. 8.1 c) Ley 8/2015 Canarias','Asume el tratamiento de residuos en municipios de menos de 5.000 habitantes y la prevención y extinción de incendios en los de menos de 20.000.',null),
('aux-canarias:7-432e3eea4d','aux-canarias',7,'¿En qué municipios asume el cabildo el tratamiento de residuos cuando estos no lo presten?','["En los de menos de 1.000 habitantes", "En los de menos de 20.000 habitantes", "En los de menos de 5.000 habitantes", "En los de menos de 10.000 habitantes"]'::jsonb,2,'Art. 8.1 c) Ley 8/2015 Canarias','El cabildo asume la prestación del tratamiento de residuos en los municipios de menos de 5.000 habitantes cuando no la presten.',null),
('aux-canarias:7-745f688540','aux-canarias',7,'¿Cómo es, con carácter general, la asistencia de los cabildos a los municipios según la Ley 8/2015?','["Obligatoria en todos los casos, aunque el ayuntamiento no lo haya solicitado", "Voluntaria, previa solicitud del ayuntamiento", "Obligatoria para los municipios de menos de 20.000 habitantes", "Decidida de oficio por el pleno del cabildo"]'::jsonb,1,'Art. 10.4 Ley 8/2015 Canarias','La asistencia es voluntaria, previa solicitud del ayuntamiento, salvo cuando sea legalmente obligatoria.',null),
('aux-canarias:7-22a19d931f','aux-canarias',7,'¿A qué municipios prestan asistencia los cabildos especialmente, según la Ley 8/2015?','["A los de menos de 1.000 habitantes exclusivamente", "A los capitalinos", "A los de más de 50.000 habitantes", "A los de menos de 20.000 habitantes"]'::jsonb,3,'Art. 10.1 Ley 8/2015 Canarias','Prestan asistencia especialmente a los municipios de menos de 20.000 habitantes y a los de insuficiente capacidad económica y de gestión.',null),
('aux-canarias:7-0c49cee0d7','aux-canarias',7,'¿Qué principio debe atenderse, entre otros, en la atribución de competencias propias a los cabildos?','["Suficiencia financiera", "Subordinación al Gobierno", "Uniformidad insular", "Jerarquía administrativa"]'::jsonb,0,'Art. 7.2 g) Ley 8/2015 Canarias','Los principios son garantía de la autonomía insular, eficacia, eficiencia, máxima proximidad, no duplicidad, estabilidad presupuestaria y suficiencia financiera.',null),
('aux-canarias:7-46ff6c7030','aux-canarias',7,'¿En qué municipios presta el cabildo los servicios de administración electrónica y contratación centralizada?','["En los de población inferior a 5.000 habitantes", "En los de población superior a 20.000 habitantes", "En los de población inferior a 20.000 habitantes", "En todos los municipios de la isla"]'::jsonb,2,'Art. 8.1 g) Ley 8/2015 Canarias','Es competencia propia del cabildo la prestación de esos servicios en los municipios con población inferior a 20.000 habitantes.',null),
('aux-canarias:7-36f2d0a745','aux-canarias',7,'¿Cómo ejercen los cabildos sus competencias propias según la Ley 8/2015?','["Previa autorización del Gobierno de Canarias", "Bajo su propia responsabilidad y sin sujeción a instrucciones", "Por delegación de los municipios de la isla, conforme a lo que acuerden sus plenos", "Bajo la dirección y las instrucciones del consejero competente por razón de la materia"]'::jsonb,1,'Art. 7.1 Ley 8/2015 Canarias','Las competencias propias se ejercen bajo su propia responsabilidad, en el marco de las leyes y sin sujeción a directrices o instrucciones.',null),
('aux-canarias:7-be7a287aec','aux-canarias',7,'¿Cuál de estas materias figura entre los ámbitos de competencia de los cabildos en la Ley 8/2015?','["Seguridad privada", "Universidades", "Aguas", "Sistema penitenciario"]'::jsonb,2,'Art. 6.2 t) Ley 8/2015 Canarias','Entre los ámbitos materiales figuran, entre otros, ordenación del territorio, carreteras, turismo, servicios sociales y aguas.',null),
('aux-canarias:7-029a7ca86f','aux-canarias',7,'¿Qué ley regula los municipios de Canarias?','["La Ley 4/2023, de 23 de marzo", "La Ley 7/2015, de 1 de abril", "La Ley 8/2015, de 1 de abril", "La Ley 14/1990, de 26 de julio"]'::jsonb,1,'Art. 1 Ley 7/2015 Canarias','La Ley 7/2015, de 1 de abril, de los municipios de Canarias regula los municipios y demás entidades del sector público municipal.',null),
('aux-canarias:7-142866d2a7','aux-canarias',7,'¿Qué entidad de gestión desconcentrada menciona expresamente la Ley de Municipios de Canarias?','["La de la isla de La Graciosa", "La de los islotes de Alegranza y Montaña Clara", "La de la isla de Lobos", "La del Parque Nacional del Teide"]'::jsonb,0,'Art. 2.1 d) Ley 7/2015 Canarias','La ley se aplica, entre otras entidades, a la entidad de gestión desconcentrada de la isla de La Graciosa.',null),
('aux-canarias:7-0ad3911bcd','aux-canarias',7,'¿Cuál de estos principios de atribución de competencias a los municipios recoge la Ley 7/2015?','["Tutela autonómica", "Subsidiariedad insular", "Uniformidad", "Máxima proximidad"]'::jsonb,3,'Art. 5.1 b) Ley 7/2015 Canarias','Los principios son garantía de la autonomía municipal, máxima proximidad, igualdad en el acceso a los servicios y suficiencia financiera y estabilidad presupuestaria.',null),
('aux-canarias:7-c84240048f','aux-canarias',7,'Según la Ley 7/2015, ¿qué competencias se atribuyen a los municipios en virtud de la garantía de la autonomía municipal?','["Las que no quieran asumir los cabildos", "Las que afecten preponderantemente al círculo de intereses vecinales", "Las que determine cada año la ley de presupuestos", "Solo las que sean exclusivamente municipales"]'::jsonb,1,'Art. 6.1 Ley 7/2015 Canarias','Se atribuye a los municipios toda competencia que afecte preponderantemente al círculo de intereses vecinales, aunque no sea exclusivamente municipal.',null),
('aux-canarias:7-58369ba912','aux-canarias',7,'¿Qué son las competencias propias de los municipios según la Ley 7/2015?','["Las que asumen por acuerdo del Pleno municipal adoptado por mayoría absoluta de sus miembros", "Las que les delegan los cabildos insulares mediante decreto de su presidente o presidenta", "Aquellas cuya titularidad les atribuyen las leyes del Estado y de la Comunidad Autónoma", "Las que figuran en sus ordenanzas fiscales"]'::jsonb,2,'Art. 10.1 Ley 7/2015 Canarias','Son competencias propias aquellas cuya titularidad atribuyen las leyes del Estado y de la Comunidad Autónoma de Canarias.',null),
('aux-canarias:7-6ba576cc77','aux-canarias',7,'En las competencias delegadas a los municipios, ¿quién conserva la titularidad?','["La administración delegante", "La Comunidad Autónoma en todo caso", "El cabildo insular", "El municipio delegado"]'::jsonb,0,'Art. 10.2 Ley 7/2015 Canarias','Son delegadas las competencias cuyo ejercicio se atribuye al municipio, conservando la titularidad la administración delegante.',null),
('aux-canarias:7-1a3f4c5d61','aux-canarias',7,'¿Qué llevan aparejado las nuevas competencias propias que impliquen cargas adicionales para los municipios canarios?','["Una subida automática de los tributos municipales", "Un plazo de carencia de dos años", "La autorización del Ministerio de Hacienda", "Los correspondientes traspasos de recursos y medios de la comunidad autónoma"]'::jsonb,3,'Art. 9 Ley 7/2015 Canarias','Por el principio de suficiencia financiera, llevarán aparejados los traspasos de recursos y medios de la comunidad autónoma.',null),
('aux-canarias:7-18095491c7','aux-canarias',7,'¿Cuál de estas materias figura entre las competencias que los municipios canarios asumen en todo caso según la Ley 7/2015?','["Igualdad de género", "Defensa", "Puertos de interés general", "Relaciones internacionales"]'::jsonb,0,'Art. 11 h) Ley 7/2015 Canarias','Los municipios asumen las competencias que les asignen las leyes sectoriales canarias en materias como igualdad de género, vivienda, urbanismo o turismo.',null),
('aux-canarias:7-da2de27a5b','aux-canarias',7,'Para prestar residuos o incendios en municipios que no los presten, ¿qué plazo debe conceder el cabildo para que manifiesten su voluntad de hacerlo?','["Quince días", "Dos meses", "Tres meses", "Un mes"]'::jsonb,1,'Art. 12.2 Ley 7/2015 Canarias','El cabildo debe conceder a los municipios un plazo de dos meses; si no se manifiestan, viene obligado a prestarlos.',null),
('aux-canarias:7-fe5518553d','aux-canarias',7,'¿Quién solicita la asistencia del cabildo en los municipios de más de 20.000 habitantes?','["El Pleno, por mayoría absoluta", "La Junta de Portavoces", "El alcalde, dando cuenta al Pleno", "El secretario municipal"]'::jsonb,2,'Art. 12.1 Ley 7/2015 Canarias','La asistencia la solicita el alcalde, dando cuenta al Pleno (o a la Junta de Gobierno local en los municipios de gran población).',null),
('aux-canarias:8-3558913fbc','aux-canarias',8,'Si los Presupuestos Generales de Canarias no se aprueban antes del primer día del ejercicio, ¿qué ocurre?','["Se aplica el proyecto presentado por el Gobierno", "Rige el presupuesto del Estado", "Se tramita un presupuesto provisional por decreto-ley", "Se prorrogan automáticamente los anteriores"]'::jsonb,3,'Art. 185.3 EACan','Si no se aprueban antes del primer día del ejercicio, los anteriores quedan automáticamente prorrogados.',null),
('aux-canarias:8-2aa2f1a25b','aux-canarias',8,'¿Qué período tienen los Presupuestos Generales de la Comunidad Autónoma de Canarias?','["Plurianual de cuatro años", "Anual, igual que los del Estado", "El de la legislatura", "Bienal"]'::jsonb,1,'Art. 185.2 EACan','Los Presupuestos tienen carácter anual e igual período que los del Estado.',null),
('aux-canarias:8-e030d517c9','aux-canarias',8,'¿A quién corresponde la aprobación y fiscalización de los Presupuestos Generales de Canarias?','["Al Tribunal de Cuentas", "A la Audiencia de Cuentas", "Al Parlamento de Canarias", "Al Gobierno de Canarias"]'::jsonb,2,'Art. 185.1 EACan','Corresponde al Parlamento de Canarias la aprobación y fiscalización de los Presupuestos Generales de la Comunidad.',null),
('aux-canarias:8-e5207540ed','aux-canarias',8,'¿Cómo define la Ley 11/2006 de la Hacienda Pública Canaria los Presupuestos Generales de la Comunidad Autónoma?','["El plan plurianual de inversiones aprobado por el Gobierno", "El documento que recoge la previsión de ingresos tributarios de la comunidad", "La relación de créditos ampliables de cada consejería", "La expresión cifrada, conjunta y sistemática de los derechos y obligaciones a liquidar durante el ejercicio"]'::jsonb,3,'Art. 35 Ley 11/2006 Canarias','Los Presupuestos son la expresión cifrada, conjunta y sistemática de los derechos y obligaciones a liquidar durante el ejercicio por los órganos y entidades del sector público.',null),
('aux-canarias:8-0ae8f7068b','aux-canarias',8,'¿Con qué período coincide el ejercicio presupuestario de la Comunidad Autónoma de Canarias?','["Con el periodo de sesiones del Parlamento", "Del 1 de julio al 30 de junio", "Con la legislatura", "Con el año natural"]'::jsonb,3,'Art. 37 Ley 11/2006 Canarias','El ejercicio presupuestario coincide con el año natural.',null),
('aux-canarias:8-d63c3117a8','aux-canarias',8,'¿Hasta qué fecha pueden reconocerse obligaciones imputables al ejercicio presupuestario anterior en Canarias?','["Hasta el quince de enero siguiente", "Hasta el treinta y uno de diciembre", "Hasta el treinta y uno de marzo siguiente", "Hasta el treinta y uno de enero siguiente"]'::jsonb,0,'Art. 37 b) Ley 11/2006 Canarias','Se imputan las obligaciones reconocidas hasta el quince de enero siguiente por gastos realizados antes de que expire el ejercicio.',null),
('aux-canarias:8-945edfe7ba','aux-canarias',8,'¿Antes de qué fecha debe remitirse al Parlamento el proyecto de Ley de Presupuestos Generales de Canarias?','["Antes del 30 de septiembre del año anterior", "Antes del 1 de noviembre del año anterior", "Antes del 15 de diciembre del año anterior", "Antes del 1 de octubre del año anterior"]'::jsonb,1,'Art. 39.1 Ley 11/2006 Canarias','El proyecto de ley se remite al Parlamento de Canarias antes del día 1 de noviembre del año anterior al que se refiera.',null),
('aux-canarias:8-ff6e4f4b15','aux-canarias',8,'¿Quién eleva al Gobierno de Canarias el anteproyecto de Ley de Presupuestos Generales?','["La Comisión de Presupuestos del Parlamento", "El presidente del Gobierno", "El consejero competente en materia de Hacienda", "La Intervención General"]'::jsonb,2,'Art. 38.4 Ley 11/2006 Canarias','Corresponde al consejero competente en materia de Hacienda elevar al Gobierno el anteproyecto de Ley de Presupuestos.',null),
('aux-canarias:8-ceb685ef4f','aux-canarias',8,'Si la Ley de Presupuestos de Canarias no se aprueba antes del primer día del ejercicio, ¿qué se prorroga?','["Solo los créditos de personal y los destinados a la amortización de la deuda", "Los presupuestos definitivos del ejercicio anterior, con todas sus modificaciones", "Los presupuestos iniciales del ejercicio anterior", "El proyecto de ley remitido al Parlamento"]'::jsonb,2,'Art. 40.1 Ley 11/2006 Canarias','Se consideran automáticamente prorrogados los presupuestos iniciales del ejercicio anterior y los créditos generados para nuevas competencias.',null),
('aux-canarias:8-780e23b848','aux-canarias',8,'¿Qué créditos no se prorrogan cuando no se aprueban a tiempo los Presupuestos de Canarias?','["Los de la sección de Deuda Pública", "Los de programas o actuaciones que terminen en el ejercicio prorrogado", "Los destinados a los cabildos insulares", "Los de personal"]'::jsonb,1,'Art. 40.2 Ley 11/2006 Canarias','La prórroga no afecta a los créditos de programas o actuaciones que terminen en el ejercicio prorrogado ni a obligaciones que se extingan en él.',null),
('aux-canarias:8-de335b4ba7','aux-canarias',8,'¿Qué clasificación de los estados de gastos agrupa los créditos por capítulos, separando operaciones corrientes, de capital y financieras?','["La clasificación económica", "La clasificación orgánica", "La clasificación territorial", "La clasificación por programas"]'::jsonb,0,'Art. 42.1 c) Ley 11/2006 Canarias','La clasificación económica agrupa los créditos por capítulos, separando operaciones corrientes, de capital y financieras.',null),
('aux-canarias:8-6abf30c5e1','aux-canarias',8,'¿Qué clasificación de los gastos agrupa los créditos por ámbito exterior, regional o insular?','["La clasificación orgánica", "La clasificación económica", "La clasificación funcional", "La clasificación territorial"]'::jsonb,3,'Art. 42.1 d) Ley 11/2006 Canarias','La clasificación territorial agrupa por ámbito exterior, regional o insular los créditos asignados a los centros gestores.',null),
('aux-canarias:8-7bf0e49346','aux-canarias',8,'¿Según qué clasificaciones se estructuran los estados de ingresos de los entes con presupuesto limitativo en Canarias?','["Orgánica, por programas y territorial", "Por programas y económica", "Económica y funcional", "Orgánica y económica"]'::jsonb,3,'Art. 43 Ley 11/2006 Canarias','Los estados de ingresos se estructuran siguiendo las clasificaciones orgánica y económica.',null),
('aux-canarias:8-1da081951c','aux-canarias',8,'¿Qué carácter tienen los créditos para gastos en la Ley de la Hacienda Pública Canaria?','["Ampliable en todo caso", "Limitativo", "Estimativo", "Orientativo"]'::jsonb,1,'Art. 48 Ley 11/2006 Canarias','Los créditos para gastos son limitativos: no pueden adquirirse compromisos por cuantía superior a los créditos autorizados.',null),
('aux-canarias:8-34bde77eaf','aux-canarias',8,'¿Qué consecuencia tienen los actos administrativos que adquieran compromisos de gasto superiores a los créditos autorizados?','["Son anulables", "Son válidos si se convalidan por el Gobierno", "Son nulos de pleno derecho", "Son irregularidades no invalidantes"]'::jsonb,2,'Art. 48 Ley 11/2006 Canarias','Son nulos de pleno derecho los actos y disposiciones de rango inferior a ley que incumplan la limitación de los créditos.',null),
('aux-canarias:8-53847205d4','aux-canarias',8,'¿A cuántos ejercicios pueden aplicarse como máximo los compromisos de gasto plurianuales en Canarias, con carácter general?','["Cuatro", "Tres", "Cinco", "Seis"]'::jsonb,0,'Art. 49.2 Ley 11/2006 Canarias','El número de ejercicios a que pueden aplicarse los gastos no será superior a cuatro.',null),
('aux-canarias:8-ced4b8ee78','aux-canarias',8,'¿Qué porcentaje del crédito inicial puede imputarse en el ejercicio inmediato siguiente en un gasto plurianual en Canarias?','["El 60 %", "El 80 %", "El 70 %", "El 50 %"]'::jsonb,2,'Art. 49.2 Ley 11/2006 Canarias','Los porcentajes son el 70 % en el ejercicio siguiente, el 60 % en el segundo y el 50 % en el tercero y cuarto.',null),
('aux-canarias:8-c49854bbbc','aux-canarias',8,'¿Qué retención adicional de crédito se practica en los contratos de obra plurianuales en Canarias?','["El 15 % del presupuesto de licitación", "El 10 % del presupuesto de licitación", "El 20 % del importe de adjudicación", "El 5 % del presupuesto de licitación"]'::jsonb,1,'Art. 49.2 Ley 11/2006 Canarias','Se efectúa una retención adicional del 10 % del presupuesto de licitación, que se ajusta al 10 % de la adjudicación una vez adjudicada la obra.',null),
('aux-canarias:8-2cf10d1ee2','aux-canarias',8,'¿Cuáles son las fases de la gestión del presupuesto de gastos en la Ley 11/2006, por orden?','["Aprobación, reconocimiento de la obligación, compromiso, ordenación del pago y pago material", "Autorización, disposición, liquidación y pago", "Compromiso, aprobación, ordenación del pago, reconocimiento de la obligación y pago material", "Aprobación, compromiso, reconocimiento de la obligación, ordenación del pago y pago material"]'::jsonb,3,'Art. 68.1 Ley 11/2006 Canarias','Las fases son aprobación del gasto, compromiso, reconocimiento de la obligación, ordenación del pago y pago material.',null),
('aux-canarias:8-49b0a0157b','aux-canarias',8,'¿Qué fase de la ejecución del gasto inicia el procedimiento sin implicar relaciones con terceros?','["La aprobación del gasto", "El compromiso de gasto", "El reconocimiento de la obligación", "La ordenación del pago"]'::jsonb,0,'Art. 68.2 Ley 11/2006 Canarias','La aprobación inicia el procedimiento de ejecución del gasto, sin que implique relaciones con terceras personas.',null),
('aux-canarias:8-c841e30370','aux-canarias',8,'¿Qué fase de la ejecución del gasto vincula a la Hacienda Pública frente a terceros a la realización del gasto?','["El compromiso de gasto", "La aprobación del gasto", "El pago material", "La ordenación del pago"]'::jsonb,0,'Art. 68.3 Ley 11/2006 Canarias','El compromiso es un acto con relevancia jurídica para con terceros que vincula a la Hacienda Pública a realizar el gasto.',null),
('aux-canarias:8-0a77370ffd','aux-canarias',8,'¿Qué son las generaciones de crédito según la Ley 11/2006?','["Créditos para gastos que no pueden demorarse al ejercicio siguiente", "Traspasos de dotaciones entre créditos", "Modificaciones que incrementan los créditos por ingresos no previstos o superiores a los previstos", "Remanentes del ejercicio anterior que se suman al actual"]'::jsonb,2,'Art. 55.1 Ley 11/2006 Canarias','Las generaciones incrementan los créditos como consecuencia de ingresos no previstos o superiores a los del presupuesto inicial.',null),
('aux-canarias:8-2f2a3f7c75','aux-canarias',8,'¿Qué son las transferencias de crédito según la Ley 11/2006?','["Créditos que se amplían hasta el importe de las obligaciones", "Traspasos de dotaciones entre créditos", "Incrementos de crédito por ingresos no previstos", "Aportaciones a los cabildos insulares"]'::jsonb,1,'Art. 54.1 Ley 11/2006 Canarias','Las transferencias son traspasos de dotaciones entre créditos, con las restricciones del art. 54.',null),
('aux-canarias:8-f2d077605e','aux-canarias',8,'¿Desde qué créditos no pueden realizarse transferencias a créditos para operaciones corrientes?','["Desde créditos de la sección Deuda Pública", "Desde créditos para gastos de funcionamiento", "Desde créditos de personal", "Desde créditos para operaciones de capital"]'::jsonb,3,'Art. 54.1 a) Ley 11/2006 Canarias','No pueden hacerse transferencias desde operaciones financieras al resto de créditos ni desde operaciones de capital a operaciones corrientes.',null),
('aux-canarias:8-f7ec5c9896','aux-canarias',8,'¿Cómo se tramita en Canarias un crédito extraordinario o suplemento de crédito de la Administración autonómica?','["Por orden del consejero de Hacienda publicada en el Boletín Oficial de Canarias", "Por resolución de la Intervención General", "Mediante proyecto de ley remitido al Parlamento", "Por decreto del Gobierno sin intervención parlamentaria"]'::jsonb,2,'Art. 57.2 Ley 11/2006 Canarias','El consejero de Hacienda propone al Gobierno la remisión de un proyecto de ley al Parlamento.',null),
('aux-canarias:8-4112ab575a','aux-canarias',8,'¿Cuál de estas es una modalidad de modificación de créditos prevista en la Ley 11/2006?','["Prórrogas", "Retenciones", "Anticipos de caja fija", "Incorporaciones"]'::jsonb,3,'Art. 53.1 Ley 11/2006 Canarias','Las modificaciones son transferencias, generaciones, ampliaciones, créditos extraordinarios y suplementos, e incorporaciones.',null),
('aux-canarias:8-268e8bab70','aux-canarias',8,'¿Cuándo aprueba el Gobierno de Canarias los escenarios presupuestarios plurianuales?','["En el primer cuatrimestre del año", "En el último trimestre del año", "En el mes de julio", "Al aprobar el proyecto de presupuestos"]'::jsonb,0,'Art. 26.1 Ley 11/2006 Canarias','El Gobierno aprueba en el primer cuatrimestre los escenarios presupuestarios referidos a los tres ejercicios siguientes.',null),
('aux-canarias:8-d9b738a389','aux-canarias',8,'¿A qué periodo se refieren los programas de actuación plurianual de los entes con presupuesto limitativo?','["A un único ejercicio, prorrogable una sola vez por igual periodo", "No inferior a dos años ni superior a tres", "A la legislatura completa", "No inferior a tres años ni superior a cinco"]'::jsonb,1,'Art. 28.1 Ley 11/2006 Canarias','Se refieren a un período no inferior a dos años ni superior a tres, salvo causa justificada.',null),
('aux-canarias:9-181aaec658','aux-canarias',9,'¿Cuántas instituciones enumera el artículo 13 del Tratado de la Unión Europea?','["Cinco", "Seis", "Nueve", "Siete"]'::jsonb,3,'Art. 13 TUE','Parlamento Europeo, Consejo Europeo, Consejo, Comisión, Tribunal de Justicia de la UE, Banco Central Europeo y Tribunal de Cuentas.',null),
('aux-canarias:9-acc0d5fedb','aux-canarias',9,'¿Cuál de los siguientes NO es una institución de la Unión según el artículo 13 del TUE?','["El Comité de las Regiones", "El Tribunal de Cuentas", "El Banco Central Europeo", "El Consejo Europeo"]'::jsonb,0,'Art. 13 TUE','El Comité de las Regiones y el Comité Económico y Social son órganos consultivos, no instituciones.',null),
('aux-canarias:9-adc557cc63','aux-canarias',9,'¿Por cuánto tiempo se elige a los miembros del Parlamento Europeo?','["Cinco años", "Cuatro años", "Dos años y medio", "Seis años"]'::jsonb,0,'Art. 14.3 TUE','Se eligen por sufragio universal directo, libre y secreto.',null),
('aux-canarias:9-883e69bbcf','aux-canarias',9,'El número de miembros del Parlamento Europeo no puede exceder de:','["700, incluido el Presidente", "750, más el Presidente", "751, más el Presidente", "800, más el Presidente"]'::jsonb,1,'Art. 14.2 TUE','Ningún Estado puede tener más de 96 escaños ni menos de 6.',null),
('aux-canarias:9-f5c49c7604','aux-canarias',9,'¿Dónde tiene su sede oficial el Parlamento Europeo?','["En Fráncfort", "En Luxemburgo", "En Bruselas", "En Estrasburgo"]'::jsonb,3,'Sedes de las instituciones','También trabaja en Bruselas y su Secretaría General está en Luxemburgo.',null),
('aux-canarias:9-86af4aa8d7','aux-canarias',9,'¿Quiénes componen el Consejo Europeo?','["Los Ministros de Asuntos Exteriores de los Estados miembros, el Alto Representante y el Presidente de la Comisión", "Un representante de cada Estado miembro de rango ministerial", "Los Presidentes de los Parlamentos nacionales de los Estados miembros y el Presidente del Parlamento Europeo", "Los Jefes de Estado o de Gobierno de los Estados miembros, su Presidente y el Presidente de la Comisión"]'::jsonb,3,'Art. 15.2 TUE','El Alto Representante participa en sus trabajos, pero no es miembro.',null),
('aux-canarias:9-9dca3f307a','aux-canarias',9,'El Presidente del Consejo Europeo es elegido por un mandato de:','["Seis meses, coincidiendo con la presidencia rotatoria", "Cinco años, no renovable", "Dos años, renovable indefinidamente", "Dos años y medio, renovable una sola vez"]'::jsonb,3,'Art. 15.5 TUE','Lo elige el propio Consejo Europeo por mayoría cualificada.',null),
('aux-canarias:9-192e078a02','aux-canarias',9,'El Consejo de la Unión Europea está compuesto por:','["Un representante de cada Estado miembro de rango ministerial", "Un comisario por cada Estado miembro, nombrado por su Gobierno nacional", "Los Jefes de Estado o de Gobierno de los Estados miembros y su Presidente", "Los embajadores de los Estados miembros ante la Unión, con rango de representantes permanentes"]'::jsonb,0,'Art. 16.2 TUE','Ese representante puede comprometer al Gobierno de su Estado y ejercer el derecho de voto.',null),
('aux-canarias:9-5373126ce3','aux-canarias',9,'Desde 2014, la mayoría cualificada en el Consejo se define como:','["Al menos dos tercios de los Estados miembros que representen como mínimo la mitad de la población de la Unión", "La mayoría absoluta de los Estados miembros, sea cual sea su población, siempre que incluya a los cuatro más poblados", "Al menos el 55 % de los miembros del Consejo que representen al menos el 65 % de la población de la Unión", "Al menos el 65 % de los miembros del Consejo que representen como mínimo el 55 % de la población de la Unión"]'::jsonb,2,'Art. 16.4 TUE','La minoría de bloqueo debe incluir al menos a cuatro miembros del Consejo.',null),
('aux-canarias:9-a492dbcdd1','aux-canarias',9,'¿Qué institución tiene, como regla general, la iniciativa legislativa en la Unión Europea?','["La Comisión Europea", "El Consejo Europeo", "El Consejo de la Unión", "El Parlamento Europeo"]'::jsonb,0,'Art. 17.2 TUE','Los actos legislativos solo pueden adoptarse a propuesta de la Comisión, salvo que los Tratados dispongan otra cosa.',null),
('aux-canarias:9-c49aedc5ee','aux-canarias',9,'¿Cómo se elige al Presidente de la Comisión Europea?','["Lo eligen los ciudadanos de la Unión por sufragio universal directo cada cinco años", "Lo nombra el Consejo de la Unión por mayoría simple, a propuesta del Parlamento Europeo", "El Consejo Europeo propone un candidato por mayoría cualificada y el Parlamento Europeo lo elige por mayoría de sus miembros", "Lo elige directamente el Consejo Europeo por unanimidad, sin intervención del Parlamento"]'::jsonb,2,'Art. 17.7 TUE','El Consejo Europeo tiene en cuenta el resultado de las elecciones al Parlamento Europeo.',null),
('aux-canarias:9-d38de659a5','aux-canarias',9,'¿Qué cargo ocupa el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad dentro de la Comisión?','["Es su Secretario General, con voz pero sin voto", "Es uno de sus Vicepresidentes", "Es su Presidente, por razón de su cargo", "No forma parte de la Comisión, sino del Consejo Europeo"]'::jsonb,1,'Art. 18.4 TUE','Además preside el Consejo de Asuntos Exteriores.',null),
('aux-canarias:9-3850780d38','aux-canarias',9,'¿Dónde tiene su sede el Tribunal de Justicia de la Unión Europea?','["En Bruselas", "En Estrasburgo", "En Luxemburgo", "En La Haya"]'::jsonb,2,'Sedes de las instituciones','En La Haya está el Tribunal Internacional de Justicia y en Estrasburgo el Tribunal Europeo de Derechos Humanos, que no son órganos de la UE.',null),
('aux-canarias:9-c7b4a72317','aux-canarias',9,'¿Dónde tiene su sede el Banco Central Europeo?','["En Ámsterdam", "En Luxemburgo", "En Bruselas", "En Fráncfort"]'::jsonb,3,'Sedes de las instituciones','El BCE dirige la política monetaria de la zona euro.',null),
('aux-canarias:9-d1b1befa8f','aux-canarias',9,'Según el artículo 288 del TFUE, el reglamento:','["Obliga al Estado destinatario en cuanto al resultado, dejando a las autoridades nacionales la elección de la forma y los medios", "No es vinculante y solo expresa una opinión de las instituciones", "Tiene alcance general, es obligatorio en todos sus elementos y directamente aplicable en cada Estado miembro", "Solo es obligatorio para sus destinatarios, que deben estar designados en él"]'::jsonb,2,'Art. 288 TFUE','La segunda opción describe la directiva, la tercera la decisión y la cuarta los dictámenes.',null),
('aux-canarias:9-38d9608f7c','aux-canarias',9,'¿Qué acto de la Unión obliga al Estado miembro destinatario en cuanto al resultado que deba conseguirse, dejando a las autoridades nacionales la elección de la forma y de los medios?','["La recomendación", "La decisión", "El reglamento", "La directiva"]'::jsonb,3,'Art. 288 TFUE','Las directivas deben transponerse al derecho interno.',null),
('aux-canarias:9-d63068fa55','aux-canarias',9,'Según el artículo 288 del TFUE, las recomendaciones y los dictámenes:','["Son obligatorios en todos sus elementos", "Solo obligan a sus destinatarios", "Obligan solo en cuanto al resultado", "No son vinculantes"]'::jsonb,3,'Art. 288 TFUE','Son actos de las instituciones sin fuerza obligatoria.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-canarias:9-adc94d5d15','aux-canarias',9,'En el procedimiento legislativo ordinario, los actos se adoptan conjuntamente por:','["El Consejo Europeo y el Parlamento, a propuesta del Consejo", "La Comisión y el Consejo Europeo, oído el Parlamento", "El Parlamento Europeo y el Consejo, a propuesta de la Comisión", "El Consejo de la Unión por unanimidad, previa consulta al Parlamento"]'::jsonb,2,'Art. 294 TFUE','Antes del Tratado de Lisboa se llamaba procedimiento de codecisión.',null),
('aux-canarias:9-921e704e0a','aux-canarias',9,'¿Quién elige al Defensor del Pueblo Europeo?','["El Tribunal de Justicia", "El Consejo Europeo", "El Parlamento Europeo", "La Comisión Europea"]'::jsonb,2,'Art. 228 TFUE','Recibe reclamaciones sobre casos de mala administración en la acción de las instituciones, órganos y organismos de la Unión.',null),
('aux-canarias:9-621a22500a','aux-canarias',9,'¿Cuántos ciudadanos de la Unión, como mínimo, deben respaldar una iniciativa ciudadana europea?','["Quinientos mil, de al menos cinco Estados miembros distintos de la Unión", "Dos millones, procedentes como mínimo de la mitad de los Estados miembros", "Cien mil, sin importar su nacionalidad ni su Estado de residencia", "Un millón, de un número significativo de Estados miembros"]'::jsonb,3,'Art. 11.4 TUE','Con ella se invita a la Comisión a presentar una propuesta legislativa.',null),
('aux-canarias:9-91d3a410c4','aux-canarias',9,'¿Qué artículo del Tratado de la Unión Europea regula la retirada voluntaria de un Estado miembro?','["El artículo 7", "El artículo 49", "El artículo 50", "El artículo 48"]'::jsonb,2,'Art. 50 TUE','El artículo 49 regula la adhesión, el 7 la suspensión de derechos y el 48 la revisión de los Tratados.',null),
('aux-canarias:9-45e30cfd30','aux-canarias',9,'¿A qué institución corresponde el control de las cuentas de la Unión?','["Al Banco Central Europeo", "A la Oficina Europea de Lucha contra el Fraude", "Al Tribunal de Justicia de la Unión", "Al Tribunal de Cuentas Europeo"]'::jsonb,3,'Art. 285 TFUE','Tiene su sede en Luxemburgo y está formado por un nacional de cada Estado miembro.',null),
('aux-canarias:9-cbce805a50','aux-canarias',9,'¿Cuándo puede el Gobierno de Canarias formar parte de las delegaciones españolas ante la Unión Europea?','["Siempre que lo solicite el Parlamento de Canarias", "Solo en materia de pesca", "Solo cuando se negocien ayudas de Estado para Canarias", "Cuando se vea afectada su condición de región ultraperiférica"]'::jsonb,3,'Art. 196.3 EACan','El Gobierno de Canarias podrá formar parte de las delegaciones españolas cuando se vea afectada su condición de región ultraperiférica.',null),
('aux-canarias:9-ed3c6cb8c0','aux-canarias',9,'¿A quién corresponde la gestión de los fondos europeos en materias de competencia de Canarias?','["A los cabildos insulares", "Al Estado, a través de la Delegación del Gobierno", "A la Comunidad Autónoma de Canarias", "A la Administración General del Estado y a los cabildos de forma conjunta"]'::jsonb,2,'Art. 197.2 EACan','Corresponde a la Comunidad Autónoma de Canarias la gestión de los fondos europeos en materias de su competencia.',null),
('aux-canarias:10-abd6fa82d1','aux-canarias',10,'La Ley Orgánica 3/2007 tiene por objeto:','["Hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres", "Establecer medidas de protección integral contra la violencia de género y de igualdad de oportunidades en el empleo", "Hacer efectivo el derecho de igualdad de trato entre mujeres y hombres, pero solo en el ámbito del empleo público y de la negociación colectiva", "Regular la igualdad de trato y la no discriminación por cualquier circunstancia personal"]'::jsonb,0,'Art. 1.1 LO 3/2007','Su objeto es hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres.',null),
('aux-canarias:10-16efc76198','aux-canarias',10,'El principio de igualdad de trato entre mujeres y hombres supone:','["La igualdad en el ámbito laboral y en el acceso al empleo", "La ausencia de toda discriminación, directa o indirecta, por razón de sexo", "La ausencia de discriminación directa por razón de sexo, pero no de la indirecta, que se rige por la normativa laboral", "La paridad obligatoria en todos los órganos públicos y privados, con independencia de su composición"]'::jsonb,1,'Art. 3 LO 3/2007','Supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, especialmente por maternidad, obligaciones familiares y estado civil.',null),
('aux-canarias:10-8accd0afb2','aux-canarias',10,'Se considera discriminación directa por razón de sexo la situación en que una persona:','["Recibe una medida de acción positiva destinada a corregir situaciones de desigualdad", "Es tratada igual que otra persona en una situación distinta", "Es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable", "Sufre una desventaja particular respecto de personas del otro sexo por una disposición, criterio o práctica aparentemente neutros"]'::jsonb,2,'Art. 6.1 LO 3/2007','Es la situación de quien es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable. El trato por disposición aparentemente neutra es la discriminación indirecta.',null),
('aux-canarias:10-c7da8489aa','aux-canarias',10,'El acoso sexual es cualquier comportamiento, verbal o físico, de naturaleza sexual que:','["Se produzca fuera del lugar de trabajo", "Se repita al menos tres veces y lo denuncie la persona afectada o un tercero", "Produzca una lesión física acreditada", "Tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona"]'::jsonb,3,'Art. 7.1 LO 3/2007','Tiene el propósito o produce el efecto de atentar contra la dignidad de una persona, en particular cuando crea un entorno intimidatorio, degradante u ofensivo.',null),
('aux-canarias:10-9aaa0a6127','aux-canarias',10,'Todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad constituye:','["Discriminación directa por razón de sexo", "Discriminación indirecta por razón de sexo, salvo que la empresa acredite una justificación objetiva", "Acoso por razón de sexo", "Una infracción laboral leve"]'::jsonb,0,'Art. 8 LO 3/2007','Constituye discriminación directa por razón de sexo.',null),
('aux-canarias:10-eb32ff35e3','aux-canarias',10,'Según la LO 3/2007, el principio de igualdad de trato y oportunidades informará la actuación de todos los Poderes Públicos con carácter:','["Excepcional", "Transversal", "Subsidiario", "Voluntario"]'::jsonb,1,'Art. 15 LO 3/2007','Informará, con carácter transversal, la actuación de todos los Poderes Públicos.',null),
('aux-canarias:10-a521c1b9da','aux-canarias',10,'¿Qué empresas deben elaborar y aplicar un plan de igualdad?','["Todas, cualquiera que sea su plantilla", "Las de más de 250 trabajadores", "Las de cincuenta o más trabajadores", "Solo las empresas públicas y las que contraten con la Administración, cualquiera que sea su plantilla"]'::jsonb,2,'Art. 45.2 LO 3/2007','Las empresas de cincuenta o más trabajadores.',null),
('aux-canarias:10-bfa8324011','aux-canarias',10,'Según la LO 3/2007, hay composición equilibrada cuando las personas de cada sexo:','["Son exactamente el 50 %", "No superan el 70 % ni son menos del 30 %", "No superan el 55 % ni son menos del 45 %", "No superan el 60 % ni son menos del 40 %"]'::jsonb,3,'Disp. adicional 1.ª LO 3/2007','Las personas de cada sexo no superan el sesenta por ciento ni son menos del cuarenta por ciento.',null),
('aux-canarias:10-b5efb188da','aux-canarias',10,'El Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado se aprueba por el Gobierno:','["Cada diez años", "Cada año", "Solo cuando lo pide el Congreso", "Al inicio de cada legislatura"]'::jsonb,3,'Art. 64 LO 3/2007','Su cumplimiento se evalúa anualmente por el Consejo de Ministros.',null),
('aux-canarias:10-da1501c93d','aux-canarias',10,'En los litigios sobre acoso sexual y acoso por razón de sexo, está legitimada:','["Cualquier ciudadano", "Únicamente la persona acosada", "El sindicato mayoritario en todo caso", "El Ministerio Fiscal en exclusiva"]'::jsonb,1,'Art. 12.3 LO 3/2007','La persona acosada es la única legitimada.',null),
('aux-canarias:10-27296d84d3','aux-canarias',10,'Según el art. 6.3 de la LO 3/2007, toda orden de discriminar, directa o indirectamente, por razón de sexo:','["Se considerará en todo caso discriminatoria", "No tiene relevancia jurídica si no llega a ejecutarse", "Solo es discriminatoria si se ejecuta", "Es válida si procede de un superior"]'::jsonb,0,'Art. 6.3 LO 3/2007','La orden de discriminar es en sí misma discriminación.',null),
('aux-canarias:10-b60680165b','aux-canarias',10,'Las acciones positivas para hacer efectivo el derecho a la igualdad pueden adoptarlas:','["Solo el Gobierno y las Administraciones públicas", "Solo los jueces y tribunales en sus sentencias", "Solo las empresas de más de 250 trabajadores, dentro de su plan de igualdad negociado con la representación legal de los trabajadores", "Los poderes públicos y también las personas físicas y jurídicas privadas"]'::jsonb,3,'Art. 11 LO 3/2007','Deben ser razonables y proporcionadas.',null),
('aux-canarias:10-97962d8a3a','aux-canarias',10,'Los proyectos de disposiciones de carácter general y los planes de especial relevancia que se sometan a la aprobación del Consejo de Ministros deberán incorporar:','["Un informe del Consejo de Estado en todo caso", "Un informe sobre su impacto por razón de género", "Un informe económico de la UE", "La firma de todas las Comunidades Autónomas"]'::jsonb,1,'Art. 19 LO 3/2007','Es el informe de impacto de género.',null),
('aux-canarias:10-ec0ceab504','aux-canarias',10,'Según la LO 3/2007, se considera discriminación por razón de sexo cualquier trato adverso o efecto negativo producido como consecuencia de:','["Su afiliación a un partido político o a un sindicato", "Su cambio de domicilio", "La presentación por una persona de una queja, reclamación, denuncia o demanda destinada a impedir su discriminación", "Su ascenso profesional o la obtención de un puesto de libre designación tras un procedimiento de provisión con convocatoria pública"]'::jsonb,2,'Art. 9 LO 3/2007','Es la garantía de indemnidad frente a represalias.',null),
('aux-canarias:10-74af988505','aux-canarias',10,'Entre los criterios de actuación de las Administraciones en el empleo público, la LO 3/2007 incluye:','["Promover la presencia equilibrada de mujeres y hombres en los órganos de selección y valoración", "Suprimir los planes de igualdad", "Establecer cuotas obligatorias del 60 % de mujeres en todos los órganos de selección y valoración", "Reservar los puestos directivos a la persona más antigua"]'::jsonb,0,'Art. 51 d) LO 3/2007','También establecer medidas efectivas para eliminar cualquier discriminación retributiva.',null),
('aux-canarias:10-1c94361489','aux-canarias',10,'En los procedimientos (no penales) en que se aleguen actuaciones discriminatorias por razón de sexo, corresponde probar la ausencia de discriminación a:','["La persona demandante", "El Ministerio Fiscal", "La persona demandada", "El juez"]'::jsonb,2,'Art. 13.1 LO 3/2007','Es la inversión de la carga de la prueba; no se aplica a los procesos penales.',null),
('aux-canarias:10-e2b422fe2f','aux-canarias',10,'¿A quién se aplica la Ley 1/2010 canaria de igualdad, además de en el territorio del archipiélago?','["A quien tenga la condición política de canario y resida en el exterior", "A las empresas con sede social en Canarias que operen fuera del archipiélago, en todo caso", "A todos los españoles de origen canario, con independencia de su lugar de residencia", "A ninguna persona fuera del archipiélago"]'::jsonb,0,'Art. 2.1 Ley 1/2010 Canarias','La ley se aplica en el territorio del archipiélago y a quien tenga la condición política de canario o canaria y resida en el exterior.',null),
('aux-canarias:10-aebdd6f495','aux-canarias',10,'Según la Ley 1/2010 canaria, ¿qué principio comporta aplicar la perspectiva de género en la planificación, ejecución y evaluación de todas las políticas?','["La coordinación", "La acción positiva", "La transversalidad", "La corresponsabilidad"]'::jsonb,2,'Art. 4.15 Ley 1/2010 Canarias','La transversalidad comporta aplicar la perspectiva de género en las fases de planificación, ejecución y evaluación de todas las políticas.',null),
('aux-canarias:10-6f6d3b8f2f','aux-canarias',10,'¿Qué informe deben incorporar los proyectos de ley, reglamentos y planes del Gobierno de Canarias según la Ley 1/2010?','["Un informe del Consejo Consultivo de Canarias", "Un informe de evaluación del impacto de género", "Un informe de la Comisión Interdepartamental para la Igualdad", "Un informe del Observatorio de la Igualdad de Género"]'::jsonb,1,'Art. 6.2 Ley 1/2010 Canarias','En su tramitación debe emitirse un informe de evaluación del impacto de género de su contenido.',null),
('aux-canarias:10-ad1a1ed028','aux-canarias',10,'¿Qué órgano elabora y tramita la Estrategia de Igualdad de Género del Gobierno de Canarias?','["El Consejo Canario de Igualdad de Género", "La Consejería de Hacienda", "La Comisión Interdepartamental para la Igualdad", "El Instituto Canario de Igualdad"]'::jsonb,3,'Art. 7.2 Ley 1/2010 Canarias','La elaboración y tramitación de la Estrategia de Igualdad de Género corresponde al Instituto Canario de Igualdad.',null),
('aux-canarias:10-886eb72077','aux-canarias',10,'¿Qué naturaleza tiene la Estrategia de Igualdad de Género para la Administración Pública de Canarias?','["Vinculante", "Orientativa", "Facultativa para cada consejería", "Solo vinculante para los cabildos"]'::jsonb,0,'Art. 7.1 Ley 1/2010 Canarias','La estrategia es de carácter transversal y de naturaleza vinculante para la Administración Pública de la Comunidad Autónoma.',null),
('aux-canarias:10-1668c88e2b','aux-canarias',10,'¿Qué órgano emite el informe de evaluación de impacto de género sobre el anteproyecto de Ley del Presupuesto de Canarias?','["La Audiencia de Cuentas", "El Instituto Canario de Igualdad, a través de su unidad de presupuestos con perspectiva de género", "La Intervención General", "La Comisión de Impacto de Género en los Presupuestos"]'::jsonb,3,'Art. 9.1 Ley 1/2010 Canarias','Lo emite la Comisión de Impacto de Género en los Presupuestos, dependiente de la consejería de Hacienda, con participación del Instituto Canario de Igualdad.',null),
('aux-canarias:10-569670d9f4','aux-canarias',10,'¿Dónde se crean las Unidades de Igualdad de Género según la Ley 1/2010 canaria?','["Solo en la consejería competente en igualdad", "En cada cabildo insular", "En todas las consejerías", "En los ayuntamientos de más de 20.000 habitantes"]'::jsonb,2,'Art. 68.1 Ley 1/2010 Canarias','Se crean Unidades de Igualdad de Género en todas las consejerías para impulsar la perspectiva de género en sus políticas.',null),
('aux-canarias:10-04972b8400','aux-canarias',10,'¿Qué órgano asume en cada consejería las funciones de la Unidad de Igualdad de Género, salvo que se determine otro?','["La dirección general de personal", "La secretaría general técnica", "El gabinete del consejero", "La viceconsejería"]'::jsonb,1,'Art. 68.2 Ley 1/2010 Canarias','Cada consejería encomienda a su secretaría general técnica o, en su defecto, al órgano que determine el consejero, las funciones de la Unidad.',null),
('aux-canarias:10-d7d8a9e214','aux-canarias',10,'¿A qué organismo está adscrito el Observatorio de la Igualdad de Género de Canarias?','["A la Consejería de Educación", "Al Instituto Canario de Igualdad", "Al Parlamento de Canarias", "A la Presidencia del Gobierno"]'::jsonb,1,'Art. 69.1 Ley 1/2010 Canarias','El Observatorio es un órgano asesor adscrito al Instituto Canario de Igualdad.',null),
('aux-canarias:10-36ca0db97f','aux-canarias',10,'¿Quién preside la Comisión Interdepartamental para la Igualdad entre Mujeres y Hombres de Canarias?','["La persona titular de la consejería competente en igualdad", "La directora o director del Instituto Canario de Igualdad, por delegación", "El presidente del Gobierno de Canarias", "El vicepresidente del Gobierno"]'::jsonb,0,'Art. 67.1 Ley 1/2010 Canarias','La Comisión, con representación de todas las consejerías, la preside el titular de la consejería competente en materia de igualdad.',null),
('aux-canarias:10-f3d730299e','aux-canarias',10,'¿Qué es el Consejo Canario de Igualdad de Género?','["El órgano directivo de la política de igualdad del Gobierno de Canarias, con rango de dirección general", "Un órgano de la Diputación del Común", "La comisión parlamentaria de igualdad", "El órgano de consulta del Instituto Canario de Igualdad y de participación de organizaciones"]'::jsonb,3,'Art. 70.1 Ley 1/2010 Canarias','Es el órgano de consulta del Instituto Canario de Igualdad y de participación de organizaciones y agentes sociales que trabajan por la igualdad.',null),
('aux-canarias:10-58a96ba00d','aux-canarias',10,'¿Quién elabora periódicamente planes de igualdad según el artículo 35 de la Ley 1/2010 canaria?','["El Parlamento de Canarias", "Los cabildos insulares exclusivamente", "El Gobierno de Canarias, sus empresas públicas y entidades instrumentales", "Solo las empresas privadas de más de 50 trabajadores con sede en Canarias"]'::jsonb,2,'Art. 35.1 Ley 1/2010 Canarias','El Gobierno de Canarias, sus empresas públicas y entidades instrumentales elaboran periódicamente planes de igualdad.',null),
('aux-canarias:10-7cb467bece','aux-canarias',10,'¿Qué distintivo pueden tener las empresas para obtener preferencia en la adjudicación en caso de empate según la Ley 1/2010?','["La Marca de Excelencia Canaria en igualdad", "El certificado de empresa familiar canaria", "El sello de Responsabilidad Social de Canarias", "El distintivo Igualdad en la Empresa del Estado únicamente"]'::jsonb,0,'Art. 13.2 Ley 1/2010 Canarias','Los pliegos darán preferencia, en igualdad de condiciones, a las empresas con la Marca de Excelencia Canaria de Igualdad o con medidas de igualdad.',null),
('aux-canarias:10-3f10a6ba7b','aux-canarias',10,'¿Con qué empresas no formalizará la Administración canaria ayudas y subvenciones según la Ley 1/2010?','["Con las que no tengan plan de igualdad, sea cual sea su número de trabajadores", "Con las de menos de diez trabajadores", "Con las sancionadas o condenadas en firme por prácticas laborales discriminatorias", "Con las que tengan sede fuera de Canarias"]'::jsonb,2,'Art. 14.2 Ley 1/2010 Canarias','No se formalizarán con empresas sancionadas o condenadas en firme por alentar o tolerar prácticas laborales discriminatorias.',null),
('aux-canarias:10-a97385668f','aux-canarias',10,'¿Qué se designará en los consejos escolares de los centros públicos y concertados de Canarias según la Ley 1/2010?','["Una comisión de igualdad de tres miembros", "Una persona con formación en igualdad de género", "Un inspector de igualdad nombrado por el Instituto Canario de Igualdad", "Un representante del Instituto Canario de Igualdad en cada centro"]'::jsonb,1,'Art. 20 Ley 1/2010 Canarias','Se designará una persona con formación en igualdad de género que impulse y siga las medidas educativas de igualdad.',null),
('aux-canarias:11-9d99fae358','aux-canarias',11,'La LO 1/2004 actúa contra la violencia que se ejerce sobre las mujeres por parte de quienes sean o hayan sido sus cónyuges o parejas:','["Aun sin convivencia", "Solo si conviven", "Solo si están casados", "Solo si hay hijos en común"]'::jsonb,0,'Art. 1.1 LO 1/2004','Comprende a quienes sean o hayan sido sus cónyuges o hayan estado ligados por relaciones similares de afectividad, aun sin convivencia.',null),
('aux-canarias:11-6668dda15d','aux-canarias',11,'Según la LO 1/2004, la violencia de género comprende:','["Solo la violencia física que cause lesiones", "Todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad", "Todo acto de violencia física, incluidas las agresiones a la libertad sexual, pero no la violencia psicológica, las amenazas ni las coacciones, que se rigen por el Código Penal", "Solo la violencia física ejercida en el domicilio familiar que cause lesiones acreditadas por un médico, excluidas las amenazas, las coacciones y la violencia psicológica"]'::jsonb,1,'Art. 1.3 LO 1/2004','Comprende todo acto de violencia física y psicológica, incluidas agresiones a la libertad sexual, amenazas, coacciones o privación arbitraria de libertad.',null),
('aux-canarias:11-ea6568aba0','aux-canarias',11,'¿Cuál de estos derechos tiene la trabajadora víctima de violencia de género?','["Una indemnización automática a cargo de su empresa", "El ascenso de categoría", "La reducción o reordenación de su tiempo de trabajo, la movilidad geográfica o la suspensión con reserva de puesto", "La reducción de jornada sin disminución proporcional del salario, la movilidad geográfica y el cambio de empresa dentro del grupo"]'::jsonb,2,'Art. 21.1 LO 1/2004','Tiene derecho, entre otros, a la reducción o reordenación de jornada, la movilidad geográfica, el cambio de centro, la suspensión con reserva de puesto y la extinción del contrato.',null),
('aux-canarias:11-63bf6aaa1c','aux-canarias',11,'Para acreditar la situación de violencia de género y acceder a los derechos laborales sirve, entre otros:','["Una declaración jurada de un vecino o familiar", "El certificado de empadronamiento junto con una declaración jurada de la propia trabajadora", "Un parte de lesiones expedido por una clínica privada sin intervención judicial ni fiscal", "La orden de protección o el informe del Ministerio Fiscal"]'::jsonb,3,'Art. 23 LO 1/2004','Se acredita con sentencia condenatoria, orden de protección, informe del Ministerio Fiscal, informe de los servicios sociales o especializados u otro título previsto.',null),
('aux-canarias:11-d853c73739','aux-canarias',11,'La funcionaria víctima de violencia de género tiene derecho, entre otros, a:','["La excedencia, la reducción o reordenación de su tiempo de trabajo y la movilidad geográfica", "El cambio automático de cuerpo o escala", "Un permiso retribuido de un año, la reducción de jornada sin merma de retribuciones y la jubilación anticipada voluntaria", "La jubilación anticipada sin reducción de la pensión y un permiso retribuido de un año completo"]'::jsonb,0,'Art. 24 LO 1/2004','Tiene derecho a la reducción o reordenación de su tiempo de trabajo, a la movilidad geográfica de centro de trabajo y a la excedencia.',null),
('aux-canarias:11-950dd33fd5','aux-canarias',11,'¿Qué órganos judiciales creó la LO 1/2004?','["Las Audiencias de Familia", "Los Juzgados de Violencia sobre la Mujer", "Los Tribunales de Igualdad", "Las Salas de Género del Tribunal Supremo"]'::jsonb,1,'Art. 43 LO 1/2004','Creó los Juzgados de Violencia sobre la Mujer, añadiendo el art. 87 bis a la LOPJ.',null),
('aux-canarias:11-d2a2da9527','aux-canarias',11,'El Fiscal contra la Violencia sobre la Mujer:','["Es elegido por el Congreso por mayoría de tres quintos", "Depende orgánicamente del Ministerio de Igualdad, que lo nombra a propuesta del Consejo de Ministros", "Es nombrado, oído el Consejo Fiscal, como delegado, con categoría de Fiscal de Sala", "Es un fiscal de cada provincia"]'::jsonb,2,'Art. 70 LO 1/2004','Se nombra, oído el Consejo Fiscal, como delegado, con categoría de Fiscal de Sala.',null),
('aux-canarias:11-8d79dca1e9','aux-canarias',11,'Según la LO 1/2004, la víctima de violencia de género tiene derecho a recibir asesoramiento jurídico gratuito:','["Solo si es funcionaria o empleada pública", "Solo después de que recaiga sentencia condenatoria firme contra el agresor", "En el momento inmediatamente previo a la interposición de la denuncia", "Solo si tiene hijos menores a su cargo"]'::jsonb,2,'Art. 20.1 LO 1/2004','También tienen derecho a defensa y representación gratuitas.',null),
('aux-canarias:11-069ad0f102','aux-canarias',11,'Según la LO 1/2004, en cada partido judicial habrá:','["Uno o más Juzgados de Violencia sobre la Mujer", "Un Juzgado de Paz especializado", "Un Tribunal de Violencia de Género con jurado", "Una Audiencia especializada"]'::jsonb,0,'Art. 43 LO 1/2004 (art. 87 bis LOPJ)','La LO 1/2004 añadió el art. 87 bis a la LOPJ.',null),
('aux-canarias:11-421d20b1f9','aux-canarias',11,'La información a las víctimas de violencia de género sobre sus derechos se garantizará también a las mujeres que, por sus circunstancias personales y sociales, tengan dificultad de acceso, como:','["Solo las mujeres extranjeras en situación irregular", "Solo las empleadas públicas", "Solo las menores de edad, a través de sus representantes legales", "Las mujeres con discapacidad, en formato accesible"]'::jsonb,3,'Art. 18.2 LO 1/2004','También a quienes no dominen las lenguas oficiales (art. 18.3).',null),
('aux-canarias:11-370f462afb','aux-canarias',11,'El Observatorio Estatal de Violencia sobre la Mujer es:','["Una organización no gubernamental de ámbito estatal declarada de utilidad pública", "Un órgano colegiado de asesoramiento, evaluación y colaboración institucional", "Una sección especializada de la Fiscalía", "Un juzgado especializado en violencia sobre la mujer con competencia en toda España"]'::jsonb,1,'Art. 30.1 LO 1/2004','Remite al Gobierno y a las CCAA un informe anual.',null),
('aux-canarias:11-668b27dad0','aux-canarias',11,'La suspensión y la extinción del contrato de trabajo de la trabajadora víctima de violencia de género:','["Darán lugar a situación legal de desempleo", "Requieren autorización judicial previa", "No dan derecho a prestación por desempleo, salvo que lo reconozca una sentencia", "Se consideran despido disciplinario"]'::jsonb,0,'Art. 21.2 LO 1/2004','El tiempo de suspensión se considera periodo de cotización efectiva.',null),
('aux-canarias:11-ab56a26820','aux-canarias',11,'Las ausencias o faltas de puntualidad al trabajo de la trabajadora víctima de violencia de género motivadas por su situación física o psicológica:','["Se descuentan del sueldo en todo caso, aunque los servicios sociales de atención o de salud acrediten que están motivadas por su situación física o psicológica", "Se considerarán justificadas y serán remuneradas cuando así lo determinen los servicios sociales de atención o de salud", "Requieren autorización judicial", "Serán siempre sancionadas como falta leve, aunque los servicios sociales de atención o de salud acrediten que derivan de su situación"]'::jsonb,1,'Art. 21.4 LO 1/2004','Deben comunicarse a la empresa a la mayor brevedad.',null),
('aux-canarias:11-6e0331bfdf','aux-canarias',11,'Los servicios de asistencia social integral a las víctimas de violencia de género responderán, entre otros, a los principios de:','["Gratuidad parcial, voluntariedad, subsidiariedad respecto de los servicios generales y atención exclusiva en horario de oficina", "Secreto, discrecionalidad, gratuidad parcial, subsidiariedad respecto de los servicios generales y atención en horario de oficina", "Centralización y uniformidad", "Atención permanente, actuación urgente, especialización de prestaciones y multidisciplinariedad profesional"]'::jsonb,3,'Art. 19.1 LO 1/2004','Son los principios de la asistencia social integral.',null),
('aux-canarias:11-841732c9db','aux-canarias',11,'La Delegación del Gobierno contra la Violencia de Género, entre otras funciones:','["Dicta resoluciones vinculantes para los juzgados de violencia sobre la mujer", "Dirige y coordina a la policía judicial en las investigaciones de violencia de género y dicta instrucciones a los juzgados especializados", "Elabora la Macroencuesta de Violencia contra las Mujeres y está legitimada ante los órganos jurisdiccionales", "Impone sanciones administrativas a los agresores y dirige las investigaciones de la policía judicial en los casos más graves"]'::jsonb,2,'Art. 29 LO 1/2004','Formula las políticas públicas en materia de violencia de género.',null),
('aux-canarias:11-64c8e973e7','aux-canarias',11,'¿Qué norma aprobó el Texto Refundido de la Ley General de derechos de las personas con discapacidad y de su inclusión social?','["El Real Decreto Legislativo 1/2013, de 29 de noviembre", "El Real Decreto Legislativo 5/2015, de 30 de octubre", "La Ley 39/2006, de 14 de diciembre", "La Ley 51/2003, de 2 de diciembre"]'::jsonb,0,'RDL 1/2013','La Ley 39/2006 regula la dependencia y el RDL 5/2015 es el TREBEP.',null),
('aux-canarias:11-63497b067f','aux-canarias',11,'Según el Real Decreto Legislativo 1/2013, tienen la consideración de personas con discapacidad, a todos los efectos, aquellas a quienes se haya reconocido un grado de discapacidad:','["Igual o superior al 33 %", "Igual o superior al 65 %", "Igual o superior al 25 %", "Superior al 50 %"]'::jsonb,0,'Art. 4.2 RDL 1/2013','También se consideran así, entre otros, los pensionistas de la Seguridad Social con incapacidad permanente total, absoluta o gran invalidez.',null),
('aux-canarias:11-74178294b8','aux-canarias',11,'Las empresas públicas y privadas que empleen a 50 o más trabajadores están obligadas a que, de entre ellos, sean trabajadores con discapacidad al menos:','["El 2 %", "El 7 %", "El 1 %", "El 5 %"]'::jsonb,0,'Art. 42.1 RDL 1/2013','Excepcionalmente pueden quedar exentas aplicando medidas alternativas.',null),
('aux-canarias:11-31cb197c4c','aux-canarias',11,'Según el RDL 1/2013, los «ajustes razonables» son:','["Las ayudas económicas que concede la Administración a las personas con un grado de discapacidad superior al 65 % para adaptar su puesto de trabajo y su vivienda habitual", "Las reducciones de jornada a las que tienen derecho todos los trabajadores con discapacidad", "Las modificaciones y adaptaciones necesarias y adecuadas que no impongan una carga desproporcionada o indebida, cuando se requieran en un caso particular", "Las bonificaciones fiscales que reciben las empresas por contratar personas con discapacidad"]'::jsonb,2,'Art. 2 RDL 1/2013','Buscan facilitar la accesibilidad y la participación en igualdad de condiciones.',null),
('aux-canarias:11-aac049efe9','aux-canarias',11,'Según el RDL 1/2013, la accesibilidad universal es:','["El derecho de las personas con discapacidad a recibir una prestación económica de la Comunidad Autónoma para adaptar su vivienda habitual y su vehículo particular", "La condición que deben cumplir entornos, procesos, bienes, productos, servicios y objetos para ser comprensibles, utilizables y practicables por todas las personas", "La obligación de reservar plazas de aparcamiento en todos los edificios públicos", "El acceso gratuito de las personas con discapacidad a los transportes públicos"]'::jsonb,1,'Art. 2 RDL 1/2013','Debe darse en condiciones de seguridad y comodidad y de la forma más autónoma y natural posible.',null),
('aux-canarias:12-d7d8e86ce2','aux-canarias',12,'Las personas físicas, ¿pueden elegir si se comunican con las Administraciones por medios electrónicos?','["Sí, en todo momento, salvo que estén obligadas", "No, siempre deben usar medios electrónicos", "No, siempre deben ir en persona", "Solo si son mayores de 65 años"]'::jsonb,0,'Art. 14.1 Ley 39/2015','Pueden elegir en todo momento, salvo que estén obligadas a relacionarse electrónicamente.',null),
('aux-canarias:12-ab1354051e','aux-canarias',12,'¿Cuál de los siguientes NO está obligado, con carácter general, a relacionarse electrónicamente con las Administraciones?','["Una persona jurídica", "Una persona física que actúa en su propio nombre", "Una entidad sin personalidad jurídica", "Un empleado público en trámites por razón de su condición"]'::jsonb,1,'Art. 14.2 Ley 39/2015','Están obligados las personas jurídicas, las entidades sin personalidad, los profesionales con colegiación obligatoria, los representantes de obligados y los empleados públicos en esos trámites.',null),
('aux-canarias:12-8d6c5c78e7','aux-canarias',12,'Las personas tienen derecho a comunicarse con las Administraciones a través de:','["Un número de WhatsApp oficial de cada organismo", "Su correo electrónico personal, que tiene la misma validez que el registro", "Un Punto de Acceso General electrónico", "Los perfiles oficiales en redes sociales"]'::jsonb,2,'Art. 13 a) Ley 39/2015','Tienen derecho a comunicarse a través de un Punto de Acceso General electrónico de la Administración.',null),
('aux-canarias:12-07713e43a7','aux-canarias',12,'Es un derecho del interesado en el procedimiento:','["Obtener una resolución favorable si la Administración no resuelve en plazo", "Conocer en cualquier momento el estado de la tramitación de los procedimientos en los que sea interesado", "Elegir al instructor del procedimiento", "Conocer en cualquier momento el estado de tramitación de cualquier procedimiento de la Administración, aunque no tenga la condición de interesado"]'::jsonb,1,'Art. 53.1 a) Ley 39/2015','También el sentido del silencio, el órgano competente y obtener copia de los documentos.',null),
('aux-canarias:12-dba7cb5ed0','aux-canarias',12,'La Administración instructora deberá traducir al castellano:','["Los documentos que deban surtir efecto fuera del territorio de la Comunidad y los dirigidos a interesados que lo soliciten expresamente", "Todos los documentos redactados en lengua cooficial, sin excepción", "Solo los documentos dirigidos a interesados que residan fuera de la Comunidad Autónoma", "Los documentos que deban surtir efecto en la Comunidad, y los dirigidos a interesados que no conozcan la lengua cooficial aunque no lo pidan"]'::jsonb,0,'Art. 15.3 Ley 39/2015','Se traducen los que deban surtir efecto fuera de la Comunidad y los que pidan los interesados.',null),
('aux-canarias:12-1c976c00d5','aux-canarias',12,'En los procedimientos sancionadores, el presunto responsable tiene derecho, además:','["A elegir la sanción entre las previstas para la infracción", "A no declarar contra sí mismo, pero no a la presunción de inocencia, que es exclusiva del proceso penal", "A que se le notifique la sanción", "A la presunción de no existencia de responsabilidad administrativa mientras no se demuestre lo contrario"]'::jsonb,3,'Art. 53.2 b) Ley 39/2015','Es la presunción de inocencia en el ámbito sancionador.',null),
('aux-canarias:12-054568e021','aux-canarias',12,'Si concurren varios interesados en un procedimiento de la AGE y existe discrepancia en cuanto a la lengua:','["Se tramitará en la lengua cooficial", "Lo decide el interesado que figure en primer lugar", "Se tramitará en ambas lenguas", "El procedimiento se tramitará en castellano"]'::jsonb,3,'Art. 15.1 Ley 39/2015','En caso de discrepancia, se tramita en castellano.',null),
('aux-canarias:12-e475067c65','aux-canarias',12,'Según el art. 53.1 d), los interesados pueden formular alegaciones y aportar documentos:','["Solo en la solicitud inicial", "Solo en el período de prueba", "En cualquier fase del procedimiento anterior al trámite de audiencia", "En cualquier fase del procedimiento, incluso después de dictarse la resolución"]'::jsonb,2,'Art. 53.1 d) Ley 39/2015','Hasta el trámite de audiencia, que deberán ser tenidos en cuenta al redactar la propuesta de resolución.',null),
('aux-canarias:12-8b28da9995','aux-canarias',12,'Es un derecho de las personas en sus relaciones con las AAPP según el art. 13:','["Elegir al funcionario que tramite su expediente", "Obtener una resolución favorable si la Administración incumple el plazo máximo para resolver", "Ser tratados con respeto y deferencia por las autoridades y empleados públicos", "Ser atendidos en la lengua que elijan, cualquiera que sea la Administración"]'::jsonb,2,'Art. 13 e) Ley 39/2015','Otros: comunicarse por el Punto de Acceso General electrónico, ser asistidos en el uso de medios electrónicos, usar lenguas cooficiales, acceso a información pública…',null),
('aux-canarias:12-ae223b69ac','aux-canarias',12,'En los procedimientos tramitados por la AGE, la lengua será:','["Siempre la lengua cooficial del territorio donde tenga su sede el órgano", "El castellano, sin que los interesados puedan utilizar ninguna otra lengua, aunque se dirijan a órganos con sede en una Comunidad Autónoma con lengua cooficial", "El castellano, aunque los interesados que se dirijan a órganos con sede en una Comunidad con lengua cooficial podrán utilizar también esta", "La que elija el funcionario que tramite el procedimiento, castellano o lengua cooficial, sin que el interesado pueda solicitar que se utilice otra"]'::jsonb,2,'Art. 15.1 Ley 39/2015','La lengua de la AGE es el castellano, con posibilidad de usar la cooficial ante órganos con sede en esa Comunidad.',null),
('aux-canarias:12-5e70fa5556','aux-canarias',12,'La obligación de relacionarse electrónicamente con la Administración para ciertos colectivos de personas físicas puede establecerse:','["Reglamentariamente, para cualquier persona física mayor de edad", "Por resolución del órgano instructor en cada procedimiento concreto", "Reglamentariamente, si queda acreditado que tienen acceso y disponibilidad de los medios electrónicos", "Solo por ley y únicamente para los profesionales que estén colegiados"]'::jsonb,2,'Art. 14.3 Ley 39/2015','Puede imponerse por reglamento a colectivos que, por capacidad económica, técnica o dedicación profesional, tengan acceso a esos medios.',null),
('aux-canarias:12-d6d9417425','aux-canarias',12,'Según el artículo 13 de la Ley 39/2015, es un derecho de las personas en sus relaciones con las Administraciones Públicas:','["Obtener siempre una resolución favorable cuando cumplan los requisitos formales", "Exigir que se les atienda fuera del horario de atención al público", "Elegir al funcionario que tramitará su procedimiento", "Ser tratadas con respeto y deferencia por las autoridades y empleados públicos, que habrán de facilitarles el ejercicio de sus derechos"]'::jsonb,3,'Art. 13 e) Ley 39/2015','El artículo 13 recoge también, entre otros, el derecho a ser asistidas en el uso de medios electrónicos.',null),
('aux-canarias:12-226c8f5c00','aux-canarias',12,'¿Cuál de los siguientes está obligado a relacionarse electrónicamente con las Administraciones según el artículo 14.2 de la Ley 39/2015?','["Las personas físicas mayores de 65 años", "Los extranjeros residentes en España", "Las personas jurídicas", "Los autónomos sin colegiación obligatoria"]'::jsonb,2,'Art. 14.2 Ley 39/2015','También las entidades sin personalidad jurídica, los profesionales de colegiación obligatoria en el ejercicio de su actividad, sus representantes y los empleados públicos en los trámites por su condición de tales.',null),
('aux-canarias:13-44bc3e0a04','aux-canarias',13,'En la atención al público, la escucha activa consiste en:','["Prestar atención plena al interlocutor y demostrarle que se le entiende, por ejemplo resumiendo o preguntando", "Escuchar en silencio, sin hacer preguntas ni dar ninguna señal, hasta que el ciudadano haya terminado de hablar", "Tomar nota de la petición del ciudadano y remitirla por escrito a la unidad competente para que esta le conteste", "Hablar más que el ciudadano para dirigir la conversación hacia la solución que ya se conoce de antemano en cada caso"]'::jsonb,0,'Comunicación en la atención al público','Incluye señales verbales y no verbales de comprensión, como asentir o parafrasear.',null),
('aux-canarias:13-f31b8a1c23','aux-canarias',13,'La empatía en la atención al ciudadano supone:','["Tratar a cada persona con la misma frialdad para ser imparcial", "Dar siempre la razón al ciudadano para evitar conflictos", "Ponerse en el lugar del otro y comprender su situación y sus sentimientos", "Compartir con el ciudadano las opiniones personales sobre la Administración"]'::jsonb,2,'Comunicación en la atención al público','Comprender no significa necesariamente estar de acuerdo.',null),
('aux-canarias:13-3b033aa693','aux-canarias',13,'La asertividad es la habilidad de:','["Responder con rapidez sin escuchar los argumentos del otro", "Expresar las propias opiniones y necesidades de forma clara y respetuosa, sin agredir ni someterse", "Imponer el criterio propio al interlocutor cuando se tiene autoridad para ello, aunque el otro no esté de acuerdo", "Evitar cualquier desacuerdo con el ciudadano cediendo a lo que pide, aunque no sea posible atenderlo"]'::jsonb,1,'Comunicación en la atención al público','Es el punto medio entre la conducta pasiva y la agresiva.',null),
('aux-canarias:13-60a2ab5f15','aux-canarias',13,'La proxémica estudia:','["La forma de redactar los escritos y comunicaciones administrativos dirigidos a los ciudadanos", "El tono, el volumen, el ritmo y las pausas de la voz al hablar con otras personas", "Los gestos, la postura y los movimientos del cuerpo durante la conversación", "El uso del espacio y las distancias entre las personas en la comunicación"]'::jsonb,3,'Comunicación no verbal','Los gestos y movimientos los estudia la kinésica y los aspectos de la voz, el paralenguaje.',null),
('aux-canarias:13-f54887cc1c','aux-canarias',13,'El tono, el volumen, el ritmo y las pausas de la voz forman parte de:','["El paralenguaje", "La proxémica", "La comunicación escrita", "La kinésica"]'::jsonb,0,'Comunicación no verbal','Acompañan a las palabras y pueden reforzar o contradecir el mensaje verbal.',null),
('aux-canarias:13-844b7c8d20','aux-canarias',13,'La kinésica es la parte de la comunicación no verbal que estudia:','["Los gestos, la postura y los movimientos corporales", "Las características de la voz, como el tono, el timbre y el volumen", "El vocabulario técnico de la Administración", "Las distancias que mantienen los interlocutores durante la conversación"]'::jsonb,0,'Comunicación no verbal','La mirada y la expresión facial también se incluyen en la kinésica.',null),
('aux-canarias:13-ede0015717','aux-canarias',13,'Según el Real Decreto 951/2005, ¿cuál de los siguientes es uno de los programas del marco general para la mejora de la calidad en la AGE?','["El programa de quejas y sugerencias", "El programa de teletrabajo", "El programa de acción social", "El programa de evaluación del desempeño individual"]'::jsonb,0,'Art. 3.1 RD 951/2005','Los programas son: análisis de la demanda y evaluación de la satisfacción, cartas de servicios, quejas y sugerencias, evaluación de la calidad, reconocimiento y Observatorio de la Calidad.',null),
('aux-canarias:13-72cd274a1a','aux-canarias',13,'Según el Real Decreto 951/2005, ¿en qué plazo debe informarse al ciudadano de las actuaciones realizadas tras una queja o sugerencia?','["Tres meses desde su presentación", "Quince días naturales", "Veinte días hábiles", "Un mes desde su presentación"]'::jsonb,2,'Art. 16.1 RD 951/2005','El plazo se suspende si se requiere al interesado para que aclare su queja, por un máximo de diez días hábiles.',null),
('aux-canarias:13-ebaf0acf08','aux-canarias',13,'Si el ciudadano no recibe respuesta a su queja en el plazo establecido, según el RD 951/2005 puede dirigirse a:','["El Tribunal de Cuentas", "La Inspección General de Servicios del departamento", "El Defensor del Pueblo, como único cauce", "El juzgado de lo contencioso-administrativo"]'::jsonb,1,'Art. 16.3 RD 951/2005','La Inspección General de Servicios conocerá las causas de la falta de contestación.',null),
('aux-canarias:13-84784ce8d7','aux-canarias',13,'Las quejas formuladas conforme al Real Decreto 951/2005:','["No tienen la calificación de recurso administrativo ni interrumpen los plazos de los procedimientos", "Interrumpen los plazos para recurrir", "Tienen la consideración de recurso de alzada ante el superior jerárquico del órgano que dictó el acto del que se quejan", "Suspenden la ejecución del acto del que se quejan"]'::jsonb,0,'Art. 19 RD 951/2005','Tampoco condicionan el ejercicio de las demás acciones o derechos del interesado.',null),
('aux-canarias:13-1fa7ef5638','aux-canarias',13,'¿Cómo pueden presentarse las quejas y sugerencias según el RD 951/2005?','["Por escrito dirigido al Subsecretario, con firma reconocida ante notario", "A través del Defensor del Pueblo, que las traslada al órgano afectado", "Mediante comparecencia personal ante la Inspección General de Servicios del departamento", "De forma presencial, por correo postal o por medios electrónicos"]'::jsonb,3,'Art. 15 RD 951/2005','Las presentadas por medios electrónicos deben ir firmadas electrónicamente.',null),
('aux-canarias:13-0b6c067508','aux-canarias',13,'Las cartas de servicios se aprueban, según el RD 951/2005:','["Por orden del Ministro, sin necesidad de informe previo", "Por real decreto del Consejo de Ministros, a propuesta del Ministro del departamento y previo dictamen preceptivo del Consejo de Estado en pleno", "Por resolución del Subsecretario del departamento, previo informe favorable de la Secretaría General competente en función pública", "Por acuerdo de la Comisión General de Secretarios de Estado y Subsecretarios"]'::jsonb,2,'Art. 11.1 RD 951/2005','La resolución de aprobación se publica en el BOE.',null),
('aux-canarias:13-407bd7a1f8','aux-canarias',13,'Las cartas de servicios deben actualizarse:','["Cada cinco años", "Periódicamente y, al menos, cada tres años", "Cada año", "Solo cuando cambie la normativa del servicio"]'::jsonb,1,'Art. 10.4 RD 951/2005','También deben revisarse cuando cambien los servicios o los compromisos.',null),
('aux-canarias:13-8dc776c70a','aux-canarias',13,'¿Qué recogen las cartas de servicios?','["Los servicios que se ofrecen, los derechos de los usuarios y los compromisos de calidad asumidos", "La relación de puestos de trabajo del organismo", "Las retribuciones de los empleados públicos que prestan servicio en la unidad y su régimen de jornada y horario", "Las sanciones que pueden imponerse a los ciudadanos que incumplan las normas de utilización de los servicios"]'::jsonb,0,'Art. 8 RD 951/2005','Incluyen medidas de subsanación en caso de incumplimiento, que no dan lugar a responsabilidad patrimonial.',null),
('aux-canarias:13-bf2730e7d6','aux-canarias',13,'Las medidas de subsanación previstas en una carta de servicios para el caso de incumplimiento de los compromisos:','["Suponen la anulación de los actos administrativos dictados durante el incumplimiento", "Obligan a abrir un expediente disciplinario al responsable del servicio incumplido", "Dan derecho a una indemnización automática al usuario afectado por el incumplimiento", "No darán lugar a responsabilidad patrimonial de la Administración"]'::jsonb,3,'Art. 9 RD 951/2005','Normalmente consisten en una comunicación del responsable explicando las causas y las medidas adoptadas.',null),
('aux-canarias:13-448645bf4c','aux-canarias',13,'¿Qué órgano analiza periódicamente la percepción ciudadana sobre los servicios públicos según el RD 951/2005?','["El Instituto Nacional de Estadística", "El Observatorio de la Calidad de los Servicios Públicos", "El Centro de Investigaciones Sociológicas", "El Consejo de Transparencia y Buen Gobierno"]'::jsonb,1,'Art. 26 RD 951/2005','Publica un informe anual de evaluación global con conclusiones y recomendaciones.',null),
('aux-canarias:13-5a3401fe26','aux-canarias',13,'¿Cuántos programas integran el marco general para la mejora de la calidad del RD 951/2005?','["Cinco", "Ocho", "Seis", "Cuatro"]'::jsonb,2,'Art. 3 RD 951/2005','Son seis: análisis de la demanda y evaluación de la satisfacción, cartas de servicios, quejas y sugerencias, evaluación de la calidad, reconocimiento y Observatorio de la Calidad.',null),
('aux-canarias:13-a62433b1a1','aux-canarias',13,'Según el RD 951/2005, la unidad que coordina los programas de calidad en cada departamento ministerial la designa:','["El Inspector General de Servicios de la Administración Pública", "El Secretario de Estado de Función Pública", "El Subsecretario del departamento", "El Ministro del departamento"]'::jsonb,2,'Art. 3 RD 951/2005','Cada Subsecretario designa la unidad responsable de coordinar los programas de calidad en su departamento.',null),
('aux-canarias:13-8037d8b052','aux-canarias',13,'Según el RD 951/2005, la satisfacción de los usuarios con los servicios se medirá:','["De forma sistemática y permanente", "Solo cuando se reciban quejas", "Una vez al año, en el primer trimestre", "Cada tres años, al revisar la carta de servicios"]'::jsonb,0,'Art. 5 RD 951/2005','La medición de la percepción de la calidad por los usuarios se hace de forma sistemática y permanente.',null),
('aux-canarias:13-5239bb24c2','aux-canarias',13,'La resolución que aprueba una carta de servicios, según el RD 951/2005, se publica en:','["El tablón de anuncios de la oficina", "Únicamente en la sede electrónica del órgano", "El Boletín Oficial del Estado", "El Diario de Sesiones del Congreso"]'::jsonb,2,'Art. 11 RD 951/2005','La resolución aprobatoria se publica en el BOE y las cartas se difunden también por internet y en las oficinas.',null),
('aux-canarias:13-090c19eb5a','aux-canarias',13,'Los órganos con carta de servicios deben enviar, según el RD 951/2005, un informe anual sobre su cumplimiento:','["Cada tres años", "Durante el primer semestre de cada año", "En el mes de diciembre", "Durante el primer trimestre de cada año"]'::jsonb,3,'Art. 12 RD 951/2005','Los órganos remiten anualmente, en el primer trimestre, un informe sobre el grado de cumplimiento de los compromisos.',null),
('aux-canarias:13-4f8018e9fd','aux-canarias',13,'Si la unidad de quejas pide al ciudadano que aclare su queja, según el RD 951/2005 este dispone para hacerlo de:','["10 días hábiles", "15 días hábiles", "5 días hábiles", "20 días hábiles"]'::jsonb,0,'Art. 16 RD 951/2005','El plazo de 20 días hábiles para contestar se suspende y el ciudadano tiene 10 días hábiles para responder a la aclaración.',null),
('aux-canarias:13-c64cac1c47','aux-canarias',13,'¿Qué órgano realiza el seguimiento de las quejas y sugerencias en cada departamento, según el RD 951/2005?','["El Defensor del Pueblo", "El Tribunal de Cuentas", "El Consejo de Transparencia y Buen Gobierno de la Administración", "La Inspección General de Servicios del departamento"]'::jsonb,3,'Art. 17 RD 951/2005','Las Inspecciones Generales de Servicios de los departamentos realizan el seguimiento de las quejas y sugerencias.',null),
('aux-canarias:13-15e214d8d1','aux-canarias',13,'Según el RD 951/2005, para obtener el reconocimiento a la excelencia una organización debe haber realizado previamente:','["Una carta de servicios electrónica", "Una encuesta de satisfacción del Centro de Investigaciones Sociológicas", "Una autoevaluación conforme a un modelo de gestión de calidad reconocido", "Una auditoría del Tribunal de Cuentas"]'::jsonb,2,'Art. 23 RD 951/2005','Para optar al reconocimiento a la excelencia es requisito haber realizado una autoevaluación según los modelos de gestión de calidad reconocidos.',null),
('aux-canarias:13-7eaf6086e4','aux-canarias',13,'Según el RD 951/2005, ¿quién designa la unidad encargada de gestionar las quejas y sugerencias?','["La Agencia Española de Protección de Datos", "El Ministerio de Hacienda para todos los departamentos", "Cada órgano o organismo, que debe contestar al ciudadano", "El Defensor del Pueblo para toda la Administración"]'::jsonb,2,'Art. 14 RD 951/2005','Cada órgano designa la unidad responsable de la gestión de quejas y sugerencias, que debe responder al ciudadano.',null),
('aux-canarias:13-4f594cf7d6','aux-canarias',13,'Los órganos que prestan servicios electrónicos operativos deben tener, según el RD 951/2005:','["Un libro de reclamaciones en papel", "Un certificado de calidad ISO", "Cartas de servicios electrónicos", "Un defensor del usuario propio"]'::jsonb,2,'Art. 13 RD 951/2005','Los órganos con servicios electrónicos operativos elaboran cartas de servicios electrónicos.',null),
('aux-canarias:13-7e7da0f07d','aux-canarias',13,'¿Qué norma regula los servicios de información administrativa y atención al ciudadano en la Administración General del Estado?','["El Real Decreto 203/2021, de 30 de marzo de 2021", "El Real Decreto 364/1995, de 10 de marzo de 1995", "El Real Decreto 951/2005, de 29 de julio de 2005", "El Real Decreto 208/1996, de 9 de febrero"]'::jsonb,3,'RD 208/1996','El RD 951/2005 regula el marco general para la mejora de la calidad y el RD 203/2021 el Reglamento de actuación y funcionamiento del sector público por medios electrónicos.',null),
('aux-canarias:13-758878990d','aux-canarias',13,'Según el Real Decreto 208/1996, la información administrativa puede ser:','["Verbal, escrita o telemática", "Ordinaria o extraordinaria", "General o particular", "Pública, reservada o secreta"]'::jsonb,2,'Art. 1 RD 208/1996','Es el cauce a través del cual los ciudadanos conocen sus derechos y obligaciones y la utilización de los bienes y servicios públicos.',null),
('aux-canarias:13-24caf6636b','aux-canarias',13,'La información general, según el Real Decreto 208/1996, se facilitará:','["A los interesados en un procedimiento administrativo o a sus representantes legales debidamente acreditados", "Previo pago de la tasa correspondiente", "A quien la solicite por escrito y acredite un interés legítimo, personal y directo en el asunto", "Obligatoriamente a los ciudadanos, sin exigir para ello la acreditación de legitimación alguna"]'::jsonb,3,'Art. 2.2 RD 208/1996','Se refiere a la identificación, fines, competencia, estructura y localización de los órganos, y a los requisitos de procedimientos y servicios.',null),
('aux-canarias:13-8cb0b2b854','aux-canarias',13,'La información particular, según el Real Decreto 208/1996, es la relativa a:','["La estructura, las funciones y la localización de los órganos administrativos, así como la identificación de sus titulares y su horario de atención al público", "Los requisitos jurídicos para acceder a una prestación pública", "El estado o el contenido de los procedimientos en tramitación y la identificación de las autoridades y el personal bajo cuya responsabilidad se tramiten", "Las publicaciones oficiales editadas por los Ministerios"]'::jsonb,2,'Art. 3.1 RD 208/1996','Lo demás corresponde a la información general.',null),
('aux-canarias:13-4f4ba8486e','aux-canarias',13,'¿A quién puede facilitarse la información particular?','["A las personas que tengan la condición de interesados o a sus representantes legales", "A los abogados colegiados que intervengan en el procedimiento en nombre de un tercero", "A cualquier empleado público de la Administración General del Estado que la pida por escrito", "A cualquier ciudadano que la solicite, aunque no se identifique ni acredite interés alguno"]'::jsonb,0,'Art. 3.2 RD 208/1996','Debe respetarse la normativa de protección de datos personales.',null),
('aux-canarias:13-20a1305a60','aux-canarias',13,'Según el Real Decreto 208/1996, la orientación sobre los requisitos de los procedimientos que se presta en las oficinas de información:','["Vincula a la Administración en la resolución posterior del procedimiento al que se refiera", "Puede incluir la interpretación de la norma aplicable al caso concreto que plantee el ciudadano", "Debe darse siempre por escrito y con la firma del jefe de la oficina", "No puede entrañar una interpretación normativa ni una consideración jurídica o económica"]'::jsonb,3,'Art. 4 b) RD 208/1996','Se limita a la determinación de conceptos, la información sobre opciones legales o la colaboración en la cumplimentación de impresos.',null),
('aux-canarias:13-c00ede71b7','aux-canarias',13,'¿Cuál de las siguientes es una función de atención al ciudadano según el artículo 4 del RD 208/1996?','["La imposición de sanciones por infracciones leves", "La resolución definitiva de los recursos de alzada presentados por los ciudadanos contra actos del propio departamento", "La aprobación de las cartas de servicios del departamento", "La recepción y acogida, para facilitar la orientación y ayuda que precisen en el momento inicial de su visita"]'::jsonb,3,'Art. 4 a) RD 208/1996','Otras funciones son la orientación, la gestión, la recepción de iniciativas y sugerencias y la recepción de quejas.',null),
('aux-canarias:13-acf1785888','aux-canarias',13,'Las oficinas de información y atención al ciudadano de los servicios centrales pueden ser, según el RD 208/1996:','["Oficinas generales, para cualquier asunto, y oficinas especiales, para los procedimientos de cada organismo público adscrito", "Oficinas centrales en la sede de cada Ministerio, que pueden tener oficinas delegadas, y oficinas de organismos públicos", "Oficinas provinciales e insulares", "Oficinas de registro y oficinas de archivo, dependientes en ambos casos de la Secretaría General Técnica del Ministerio correspondiente"]'::jsonb,1,'Art. 8 RD 208/1996','En los órganos territoriales existen oficinas en las Delegaciones y Subdelegaciones del Gobierno.',null),
('aux-canarias:13-02863cebf9','aux-canarias',13,'Según el Real Decreto 208/1996, las oficinas de información de una Administración pueden informar sobre otras Administraciones:','["Cuando lo autorice el Delegado del Gobierno en la Comunidad Autónoma", "Cuando lo autorice el Consejo de Ministros", "Cuando así se prevea en un convenio de colaboración entre ellas", "Cuando el ciudadano lo pida expresamente por escrito"]'::jsonb,2,'Art. 10 RD 208/1996','También pueden crearse oficinas conjuntas de varias Administraciones.',null),
('aux-canarias:13-7cdc928897','aux-canarias',13,'Según el RD 208/1996, la función de orientación e información al ciudadano:','["Incluye interpretar las normas aplicables al caso concreto", "No puede suponer interpretación normativa ni valoración jurídica o económica", "Permite emitir valoraciones jurídicas, aunque no vinculantes", "Excluye ayudar al ciudadano a cumplimentar impresos y solicitudes oficiales"]'::jsonb,1,'Art. 4 b) RD 208/1996','La orientación se limita a aclarar conceptos, explicar opciones y ayudar a cumplimentar impresos; no puede entrañar interpretación normativa ni consideración jurídica o económica.',null),
('aux-canarias:13-604ad13d27','aux-canarias',13,'Según el RD 208/1996, la función de gestión de las oficinas de información comprende:','["La resolución de los procedimientos iniciados en la oficina", "La instrucción completa de los expedientes de queja y de sus recursos", "La expedición de cualquier certificado administrativo", "Las gestiones urgentes y sencillas que requieran respuesta inmediata"]'::jsonb,3,'Art. 4 c) RD 208/1996','La gestión incluye recibir la documentación inicial cuando la norma lo prevea y realizar gestiones urgentes y sencillas que requieran una respuesta inmediata.',null),
('aux-canarias:13-dd19548bf2','aux-canarias',13,'Las quejas por tardanzas, desatenciones u otras actuaciones irregulares corresponden, según el RD 208/1996, a la función de:','["Recepción de quejas y reclamaciones", "Recepción de iniciativas y sugerencias", "Orientación e información", "Asistencia en el derecho de petición"]'::jsonb,0,'Art. 4 e) RD 208/1996','El art. 4 e) atribuye a las oficinas la recepción de las quejas por tardanzas, desatenciones o cualquier otro tipo de actuación irregular.',null),
('aux-canarias:13-4f1b58eed8','aux-canarias',13,'Si un ciudadano quiere ejercer el derecho de petición sin saber a quién dirigirlo, según el RD 208/1996 la oficina debe:','["Inadmitir la petición por falta de destinatario", "Archivarla hasta que el propio ciudadano identifique al órgano competente para resolver", "Orientarle y remitir la petición si no tiene destinatario o lo tiene equivocado", "Indicarle que acuda al Defensor del Pueblo"]'::jsonb,2,'Art. 4 f) RD 208/1996','Las unidades deben orientar sobre el ejercicio del derecho de petición y remitir las peticiones que carezcan de destinatario o lo tengan erróneo.',null),
('aux-canarias:13-e3e9afc6e1','aux-canarias',13,'Según el RD 208/1996, la información general se difundirá preferentemente:','["Exclusivamente a través del Boletín Oficial del Estado", "Por medios a distancia, como publicaciones o el teléfono", "Mediante notificación individual a cada interesado", "Solo de forma presencial en las oficinas de atención"]'::jsonb,1,'Art. 2 RD 208/1996','El art. 2.4 manda utilizar los medios adecuados, favoreciendo los que permiten la información a distancia (publicaciones, teléfono y otras tecnologías).',null),
('aux-canarias:13-c4f89634f5','aux-canarias',13,'¿Quién facilita la información particular según el RD 208/1996?','["La Inspección General de Servicios", "El Centro de Información Administrativa", "Las oficinas de registro de cualquier Administración", "Las unidades de gestión que tramitan los procedimientos"]'::jsonb,3,'Art. 3 RD 208/1996','La información particular la facilitan las unidades de gestión; las oficinas de información pueden conectarse con ellas para responder con rapidez.',null),
('aux-canarias:13-fdffd71e37','aux-canarias',13,'Según el RD 208/1996, el Centro de Información Administrativa tiene nivel orgánico de:','["Subdirección General", "Dirección General", "Servicio", "Secretaría General"]'::jsonb,0,'Art. 6 RD 208/1996','El Centro de Información Administrativa tiene nivel orgánico de Subdirección General.',null),
('aux-canarias:13-91dad2ebdb','aux-canarias',13,'Las oficinas centrales de información de los servicios territoriales de la Administración General del Estado dependen, según el RD 208/1996, de:','["Los ayuntamientos de las capitales de provincia", "Las diputaciones provinciales", "Las consejerías de presidencia de las comunidades autónomas", "Las Delegaciones del Gobierno en las comunidades autónomas"]'::jsonb,3,'Art. 9 RD 208/1996','Las oficinas centrales territoriales se integran en las Delegaciones del Gobierno (y en las antiguas Gobiernos Civiles, hoy Subdelegaciones, y Delegaciones Insulares).',null),
('aux-canarias:13-2a005501b5','aux-canarias',13,'Para crear oficinas integradas de información con participación de varias Administraciones, el RD 208/1996 prevé:','["Un convenio de colaboración entre ellas", "Una ley aprobada por las Cortes Generales", "Una orden del ministerio competente", "Un real decreto del Consejo de Ministros"]'::jsonb,0,'Art. 10 RD 208/1996','El art. 10 permite, mediante convenio de colaboración entre Administraciones, intercambiar información o crear oficinas integradas.',null),
('aux-canarias:14-32a5811ba2','aux-canarias',14,'La información de publicidad activa debe publicarse:','["En las sedes electrónicas o páginas web, de forma clara y estructurada, preferiblemente en formatos reutilizables", "En el boletín oficial correspondiente y, si el organismo dispone de ella, también en su página web, en formato no reutilizable", "En el tablón de anuncios físico de cada organismo y en su sede electrónica, en formato papel", "En la página web, pero solo a petición del interesado y en el formato que este elija, sin obligación de que sean reutilizables ni de actualizarla periódicamente"]'::jsonb,0,'Art. 5.4 Ley 19/2013','Se publica en las sedes electrónicas o páginas web, de manera clara, estructurada y entendible, y preferiblemente en formatos reutilizables.',null),
('aux-canarias:14-0296ad34d5','aux-canarias',14,'El Portal de la Transparencia de la Administración General del Estado depende:','["Del Consejo de Transparencia y Buen Gobierno", "Del Ministerio de la Presidencia", "Del Defensor del Pueblo", "De las Cortes Generales"]'::jsonb,1,'Art. 10.1 Ley 19/2013','El Portal de la Transparencia depende del Ministerio de la Presidencia.',null),
('aux-canarias:14-2b1f4dc1c7','aux-canarias',14,'¿Quién tiene derecho a acceder a la información pública según la Ley 19/2013?','["Los ciudadanos españoles y los extranjeros residentes legalmente en España", "Solo quienes tengan la condición de interesados en un procedimiento administrativo", "Todas las personas, en los términos del art. 105.b) de la Constitución", "Los mayores de edad empadronados en España, en los términos de la Ley 39/2015"]'::jsonb,2,'Art. 12 Ley 19/2013','Todas las personas tienen derecho a acceder a la información pública, en los términos del art. 105.b) de la Constitución.',null),
('aux-canarias:14-08bc6e9789','aux-canarias',14,'Según la Ley 19/2013, se entiende por información pública:','["Los documentos publicados en el BOE y en los boletines autonómicos y provinciales", "Los contenidos o documentos en poder de los sujetos obligados, cualquiera que sea su origen, autor o finalidad, incluidos los privados", "Los documentos que los ciudadanos entregan a la Administración en un procedimiento", "Los contenidos o documentos en poder de los sujetos obligados, elaborados o adquiridos en el ejercicio de sus funciones"]'::jsonb,3,'Art. 13 Ley 19/2013','Son los contenidos o documentos, cualquiera que sea su formato o soporte, en poder de los sujetos obligados, elaborados o adquiridos en el ejercicio de sus funciones.',null),
('aux-canarias:14-9f7300baa0','aux-canarias',14,'Al presentar una solicitud de acceso a la información pública, el solicitante:','["No está obligado a motivarla", "Debe motivarla siempre", "Debe acreditar un interés legítimo", "Debe pagar una tasa previa"]'::jsonb,0,'Art. 17.3 Ley 19/2013','El solicitante no está obligado a motivar su solicitud, aunque puede exponer los motivos.',null),
('aux-canarias:14-7e3638fdfc','aux-canarias',14,'¿En qué plazo debe resolverse una solicitud de acceso a la información pública?','["Diez días desde su recepción por el órgano competente, ampliable por otros diez", "Un mes desde su recepción por el órgano competente, ampliable por otro mes", "Tres meses desde su presentación, ampliable por otros tres", "Quince días hábiles desde su presentación, sin posibilidad de ampliación"]'::jsonb,1,'Art. 20.1 Ley 19/2013','El plazo máximo es de un mes desde la recepción por el órgano competente, ampliable por otro mes por el volumen o la complejidad de la información.',null),
('aux-canarias:14-7156abd1d4','aux-canarias',14,'Si no se resuelve en plazo una solicitud de acceso a la información pública, se entiende:','["Estimada", "Caducada", "Desestimada", "Remitida al Consejo de Transparencia"]'::jsonb,2,'Art. 20.4 Ley 19/2013','Transcurrido el plazo sin resolución expresa, la solicitud se entiende desestimada.',null),
('aux-canarias:14-22ae48b433','aux-canarias',14,'El acceso a la información pública es:','["De pago, conforme a las tasas que fije cada Administración", "Gratuito sin excepción alguna, incluidas la expedición de copias y la transposición a otro formato", "Gratuito para las personas físicas y de pago para las empresas", "Gratuito, sin perjuicio de las exacciones por expedición de copias o cambio de formato"]'::jsonb,3,'Art. 22.4 Ley 19/2013','El acceso es gratuito, aunque pueden exigirse exacciones por la expedición de copias o la transposición a formatos distintos del original.',null),
('aux-canarias:14-727234982f','aux-canarias',14,'La reclamación ante el Consejo de Transparencia y Buen Gobierno:','["Es potestativa y previa a la vía contencioso-administrativa, y se presenta en el plazo de un mes", "Es obligatoria y previa a la vía contencioso-administrativa, y se presenta en el plazo de un mes", "Es potestativa y previa a la vía contencioso-administrativa, y se presenta en el plazo de tres meses", "Sustituye al recurso contencioso-administrativo, y se presenta en el plazo de dos meses"]'::jsonb,0,'Art. 24 Ley 19/2013','Es potestativa y previa a la impugnación en vía contencioso-administrativa. Se presenta en el plazo de un mes.',null),
('aux-canarias:14-036883ebdd','aux-canarias',14,'¿En qué plazo debe resolver el Consejo de Transparencia y Buen Gobierno una reclamación?','["Un mes; transcurrido ese plazo sin resolución, se entiende estimada", "Tres meses; transcurrido ese plazo, se entiende desestimada", "Seis meses; transcurrido ese plazo, se entiende desestimada", "Tres meses; transcurrido ese plazo sin resolución expresa, se entiende estimada"]'::jsonb,1,'Art. 24.4 Ley 19/2013','El plazo máximo es de tres meses. Transcurrido sin resolución, la reclamación se entiende desestimada.',null),
('aux-canarias:14-5cb2b7a099','aux-canarias',14,'El Presidente del Consejo de Transparencia y Buen Gobierno es nombrado por un periodo de:','["Cuatro años renovables", "Seis años", "Cinco años no renovable", "Tres años renovables una vez"]'::jsonb,2,'Art. 37.1 Ley 19/2013','Es nombrado por un período no renovable de cinco años.',null),
('aux-canarias:14-a749d2dd58','aux-canarias',14,'¿Cuál de los siguientes es un límite al derecho de acceso a la información pública?','["Que el solicitante no motive su solicitud ni explique para qué la quiere", "Que la información tenga más de cinco años de antigüedad", "Que la información solo esté disponible en formato papel", "Que el acceso suponga un perjuicio para la seguridad nacional"]'::jsonb,3,'Art. 14.1 Ley 19/2013','Entre los límites están la seguridad nacional, la defensa y las relaciones exteriores, entre otros.',null),
('aux-canarias:14-2b60edbc09','aux-canarias',14,'Según la Ley 19/2013, el Consejo de Transparencia y Buen Gobierno es:','["Un organismo público con personalidad jurídica propia", "Una dirección general del Ministerio de Hacienda", "Un órgano de las Cortes Generales", "Un órgano del Poder Judicial"]'::jsonb,0,'Art. 33 Ley 19/2013','Es un organismo público con personalidad jurídica propia y plena capacidad de obrar.',null),
('aux-canarias:14-43dec96ba5','aux-canarias',14,'Las infracciones muy graves de buen gobierno de la Ley 19/2013 prescriben a los:','["Tres años", "Dos años", "Un año", "Cinco años"]'::jsonb,3,'Art. 32 Ley 19/2013','Las graves a los tres años y las leves al año.',null),
('aux-canarias:14-566b61af20','aux-canarias',14,'Entre la información económica que debe publicarse según el art. 8 de la Ley 19/2013 se encuentran:','["Los datos de salud y las bajas laborales de los empleados públicos de cada departamento", "Las nóminas de todos los funcionarios y del personal laboral, con su nombre y puesto de trabajo", "Las declaraciones del IRPF de los ciudadanos", "Las retribuciones percibidas anualmente por los altos cargos y máximos responsables"]'::jsonb,3,'Art. 8.1 f) Ley 19/2013','También contratos, convenios, subvenciones y presupuestos.',null),
('aux-canarias:14-6f73761c03','aux-canarias',14,'Según la Ley 19/2013, la sanción por infracciones muy graves de buen gobierno incluye:','["Una multa de entre 600 y 6.000 euros y una amonestación pública en el boletín oficial correspondiente", "La destitución y la imposibilidad de ser nombrado alto cargo durante un periodo de entre cinco y diez años", "La suspensión de empleo por un día", "Una amonestación"]'::jsonb,1,'Art. 30 Ley 19/2013','Las infracciones leves se sancionan con amonestación.',null),
('aux-canarias:14-5ed4d5e531','aux-canarias',14,'Según la Ley 19/2013, están obligadas a cumplir las obligaciones de publicidad activa las entidades privadas que perciban durante un año ayudas o subvenciones públicas en una cuantía superior a:','["10.000 euros", "100.000 euros", "50.000 euros", "1.000.000 de euros"]'::jsonb,1,'Art. 3 b) Ley 19/2013','O cuando al menos el 40 % de sus ingresos anuales tengan carácter de ayuda pública, con un mínimo de 5.000 euros.',null),
('aux-canarias:14-a8e21948ce','aux-canarias',14,'El Consejo de Transparencia y Buen Gobierno se estructura en:','["Un Pleno y una Junta de Portavoces de los grupos parlamentarios del Congreso", "Una Sala de lo Contencioso y una Sala de lo Penal", "La Comisión de Transparencia y Buen Gobierno y el Presidente del Consejo", "Un Presidente, un Vicepresidente y una Secretaría General, con un Pleno de doce miembros"]'::jsonb,2,'Art. 35 Ley 19/2013','La Comisión incluye, entre otros, un Diputado y un Senador.',null),
('aux-canarias:14-42f8c76696','aux-canarias',14,'Forman parte de la Comisión de Transparencia y Buen Gobierno, entre otros:','["Un Diputado, un Senador, un representante del Tribunal de Cuentas y uno del Defensor del Pueblo", "Los Presidentes de las Comunidades Autónomas", "Los Alcaldes de capitales de provincia", "Un Diputado, un Senador, un representante del Consejo General del Poder Judicial y uno del Tribunal Supremo"]'::jsonb,0,'Art. 36.2 Ley 19/2013','También representantes de la AEPD, de la Secretaría de Estado de Administraciones Públicas y de la AIReF.',null),
('aux-canarias:14-9184eb51f9','aux-canarias',14,'Si la información solicitada puede afectar a derechos o intereses de terceros, se les concederá para alegaciones un plazo de:','["Cinco días", "Diez días", "Un mes", "Quince días"]'::jsonb,3,'Art. 19.3 Ley 19/2013','El plazo para resolver se suspende hasta recibir las alegaciones o transcurrir el plazo.',null),
('aux-canarias:14-7180ba8685','aux-canarias',14,'Según la Ley 19/2013, se inadmitirán a trámite las solicitudes de acceso:','["Presentadas por personas extranjeras no residentes en España o por quien no acredite un interés legítimo directo", "Que no estén motivadas o en las que el solicitante no acredite un interés directo en la información", "Relativas a información que tenga carácter auxiliar o de apoyo, como notas, borradores u opiniones", "Presentadas por personas jurídicas o por entidades sin personalidad jurídica"]'::jsonb,2,'Art. 18.1 b) Ley 19/2013','También las que requieran reelaboración, las referidas a información en elaboración o las manifiestamente repetitivas o abusivas.',null),
('aux-canarias:14-70adcdf014','aux-canarias',14,'Si el acceso a la información no puede realizarse en el momento de la notificación de la resolución, deberá otorgarse en un plazo no superior a:','["Quince días", "Diez días", "Un mes", "Tres días"]'::jsonb,1,'Art. 22.1 Ley 19/2013','El acceso se realizará preferentemente por vía electrónica.',null),
('aux-canarias:14-d48e95f2e9','aux-canarias',14,'Según el art. 23 de la Ley 19/2013, la reclamación ante el Consejo de Transparencia y Buen Gobierno:','["No tiene efectos", "Es previa y obligatoria al recurso de alzada", "Sustituye a los recursos administrativos", "Es posterior al recurso de reposición"]'::jsonb,2,'Art. 23.1 Ley 19/2013','Tiene la consideración de sustitutiva de los recursos administrativos.',null),
('aux-canarias:14-9572807c35','aux-canarias',14,'¿Qué ley estatal regula la transparencia de la actividad pública y el derecho de acceso a la información?','["La Ley 19/2013, de 9 de diciembre", "La LO 3/2018, de 5 de diciembre", "La Ley 39/2015, de 1 de octubre", "La Ley 37/2007, de 16 de noviembre"]'::jsonb,0,'Ley 19/2013','La Ley 37/2007 regula la reutilización de la información del sector público y la LO 3/2018, la protección de datos.',null),
('aux-canarias:14-026820d73c','aux-canarias',14,'Según el artículo 6 de la Ley 19/2013, los sujetos obligados deben publicar, como información institucional y organizativa:','["Las funciones que desarrollan, la normativa que les sea de aplicación y su estructura organizativa", "Los expedientes de los procedimientos sancionadores que tramiten", "Las retribuciones de todos los empleados públicos, con su nombre y apellidos", "Las actas completas de todas las reuniones de sus órganos colegiados"]'::jsonb,0,'Art. 6.1 Ley 19/2013','Incluyen un organigrama actualizado que identifique a los responsables de los diferentes órganos y su perfil y trayectoria profesional.',null),
('aux-canarias:14-d63e957a8f','aux-canarias',14,'Según el artículo 7 de la Ley 19/2013, ¿qué información de relevancia jurídica debe publicarse?','["Los informes de los servicios jurídicos sobre cualquier asunto en tramitación", "Las denuncias presentadas por los ciudadanos contra las autoridades", "Los anteproyectos de ley y los proyectos de reglamento, entre otros documentos", "Las sentencias firmes dictadas contra la Administración en los últimos cinco años"]'::jsonb,2,'Art. 7 Ley 19/2013','También las directrices, instrucciones y circulares que supongan una interpretación del Derecho o tengan efectos jurídicos y las memorias e informes de los expedientes normativos.',null),
('aux-canarias:14-b067189a4e','aux-canarias',14,'Según la Ley 19/2013, ¿deben publicarse las retribuciones percibidas anualmente por los altos cargos?','["Sí, como información económica, presupuestaria y estadística", "No, porque son datos personales protegidos", "Solo si lo solicita un ciudadano mediante el derecho de acceso", "Las de los Ministros y Secretarios de Estado, pero no las del resto"]'::jsonb,0,'Art. 8.1 f) Ley 19/2013','También se publican las indemnizaciones percibidas con ocasión del abandono del cargo.',null),
('aux-canarias:14-6d055296e7','aux-canarias',14,'¿Cuándo entraron en vigor los títulos preliminar, I y III de la Ley 19/2013 para la Administración General del Estado?','["A los dos años de su publicación en el Boletín Oficial del Estado", "A los seis meses de su publicación en el Boletín Oficial del Estado", "Al año de su publicación en el Boletín Oficial del Estado", "Al día siguiente de su publicación en el Boletín Oficial del Estado"]'::jsonb,2,'Disposición final novena Ley 19/2013','El título II (buen gobierno) entró en vigor al día siguiente de su publicación. Las CCAA y Entidades Locales tuvieron dos años para adaptarse.',null),
('aux-canarias:14-22431bd1dc','aux-canarias',14,'El título II de la Ley 19/2013 regula:','["El buen gobierno", "La publicidad activa", "El derecho de acceso a la información pública", "El Consejo de Transparencia y Buen Gobierno"]'::jsonb,0,'Ley 19/2013','El título I regula la transparencia (publicidad activa y derecho de acceso) y el título III el Consejo de Transparencia y Buen Gobierno.',null),
('aux-canarias:14-d9328d014f','aux-canarias',14,'Cuando un límite al derecho de acceso no afecte a la totalidad de la información solicitada:','["Se deniega el acceso a la totalidad de la información, aunque el límite afecte solo a una parte de ella, para evitar que se conozca el resto", "Se remite la solicitud al Consejo de Transparencia y Buen Gobierno", "Se suspende el procedimiento hasta que el límite deje de aplicarse y se notifica esta circunstancia al solicitante y a los terceros afectados", "Se concede el acceso parcial, omitiendo la información afectada por el límite, salvo que resulte una información distorsionada o sin sentido"]'::jsonb,3,'Art. 16 Ley 19/2013','Debe indicarse al solicitante qué parte de la información ha sido omitida.',null),
('aux-canarias:14-7e76ccf793','aux-canarias',14,'Según la Ley 19/2013, la solicitud de acceso que se refiera a información cuya divulgación requiera una acción previa de reelaboración:','["Se inadmitirá a trámite mediante resolución motivada", "Se remitirá al órgano que elaboró la información originalmente", "Se tramitará con un plazo ampliado de tres meses", "Se estimará, pero el solicitante deberá abonar el coste de la reelaboración"]'::jsonb,0,'Art. 18.1 c) Ley 19/2013','Es una de las causas de inadmisión, junto con la información en curso de elaboración o de carácter auxiliar, entre otras.',null),
('aux-canarias:14-c357dfc528','aux-canarias',14,'Si la solicitud de acceso se refiere a información que no obre en poder del sujeto al que se dirige:','["Este la archivará y el solicitante deberá presentar una nueva solicitud ante el órgano que corresponda", "Este deberá recabar la información del órgano que la posea y resolver la solicitud en el plazo ordinario", "Este la remitirá al competente, si lo conoce, e informará de esta circunstancia al solicitante", "Este la inadmitirá a trámite, aunque conozca cuál es el órgano o entidad competente para resolver"]'::jsonb,2,'Art. 19.1 Ley 19/2013','Si desconoce el órgano competente, procede la inadmisión.',null),
('aux-canarias:14-471506dc8a','aux-canarias',14,'El plazo para resolver una solicitud de acceso a la información puede ampliarse:','["Por tres meses más, sin necesidad de comunicarlo previamente al solicitante, cuando así lo acuerde el titular del órgano que debe resolver", "No puede ampliarse, porque es un plazo improrrogable", "Por otro mes, en el caso de que el volumen o la complejidad de la información lo hagan necesario, previa notificación al solicitante", "Por quince días hábiles, solo si hay terceros afectados"]'::jsonb,2,'Art. 20.1 Ley 19/2013','El plazo ordinario es de un mes desde la recepción de la solicitud por el órgano competente.',null),
('aux-canarias:14-4a51c7a92a','aux-canarias',14,'Según la Ley 19/2013, ¿qué resoluciones sobre el derecho de acceso deben ser motivadas?','["Las que denieguen totalmente el acceso a la información", "Todas las resoluciones, tanto si conceden como si deniegan el acceso", "Las que denieguen el acceso, las que concedan el acceso parcial o a través de una modalidad distinta a la solicitada y las que permitan el acceso con oposición de un tercero", "Las que concedan el acceso, porque afectan a la confidencialidad de la información"]'::jsonb,2,'Art. 20.2 Ley 19/2013','Así lo exige el artículo 20.2.',null),
('aux-canarias:14-5530fdd4fa','aux-canarias',14,'El acceso a la información pública, según la Ley 19/2013:','["Es gratuito, aunque la expedición de copias o la transposición a formatos diferentes del original puede dar lugar a exacciones", "Es gratuito solo para los ciudadanos españoles residentes en España", "Está sujeto al pago de una tasa por cada solicitud presentada, cuya cuantía fija cada año la Ley de Presupuestos Generales del Estado", "Es gratuito, incluida también la expedición de copias en papel o en soporte electrónico y la transposición a otros formatos"]'::jsonb,0,'Art. 22.4 Ley 19/2013','La forma preferente de acceso es la electrónica.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-canarias:14-871a129bec','aux-canarias',14,'¿Qué unidades deben existir en la Administración General del Estado para facilitar el conocimiento y acceso a la información pública?','["Delegaciones de protección de datos", "Unidades de información", "Oficinas de asistencia en materia de registros", "Inspecciones generales de servicios"]'::jsonb,1,'Art. 21 Ley 19/2013','Se encargan, entre otras funciones, de recabar y difundir la información de publicidad activa y de recibir y tramitar las solicitudes de acceso.',null),
('aux-canarias:14-f4e3e784f6','aux-canarias',14,'Según la Ley 19/2013, la información de publicidad activa se publicará:','["De forma periódica y actualizada, en las sedes electrónicas o páginas web, de una manera clara, estructurada y entendible y preferiblemente en formatos reutilizables", "Cuando lo solicite cualquier ciudadano por escrito", "Una vez al año, en el Boletín Oficial del Estado y en los diarios oficiales de las Comunidades Autónomas, en un anexo específico que recoja toda la información obligatoria", "En el tablón de anuncios físico de cada órgano"]'::jsonb,0,'Arts. 5.1 y 5.4 Ley 19/2013','Se establecen los mecanismos adecuados para facilitar la accesibilidad, la interoperabilidad y la calidad de la información.',null),
('aux-canarias:14-fe775bee9b','aux-canarias',14,'Según el artículo 26 de la Ley 19/2013, ¿cuál de los siguientes es un principio general de actuación de los altos cargos?','["Mantener en secreto todas sus reuniones con grupos de interés", "Actuar con transparencia en la gestión de los asuntos públicos", "Afiliarse obligatoriamente a un partido político", "Percibir una retribución acorde con la de su sector privado de origen"]'::jsonb,1,'Art. 26.2 a) Ley 19/2013','Otros principios son la dedicación al servicio público, la imparcialidad, la igualdad de trato y la diligencia.',null),
('aux-canarias:15-60fe65de09','aux-canarias',15,'La LO 3/2018 de Protección de Datos tiene por objeto:','["Sustituir al Reglamento (UE) 2016/679 y regular los derechos digitales", "Adaptar el ordenamiento español al Reglamento (UE) 2016/679 y garantizar los derechos digitales", "Trasponer la Directiva 95/46/CE y regular la videovigilancia", "Adaptar el ordenamiento al Reglamento (UE) 2016/679, pero sin regular los llamados derechos digitales"]'::jsonb,1,'Art. 1 LO 3/2018','Adapta el ordenamiento al Reglamento (UE) 2016/679 y garantiza los derechos digitales conforme al art. 18.4 de la Constitución.',null),
('aux-canarias:15-9f12594032','aux-canarias',15,'El deber de confidencialidad de quienes intervienen en el tratamiento de datos:','["Termina al finalizar la relación con el responsable", "Dura un año tras finalizar la relación", "Se mantiene aun cuando haya finalizado la relación", "Solo afecta al responsable del tratamiento"]'::jsonb,2,'Art. 5 LO 3/2018','Afecta a responsables, encargados y demás intervinientes, y se mantiene aun cuando haya finalizado la relación.',null),
('aux-canarias:15-132d01abab','aux-canarias',15,'¿Cómo define la LO 3/2018 el consentimiento del afectado?','["Toda manifestación de voluntad libre, informada e inequívoca, aunque sea tácita o derive del silencio", "Toda manifestación de voluntad expresa y por escrito, firmada en papel o electrónicamente", "La aceptación tácita de las condiciones, siempre que se haya informado previamente", "Toda manifestación de voluntad libre, específica, informada e inequívoca"]'::jsonb,3,'Art. 6.1 LO 3/2018','Es toda manifestación de voluntad libre, específica, informada e inequívoca, mediante una declaración o una clara acción afirmativa.',null),
('aux-canarias:15-147ae3b86e','aux-canarias',15,'El tratamiento de los datos de un menor puede basarse en su propio consentimiento cuando sea mayor de:','["Catorce años", "Dieciséis años", "Doce años", "Dieciocho años"]'::jsonb,0,'Art. 7.1 LO 3/2018','Solo cuando sea mayor de catorce años, salvo que la ley exija la asistencia de los titulares de la patria potestad o tutela.',null),
('aux-canarias:15-cbbdb206bc','aux-canarias',15,'¿Basta el consentimiento del afectado para tratar datos cuya finalidad principal sea identificar su ideología o religión?','["Sí, siempre", "No, el solo consentimiento no basta para levantar la prohibición", "Sí, si es por escrito", "Solo si lo autoriza la Agencia Española de Protección de Datos"]'::jsonb,1,'Art. 9.1 LO 3/2018','El solo consentimiento no basta para tratar datos cuya finalidad principal sea identificar ideología, afiliación sindical, religión, orientación sexual, creencias u origen racial o étnico.',null),
('aux-canarias:15-2e3b62a5b1','aux-canarias',15,'Los artículos 13 a 18 de la LO 3/2018 regulan los derechos de:','["Petición, queja, sugerencia, acceso a archivos y registros públicos, y reclamación ante la Agencia", "Acceso a la información pública, rectificación, reclamación y oposición", "Acceso, rectificación, supresión, limitación del tratamiento, portabilidad y oposición", "Rectificación, réplica, supresión y olvido en medios de comunicación"]'::jsonb,2,'Arts. 13 a 18 LO 3/2018','Regulan, en este orden, los derechos de acceso, rectificación, supresión, limitación del tratamiento, portabilidad y oposición.',null),
('aux-canarias:15-caa6d790f2','aux-canarias',15,'¿Cuándo deben designar un delegado de protección de datos los responsables y encargados del tratamiento?','["Solo cuando tengan más de 250 empleados o traten datos de más de 10.000 personas", "En ningún caso es obligatorio, aunque la ley recomienda su designación a las entidades públicas", "Solo cuando lo requiera expresamente la Agencia Española de Protección de Datos", "En los supuestos del art. 37.1 del Reglamento (UE) 2016/679 y en las entidades que enumera la ley"]'::jsonb,3,'Art. 34.1 LO 3/2018','Deben designarlo en los supuestos del art. 37.1 del Reglamento europeo y, en todo caso, en las entidades que enumera el propio artículo.',null),
('aux-canarias:15-40f63e581a','aux-canarias',15,'La Agencia Española de Protección de Datos es:','["Una autoridad administrativa independiente de ámbito estatal", "Una dirección general adscrita al Ministerio del Interior, sin personalidad jurídica", "Un órgano adscrito al Consejo General del Poder Judicial", "Una agencia de la Unión Europea con sede en España"]'::jsonb,0,'Art. 44.1 LO 3/2018','Es una autoridad administrativa independiente de ámbito estatal.',null),
('aux-canarias:15-5fbf3d0931','aux-canarias',15,'El mandato de la Presidencia de la Agencia Española de Protección de Datos es de:','["Cuatro años, no renovable", "Cinco años, renovable por otro periodo de igual duración", "Seis años, no renovable, contados desde su toma de posesión", "Cuatro años, renovable por otro periodo de igual duración"]'::jsonb,1,'Art. 48.5 LO 3/2018','El mandato es de cinco años y puede renovarse por otro periodo de igual duración.',null),
('aux-canarias:15-b43c8ab844','aux-canarias',15,'¿Cuándo prescriben las infracciones leves en materia de protección de datos?','["A los seis meses", "A los dos años", "Al año", "A los tres años"]'::jsonb,2,'Art. 74 LO 3/2018','Las infracciones muy graves prescriben a los tres años (art. 72), las graves a los dos años (art. 73) y las leves al año (art. 74).',null),
('aux-canarias:15-212ff18573','aux-canarias',15,'Las sanciones de protección de datos de importe superior a 300.000 euros prescriben a:','["Al año", "Los dos años", "Los seis meses", "Los tres años"]'::jsonb,3,'Art. 78.1 LO 3/2018','Hasta 40.000 € prescriben al año; entre 40.001 y 300.000 €, a los dos años; y las superiores a 300.000 €, a los tres años.',null),
('aux-canarias:15-b43e7b614d','aux-canarias',15,'¿Se aplica el régimen sancionador de la LO 3/2018 al delegado de protección de datos?','["No", "Sí, en todo caso", "Solo por infracciones muy graves", "Solo si es personal laboral"]'::jsonb,0,'Art. 70.2 LO 3/2018','El régimen sancionador de la ley no es de aplicación al delegado de protección de datos.',null),
('aux-canarias:15-eeab76985c','aux-canarias',15,'Los herederos de una persona fallecida, ¿pueden solicitar el acceso, la rectificación o la supresión de sus datos?','["No, salvo que el fallecido lo hubiese autorizado expresamente en vida", "Sí, salvo que el fallecido lo hubiese prohibido expresamente o lo establezca una ley", "Sí, pero solo con autorización judicial y acreditando un interés legítimo", "Sí, durante el primer año tras el fallecimiento, salvo prohibición expresa del fallecido"]'::jsonb,1,'Art. 3.1 LO 3/2018','Pueden hacerlo las personas vinculadas al fallecido por razones familiares o de hecho y sus herederos, salvo prohibición expresa del fallecido o de una ley.',null),
('aux-canarias:15-610f97318e','aux-canarias',15,'El derecho al olvido en búsquedas de Internet permite pedir a los motores de búsqueda:','["Que eliminen de los resultados de una búsqueda por el nombre los enlaces a información inadecuada, inexacta, no pertinente, no actualizada o excesiva", "Que paguen una indemnización automática", "Que borren la página web original en todo caso, junto con todas sus copias y enlaces, aunque la información sea exacta, pertinente y actualizada y su difusión sea lícita", "Que cierren la cuenta del usuario"]'::jsonb,0,'Art. 93.1 LO 3/2018','Es el derecho al olvido frente a buscadores.',null),
('aux-canarias:15-0a7b2cc125','aux-canarias',15,'El acceso a los contenidos gestionados por prestadores de servicios digitales de personas fallecidas se regula en la LO 3/2018 como:','["Testamento digital", "Herencia yacente", "Derecho de rectificación", "Derecho de portabilidad"]'::jsonb,0,'Art. 96 LO 3/2018','Salvo que el fallecido lo hubiese prohibido expresamente.',null),
('aux-canarias:15-e8ac1fa4cb','aux-canarias',15,'En ningún caso se admitirá la instalación de sistemas de grabación de sonidos o videovigilancia en:','["Las entradas de los edificios", "Los aparcamientos", "Lugares destinados al descanso o esparcimiento de los trabajadores, como vestuarios, aseos o comedores", "Las zonas de caja y de atención al público, aunque se informe previamente a los trabajadores"]'::jsonb,2,'Art. 89.2 LO 3/2018','Protección de la intimidad en el trabajo.',null),
('aux-canarias:15-2932e50702','aux-canarias',15,'En los sistemas de información crediticia, los datos solo pueden mantenerse mientras persista el incumplimiento, con el límite máximo de:','["Cinco años desde la fecha de vencimiento de la obligación", "Diez años", "Un año", "Seis años desde la fecha de inclusión en el sistema"]'::jsonb,0,'Art. 20.1 d) LO 3/2018','Límite temporal de los ficheros de morosos.',null),
('aux-canarias:15-ad40b0420e','aux-canarias',15,'Quienes pretendan realizar comunicaciones de mercadotecnia directa deben consultar previamente:','["El censo electoral", "El Registro Civil", "El padrón municipal de habitantes y el censo de empresas", "Los sistemas de exclusión publicitaria"]'::jsonb,3,'Art. 23.4 LO 3/2018','Salvo que el afectado haya prestado su consentimiento a recibirlas.',null),
('aux-canarias:15-2e99b68be2','aux-canarias',15,'El tratamiento de los datos de un menor de catorce años fundado en el consentimiento solo es lícito si consta:','["El consentimiento del propio menor, si tiene madurez suficiente", "El consentimiento del titular de la patria potestad o tutela", "El consentimiento del centro escolar", "Una autorización judicial en todo caso"]'::jsonb,1,'Art. 7.2 LO 3/2018','A partir de los 14 años el menor puede consentir por sí mismo.',null),
('aux-canarias:15-5ec8990bc1','aux-canarias',15,'La prueba del cumplimiento del deber de responder a la solicitud de ejercicio de derechos corresponde a:','["El encargado del tratamiento", "La AEPD", "El responsable del tratamiento", "El afectado"]'::jsonb,2,'Art. 12.4 LO 3/2018','La carga de la prueba recae en el responsable.',null),
('aux-canarias:15-06bedcbb73','aux-canarias',15,'El procedimiento sancionador en materia de protección de datos tendrá una duración máxima de:','["Doce meses desde la fecha del acuerdo de inicio", "Dos años desde la fecha de la reclamación del interesado", "Seis meses desde la fecha de presentación de la denuncia", "Tres meses"]'::jsonb,0,'Art. 64.2 LO 3/2018','Así lo establece el art. 64.2.',null),
('aux-canarias:15-4a227edf56','aux-canarias',15,'El plazo para resolver el procedimiento cuando se reclama exclusivamente la falta de atención de una solicitud de ejercicio de derechos es de:','["Un mes", "Doce meses", "Tres meses", "Seis meses"]'::jsonb,3,'Art. 64.1 LO 3/2018','El procedimiento sancionador tiene una duración máxima de doce meses (art. 64.2).',null),
('aux-canarias:15-db5e86f90a','aux-canarias',15,'Las imágenes captadas por sistemas de videovigilancia deben suprimirse, con carácter general, en el plazo máximo de:','["Una semana desde su captación", "Un mes desde su captación", "Tres meses desde su captación", "Un año desde su captación"]'::jsonb,1,'Art. 22.3 LO 3/2018','Salvo que deban conservarse para acreditar actos contra personas, bienes o instalaciones.',null),
('aux-canarias:15-f263f49957','aux-canarias',15,'Según el art. 2.2 de la LO 3/2018, la ley NO se aplica, sin perjuicio de su art. 3, a:','["Los tratamientos de las Administraciones Públicas", "Los datos de menores", "Los tratamientos de datos de personas fallecidas", "Los datos de salud"]'::jsonb,2,'Art. 2.2 LO 3/2018','También quedan excluidos los tratamientos fuera del RGPD y las materias clasificadas.',null),
('aux-canarias:15-f054c15edb','aux-canarias',15,'La Presidencia y el Adjunto de la AEPD son nombrados:','["Por elección directa de los ciudadanos entre los candidatos propuestos por el Congreso, el Senado y el Consejo General del Poder Judicial, por cinco años", "Por el Consejo de Ministros mediante real decreto, a propuesta del Gobierno y tras su ratificación por la Comisión de Justicia del Congreso", "Por el Consejo General del Poder Judicial", "Por el Rey a propuesta del Senado, por mayoría de tres quintos, tras una comparecencia pública ante la Comisión Constitucional y previo informe favorable del Consejo de Estado"]'::jsonb,1,'Art. 48.3 LO 3/2018','El mandato es de cinco años renovable.',null),
('aux-canarias:15-2e11897d45','aux-canarias',15,'Las actuaciones del responsable para atender las solicitudes de ejercicio de derechos serán, con carácter general:','["De pago obligatorio", "Gratuitas solo para menores", "Sujetas a tasa estatal", "Gratuitas"]'::jsonb,3,'Art. 12.7 LO 3/2018','Sin perjuicio de lo dispuesto en el RGPD para solicitudes infundadas o excesivas.',null),
('aux-canarias:15-908a0a9bf7','aux-canarias',15,'Las infracciones graves en materia de protección de datos prescriben a los:','["Seis meses", "Tres años", "Dos años", "Un año"]'::jsonb,2,'Art. 73 LO 3/2018','Las muy graves a los tres años.',null),
('aux-canarias:15-84c707ffc9','aux-canarias',15,'Según el art. 81 de la LO 3/2018:','["Solo los mayores de edad pueden acceder a Internet", "Todos tienen derecho a acceder a Internet independientemente de su condición personal, social, económica o geográfica", "El acceso a Internet depende de autorización administrativa", "Todos tienen derecho a acceder a Internet, salvo las limitaciones que establezca cada prestador por razones económicas o geográficas"]'::jsonb,1,'Art. 81.1 LO 3/2018','Derecho de acceso universal a Internet.',null),
('aux-canarias:15-c989cd8f9a','aux-canarias',15,'Las infracciones muy graves en materia de protección de datos prescriben a los:','["Un año", "Tres años", "Dos años", "Cinco años"]'::jsonb,1,'Art. 72.1 LO 3/2018','Las graves a los dos años y las leves al año.',null),
('aux-canarias:15-dd0d8e1811','aux-canarias',15,'Los responsables y encargados deben comunicar a la AEPD o autoridad autonómica las designaciones, nombramientos y ceses de los delegados de protección de datos en el plazo de:','["Un mes", "Tres días", "Diez días", "Quince días"]'::jsonb,2,'Art. 34.3 LO 3/2018','Plazo de diez días.',null),
('aux-canarias:15-6f5c896bf7','aux-canarias',15,'El derecho a la desconexión digital garantiza a los trabajadores y empleados públicos:','["El uso libre de redes sociales en el trabajo", "Que puedan desconectar los dispositivos de la oficina durante la jornada laboral cuando lo consideren necesario para concentrarse en sus tareas", "Que no se use el correo electrónico en la empresa", "El respeto de su tiempo de descanso, permisos y vacaciones fuera del tiempo de trabajo legal o convencionalmente establecido"]'::jsonb,3,'Art. 88.1 LO 3/2018','El empleador debe elaborar una política interna, previa audiencia de los representantes.',null),
('aux-canarias:15-20e26061c7','aux-canarias',15,'El ejercicio del derecho de acceso más de una vez durante el plazo de ___ podrá considerarse repetitivo, salvo causa legítima:','["Seis meses", "Tres meses", "Un año", "Un mes"]'::jsonb,0,'Art. 13.3 LO 3/2018','Así lo dispone el art. 13.3.',null),
('aux-canarias:15-97ec0cf29d','aux-canarias',15,'Transcurrido el plazo de prescripción de las posibles responsabilidades, los datos bloqueados deberán ser:','["Destruidos", "Transferidos a la AEPD", "Publicados", "Conservados indefinidamente"]'::jsonb,0,'Art. 32.2 LO 3/2018','El bloqueo es temporal hasta la prescripción.',null),
('aux-canarias:15-88ae4c7109','aux-canarias',15,'Si el afectado presenta una reclamación previa ante el delegado de protección de datos, este deberá comunicar su decisión en el plazo máximo de:','["Un mes", "Diez días", "Seis meses", "Dos meses"]'::jsonb,3,'Art. 37.1 LO 3/2018','Si la AEPD remite la reclamación al delegado, este responde en un mes (art. 37.2).',null),
('aux-canarias:16-f47cd59342','aux-canarias',16,'Según la Ley 40/2015, ¿qué carácter tiene la competencia de los órganos administrativos?','["Delegable en todo caso", "Renunciable con autorización del superior", "Transferible a otras Administraciones por convenio", "Irrenunciable"]'::jsonb,3,'Art. 8.1 Ley 40/2015','La competencia es irrenunciable y se ejerce por los órganos que la tengan atribuida como propia, salvo delegación o avocación.',null),
('aux-canarias:16-d44978bba0','aux-canarias',16,'¿Cuál de estas técnicas sí altera la titularidad de la competencia?','["La desconcentración", "La delegación de competencias", "La delegación de firma", "La encomienda de gestión"]'::jsonb,0,'Art. 8 Ley 40/2015','La delegación, la encomienda, la delegación de firma y la suplencia no alteran la titularidad; la desconcentración transfiere titularidad y ejercicio a órganos dependientes.',null),
('aux-canarias:16-16e34fe36b','aux-canarias',16,'Si una norma atribuye una competencia a una Administración sin especificar el órgano, ¿a quién corresponde instruir y resolver?','["Al órgano superior de esa Administración por razón de la materia, en todo caso y sin excepción", "A los órganos inferiores competentes por razón de la materia y del territorio", "Al órgano que designe en cada caso el titular del departamento ministerial correspondiente", "Al órgano que primero conozca del asunto"]'::jsonb,1,'Art. 8.3 Ley 40/2015','Corresponde a los órganos inferiores competentes por materia y territorio; si hay varios, a su superior jerárquico común.',null),
('aux-canarias:16-9ed25a2ebd','aux-canarias',16,'¿Puede delegarse la competencia para adoptar disposiciones de carácter general?','["Sí, en órganos dependientes jerárquicamente", "Sí, si lo autoriza el superior jerárquico", "Solo en el ámbito de la Administración local", "No, en ningún caso"]'::jsonb,3,'Art. 9.2 b) Ley 40/2015','No pueden delegarse las competencias relativas a la adopción de disposiciones de carácter general.',null),
('aux-canarias:16-f8c4059be6','aux-canarias',16,'¿Puede delegarse la resolución de recursos en el mismo órgano que dictó el acto recurrido?','["Sí, si el recurso es de reposición", "Sí, con publicación en el boletín oficial", "No, está expresamente prohibido", "Solo si lo prevé el reglamento orgánico"]'::jsonb,2,'Art. 9.2 c) Ley 40/2015','No pueden delegarse las competencias relativas a la resolución de recursos en los órganos que hayan dictado los actos recurridos.',null),
('aux-canarias:16-2ed20d492e','aux-canarias',16,'¿Dónde deben publicarse las delegaciones de competencias de un órgano de la Comunidad Autónoma de Canarias?','["No necesitan publicación", "En el Boletín Oficial del Estado", "En el Boletín Oficial de Canarias", "En el tablón de anuncios del órgano"]'::jsonb,2,'Art. 9.3 Ley 40/2015','Las delegaciones y su revocación se publican en el boletín de la Administración a que pertenezca el órgano delegante: para Canarias, el BOC.',null),
('aux-canarias:16-e999be6899','aux-canarias',16,'¿A qué órgano se consideran dictadas las resoluciones adoptadas por delegación?','["A ambos de forma solidaria", "Al órgano delegado", "Al superior jerárquico común", "Al órgano delegante"]'::jsonb,3,'Art. 9.4 Ley 40/2015','Las resoluciones adoptadas por delegación indicarán esta circunstancia y se considerarán dictadas por el órgano delegante.',null),
('aux-canarias:16-c2337cb4c8','aux-canarias',16,'¿Pueden delegarse las competencias que se ejercen por delegación?','["No, salvo autorización expresa de una ley", "No, en ningún caso, ni siquiera por ley", "Sí, con consentimiento del delegante", "Sí, siempre que se publique"]'::jsonb,0,'Art. 9.5 Ley 40/2015','Salvo autorización expresa de una ley, no podrán delegarse las competencias que se ejerzan por delegación.',null),
('aux-canarias:16-c773bbca8b','aux-canarias',16,'¿Cuándo puede revocarse una delegación de competencias?','["Previa audiencia del órgano delegado", "En cualquier momento, por el órgano que la confirió", "Solo al finalizar el plazo fijado", "Solo por el superior jerárquico del delegante"]'::jsonb,1,'Art. 9.6 Ley 40/2015','La delegación es revocable en cualquier momento por el órgano que la haya conferido.',null),
('aux-canarias:16-dd5e8713bf','aux-canarias',16,'¿Cabe recurso contra el acuerdo de avocación?','["Sí, recurso de alzada ante el superior jerárquico del órgano que haya acordado la avocación", "Solo recurso contencioso-administrativo directo", "No, aunque puede impugnarse en el recurso contra la resolución del procedimiento", "Sí, recurso potestativo de reposición"]'::jsonb,2,'Art. 10.2 Ley 40/2015','Contra el acuerdo de avocación no cabe recurso, aunque puede impugnarse en el que se interponga contra la resolución final.',null),
('aux-canarias:16-7ffc2de04e','aux-canarias',16,'¿Qué requisito formal debe cumplir la avocación?','["Publicación en el boletín oficial correspondiente antes de que surta efecto la avocación", "Acuerdo motivado notificado a los interesados antes o a la vez que la resolución final", "Informe previo del órgano delegado", "Autorización del órgano colegiado superior"]'::jsonb,1,'Art. 10.2 Ley 40/2015','La avocación se realiza mediante acuerdo motivado notificado a los interesados con anterioridad o simultáneamente a la resolución final.',null),
('aux-canarias:16-f720a5f3fb','aux-canarias',16,'En una delegación en órganos no dependientes jerárquicamente, ¿quién puede avocar un asunto?','["Cualquier órgano superior", "El órgano delegado, devolviéndolo", "El superior jerárquico del órgano delegado", "Únicamente el órgano delegante"]'::jsonb,3,'Art. 10.1 Ley 40/2015','En la delegación en órganos no dependientes jerárquicamente, solo puede avocar el órgano delegante.',null),
('aux-canarias:16-5112b15dd4','aux-canarias',16,'¿Qué puede ser objeto de encomienda de gestión?','["Actividades de carácter material o técnico", "La adopción de disposiciones generales", "La resolución de procedimientos", "Prestaciones propias de los contratos del sector público"]'::jsonb,0,'Art. 11.1 Ley 40/2015','Se encomienda la realización de actividades de carácter material o técnico; no puede tener por objeto prestaciones propias de los contratos.',null),
('aux-canarias:16-65d8fb8381','aux-canarias',16,'En una encomienda de gestión, ¿qué condición tiene el órgano encomendado respecto de los datos personales?','["Corresponsable del tratamiento", "Encargado del tratamiento", "Responsable del tratamiento", "Delegado de protección de datos"]'::jsonb,1,'Art. 11.2 Ley 40/2015','El órgano o entidad encomendado tiene la condición de encargado del tratamiento de los datos personales.',null),
('aux-canarias:16-238695f7f2','aux-canarias',16,'¿Cómo se formaliza una encomienda de gestión entre órganos de distintas Administraciones?','["Por resolución del órgano encomendado", "Por acuerdo verbal de los titulares", "Mediante convenio publicado en el boletín oficial correspondiente", "Mediante contrato administrativo de servicios adjudicado sin publicidad"]'::jsonb,2,'Art. 11.3 b) Ley 40/2015','Entre distintas Administraciones se formaliza mediante convenio, que debe publicarse en el boletín correspondiente.',null),
('aux-canarias:16-1008428310','aux-canarias',16,'¿Necesita publicación la delegación de firma para su validez?','["Sí, en el boletín oficial correspondiente", "Solo si afecta a resoluciones sancionadoras", "Sí, en el tablón de edictos", "No"]'::jsonb,3,'Art. 12.2 Ley 40/2015','La delegación de firma no altera la competencia del delegante y para su validez no es necesaria su publicación.',null),
('aux-canarias:16-3530b254bf','aux-canarias',16,'¿En quién puede delegarse la firma de resoluciones y actos?','["En los titulares de órganos o unidades que dependan del delegante", "En cualquier funcionario de la Administración", "En órganos de otras Administraciones", "Solo en el superior jerárquico"]'::jsonb,0,'Art. 12.1 Ley 40/2015','La firma puede delegarse en los titulares de los órganos o unidades administrativas que dependan del delegante.',null),
('aux-canarias:16-4018630311','aux-canarias',16,'Si no se designa suplente para un órgano vacante, ¿quién ejerce su competencia?','["Nadie hasta el nombramiento del nuevo titular", "Quien designe el órgano inmediato superior", "El órgano delegado más reciente", "El funcionario de mayor antigüedad del órgano"]'::jsonb,1,'Art. 13.1 Ley 40/2015','Si no se designa suplente, la competencia se ejerce por quien designe el órgano administrativo inmediato superior.',null),
('aux-canarias:16-24e9f626fe','aux-canarias',16,'¿Entre qué órganos pueden suscitarse conflictos de atribuciones según la Ley 40/2015?','["Entre órganos de una misma Administración no relacionados jerárquicamente", "Entre órganos de distintas Administraciones", "Entre un órgano y su superior jerárquico, cuando discrepen sobre la competencia para resolver", "Entre cualquier órgano y otro de la misma o distinta Administración, una vez finalizado el procedimiento"]'::jsonb,0,'Art. 14.3 Ley 40/2015','Los conflictos de atribuciones solo pueden suscitarse entre órganos de una misma Administración no relacionados jerárquicamente y en procedimientos no finalizados.',null),
('aux-canarias:16-5a3e867cbc','aux-canarias',16,'¿Qué debe hacer el órgano que se estime incompetente para resolver un asunto?','["Solicitar informe al Consejo Consultivo", "Archivar el expediente y notificar a los interesados que deben presentar nueva solicitud ante otro órgano", "Remitir directamente las actuaciones al competente y notificarlo a los interesados", "Devolver la solicitud al interesado para que la presente ante el órgano que considere competente"]'::jsonb,2,'Art. 14.1 Ley 40/2015','Remitirá directamente las actuaciones al órgano que considere competente, notificándolo a los interesados.',null),
('aux-canarias:17-8483d7146b','aux-canarias',17,'Según el art. 8.2 del TREBEP, los empleados públicos se clasifican en:','["Funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual", "Funcionarios de carrera, funcionarios interinos, personal laboral, personal eventual y personal directivo profesional", "Funcionarios de carrera, personal laboral, personal eventual y personal directivo", "Funcionarios de carrera, funcionarios interinos y personal laboral fijo o temporal"]'::jsonb,0,'Art. 8.2 TREBEP','Se clasifican en funcionarios de carrera, funcionarios interinos, personal laboral (fijo, por tiempo indefinido o temporal) y personal eventual.',null),
('aux-canarias:17-d14b60bc80','aux-canarias',17,'Las funciones que implican participación directa o indirecta en el ejercicio de potestades públicas corresponden:','["A cualquier empleado público, sea funcionario o laboral", "Exclusivamente a los funcionarios públicos", "Al personal laboral fijo y a los funcionarios de carrera, en los términos que establezca la ley de cada Administración", "Exclusivamente a los funcionarios de carrera, nunca a los interinos"]'::jsonb,1,'Art. 9.2 TREBEP','Corresponden exclusivamente a los funcionarios públicos, en los términos que establezca la ley de desarrollo de cada Administración.',null),
('aux-canarias:17-651924a21c','aux-canarias',17,'Un funcionario interino nombrado para cubrir una plaza vacante puede ocuparla como máximo:','["Un año", "Dos años", "Tres años", "Cinco años"]'::jsonb,2,'Art. 10.1 a) TREBEP','Las plazas vacantes pueden cubrirse por interinos cuando no sea posible su cobertura por funcionarios de carrera, por un máximo de tres años.',null),
('aux-canarias:17-91a625d01a','aux-canarias',17,'El nombramiento de interinos por exceso o acumulación de tareas tiene un plazo máximo de:','["Seis meses dentro de un periodo de doce", "Doce meses dentro de un periodo de veinticuatro", "Tres años", "Nueve meses dentro de un periodo de dieciocho"]'::jsonb,3,'Art. 10.1 d) TREBEP','El plazo máximo es de nueve meses dentro de un periodo de dieciocho meses.',null),
('aux-canarias:17-e6e592e86c','aux-canarias',17,'El nombramiento de interinos para ejecutar programas de carácter temporal no puede superar:','["Tres años, ampliable hasta doce meses más por las leyes de Función Pública", "Dos años, ampliable hasta seis meses más por las leyes de Función Pública que se dicten en desarrollo del Estatuto", "Tres años, sin posibilidad de ampliación", "Cuatro años, ampliable hasta doce meses más por las leyes de Función Pública"]'::jsonb,0,'Art. 10.1 c) TREBEP','No puede ser superior a tres años, ampliable hasta doce meses más por las leyes de Función Pública de cada Administración.',null),
('aux-canarias:17-4fffc9f0a4','aux-canarias',17,'El personal eventual realiza funciones:','["De carácter técnico permanente, previstas en la relación de puestos de trabajo de cada Administración", "Expresamente calificadas como de confianza o asesoramiento especial", "De inspección y control, expresamente calificadas como tales", "De confianza, pero que implican el ejercicio de potestades públicas"]'::jsonb,1,'Art. 12.1 TREBEP','El personal eventual solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial.',null),
('aux-canarias:17-509e2c9038','aux-canarias',17,'Haber sido personal eventual, ¿puede constituir mérito para el acceso a la función pública?','["Sí, siempre", "Sí, si se prestaron servicios más de un año", "No", "Solo en la promoción interna"]'::jsonb,2,'Art. 12.4 TREBEP','La condición de personal eventual no puede constituir mérito para el acceso a la Función Pública o para la promoción interna.',null),
('aux-canarias:17-63a37e7a7c','aux-canarias',17,'¿Cuál de los siguientes NO es un requisito para adquirir la condición de funcionario de carrera?','["Superar el proceso selectivo", "Acatar la Constitución", "Haber prestado servicios previos como interino", "Tomar posesión dentro del plazo establecido"]'::jsonb,2,'Art. 62.1 TREBEP','Se requiere superar el proceso selectivo, el nombramiento publicado en el diario oficial, el acatamiento de la Constitución (y Estatuto de Autonomía y resto del ordenamiento) y la toma de posesión.',null),
('aux-canarias:17-80fd899882','aux-canarias',17,'¿Cuál de las siguientes NO es causa de pérdida de la condición de funcionario de carrera?','["La renuncia", "La jubilación total", "La pérdida de la nacionalidad", "La excedencia voluntaria"]'::jsonb,3,'Art. 63 TREBEP','Son causas la renuncia, la pérdida de la nacionalidad, la jubilación total, la pena de inhabilitación firme y la sanción firme de separación del servicio. La excedencia es una situación administrativa.',null),
('aux-canarias:17-71d1b76bc5','aux-canarias',17,'La jubilación forzosa de los funcionarios se declara al cumplir:','["65 años, pudiendo solicitar la prolongación hasta los 70", "67 años, sin posibilidad de solicitar la prolongación de la permanencia en el servicio activo", "65 años, pudiendo solicitar la prolongación hasta los 72", "60 años, pudiendo solicitar la prolongación hasta los 65"]'::jsonb,0,'Art. 67.3 TREBEP','Se declara a los sesenta y cinco años, aunque el funcionario puede solicitar la prolongación de la permanencia hasta los setenta.',null),
('aux-canarias:17-546a513ee0','aux-canarias',17,'El personal eventual:','["Tiene derecho a la inamovilidad tras dos años de servicio, y su nombramiento corresponde al órgano de selección tras un concurso de méritos con convocatoria pública", "Ocupa puestos reservados a funcionarios de carrera", "Solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, y su nombramiento y cese son libres", "Accede mediante concurso de méritos"]'::jsonb,2,'Art. 12.1 y 12.3 TREBEP','El cese tiene lugar, en todo caso, cuando se produzca el de la autoridad a la que preste su función de confianza.',null),
('aux-canarias:17-3affab6cde','aux-canarias',17,'Los funcionarios pueden solicitar la prolongación de la permanencia en el servicio activo, una vez cumplida la edad de jubilación forzosa, como máximo hasta:','["Sin límite", "Los setenta años", "Los sesenta y siete años", "Los sesenta y ocho años"]'::jsonb,1,'Art. 67.3 TREBEP','La jubilación forzosa se declara al cumplir 65 años.',null),
('aux-canarias:17-10cc5de6c7','aux-canarias',17,'La renuncia voluntaria a la condición de funcionario:','["Habrá de ser manifestada por escrito y será aceptada expresamente por la Administración, salvo que el funcionario esté sujeto a expediente disciplinario o procesado", "Puede manifestarse verbalmente ante el superior jerárquico", "No necesita aceptación expresa y surte efectos desde su presentación, aunque el funcionario esté sujeto a expediente disciplinario o haya sido procesado por un delito", "No está permitida mientras el funcionario no haya cumplido la edad de jubilación, salvo que lo autorice expresamente el Consejo de Gobierno por razones excepcionales de interés público"]'::jsonb,0,'Art. 64 TREBEP','La renuncia no inhabilita para volver a ingresar por el procedimiento de selección.',null),
('aux-canarias:17-0b6b13d193','aux-canarias',17,'Transcurridos tres años desde el nombramiento de un interino en plaza vacante, esta:','["Solo podrá ser ocupada por personal funcionario de carrera, salvo que el proceso selectivo quede desierto", "Se amortiza automáticamente y el interino cesa sin derecho a indemnización, aunque el proceso selectivo no se haya convocado", "Pasa a ser plaza de personal laboral", "Se convierte automáticamente en plaza en propiedad del interino que la ocupa, sin necesidad de proceso selectivo"]'::jsonb,0,'Art. 10.4 TREBEP','Se produce el fin de la relación de interinidad.',null),
('aux-canarias:17-81efd30d1c','aux-canarias',17,'La designación del personal directivo profesional atenderá a principios de:','["Libre designación política por el titular del órgano superior", "Sorteo entre funcionarios del subgrupo A1", "Antigüedad en el cuerpo, y en caso de empate, mérito y capacidad mediante procedimientos que garanticen la publicidad y la concurrencia", "Mérito y capacidad y criterios de idoneidad, mediante procedimientos que garanticen la publicidad y concurrencia"]'::jsonb,3,'Art. 13.2 TREBEP','Así lo establece el art. 13.2.',null),
('aux-canarias:18-50aaf4420f','aux-canarias',18,'¿Qué edad mínima se exige para participar en los procesos selectivos?','["Dieciséis años", "Dieciocho años", "Diecisiete años", "Veintiún años"]'::jsonb,0,'Art. 56.1 c) TREBEP','Tener cumplidos dieciséis años y no exceder, en su caso, la edad máxima de jubilación forzosa.',null),
('aux-canarias:18-a9e6c390b5','aux-canarias',18,'¿Cuáles son los sistemas selectivos de los funcionarios de carrera?','["Concurso y libre designación con convocatoria pública", "Oposición y concurso-oposición; el concurso, solo con carácter excepcional y en virtud de ley", "Oposición y concurso-oposición; el concurso, con carácter ordinario y sin necesidad de previsión en una ley", "Oposición, concurso y entrevista personal, que pueden utilizarse indistintamente según lo que decida cada convocatoria"]'::jsonb,1,'Art. 61.6 TREBEP','Son la oposición y el concurso-oposición. El concurso de valoración de méritos solo cabe excepcionalmente y en virtud de ley.',null),
('aux-canarias:18-3082ee7cd3','aux-canarias',18,'En las ofertas de empleo público se reservará un cupo para personas con discapacidad no inferior al:','["2 % de las vacantes", "5 % de las vacantes", "10 % de las vacantes", "7 % de las vacantes"]'::jsonb,3,'Art. 59.1 TREBEP','De ese cupo, al menos el 2 % de las plazas para personas con discapacidad intelectual.',null),
('aux-canarias:18-38a204830d','aux-canarias',18,'Los procedimientos de provisión de puestos de trabajo de los funcionarios de carrera son, con carácter general:','["La entrevista y la valoración del currículum", "La oposición y el concurso-oposición", "El concurso y la libre designación con convocatoria pública", "El concurso y la libre designación sin convocatoria pública"]'::jsonb,2,'Art. 78.2 TREBEP','El concurso es el procedimiento normal de provisión.',null),
('aux-canarias:18-dff7f5aaca','aux-canarias',18,'La libre designación con convocatoria pública consiste en:','["Una prueba de conocimientos eliminatoria sobre las funciones del puesto, seguida de la valoración de méritos por una comisión técnica independiente", "La antigüedad del candidato", "Un sorteo entre los candidatos", "La apreciación discrecional por el órgano competente de la idoneidad de los candidatos en relación con los requisitos del puesto"]'::jsonb,3,'Art. 80.1 TREBEP','Se aplica a los puestos que determinen las leyes por su especial responsabilidad.',null),
('aux-canarias:18-596a221ce0','aux-canarias',18,'NO pueden formar parte de los órganos de selección:','["Los funcionarios de carrera de otras Administraciones públicas", "Los funcionarios del mismo cuerpo o escala al que se aspira a ingresar y el personal laboral fijo de la misma Administración", "El personal de elección o designación política, los funcionarios interinos y el personal eventual", "El personal laboral fijo y los funcionarios de carrera que hayan preparado a aspirantes en los cinco años anteriores"]'::jsonb,2,'Art. 60.2 TREBEP','Los órganos de selección son colegiados y tienden a la paridad.',null),
('aux-canarias:18-72d619fadc','aux-canarias',18,'Los nacionales de los Estados miembros de la Unión Europea pueden acceder como funcionarios en igualdad de condiciones que los españoles, salvo a los empleos que impliquen:','["Funciones de atención al público en lengua cooficial", "Participación en el ejercicio del poder público o en las funciones de salvaguardia de los intereses del Estado", "Trabajos en entidades locales", "Funciones administrativas, de gestión o de auxilio, aunque no impliquen ejercicio de potestades públicas"]'::jsonb,1,'Art. 57.1 TREBEP','Los extranjeros con residencia legal pueden acceder como personal laboral (art. 57.4).',null),
('aux-canarias:18-a60d6e0cb5','aux-canarias',18,'Los órganos de selección no podrán proponer el acceso a la condición de funcionario de un número superior de aprobados al de plazas convocadas:','["Salvo en la Administración Local, cuando lo acuerde el Pleno", "Salvo que la convocatoria prevea otra cosa", "En ningún caso, y cualquier propuesta que lo contravenga será nula de pleno derecho", "Salvo que lo solicite el tribunal"]'::jsonb,1,'Art. 61.8 TREBEP','Regla general con la excepción prevista.',null),
('aux-canarias:18-75fe32e87d','aux-canarias',18,'Según el TREBEP, ¿cuál es el procedimiento normal de provisión de puestos de trabajo de los funcionarios de carrera?','["La adscripción provisional", "El concurso", "La comisión de servicios", "La libre designación"]'::jsonb,1,'Art. 78 TREBEP','La libre designación con convocatoria pública es el otro procedimiento ordinario, reservado a puestos determinados por su especial responsabilidad o confianza.',null),
('aux-canarias:18-0e9311f2a3','aux-canarias',18,'Según el TREBEP, en las ofertas de empleo público se reserva para personas con discapacidad intelectual, dentro del cupo general, al menos:','["El 7 % de las plazas ofertadas", "El 2 % de las plazas ofertadas", "El 1 % de las plazas ofertadas", "El 5 % de las plazas ofertadas"]'::jsonb,1,'Art. 59.1 TREBEP','El cupo total para personas con discapacidad no es inferior al 7 %, y de él al menos el 2 % es para personas con discapacidad intelectual.',null),
('aux-canarias:19-b3be3eebc6','aux-canarias',19,'¿Cuál de estas NO es una situación administrativa de los funcionarios de carrera?','["Servicios especiales", "Excedencia", "Comisión de servicios", "Suspensión de funciones"]'::jsonb,2,'Art. 85.1 TREBEP','Las situaciones son servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones. La comisión de servicios es una forma de provisión de puestos.',null),
('aux-canarias:19-bc93667b2c','aux-canarias',19,'Para obtener la excedencia voluntaria por interés particular hay que haber prestado servicios efectivos durante un mínimo de:','["Un año inmediatamente anterior a la solicitud", "Dos años inmediatamente anteriores", "Tres años, consecutivos o no, en cualquier Administración", "Cinco años inmediatamente anteriores"]'::jsonb,3,'Art. 89.2 TREBEP','Se exige haber prestado servicios efectivos en cualquier Administración durante un mínimo de cinco años inmediatamente anteriores.',null),
('aux-canarias:19-2c4c071882','aux-canarias',19,'La excedencia por cuidado de cada hijo tiene una duración:','["No superior a tres años", "No superior a un año", "No superior a cinco años", "Sin límite"]'::jsonb,0,'Art. 89.4 TREBEP','El periodo de excedencia por cuidado de cada hijo no puede ser superior a tres años.',null),
('aux-canarias:19-549399bf93','aux-canarias',19,'La suspensión firme de funciones por sanción disciplinaria no puede exceder de:','["Tres años", "Seis años", "Dos años", "Un año"]'::jsonb,1,'Art. 90.2 TREBEP','No puede exceder de seis años. Si supera seis meses, el funcionario pierde su puesto de trabajo (art. 90.1).',null),
('aux-canarias:19-595d31904b','aux-canarias',19,'Según el TREBEP, las faltas disciplinarias se clasifican en:','["Graves y leves", "Penales y administrativas", "Muy graves, graves y leves", "Muy graves y graves"]'::jsonb,2,'Art. 95.1 TREBEP','Las faltas disciplinarias pueden ser muy graves, graves y leves.',null),
('aux-canarias:19-ca49920713','aux-canarias',19,'¿Cuál de las siguientes sanciones NO aparece expresamente en la lista del art. 96.1 del TREBEP?','["Apercibimiento", "Demérito", "Traslado forzoso", "Multa económica"]'::jsonb,3,'Art. 96.1 TREBEP','Recoge la separación del servicio, el despido disciplinario, la suspensión firme de funciones, el traslado forzoso, el demérito, el apercibimiento y cualquier otra que establezca una ley.',null),
('aux-canarias:19-7a8655169d','aux-canarias',19,'¿Cuándo prescriben las faltas leves?','["A los seis meses", "Al año", "A los dos años", "A los tres meses"]'::jsonb,0,'Art. 97 TREBEP','Las faltas muy graves prescriben a los tres años, las graves a los dos años y las leves a los seis meses.',null),
('aux-canarias:19-aaa80f1bd6','aux-canarias',19,'¿Cuándo prescriben las sanciones impuestas por faltas leves?','["A los seis meses", "Al año", "A los dos años", "A los tres años"]'::jsonb,1,'Art. 97 TREBEP','Las sanciones por faltas muy graves prescriben a los tres años, las graves a los dos años y las leves al año.',null),
('aux-canarias:19-7ff94ba645','aux-canarias',19,'La suspensión provisional como medida cautelar en un expediente disciplinario no puede exceder de:','["Tres meses, salvo paralización del procedimiento imputable al interesado", "Un año, salvo paralización del procedimiento imputable a la Administración que lo tramita", "Seis meses, salvo paralización del procedimiento imputable al interesado", "Seis meses, sin excepción alguna"]'::jsonb,2,'Art. 98.3 TREBEP','No puede exceder de seis meses, salvo en caso de paralización del procedimiento imputable al interesado.',null),
('aux-canarias:19-01ccd9c597','aux-canarias',19,'El plazo de prescripción de las sanciones comenzará a contarse:','["Desde la firmeza de la resolución sancionadora", "Desde la notificación del pliego de cargos", "Desde la incoación del expediente", "Desde la comisión de la falta"]'::jsonb,0,'Art. 97 TREBEP','El de las faltas, desde que se hubieran cometido, o desde el cese de su comisión si son continuadas.',null),
('aux-canarias:19-bf17f2a4c7','aux-canarias',19,'Las faltas leves se sancionarán:','["Solo por un juez", "Sin procedimiento", "Por el procedimiento previsto para las faltas graves y muy graves", "Por un procedimiento sumario con audiencia al interesado"]'::jsonb,3,'Art. 98.1 TREBEP','Las faltas muy graves y graves exigen el procedimiento previamente establecido.',null),
('aux-canarias:19-1f5f2714e8','aux-canarias',19,'La suspensión de funciones determinará la pérdida del puesto de trabajo cuando exceda de:','["Un año", "Tres meses", "Un mes", "Seis meses"]'::jsonb,3,'Art. 90.1 TREBEP','El funcionario suspenso queda privado del ejercicio de sus funciones.',null),
('aux-canarias:19-8bbfb6c340','aux-canarias',19,'Durante la suspensión provisional como medida cautelar, el funcionario:','["Percibe íntegramente sus retribuciones hasta que se resuelva el expediente disciplinario", "No percibe ninguna retribución", "Percibirá las retribuciones básicas y, en su caso, las prestaciones familiares por hijo a cargo", "Percibirá las retribuciones complementarias, pero no las básicas"]'::jsonb,2,'Art. 98.3 TREBEP','Si la suspensión se eleva a definitiva, deberá devolver lo percibido.',null),
('aux-canarias:19-3c8aa63e25','aux-canarias',19,'Durante los dos primeros años de excedencia por cuidado de hijos o familiares, el funcionario tiene derecho a:','["Ascender automáticamente de grado", "Nada, salvo el cómputo de antigüedad", "La reserva del puesto de trabajo que desempeñaba", "Seguir percibiendo las retribuciones básicas y la reserva de un puesto en la misma localidad"]'::jsonb,2,'Art. 89.4 TREBEP','Transcurrido ese periodo, la reserva lo es a un puesto en la misma localidad y de igual retribución.',null),
('aux-canarias:19-9a40a4c35e','aux-canarias',19,'Las sanciones impuestas por faltas graves prescriben a los:','["Un año", "Dos años", "Tres años", "Seis meses"]'::jsonb,1,'Art. 97 TREBEP','Las muy graves a los tres años y las leves al año.',null),
('aux-canarias:19-25b4e59ae7','aux-canarias',19,'Las faltas muy graves prescriben a los:','["Dos años", "Seis meses", "Cinco años", "Tres años"]'::jsonb,3,'Art. 97 TREBEP','Las graves a los dos años y las leves a los seis meses.',null),
('aux-canarias:19-3a32f5e68a','aux-canarias',19,'Durante los dos primeros meses de excedencia por razón de violencia de género, la funcionaria tendrá derecho a:','["No percibir retribución alguna, aunque se le reserva el puesto de trabajo y se computa el tiempo a efectos de antigüedad", "Percibir las retribuciones íntegras y, en su caso, las prestaciones familiares por hijo a cargo", "Percibir el 50 % de sus retribuciones básicas y complementarias", "Percibir solo las retribuciones básicas, pero no las complementarias ni las prestaciones familiares por hijo a cargo"]'::jsonb,1,'Art. 89.5 TREBEP','Durante los seis primeros meses tiene reserva del puesto, prorrogable por periodos de tres meses hasta dieciocho.',null),
('aux-canarias:19-8b5978dc5f','aux-canarias',19,'La excedencia por cuidado de un familiar hasta el segundo grado que no pueda valerse por sí mismo tiene una duración no superior a:','["Tres años", "Dos años", "Cinco años", "Un año"]'::jsonb,0,'Art. 89.4 TREBEP','Igual que la excedencia por cuidado de cada hijo.',null),
('aux-canarias:19-b301ec9e53','aux-canarias',19,'Es una falta muy grave según el art. 95.2 TREBEP:','["El descuido leve en el trabajo", "El abandono del servicio", "La falta de puntualidad ocasional", "Un retraso de diez minutos"]'::jsonb,1,'Art. 95.2 c) TREBEP','Otras faltas muy graves: desobediencia abierta, acoso laboral, etc.',null),
('aux-canarias:19-460f95c46a','aux-canarias',19,'La sanción de separación del servicio de los funcionarios solo podrá imponerse por:','["Faltas graves reiteradas en el plazo de un año", "Cualquier falta", "La comisión de faltas muy graves", "Faltas graves cometidas de forma reiterada"]'::jsonb,2,'Art. 96.1 a) TREBEP','En los interinos implica la revocación del nombramiento.',null),
('aux-canarias:19-069a9189fc','aux-canarias',19,'¿Cuál de las siguientes NO es una situación administrativa de los funcionarios de carrera según el artículo 85 del TREBEP?','["Servicios especiales", "Suspensión de funciones", "Servicio en otras Administraciones Públicas", "Expectativa de destino indefinida"]'::jsonb,3,'Art. 85.1 TREBEP','Las situaciones son servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones.',null),
('aux-canarias:19-9b33359e58','aux-canarias',19,'Los funcionarios que acceden a la condición de diputado o senador de las Cortes Generales pasan a la situación de:','["Suspensión provisional de funciones", "Servicio activo con dispensa de funciones", "Excedencia voluntaria por interés particular", "Servicios especiales"]'::jsonb,3,'Art. 87.1 TREBEP','Tienen derecho a reingresar al servicio activo en la misma localidad y en las mismas condiciones y con las retribuciones correspondientes a su categoría.',null),
('aux-canarias:19-3cf4018f48','aux-canarias',19,'Según el TREBEP, los funcionarios en situación de servicios especiales:','["Pierden la condición de funcionario mientras dure la situación", "No tienen derecho a reserva de puesto ni a que se les compute el tiempo a ningún efecto", "Solo tienen derecho al cómputo de trienios, pero no a la reserva de puesto", "Tienen derecho a que se les compute el tiempo en esa situación a efectos de ascensos, reconocimiento de trienios y derechos en el régimen de Seguridad Social"]'::jsonb,3,'Art. 87.2 TREBEP','No se les aplica, sin embargo, el régimen de derechos pasivos si les corresponde otro.',null),
('aux-canarias:20-0949071c52','aux-canarias',20,'¿Cuál de estos es un derecho individual que se ejerce de forma colectiva?','["La inamovilidad en la condición de funcionario", "La formación continua", "Las vacaciones", "El ejercicio de la huelga"]'::jsonb,3,'Art. 15 TREBEP','Son derechos individuales ejercidos colectivamente la libertad sindical, la negociación colectiva y participación, la huelga, el planteamiento de conflictos colectivos y la reunión.',null),
('aux-canarias:20-0867ec2229','aux-canarias',20,'¿Cuántos días de permiso por asuntos particulares tienen los funcionarios al año?','["Seis días", "Cuatro días", "Tres días", "Ocho días"]'::jsonb,0,'Art. 48 k) TREBEP','Por asuntos particulares, seis días al año.',null),
('aux-canarias:20-667e06bc37','aux-canarias',20,'¿Cuántos días de permiso corresponden por matrimonio o registro de pareja de hecho?','["Diez días", "Quince días", "Veinte días", "Siete días"]'::jsonb,1,'Art. 48 l) TREBEP','Quince días por matrimonio o registro o constitución formalizada por documento público de pareja de hecho.',null),
('aux-canarias:20-0415c246a3','aux-canarias',20,'¿Qué duración tiene el permiso por nacimiento para la madre biológica según el TREBEP vigente?','["Dieciséis semanas", "Doce semanas", "Diecinueve semanas", "Veinticuatro semanas"]'::jsonb,2,'Art. 49 a) TREBEP','Tras la última reforma son diecinueve semanas (treinta y dos en caso de familia monoparental). Muchos tests antiguos siguen diciendo dieciséis.',null),
('aux-canarias:20-314e4c3162','aux-canarias',20,'¿Cuántos días de vacaciones retribuidas tienen los funcionarios por año completo de servicio?','["Treinta días naturales", "Veinte días hábiles", "Veinticinco días hábiles", "Veintidós días hábiles"]'::jsonb,3,'Art. 50.1 TREBEP','Veintidós días hábiles, o los que correspondan proporcionalmente si el tiempo de servicio fue menor.',null),
('aux-canarias:20-70916cd2e6','aux-canarias',20,'Las retribuciones básicas están integradas por:','["La productividad y las gratificaciones por servicios extraordinarios", "El sueldo asignado a cada subgrupo o grupo y los trienios", "El complemento de destino y el complemento específico", "El sueldo asignado a cada subgrupo, los trienios y el complemento de destino del puesto que se ocupe"]'::jsonb,1,'Art. 23 TREBEP','Los trienios consisten en una cantidad por cada tres años de servicio.',null),
('aux-canarias:20-a3c2454153','aux-canarias',20,'Los Delegados de Personal representan a los funcionarios en unidades electorales que cuenten con:','["Más de 50 funcionarios", "Menos de 6 funcionarios", "Entre 6 y 49 funcionarios", "Más de 250 funcionarios"]'::jsonb,2,'Art. 39.2 TREBEP','A partir de 50 funcionarios hay Juntas de Personal.',null),
('aux-canarias:20-be137806de','aux-canarias',20,'Según el art. 54.11, los empleados públicos garantizarán la atención al ciudadano en:','["La lengua oficial que solicite y, si lo pide, también en inglés", "Castellano exclusivamente", "La lengua que lo solicite siempre que sea oficial en el territorio", "La lengua que elija el funcionario"]'::jsonb,2,'Art. 54.11 TREBEP','Es otro principio de conducta.',null),
('aux-canarias:20-43ee431c23','aux-canarias',20,'Por traslado de domicilio sin cambio de residencia, el funcionario tiene un permiso de:','["Ningún día", "Dos días", "Un día", "Tres días"]'::jsonb,2,'Art. 48 b) TREBEP','Permiso de un día por traslado de domicilio.',null),
('aux-canarias:20-80d4c592ca','aux-canarias',20,'La funcionaria víctima de violencia de género que reduzca su jornada en un tercio o menos:','["Pierde las retribuciones básicas", "Solo cobra el 50 %", "Mantendrá sus retribuciones íntegras", "Pierde todas sus retribuciones"]'::jsonb,2,'Art. 49 d) TREBEP','Si la reducción es mayor, la disminución de retribuciones es proporcional.',null),
('aux-canarias:20-5f6978b509','aux-canarias',20,'El permiso parental para el cuidado de hijo o menor acogido por tiempo superior a un año, hasta que cumpla ocho años, tiene una duración máxima de:','["Ocho semanas, y no es retribuido", "Un año", "Dieciséis semanas retribuidas", "Cuatro semanas retribuidas"]'::jsonb,0,'Art. 49 g) TREBEP','Se requiere un preaviso de quince días.',null),
('aux-canarias:20-6f40a1d65d','aux-canarias',20,'El teletrabajo de los empleados públicos:','["Es irreversible una vez concedido y solo puede revocarse como sanción disciplinaria tras el expediente correspondiente", "Solo se permite al personal interino", "Es obligatorio para los puestos cuyas funciones permitan prestarse a distancia, salvo renuncia justificada del empleado", "Tendrá carácter voluntario y reversible, salvo en supuestos excepcionales debidamente justificados"]'::jsonb,3,'Art. 47 bis.2 TREBEP','Se realizará en los términos de las normas que se dicten en desarrollo del Estatuto.',null),
('aux-canarias:20-21922a13a1','aux-canarias',20,'Por accidente o enfermedad grave de un familiar de primer grado de consanguinidad o afinidad, el funcionario tiene un permiso de:','["Cinco días hábiles", "Diez días hábiles", "Tres días naturales", "Dos días hábiles"]'::jsonb,0,'Art. 48 a) TREBEP','Para familiares de segundo grado, cuatro días hábiles.',null),
('aux-canarias:20-2d47154286','aux-canarias',20,'Quedan excluidas de la obligatoriedad de la negociación:','["Las retribuciones complementarias de los funcionarios", "Las decisiones que afecten a las potestades de organización de las Administraciones Públicas", "Los criterios generales de acceso, carrera, provisión, sistemas de clasificación de puestos y planes de recursos humanos", "La evaluación del desempeño"]'::jsonb,1,'Art. 37.2 a) TREBEP','Las demás opciones son materias objeto de negociación (art. 37.1).',null),
('aux-canarias:20-f97fa3e255','aux-canarias',20,'Según el art. 54.6 TREBEP, los empleados públicos:','["Pueden aceptar regalos de cualquier valor siempre que los declaren a su superior jerárquico en el plazo de diez días desde su recepción y los inscriban en el registro", "Deben declarar los regalos recibidos en su declaración de bienes", "Solo pueden aceptar regalos de otros empleados públicos o de los ciudadanos, siempre que no superen el valor que fije cada Administración en su código ético", "Rechazarán cualquier regalo, favor o servicio en condiciones ventajosas que vaya más allá de los usos habituales, sociales y de cortesía"]'::jsonb,3,'Art. 54.6 TREBEP','Es un principio de conducta.',null),
('aux-canarias:20-6f14a7bf03','aux-canarias',20,'Las pagas extraordinarias de los funcionarios serán:','["Una al año, por el importe de una mensualidad de retribuciones básicas", "Cuatro al año", "Tres al año, cada una por el importe de una mensualidad de retribuciones básicas y de la mitad de las complementarias, que se abonan en marzo, junio y diciembre", "Dos al año, cada una por el importe de una mensualidad de retribuciones básicas y de la totalidad de las complementarias, salvo excepciones"]'::jsonb,3,'Art. 22.4 TREBEP','Son dos pagas al año.',null),
('aux-canarias:20-01234101d7','aux-canarias',20,'Es un derecho individual de los empleados públicos del art. 14 TREBEP:','["La formación continua y la actualización permanente de sus conocimientos", "La negociación colectiva y la participación en la determinación de las condiciones de trabajo", "La huelga y el planteamiento de conflictos colectivos de trabajo en su unidad", "El planteamiento de conflictos colectivos de trabajo"]'::jsonb,0,'Art. 14 g) TREBEP','Los demás citados son derechos individuales ejercidos colectivamente (art. 15).',null),
('aux-canarias:20-925b55b89a','aux-canarias',20,'A efectos de vacaciones de los funcionarios, los sábados:','["No se consideran días hábiles, salvo en los horarios especiales", "Computan doble", "Se consideran hábiles solo en agosto", "Se consideran siempre días hábiles, cualquiera que sea el horario del funcionario"]'::jsonb,0,'Art. 50.1 TREBEP','Las vacaciones son de 22 días hábiles.',null),
('aux-canarias:20-4ed0d3038e','aux-canarias',20,'La parte de jornada no realizada sin justificación dará lugar a:','["La deducción proporcional de haberes, que no tendrá carácter sancionador", "Ninguna consecuencia económica, aunque deberá recuperarse en otro momento de la semana", "La separación del servicio", "Una sanción disciplinaria grave, previa tramitación del expediente correspondiente"]'::jsonb,0,'Art. 30.1 TREBEP','La deducción no es una sanción.',null),
('aux-canarias:20-f67c57a76b','aux-canarias',20,'Para participar en la promoción interna, los funcionarios deben poseer una antigüedad de, al menos:','["Un año de servicio activo en el mismo cuerpo o escala", "Dos años de servicio activo en el inferior subgrupo o grupo de clasificación profesional", "Tres años de servicio activo en el mismo cuerpo o escala, de los cuales al menos uno en la misma Administración", "Cinco años de servicio activo en cualquier cuerpo o escala de la misma Administración pública"]'::jsonb,1,'Art. 18.2 TREBEP','Además de la titulación y demás requisitos exigidos.',null),
('aux-canarias:20-e40d0bccb6','aux-canarias',20,'Los trienios consisten en una cantidad, igual para cada subgrupo o grupo, por cada:','["Año de servicio", "Cinco años de servicio", "Dos años de servicio", "Tres años de servicio"]'::jsonb,3,'Art. 23 b) TREBEP','Retribución básica por antigüedad.',null),
('aux-canarias:20-11150746b2','aux-canarias',20,'Las retribuciones de los funcionarios de carrera se clasifican en:','["Ordinarias y extraordinarias", "Directas e indirectas", "Básicas y complementarias", "Fijas y variables"]'::jsonb,2,'Art. 22.1 TREBEP','Las pagas extraordinarias son dos al año.',null),
('aux-canarias:20-bc13f0c20d','aux-canarias',20,'Los Pactos y Acuerdos, salvo que se establezca otra cosa:','["Se prorrogarán de año en año si no media denuncia expresa de una de las partes", "Caducan al año de su firma, salvo que se renueven expresamente", "Se prorrogarán por periodos de cuatro años, salvo que una de las partes los denuncie con seis meses de antelación", "Duran cuatro años improrrogables"]'::jsonb,0,'Art. 38.11 TREBEP','Prórroga anual salvo denuncia.',null),
('aux-canarias:20-4dbad3dc27','aux-canarias',20,'Por fallecimiento de un familiar de primer grado en la misma localidad, el permiso es de:','["Cinco días hábiles", "Tres días hábiles", "Dos días hábiles", "Un día"]'::jsonb,1,'Art. 48 a) TREBEP','Si es en distinta localidad, cinco días hábiles.',null),
('aux-canarias:20-9688cd3a4c','aux-canarias',20,'Las Mesas de Negociación quedarán válidamente constituidas cuando las organizaciones sindicales presentes representen, como mínimo:','["El 10 % de los miembros de los órganos unitarios de representación", "La totalidad de los miembros de los órganos unitarios de representación", "La mayoría absoluta de los miembros de los órganos unitarios de representación en el ámbito de que se trate", "Un tercio de los miembros de los órganos unitarios de representación en el ámbito de que se trate"]'::jsonb,2,'Art. 35.1 TREBEP','Ninguna de las partes puede superar quince miembros (art. 35.4).',null),
('aux-canarias:20-453be8b31a','aux-canarias',20,'Si la incapacidad temporal impide disfrutar las vacaciones en el año natural, podrán disfrutarse una vez finalizada, siempre que no hayan transcurrido más de:','["Un año a partir del final del año en que se hayan originado", "Tres años", "Seis meses a partir del final del año en que se hayan originado", "Dieciocho meses a partir del final del año en que se hayan originado"]'::jsonb,3,'Art. 50.2 TREBEP','Las vacaciones no pueden sustituirse por una cuantía económica, salvo cese no voluntario.',null),
('aux-canarias:20-3481b04132','aux-canarias',20,'En el permiso por nacimiento, ¿cuántas semanas inmediatas posteriores al parto son de descanso obligatorio?','["Dos semanas", "Seis semanas", "Diez semanas", "Cuatro semanas"]'::jsonb,1,'Art. 49 a) TREBEP','Las seis semanas posteriores al parto son obligatorias e ininterrumpidas.',null),
('aux-canarias:20-81dc60a748','aux-canarias',20,'La duración del mandato de los Delegados de Personal y de las Juntas de Personal es de:','["Tres años", "Cinco años", "Dos años", "Cuatro años"]'::jsonb,3,'Art. 42 TREBEP','Pueden ser reelegidos en sucesivos procesos electorales.',null),
('aux-canarias:21-b5777555f6','aux-canarias',21,'Según el Decreto 212/1991, ¿bajo qué principio se organiza y funciona la Administración autonómica de Canarias?','["Autonomía funcional de cada consejería", "Coordinación interinsular", "Ordenación jerárquica de sus órganos", "Descentralización territorial plena"]'::jsonb,2,'Art. 2 Decreto 212/1991','El art. 2.1 dispone que la Administración autonómica se organiza y funciona bajo el principio de ordenación jerárquica de sus órganos.',null),
('aux-canarias:21-20f5dd88d1','aux-canarias',21,'Según el Decreto 212/1991, ¿cuáles son los órganos superiores de los departamentos?','["Las direcciones generales, las direcciones territoriales de cada isla y las jefaturas de servicio", "Las secretarías generales técnicas, los servicios, las secciones y los negociados", "Las viceconsejerías, las secretarías generales técnicas y las direcciones generales", "Las consejerías, las viceconsejerías, los servicios y las secciones de cada departamento"]'::jsonb,2,'Art. 2 Decreto 212/1991','El art. 2.2 los enumera: viceconsejerías, secretarías generales técnicas y direcciones generales.',null),
('aux-canarias:21-ac4dd2975f','aux-canarias',21,'¿Con qué finalidad pueden establecerse direcciones territoriales según el Decreto 212/1991?','["Para resolver los recursos de alzada contra los directores generales", "Para coordinar a los cabildos insulares en el ejercicio de las materias que la comunidad autónoma les haya delegado", "Para gestionar el personal de todas las consejerías de una isla", "Para desarrollar las funciones del departamento, o un sector de ellas, en un ámbito espacial localizado"]'::jsonb,3,'Art. 2 Decreto 212/1991','El art. 2.3 permite crearlas para desarrollar las funciones del departamento, o un sector material, en un ámbito espacial localizado.',null),
('aux-canarias:21-302aa8e87f','aux-canarias',21,'¿Cuál de estas facultades NO figura entre las del poder de dirección del art. 3.2 del Decreto 212/1991?','["Inspeccionar y evaluar el rendimiento de los servicios", "Avocar con carácter general las competencias de los inferiores", "Corregir las desviaciones que se produzcan", "Fijar los objetivos a alcanzar"]'::jsonb,1,'Art. 3 Decreto 212/1991','El poder de dirección incluye fijar objetivos, planes, ordenar e impulsar, supervisar, inspeccionar y corregir desviaciones; la avocación nunca puede tener efectos generales (art. 7.2).',null),
('aux-canarias:21-b150bf2565','aux-canarias',21,'Según el Decreto 212/1991, ¿en qué se diferencian las directrices de las instrucciones?','["Las directrices obligan en cuanto a los resultados y el plazo, con libertad en los medios", "Las directrices no son obligatorias para sus destinatarios", "Las directrices solo pueden dictarlas los consejeros", "Las directrices son obligatorias para sus destinatarios en todos sus elementos, también en los medios"]'::jsonb,0,'Art. 4 Decreto 212/1991','Las instrucciones obligan en todos sus elementos; las directrices, en los resultados y, en su caso, el plazo, con libertad en cuanto a los medios.',null),
('aux-canarias:21-f5e4155239','aux-canarias',21,'Según el Decreto 212/1991, ¿cómo son las instrucciones para sus destinatarios?','["Obligatorias solo si las dicta un órgano superior", "Obligatorias en todos sus elementos", "Orientativas, salvo que se publiquen en el BOC", "Obligatorias solo en cuanto a los resultados"]'::jsonb,1,'Art. 4 Decreto 212/1991','El art. 4.2 dice que las instrucciones son obligatorias para sus destinatarios en todos sus elementos.',null),
('aux-canarias:21-3d3feca532','aux-canarias',21,'Si una norma atribuye una competencia a la Administración autonómica sin especificar el órgano, ¿a quién corresponde instruir y resolver según el Decreto 212/1991?','["Al consejero competente por razón de la materia", "Al Gobierno de Canarias, que podrá delegarla en el consejero competente por razón de la materia", "A la secretaría general técnica del departamento, como órgano horizontal de coordinación", "A los órganos inferiores competentes por razón de la materia y del territorio"]'::jsonb,3,'Art. 6 Decreto 212/1991','No corresponde a los órganos centrales, sino a los inferiores competentes por materia y territorio; si hay varios, al de competencia territorial más amplia.',null),
('aux-canarias:21-ecd2731ff9','aux-canarias',21,'Según el Decreto 212/1991, ¿qué alcance puede tener la avocación?','["Todas las competencias del órgano inferior", "Cualquier asunto, si lo autoriza el Gobierno", "Solo un expediente o un conjunto de expedientes determinados", "Una materia completa durante un año"]'::jsonb,2,'Art. 7 Decreto 212/1991','La avocación no puede tener efectos generales y se limita a un expediente o conjunto de expedientes determinados.',null),
('aux-canarias:21-2b7172f29a','aux-canarias',21,'¿Qué requisitos exige el Decreto 212/1991 para la efectividad de la avocación?','["Que se adopte de forma motivada y se comunique al órgano afectado y a los interesados", "Que la apruebe el Gobierno y se publique en el BOC antes de dictar la resolución del expediente", "Que la solicite el órgano inferior por escrito razonado dirigido al superior jerárquico y al consejero", "Que la informe la Dirección General del Servicio Jurídico"]'::jsonb,0,'Art. 7 Decreto 212/1991','El art. 7.3 exige que se adopte de forma motivada y se comunique al órgano afectado y a los interesados en el procedimiento.',null),
('aux-canarias:21-2686cfa798','aux-canarias',21,'Según el Decreto 212/1991, ¿de quién dependen directamente las viceconsejerías?','["Del Consejo de Gobierno", "De las secretarías generales técnicas", "Del Presidente del Gobierno", "De los titulares de los departamentos"]'::jsonb,3,'Art. 9 Decreto 212/1991','En el ámbito de sus atribuciones, las viceconsejerías dependen directamente de los titulares de los departamentos.',null),
('aux-canarias:21-5eba336cd4','aux-canarias',21,'¿Cómo son nombrados los viceconsejeros, los secretarios generales técnicos y los directores generales según el Decreto 212/1991?','["Por el Parlamento de Canarias a propuesta del Gobierno", "Por decreto del Presidente, sin propuesta previa", "Por decreto del Gobierno a propuesta del consejero correspondiente", "Por orden del consejero, previa libre designación con convocatoria pública"]'::jsonb,2,'Arts. 10, 14 y 18 Decreto 212/1991','Los tres son nombrados y cesados por decreto del Gobierno a propuesta del consejero correspondiente.',null),
('aux-canarias:21-379e809ada','aux-canarias',21,'Según el Decreto 212/1991, ¿qué órgano tiene, salvo norma legal, competencia para incoar y resolver los procedimientos sancionadores por infracciones graves?','["Las viceconsejerías", "Las secretarías generales técnicas", "Las direcciones generales", "Los consejeros"]'::jsonb,0,'Art. 11 Decreto 212/1991','Las viceconsejerías resuelven los sancionadores por infracciones graves; las direcciones generales, por las leves (art. 19.2).',null),
('aux-canarias:21-cd822b988f','aux-canarias',21,'Según el Decreto 212/1991, ¿cómo se definen las secretarías generales técnicas?','["Unidades de apoyo y documentación de las decisiones", "Órganos horizontales de coordinación administrativa general de los departamentos", "Órganos a los que corresponde un sector material de las funciones del departamento", "Órganos de participación de los sectores afectados por las acciones públicas del departamento"]'::jsonb,1,'Art. 13 Decreto 212/1991','El art. 13.1 las define como órganos horizontales de coordinación administrativa general.',null),
('aux-canarias:21-21979941cf','aux-canarias',21,'¿Qué órgano elabora el anteproyecto de presupuesto del departamento según el Decreto 212/1991?','["La viceconsejería", "La dirección general competente en presupuestos", "El servicio de contratación", "La secretaría general técnica"]'::jsonb,3,'Art. 15 Decreto 212/1991','El art. 15.3 a) atribuye a la secretaría general técnica elaborar el anteproyecto de presupuesto integrando las propuestas de los demás órganos.',null),
('aux-canarias:21-3ceb03b132','aux-canarias',21,'¿Qué funciones desempeñan directamente las secretarías generales técnicas, según el art. 15.4 del Decreto 212/1991?','["La gestión de las subvenciones nominativas", "El inventario patrimonial y el archivo general", "La resolución de los recursos de alzada", "La contratación de obras de cualquier importe del departamento"]'::jsonb,1,'Art. 15 Decreto 212/1991','Además de las facultades del art. 3.2, desempeñan directamente las funciones de inventario patrimonial y archivo general.',null),
('aux-canarias:21-2944279c68','aux-canarias',21,'En materia disciplinaria, ¿qué corresponde a las secretarías generales técnicas según el Decreto 212/1991?','["Incoar los procedimientos por faltas graves y muy graves y resolverlos si no implican separación del servicio", "Imponer la sanción de separación del servicio a los funcionarios del departamento", "Únicamente sancionar las faltas leves de todo el departamento", "Informar los expedientes que resuelve la Dirección General de la Función Pública, sin incoarlos ni resolverlos"]'::jsonb,0,'Art. 15 Decreto 212/1991','El art. 15.6 d) les atribuye incoar los procedimientos por faltas graves y muy graves y resolverlos cuando la sanción no implique separación del servicio.',null),
('aux-canarias:21-bf3aca9c9b','aux-canarias',21,'Según el Decreto 212/1991, ¿cómo quedan los actos de los secretarios generales técnicos en materia de personal?','["Son recurribles en alzada ante el consejero", "Requieren ratificación del viceconsejero", "Causan estado en vía administrativa", "Son recurribles en alzada ante la Dirección General de la Función Pública"]'::jsonb,2,'Art. 16 Decreto 212/1991','El art. 16.2 dispone que causan estado en vía administrativa; los demás actos admiten alzada ante el consejero.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-canarias:21-76ffe5f835','aux-canarias',21,'¿Ante quién cabe recurso contra los actos de los directores generales en materia de personal según el Decreto 212/1991?','["Ante las secretarías generales técnicas, en los términos del recurso de alzada", "Ante el consejero competente en materia de Administraciones públicas", "Ante la Dirección General de la Función Pública, en los términos del recurso de reposición", "Ante la viceconsejería de adscripción o, en su defecto, ante el consejero del departamento"]'::jsonb,0,'Art. 20 Decreto 212/1991','En materia de personal, el recurso se presenta ante las secretarías generales técnicas en los términos previstos para el de alzada.',null),
('aux-canarias:21-18b87192d0','aux-canarias',21,'Según el Decreto 212/1991, ¿cómo son nombrados los directores territoriales?','["Por el cabildo insular de la isla correspondiente", "Por decreto del Gobierno a propuesta del consejero", "Por concurso de méritos entre funcionarios de carrera del propio departamento, con convocatoria pública en el BOC", "Por el titular del departamento, entre funcionarios de carrera, por libre designación con convocatoria pública"]'::jsonb,3,'Art. 22 Decreto 212/1991','Los nombra el titular del departamento entre funcionarios de carrera mediante libre designación con convocatoria pública, y son libremente removidos.',null),
('aux-canarias:21-feb1ae2f55','aux-canarias',21,'Según el Decreto 212/1991, ¿cómo se definen los negociados?','["Órganos de coordinación horizontal", "Unidades de apoyo y documentación de las decisiones", "Unidades de trámite y ejecución de los cometidos de las secciones", "Unidades de estudio, propuesta y gestión"]'::jsonb,2,'Art. 25 Decreto 212/1991','Los servicios son unidades de apoyo; las secciones, de estudio, propuesta y gestión; y los negociados, de trámite y ejecución.',null),
('aux-canarias:21-f6c87778dc','aux-canarias',21,'¿Cuál de estas atribuciones corresponde a los jefes de servicio según el Decreto 212/1991?','["Resolver los recursos de alzada interpuestos contra los actos de los jefes de sección y de negociado del servicio", "Resolver los procedimientos reglados de simple confrontación de hechos o aplicación automática de normas", "Incoar procedimientos sancionadores por infracciones leves", "Aprobar la relación de puestos de trabajo de su servicio"]'::jsonb,1,'Art. 27 Decreto 212/1991','El art. 27.1 b) les atribuye resolver los procedimientos reglados que consistan en la simple confrontación de hechos o la aplicación automática de normas.',null),
('aux-canarias:21-64b6b0b729','aux-canarias',21,'¿Qué atribuciones de los jefes de servicio pueden ejercer también los jefes de sección y de negociado según el Decreto 212/1991?','["Instruir procedimientos y formular propuestas de resolución", "Notificar resoluciones, expedir certificaciones y diligenciar comparecencias", "Resolver procedimientos reglados", "Proponer gratificaciones y complementos de productividad"]'::jsonb,1,'Art. 27 Decreto 212/1991','El art. 27.2 les permite realizar las atribuciones de las letras c), d) y e): notificar, certificar y diligenciar comparecencias.',null),
('aux-canarias:21-e1b6c293ae','aux-canarias',21,'Según el Decreto 212/1991, ¿cómo se crean los órganos colegiados de los departamentos?','["Por decreto del Gobierno", "Por ley del Parlamento de Canarias", "Por orden del consejero", "Por resolución de la secretaría general técnica"]'::jsonb,0,'Art. 29 Decreto 212/1991','El art. 29.2 dispone que los órganos colegiados se crean por decreto del Gobierno.',null),
('aux-canarias:21-6f27e7f7e1','aux-canarias',21,'A falta de previsión en su norma constitutiva, ¿cómo se nombra al presidente de un órgano colegiado según el Decreto 212/1991?','["Lo elige el pleno del órgano por mayoría de dos tercios en todas las votaciones", "Lo designa el consejero de adscripción", "Entre sus miembros, por mayoría absoluta en primera votación o simple en segunda", "Lo preside siempre el miembro de mayor rango"]'::jsonb,2,'Art. 30 Decreto 212/1991','En defecto de las normas constitutivas, se elige entre los miembros por mayoría absoluta en primera votación o por mayoría simple en segunda.',null),
('aux-canarias:21-84bb93c231','aux-canarias',21,'Según el Decreto 212/1991, ¿qué determinan los reglamentos orgánicos de los departamentos?','["Solo la sede de las consejerías y la distribución de sus servicios entre las islas", "Los presupuestos de los organismos autónomos", "Las retribuciones de los altos cargos y del personal eventual del departamento", "Las estructuras centrales y territoriales y las atribuciones de cada órgano"]'::jsonb,3,'Art. 31 Decreto 212/1991','Determinan las estructuras centrales y territoriales y asignan a cada órgano sus atribuciones; comprenden todos los órganos, unipersonales y colegiados.',null),
('aux-canarias:21-4b0a4c85ee','aux-canarias',21,'¿Cómo se aprueban los reglamentos orgánicos de las consejerías según el Decreto 212/1991?','["Por orden del consejero afectado", "Por decreto del Presidente, a propuesta de la consejería competente en materia de hacienda y presupuestos", "Por ley del Parlamento de Canarias", "Por decreto del Gobierno, a propuesta conjunta de la consejería afectada y de la Presidencia del Gobierno"]'::jsonb,3,'Art. 33 Decreto 212/1991','El art. 33 dispone que se aprueban por decreto del Gobierno, a propuesta conjunta de la consejería afectada y de la Presidencia del Gobierno.',null),
('aux-canarias:21-c5a5018153','aux-canarias',21,'¿Cuál de estos documentos debe acompañar a un proyecto de reglamento orgánico según el Decreto 212/1991?','["Los organigramas con la posición jerárquica de los órganos", "La memoria de impacto de género firmada por el Parlamento", "El dictamen del Consejo Económico y Social", "El informe del Consejo Consultivo de Canarias"]'::jsonb,0,'Art. 32 Decreto 212/1991','El art. 32.1 exige análisis de las áreas funcionales, justificación de la distribución de competencias, organigramas y valoración económica.',null),
('aux-canarias:21-fbdba2fce6','aux-canarias',21,'Según el Decreto 212/1991, ¿quién resuelve los conflictos de atribuciones entre dos consejerías?','["El consejero de mayor antigüedad", "La Presidencia del Gobierno", "El Consejo Consultivo de Canarias", "La Dirección General del Servicio Jurídico"]'::jsonb,1,'DA 1.ª Decreto 212/1991','Los conflictos entre órganos de un departamento los resuelve el superior jerárquico común; entre dos consejerías, la Presidencia del Gobierno.',null),
('aux-canarias:21-b3fcfd0376','aux-canarias',21,'En un conflicto de atribuciones del Decreto 212/1991, ¿en qué plazo debe informar el órgano requerido?','["Diez días", "Cinco días", "Quince días", "Un mes"]'::jsonb,2,'DA 1.ª Decreto 212/1991','El órgano requerido informa en quince días o adopta en ese plazo la resolución propuesta por el requirente.',null),
('aux-canarias:22-e83a197ef4','aux-canarias',22,'Una notificación electrónica se entiende rechazada cuando pasan sin que se acceda a su contenido:','["10 días naturales desde su puesta a disposición", "10 días hábiles desde su puesta a disposición en la sede electrónica", "15 días naturales desde su puesta a disposición", "5 días hábiles desde su puesta a disposición"]'::jsonb,0,'Art. 43.2 Ley 39/2015','Se entiende rechazada cuando han pasado diez días naturales desde su puesta a disposición sin acceder a su contenido.',null),
('aux-canarias:22-a76aa7ab0e','aux-canarias',22,'¿Qué sistema de identificación electrónica menciona expresamente el art. 9.2 de la Ley 39/2015?','["Los certificados electrónicos cualificados de firma electrónica", "El reconocimiento facial mediante la cámara del dispositivo", "La huella dactilar registrada en el DNI", "El número de teléfono móvil asociado a una cuenta bancaria del interesado"]'::jsonb,0,'Art. 9.2 Ley 39/2015','Menciona los certificados cualificados de firma, los de sello electrónico y cualquier otro sistema que las Administraciones consideren válido.',null),
('aux-canarias:22-8210c436c5','aux-canarias',22,'Con carácter general, para realizar cualquier actuación en el procedimiento, los interesados deben:','["Firmar electrónicamente todo", "Acreditar previamente su identidad", "Presentarse en persona", "Aportar un certificado de antecedentes"]'::jsonb,1,'Art. 11.1 Ley 39/2015','Basta con que acrediten previamente su identidad.',null),
('aux-canarias:22-dfc98fa0d5','aux-canarias',22,'¿Para cuál de estas actuaciones exige la Ley 39/2015 el uso de la firma?','["Consultar el estado de un expediente", "Pedir información general", "Interponer recursos", "Solicitar cita previa"]'::jsonb,2,'Art. 11.2 Ley 39/2015','Se exige firma para formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar a derechos.',null),
('aux-canarias:22-9db73beed2','aux-canarias',22,'Las Administraciones deben asistir en el uso de medios electrónicos a:','["Las empresas y demás personas jurídicas", "Los empleados públicos, para los trámites relacionados con su condición de tales", "Las entidades sin personalidad jurídica que carezcan de medios electrónicos propios", "Las personas físicas que no estén obligadas a relacionarse electrónicamente"]'::jsonb,3,'Art. 12.2 Ley 39/2015','Deben asistir a las personas físicas no obligadas, especialmente en identificación y firma, presentación de solicitudes y obtención de copias auténticas.',null),
('aux-canarias:22-5c65005c6b','aux-canarias',22,'La sede electrónica es:','["Un edificio de la Administración donde se atiende al público", "Un programa informático de gestión", "La dirección de correo electrónico oficial de un organismo público, a través de la cual se presentan escritos con plena validez jurídica", "Una dirección electrónica disponible a través de redes de telecomunicaciones cuya titularidad corresponde a una Administración"]'::jsonb,3,'Art. 38.1 Ley 40/2015','Es una dirección electrónica, disponible para los ciudadanos a través de redes de telecomunicaciones, cuya titularidad corresponde a una Administración u organismo público.',null),
('aux-canarias:22-7bc9b56cc0','aux-canarias',22,'El portal de internet de una Administración es:','["El punto de acceso electrónico que permite acceder a la información publicada y, en su caso, a la sede electrónica", "Lo mismo que la sede electrónica, con la misma responsabilidad sobre la integridad y actualización de la información y los servicios", "Un registro electrónico general en el que se presentan escritos dirigidos a cualquier órgano de esa Administración o de otras", "Un tablón de anuncios físico"]'::jsonb,0,'Art. 39 Ley 40/2015','Es el punto de acceso electrónico de titularidad pública que permite acceder a la información publicada y, en su caso, a la sede electrónica.',null),
('aux-canarias:22-b5f25201ff','aux-canarias',22,'Los interesados podrán firmar a través de cualquier medio que permita acreditar:','["La fecha del documento y su número de registro", "Su identidad, pero no la integridad del documento", "La autenticidad de la expresión de su voluntad y consentimiento, pero no la integridad del documento", "La autenticidad de la expresión de su voluntad y consentimiento, y la integridad e inalterabilidad del documento"]'::jsonb,3,'Art. 10.1 Ley 39/2015','La firma debe acreditar autenticidad de la voluntad y la integridad del documento.',null),
('aux-canarias:22-25f8297158','aux-canarias',22,'Las notificaciones se practicarán preferentemente:','["Mediante anuncio en el BOE, salvo que el interesado señale un domicilio", "En papel en el domicilio del interesado, salvo que este solicite la notificación electrónica", "Por medios electrónicos o en papel, a elección del órgano que dicte el acto", "Por medios electrónicos y, en todo caso, cuando el interesado esté obligado a recibirlas por esta vía"]'::jsonb,3,'Art. 41.1 Ley 39/2015','Se practicarán preferentemente por medios electrónicos.',null),
('aux-canarias:22-200d9db865','aux-canarias',22,'Las Administraciones están obligadas a verificar la identidad de los interesados mediante la comprobación de:','["Su huella dactilar o cualquier otro dato biométrico que conste en el DNI o en el documento identificativo equivalente", "Su nombre y apellidos o denominación o razón social, que consten en el DNI o documento identificativo equivalente", "Su dirección de correo electrónico", "Su número de teléfono móvil"]'::jsonb,1,'Art. 9.1 Ley 39/2015','Se verifica con el nombre y apellidos o razón social del DNI o documento equivalente.',null),
('aux-canarias:22-1f118b10ed','aux-canarias',22,'Si nadie se hace cargo de la notificación en papel en el domicilio, se repetirá:','["Dos veces en la misma semana, en horas distintas", "No se repite, y se publica directamente en el BOE", "Una sola vez y en una hora distinta dentro de los tres días siguientes", "Una sola vez y en la misma hora dentro de los cinco días siguientes"]'::jsonb,2,'Art. 42.2 Ley 39/2015','Se repite por una sola vez y en hora distinta dentro de los tres días siguientes.',null),
('aux-canarias:22-e7d7918aa0','aux-canarias',22,'¿Cuál de los siguientes es un sistema de identificación electrónica previsto en el art. 9.2?','["Un mensaje desde un número de teléfono previamente comunicado", "El envío de una fotocopia escaneada del DNI por correo electrónico, junto con la solicitud firmada a mano", "Los sistemas basados en certificados electrónicos cualificados de firma electrónica", "Una llamada telefónica grabada"]'::jsonb,2,'Art. 9.2 Ley 39/2015','También los certificados cualificados de sello electrónico y otros sistemas que las AAPP consideren válidos.',null),
('aux-canarias:22-be13b48c3f','aux-canarias',22,'Las Administraciones podrán practicar notificaciones por medios no electrónicos cuando:','["Para asegurar la eficacia de la actuación sea necesario practicarla por entrega directa de un empleado público", "Sea fin de semana", "La notificación sea favorable al interesado", "El interesado esté obligado a relacionarse electrónicamente con la Administración y no haya accedido a la notificación"]'::jsonb,0,'Art. 41.2 b) Ley 39/2015','También cuando el interesado comparezca espontáneamente en una oficina de asistencia y solicite la comunicación personal.',null),
('aux-canarias:22-5bdb96095a','aux-canarias',22,'Las notificaciones por medios electrónicos se entienden practicadas:','["Al día siguiente de su emisión", "Cuando el interesado contesta", "Cuando se envía al interesado el aviso de puesta a disposición por correo electrónico o SMS", "En el momento en que se produzca el acceso a su contenido"]'::jsonb,3,'Art. 43.2 Ley 39/2015','Se entienden practicadas en el momento del acceso a su contenido.',null),
('aux-canarias:22-0a5aa72201','aux-canarias',22,'La obligación de notificar en plazo se entiende cumplida, en las notificaciones electrónicas, con:','["La puesta a disposición de la notificación en la sede electrónica o en la dirección electrónica habilitada única", "La publicación de un anuncio en el BOE", "El envío del aviso al correo electrónico del interesado, aunque no se ponga a disposición la notificación", "El acceso efectivo del interesado"]'::jsonb,0,'Art. 43.3 Ley 39/2015','Se entiende cumplida con la puesta a disposición en la sede electrónica o la dirección electrónica habilitada única.',null),
('aux-canarias:22-cacadf46fc','aux-canarias',22,'Si en la notificación en papel en el domicilio el interesado no está presente, podrá hacerse cargo de ella:','["Solo un familiar mayor de 18 años", "Cualquier persona mayor de 14 años que se encuentre en el domicilio y haga constar su identidad", "Cualquier persona mayor de 16 años que se encuentre en el domicilio, sin necesidad de hacer constar su identidad", "Únicamente el interesado"]'::jsonb,1,'Art. 42.2 Ley 39/2015','Puede recogerla cualquier persona mayor de catorce años que esté en el domicilio y haga constar su identidad.',null),
('aux-canarias:22-c4769121c6','aux-canarias',22,'Según la Ley 40/2015, el titular de la sede electrónica responde de:','["La integridad, veracidad y actualización de la información y los servicios a los que pueda accederse a través de ella", "Únicamente de la disponibilidad técnica de la sede durante el horario de atención presencial", "La integridad de la información publicada, mientras que su actualización y la de los servicios corresponde al proveedor tecnológico contratado", "La veracidad de la información publicada en el portal, pero no de los servicios electrónicos de la sede"]'::jsonb,0,'Art. 38.2 Ley 40/2015','El titular de la sede responde de la integridad, veracidad y actualización de la información y los servicios accesibles a través de ella.',null),
('aux-canarias:22-01795793fd','aux-canarias',22,'Para identificarse y garantizar una comunicación segura, las sedes electrónicas utilizan:','["El código seguro de verificación del órgano titular de la sede", "Un sello de tiempo cualificado emitido por la Fábrica Nacional de Moneda y Timbre-Real Casa de la Moneda", "Certificados cualificados de autenticación de sitio web o medio equivalente", "La firma electrónica personal de la persona titular del órgano"]'::jsonb,2,'Art. 38.6 Ley 40/2015','El art. 38.6 prevé certificados reconocidos o cualificados de autenticación de sitio web o un medio equivalente.',null),
('aux-canarias:22-793a2735e8','aux-canarias',22,'Según el art. 40 de la Ley 40/2015, las Administraciones Públicas pueden identificarse mediante:','["La firma electrónica personal del titular del departamento ministerial o de la consejería, de forma exclusiva", "Un código seguro de verificación generado por el propio interesado", "Un sello electrónico basado en un certificado electrónico reconocido o cualificado", "El número de identificación profesional de cada uno de sus empleados"]'::jsonb,2,'Art. 40.1 Ley 40/2015','El sello electrónico se basa en un certificado reconocido o cualificado que incluye el NIF y la denominación de la Administración.',null),
('aux-canarias:22-62dca443c8','aux-canarias',22,'Respecto de la información que publique como propia en su portal de internet, la Administración:','["Se entiende identificada", "Debe identificarse además con la firma electrónica cualificada del órgano", "Solo se entiende identificada si incorpora un código seguro de verificación", "Debe indicar el nombre del empleado público que elaboró la información"]'::jsonb,0,'Art. 40.1 Ley 40/2015','Se entenderá identificada la Administración respecto de la información que publique como propia en su portal de internet.',null),
('aux-canarias:22-d176c32571','aux-canarias',22,'Si un interesado no obligado a relacionarse electrónicamente carece de los medios necesarios, su firma electrónica puede realizarla:','["Cualquier empleado público de la oficina, sin necesidad de consentimiento expreso del interesado", "Un funcionario habilitado, si el interesado se identifica ante él y presta su consentimiento expreso", "Un funcionario habilitado, pero solo en los procedimientos que se inician de oficio", "Un familiar del interesado, previa presentación de una declaración responsable"]'::jsonb,1,'Art. 12.2 Ley 39/2015','El funcionario firma con su propio sistema; el interesado debe identificarse y prestar consentimiento expreso, del que queda constancia.',null),
('aux-canarias:22-a098214fde','aux-canarias',22,'Los funcionarios habilitados para la identificación o firma de los interesados que no disponen de medios electrónicos constan en:','["Un registro u otro sistema equivalente que cada Administración mantiene actualizado", "El Registro Central de Personal, en una sección específica de firma electrónica", "Un listado único estatal publicado en la sede electrónica del Ministerio para la Transformación Digital y de la Función Pública", "El registro electrónico de apoderamientos de la Administración correspondiente"]'::jsonb,0,'Art. 12.3 Ley 39/2015','La AGE, las CCAA y las Entidades Locales mantienen actualizado un registro u otro sistema equivalente de funcionarios habilitados.',null),
('aux-canarias:22-5080417d8e','aux-canarias',22,'Si la Administración no envía el aviso al dispositivo o correo electrónico del interesado de que tiene una notificación electrónica:','["La notificación es nula y debe practicarse de nuevo", "La notificación puede considerarse plenamente válida", "La notificación debe repetirse en papel en el domicilio", "El plazo para acceder a la notificación se amplía diez días"]'::jsonb,1,'Art. 41.6 Ley 39/2015','La falta de práctica del aviso no impide que la notificación sea considerada plenamente válida.',null),
('aux-canarias:22-9c6287dd62','aux-canarias',22,'¿Qué registro deben mantener las Administraciones de los funcionarios habilitados para expedir copias auténticas y asistir en la presentación electrónica?','["Un registro o sistema equivalente de funcionarios habilitados", "Un registro electrónico de apoderamientos otorgados por los interesados", "Un registro de convenios suscritos con otras Administraciones públicas", "Un registro de órganos colegiados y de sus miembros titulares y suplentes"]'::jsonb,0,'Art. 12.3 Ley 39/2015','El registro electrónico de apoderamientos recoge las representaciones otorgadas por los interesados.',null),
('aux-canarias:22-ba44e1d9ff','aux-canarias',22,'Según el artículo 9 de la Ley 39/2015, ¿cuál de los siguientes es un sistema válido para que los interesados se identifiquen electrónicamente ante las Administraciones?','["La fotocopia del DNI enviada por correo electrónico", "Los sistemas de clave concertada", "El número de teléfono móvil", "La firma manuscrita escaneada"]'::jsonb,1,'Art. 9.2 Ley 39/2015','También los certificados electrónicos cualificados de firma y de sello y cualquier otro sistema que las Administraciones consideren válido en los términos y condiciones que se establezcan.',null),
('aux-canarias:22-1a0db64ee7','aux-canarias',22,'Según el artículo 43 de la Ley 39/2015, la notificación por medios electrónicos se entiende rechazada cuando:','["Han transcurrido cinco días hábiles desde su envío sin que el interesado haya contestado ni presentado alegaciones", "Han transcurrido diez días naturales desde su puesta a disposición sin que se acceda a su contenido", "Han transcurrido quince días hábiles desde que se dictó el acto", "El interesado no contesta en veinticuatro horas al aviso enviado a su dirección de correo electrónico o a su móvil"]'::jsonb,1,'Art. 43.2 Ley 39/2015','Se entiende practicada en el momento en que se produce el acceso a su contenido.',null),
('aux-canarias:22-86235e8aa1','aux-canarias',22,'¿Qué es la Dirección Electrónica Habilitada única (DEHú)?','["La dirección postal que el interesado designa para recibir las notificaciones en papel cuando no está obligado a relacionarse electrónicamente", "El punto donde el interesado puede consultar las notificaciones electrónicas que le remitan las Administraciones", "La sede electrónica del Ministerio competente en materia de función pública", "El correo electrónico oficial que la Administración asigna a cada ciudadano y a cada empresa para recibir sus comunicaciones oficiales"]'::jsonb,1,'Art. 43 Ley 39/2015 y RD 203/2021','Las notificaciones pueden practicarse por comparecencia en la sede electrónica o a través de la DEHú.',null),
('aux-canarias:22-a4173ee170','aux-canarias',22,'Según la Ley 40/2015, la sede electrónica es:','["Cualquier página web en la que aparezca el escudo de una Administración", "El edificio en el que se ubican los servidores informáticos de un Ministerio", "La dirección electrónica disponible para los ciudadanos a través de redes de telecomunicaciones, cuya titularidad corresponde a una Administración Pública", "El buzón de correo electrónico de una unidad administrativa"]'::jsonb,2,'Art. 38.1 Ley 40/2015','El titular de la sede responde de la integridad, veracidad y actualización de la información y de los servicios a los que pueda accederse a través de ella.',null),
('aux-canarias:22-ea2b63d767','aux-canarias',22,'Según la Ley 39/2015, si el interesado no dispone de los medios electrónicos necesarios, su identificación o firma electrónica en el procedimiento puede ser válidamente realizada por:','["Cualquier familiar del interesado, con su propio certificado", "El representante sindical del interesado", "Un notario de libre elección del interesado, que deberá dar fe del acto realizado y de la identidad del firmante", "Un funcionario público habilitado, mediante el uso del sistema de firma electrónica del que esté dotado"]'::jsonb,3,'Art. 12.2 Ley 39/2015','El interesado debe identificarse ante el funcionario y prestar su consentimiento expreso, que debe quedar constancia.',null),
('aux-canarias:22-013a69af10','aux-canarias',22,'El portal de internet, según la Ley 40/2015, es:','["El punto de acceso electrónico cuya titularidad corresponde a una Administración Pública u organismo y que permite el acceso a través de internet a la información publicada y, en su caso, a la sede electrónica", "La sede electrónica de cada Ministerio", "Un servidor de correo electrónico de la Administración", "El programa informático que permite firmar documentos"]'::jsonb,0,'Art. 39 Ley 40/2015','No todo portal es una sede electrónica: la sede tiene garantías de integridad, veracidad y actualización.',null),
('aux-canarias:22-28c7b4701b','aux-canarias',22,'El sello electrónico, como sistema de firma de las Administraciones, se basa en:','["Una contraseña que conoce solo el funcionario que tramita", "Un certificado electrónico reconocido o cualificado que reúna los requisitos de la legislación de firma electrónica", "El número de registro de entrada asignado al documento", "La firma manuscrita digitalizada del titular del órgano, incorporada como imagen a todos los documentos que se emitan"]'::jsonb,1,'Art. 40 Ley 40/2015','Los certificados incluyen el número de identificación fiscal y la denominación correspondiente.',null),
('aux-canarias:23-26c9444ceb','aux-canarias',23,'En los procedimientos iniciados a solicitud del interesado, el silencio administrativo es, como regla general:','["Desestimatorio, salvo las excepciones legales", "Causa de caducidad del procedimiento", "Desestimatorio, sin excepción", "Estimatorio, salvo las excepciones legales"]'::jsonb,3,'Art. 24.1 Ley 39/2015','El vencimiento del plazo sin resolución expresa legitima al interesado para entender estimada su solicitud, salvo las excepciones previstas.',null),
('aux-canarias:23-64764ed6ab','aux-canarias',23,'En los procedimientos iniciados de oficio en los que la Administración ejerce potestades sancionadoras o de intervención, el vencimiento del plazo sin resolución produce:','["La caducidad", "La estimación por silencio", "La desestimación por silencio", "La prórroga automática del plazo"]'::jsonb,0,'Art. 25.1 b) Ley 39/2015','En esos procedimientos se produce la caducidad.',null),
('aux-canarias:23-4f73445ab4','aux-canarias',23,'La estimación por silencio administrativo tiene a todos los efectos la consideración de:','["Acto administrativo finalizador del procedimiento", "Acto de trámite cualificado, recurrible en alzada", "Propuesta de resolución vinculante para el órgano competente", "Mera ficción sin efectos hasta que se dicte resolución expresa"]'::jsonb,0,'Art. 24.2 Ley 39/2015','La desestimación por silencio solo permite interponer el recurso que proceda.',null),
('aux-canarias:23-bd58cbb678','aux-canarias',23,'El silencio será desestimatorio, entre otros, en los procedimientos relativos a:','["Licencias de obra menor", "Inscripción en registros públicos", "Las solicitudes de subvenciones de concurrencia competitiva, sin excepción", "El ejercicio del derecho de petición del art. 29 de la Constitución"]'::jsonb,3,'Art. 24.1 Ley 39/2015','También en los de dominio o servicio público, medio ambiente, responsabilidad patrimonial, impugnación de actos y revisión de oficio a solicitud.',null),
('aux-canarias:23-59537fe800','aux-canarias',23,'En los procedimientos iniciados de oficio, si el procedimiento se paraliza por causa imputable al interesado:','["Se produce la caducidad inmediata del procedimiento", "Se interrumpirá el cómputo del plazo para resolver y notificar la resolución", "Se suspenderá el cómputo del plazo, pero solo si así lo acuerda el órgano por resolución motivada notificada al interesado", "Se archiva sin más trámite y se declara la caducidad del procedimiento de forma automática"]'::jsonb,1,'Art. 25.2 Ley 39/2015','La paralización imputable al interesado interrumpe el cómputo del plazo.',null),
('aux-canarias:23-54c4ff3f41','aux-canarias',23,'En los casos de estimación por silencio, la resolución expresa posterior:','["Podrá ser desestimatoria si así lo aconseja el interés público", "Deberá someterse a dictamen previo del Consejo de Estado", "Solo podrá dictarse de ser confirmatoria del mismo", "Podrá ser confirmatoria o desestimatoria, según el resultado de la instrucción y las alegaciones de los interesados"]'::jsonb,2,'Art. 24.3 a) Ley 39/2015','La resolución expresa posterior a la estimación por silencio solo puede confirmarla.',null),
('aux-canarias:23-6750305d41','aux-canarias',23,'Según el art. 35.1 i), deben motivarse también:','["Las comunicaciones internas entre órganos", "Los actos reglados, sin excepción, aunque no limiten derechos ni intereses", "Los actos que se dicten en el ejercicio de potestades discrecionales", "Los actos de trámite que no decidan el fondo ni produzcan indefensión"]'::jsonb,2,'Art. 35.1 i) Ley 39/2015','Se motivan los actos dictados en ejercicio de potestades discrecionales y los que deban serlo por disposición legal.',null),
('aux-canarias:23-22763785a3','aux-canarias',23,'Solicitado el certificado acreditativo del silencio, este deberá emitirse en el plazo máximo de:','["Tres meses", "Diez días", "Un mes", "Quince días"]'::jsonb,3,'Art. 24.4 Ley 39/2015','El certificado del silencio se emite en un máximo de quince días.',null),
('aux-canarias:23-b9b3224df1','aux-canarias',23,'Deben ser motivados, con sucinta referencia de hechos y fundamentos de derecho:','["Solo las disposiciones de carácter general y los actos que pongan fin a la vía administrativa", "Los actos que limiten derechos subjetivos o intereses legítimos", "Solo los actos favorables al interesado", "Todos los actos de trámite, aunque no limiten derechos ni decidan el fondo"]'::jsonb,1,'Art. 35.1 a) Ley 39/2015','El art. 35.1 a) exige motivar los actos que limiten derechos subjetivos o intereses legítimos.',null),
('aux-canarias:23-718cc1b7ca','aux-canarias',23,'En caso de desestimación por silencio, la resolución expresa posterior:','["No puede dictarse", "Se adoptará por la Administración sin vinculación alguna al sentido del silencio", "Debe ser necesariamente desestimatoria, en coherencia con el sentido del silencio producido", "Solo puede ser confirmatoria"]'::jsonb,1,'Art. 24.3 b) Ley 39/2015','En la estimación por silencio, en cambio, la resolución posterior solo puede ser confirmatoria.',null),
('aux-canarias:23-d9447a9c25','aux-canarias',23,'En los procedimientos iniciados de oficio de los que pudiera derivarse el reconocimiento de derechos o situaciones favorables, el vencimiento del plazo sin resolución permite a los interesados:','["Entender desestimadas sus pretensiones por silencio administrativo", "Entender estimadas sus pretensiones por silencio administrativo positivo", "Solicitar que se declare la caducidad del procedimiento", "Exigir una indemnización automática"]'::jsonb,0,'Art. 25.1 a) Ley 39/2015','En estos procedimientos el silencio es desestimatorio.',null),
('aux-canarias:23-df9ac9937b','aux-canarias',23,'Como regla general, los actos administrativos se producirán:','["En papel con firma manuscrita del titular del órgano", "De la forma que elija el interesado en su solicitud, por escrito o verbalmente, en papel o electrónicamente", "Por escrito en papel, salvo que el interesado esté obligado a relacionarse electrónicamente", "Por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma"]'::jsonb,3,'Art. 36.1 Ley 39/2015','Se producen por escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada.',null),
('aux-canarias:23-036de7a0a4','aux-canarias',23,'Las resoluciones administrativas de carácter particular no podrán vulnerar una disposición de carácter general:','["Aunque procedan de un órgano de igual o superior jerarquía al que dictó la disposición", "Salvo que lo autorice expresamente el Consejo de Ministros", "Salvo que procedan de un órgano de jerarquía superior al que dictó la disposición", "Salvo que sean favorables al interesado"]'::jsonb,0,'Art. 37.1 Ley 39/2015','Es el principio de inderogabilidad singular de los reglamentos.',null),
('aux-canarias:23-cf024a50ff','aux-canarias',23,'Según el art. 34.1 de la Ley 39/2015, los actos administrativos se producirán:','["Por el órgano competente, ajustándose a los requisitos y al procedimiento establecido", "Por el funcionario que tramite el expediente, con el visto bueno del titular del órgano", "Por cualquier órgano de la misma Administración", "Por el órgano competente, aunque no se ajusten al procedimiento establecido si el contenido es conforme a Derecho"]'::jsonb,0,'Art. 34.1 Ley 39/2015','Los actos se producen por el órgano competente ajustándose a los requisitos y al procedimiento establecido.',null),
('aux-canarias:24-4d1b300a85','aux-canarias',24,'¿Cuál de estos actos es nulo de pleno derecho?','["El que tiene un defecto de forma que no causa indefensión al interesado ni impide que el acto alcance su fin", "El dictado fuera del plazo establecido, cuando el término no sea esencial", "El dictado por un órgano manifiestamente incompetente por razón de la materia o del territorio", "El que incurre en desviación de poder o en cualquier otra infracción del ordenamiento jurídico aplicable"]'::jsonb,2,'Art. 47.1 b) Ley 39/2015','La incompetencia manifiesta por razón de la materia o del territorio es causa de nulidad de pleno derecho. Las otras opciones son, como mucho, causas de anulabilidad.',null),
('aux-canarias:24-d7221ccfb9','aux-canarias',24,'Un acto dictado prescindiendo total y absolutamente del procedimiento legalmente establecido es:','["Anulable", "Válido si se convalida", "Una irregularidad no invalidante", "Nulo de pleno derecho"]'::jsonb,3,'Art. 47.1 e) Ley 39/2015','Es una de las causas de nulidad de pleno derecho.',null),
('aux-canarias:24-f7d910e546','aux-canarias',24,'Los actos que incurren en desviación de poder son:','["Anulables", "Nulos de pleno derecho", "Válidos", "Inexistentes"]'::jsonb,0,'Art. 48.1 Ley 39/2015','Son anulables los actos que incurren en cualquier infracción del ordenamiento, incluso la desviación de poder.',null),
('aux-canarias:24-9d31e98639','aux-canarias',24,'El defecto de forma determina la anulabilidad del acto:','["Siempre, aunque el acto alcance su fin, reúna los requisitos formales indispensables y no cause indefensión", "Solo cuando el acto carece de los requisitos formales indispensables o da lugar a indefensión", "Nunca, porque el defecto de forma solo genera irregularidades no invalidantes", "Solo cuando el defecto de forma afecta a la motivación del acto, aunque no se haya producido indefensión"]'::jsonb,1,'Art. 48.2 Ley 39/2015','Solo cuando el acto carece de los requisitos formales indispensables para alcanzar su fin o da lugar a indefensión.',null),
('aux-canarias:24-7503efafae','aux-canarias',24,'La realización de actuaciones fuera del tiempo establecido implica la anulabilidad del acto:','["Siempre, cualquiera que sea la naturaleza del término o plazo", "Nunca, ya que la actuación tardía es una mera irregularidad no invalidante", "Solo cuando lo imponga la naturaleza del término o plazo", "Solo si el retraso supera el doble del plazo establecido para la actuación"]'::jsonb,2,'Art. 48.3 Ley 39/2015','Solo implica anulabilidad cuando así lo imponga la naturaleza del término o plazo.',null),
('aux-canarias:24-2329780d47','aux-canarias',24,'¿Qué actos puede convalidar la Administración subsanando los vicios de que adolezcan?','["Los nulos de pleno derecho", "Los inexistentes", "Cualquier acto", "Los anulables"]'::jsonb,3,'Art. 52.1 Ley 39/2015','La Administración puede convalidar los actos anulables, subsanando los vicios de que adolezcan.',null),
('aux-canarias:24-2a189a205f','aux-canarias',24,'Son nulas de pleno derecho las disposiciones administrativas que:','["Establezcan la retroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos individuales", "Establezcan la retroactividad de disposiciones favorables o ampliatorias de derechos individuales", "Tengan carácter organizativo y no se hayan sometido previamente al trámite de información pública ni a consulta de los interesados afectados", "Se aprueben por el Consejo de Ministros"]'::jsonb,0,'Art. 47.2 Ley 39/2015','También las que vulneren la Constitución, las leyes o disposiciones de rango superior o regulen materias reservadas a la ley.',null),
('aux-canarias:24-71ef3c2af3','aux-canarias',24,'El órgano que declare la nulidad o anule las actuaciones dispondrá siempre la conservación de:','["Aquellos actos y trámites cuyo contenido se hubiera mantenido igual de no haberse cometido la infracción", "Ningún acto del procedimiento", "Los actos de trámite anteriores a la infracción, aunque su contenido hubiera variado de no cometerse esta", "Solo la resolución final y los actos de trámite posteriores a la infracción, aunque su contenido hubiera variado"]'::jsonb,0,'Art. 51 Ley 39/2015','Es el principio de conservación de actos y trámites.',null),
('aux-canarias:24-b10b9936fd','aux-canarias',24,'La nulidad o anulabilidad de un acto:','["Implica siempre la nulidad de todo el procedimiento", "No implica la de los sucesivos en el procedimiento que sean independientes del primero", "Implica la de todos los actos posteriores del procedimiento, aunque sean independientes del primero", "Solo afecta a actos favorables"]'::jsonb,1,'Art. 49.1 Ley 39/2015','No se extiende a los actos sucesivos que sean independientes del primero.',null),
('aux-canarias:24-db4f2a9ef2','aux-canarias',24,'Si el vicio de un acto consiste en incompetencia no determinante de nulidad, la convalidación podrá realizarse por:','["El interesado afectado, mediante escrito en el que manifieste su conformidad con el acto viciado", "El órgano competente, cuando sea superior jerárquico del que dictó el acto viciado", "El propio órgano que dictó el acto, mediante una resolución posterior que subsane el vicio de incompetencia", "El Defensor del Pueblo"]'::jsonb,1,'Art. 52.3 Ley 39/2015','La incompetencia no determinante de nulidad se convalida por el órgano competente superior jerárquico.',null),
('aux-canarias:24-3fc655cdab','aux-canarias',24,'La nulidad en parte de un acto no implica la de las partes independientes, salvo que:','["Se haya notificado conjuntamente y en un mismo documento a todos los interesados afectados", "Sea un acto favorable al interesado", "La parte viciada sea de tal importancia que sin ella el acto no se habría dictado", "Lo solicite el interesado en el recurso que interponga contra el acto, justificando su conexión"]'::jsonb,2,'Art. 49.2 Ley 39/2015','Las partes independientes se mantienen, salvo que la parte viciada fuera esencial.',null),
('aux-canarias:24-209586b2f2','aux-canarias',24,'Según el art. 47.1 f), son nulos los actos expresos o presuntos contrarios al ordenamiento por los que se adquieren facultades o derechos:','["Cuando no haya terceros afectados por la adquisición", "Cuando sean favorables al interesado y no haya terceros afectados por ellos", "Cuando se hayan publicado en el boletín oficial sin haberse notificado a los interesados", "Cuando se carezca de los requisitos esenciales para su adquisición"]'::jsonb,3,'Art. 47.1 f) Ley 39/2015','Son nulos si se adquieren facultades o derechos careciendo de los requisitos esenciales.',null),
('aux-canarias:24-b8867362a2','aux-canarias',24,'Es nulo de pleno derecho el acto que:','["Lesione los derechos y libertades susceptibles de amparo constitucional", "Se dicte fuera del plazo establecido", "Tenga un defecto de forma que no produzca indefensión", "Incurra en desviación de poder o en cualquier otra infracción del ordenamiento"]'::jsonb,0,'Art. 47.1 a) Ley 39/2015','La lesión de derechos susceptibles de amparo es causa de nulidad de pleno derecho.',null),
('aux-canarias:24-79acf57813','aux-canarias',24,'Los actos nulos o anulables que contengan los elementos constitutivos de otro distinto producirán los efectos de este. Esto se denomina:','["Revocación", "Conservación de actos y trámites", "Convalidación", "Conversión de actos viciados"]'::jsonb,3,'Art. 50 Ley 39/2015','Es la conversión de actos viciados.',null),
('aux-canarias:24-2ff1dc2123','aux-canarias',24,'Es nulo de pleno derecho el acto:','["Que incurra en cualquier infracción del ordenamiento jurídico, incluida la desviación de poder", "Cuyo defecto de forma no produzca indefensión", "Que sea constitutivo de infracción penal o se dicte como consecuencia de esta", "Dictado un día inhábil"]'::jsonb,2,'Art. 47.1 d) Ley 39/2015','Los actos constitutivos de infracción penal o dictados como consecuencia de esta son nulos.',null),
('aux-canarias:24-e14ec132ce','aux-canarias',24,'Son nulos de pleno derecho los actos:','["Dictados por órgano jerárquicamente incompetente", "Que tengan un contenido imposible", "Que no indiquen los recursos", "Que tengan un error material"]'::jsonb,1,'Art. 47.1 c) Ley 39/2015','El contenido imposible es causa de nulidad (art. 47.1 c).',null),
('aux-canarias:25-4d3e5ad7e0','aux-canarias',25,'Los actos administrativos producen efectos:','["Desde su publicación en el boletín oficial, salvo que en ellos se disponga otra cosa", "Desde que son firmes en vía administrativa, salvo que se disponga otra cosa", "Desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa", "Desde su notificación, sin que puedan disponer otra cosa"]'::jsonb,2,'Art. 39.1 Ley 39/2015','Se presumen válidos y producen efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa.',null),
('aux-canarias:25-b37d4cc5a1','aux-canarias',25,'Cuando la notificación ha resultado infructuosa, se hace por medio de un anuncio en:','["El tablón de la sede del órgano", "El Boletín Oficial del Estado", "El boletín oficial de la provincia", "Un periódico de tirada nacional"]'::jsonb,1,'Art. 44 Ley 39/2015','La notificación se hace por medio de un anuncio publicado en el BOE.',null),
('aux-canarias:25-27de992372','aux-canarias',25,'La interposición de un recurso administrativo, como regla general:','["Suspende la ejecución del acto, salvo que una disposición establezca lo contrario", "No suspende la ejecución del acto, salvo que una disposición establezca lo contrario", "Suspende la ejecución del acto durante el plazo para resolver el recurso, salvo que el órgano acuerde lo contrario", "No suspende la ejecución del acto, sin que ninguna disposición normativa pueda establecer otra cosa"]'::jsonb,1,'Art. 117.1 Ley 39/2015','La interposición de cualquier recurso no suspende la ejecución del acto impugnado, salvo disposición en contrario.',null),
('aux-canarias:25-c4095e2ddd','aux-canarias',25,'Si se solicita la suspensión de la ejecución al recurrir y no hay resolución expresa, la ejecución se entiende suspendida cuando pasa:','["10 días desde la solicitud", "15 días hábiles desde la solicitud", "1 mes desde la solicitud", "3 meses desde la solicitud"]'::jsonb,2,'Art. 117.3 Ley 39/2015','Se entiende suspendida si transcurre un mes desde la solicitud sin resolución expresa.',null),
('aux-canarias:25-ece573f0dc','aux-canarias',25,'¿Cuál de los siguientes NO es un medio de ejecución forzosa de los actos administrativos?','["El apremio sobre el patrimonio", "La revocación del acto", "La ejecución subsidiaria", "La multa coercitiva"]'::jsonb,1,'Art. 100.1 Ley 39/2015','Los medios son el apremio sobre el patrimonio, la ejecución subsidiaria, la multa coercitiva y la compulsión sobre las personas.',null),
('aux-canarias:25-e9a36161e4','aux-canarias',25,'Según el art. 98.1, tampoco son inmediatamente ejecutivos los actos:','["Que sean favorables al interesado", "Que necesiten aprobación o autorización superior", "Que pongan fin a la vía administrativa y no hayan sido recurridos", "Que hayan sido notificados con indicación de los recursos procedentes"]'::jsonb,1,'Art. 98.1 d) Ley 39/2015','Tampoco cuando se acuerde su suspensión o una disposición establezca lo contrario.',null),
('aux-canarias:25-1ae6d8a303','aux-canarias',25,'En ningún caso podrá imponerse a los administrados una obligación pecuniaria que:','["No se haya notificado con al menos quince días de antelación", "Supere los 3.000 euros sin autorización judicial previa y expresa", "No estuviese establecida con arreglo a una norma de rango legal", "No estuviese establecida en una norma de rango reglamentario aprobada por el Consejo de Gobierno o el Consejo de Ministros"]'::jsonb,2,'Art. 101.2 Ley 39/2015','Las obligaciones pecuniarias requieren base en una norma de rango legal.',null),
('aux-canarias:25-749476bd25','aux-canarias',25,'La multa coercitiva:','["Requiere autorización judicial previa en todo caso", "Es independiente de las sanciones que puedan imponerse y compatible con ellas", "Sustituye a la sanción que corresponda", "Es incompatible con las sanciones, de modo que si se impone una multa coercitiva no puede imponerse sanción por los mismos hechos"]'::jsonb,1,'Art. 103.2 Ley 39/2015','La multa coercitiva es independiente de las sanciones y compatible con ellas.',null),
('aux-canarias:25-e7d94b6f72','aux-canarias',25,'Las Administraciones pueden imponer multas coercitivas:','["Solo los Ayuntamientos, en el ejercicio de su potestad sancionadora", "Solo en materia tributaria", "Cuando así lo autoricen las leyes, y en la forma y cuantía que estas determinen", "Cuando lo autorice un reglamento, en la forma y cuantía que determine el órgano que ordena la ejecución"]'::jsonb,2,'Art. 103.1 Ley 39/2015','Requieren autorización legal y se reiteran por lapsos de tiempo suficientes para cumplir lo ordenado.',null),
('aux-canarias:25-4744cd0567','aux-canarias',25,'Si para la ejecución forzosa fuese necesario entrar en el domicilio del afectado, se requiere:','["Su consentimiento o, en su defecto, la oportuna autorización judicial", "Basta la resolución administrativa que ordena la ejecución, notificada al afectado", "Autorización del Delegado del Gobierno o, en su defecto, del alcalde", "Su consentimiento o, en su defecto, autorización del órgano superior jerárquico del que ordenó la ejecución"]'::jsonb,0,'Art. 100.3 Ley 39/2015','Se necesita el consentimiento del afectado o autorización judicial.',null),
('aux-canarias:25-d354efe26c','aux-canarias',25,'NO será inmediatamente ejecutiva la resolución:','["De un procedimiento sancionador contra la que quepa algún recurso en vía administrativa, incluido el potestativo de reposición", "De un procedimiento sancionador contra la que quepa recurso de alzada, pero no si solo cabe el potestativo de reposición", "De una solicitud de licencia que haya sido estimada", "De un recurso de alzada"]'::jsonb,0,'Art. 98.1 b) Ley 39/2015','Las sanciones no son ejecutivas mientras quepa recurso administrativo.',null),
('aux-canarias:25-12d646bb29','aux-canarias',25,'La ejecución subsidiaria procede respecto de actos que:','["Impongan obligaciones de no hacer o de soportar, previo apercibimiento al obligado", "Impongan al obligado el pago de cantidades líquidas", "Sean personalísimos de hacer y el obligado se niegue a realizarlos en el plazo fijado", "Por no ser personalísimos puedan ser realizados por sujeto distinto del obligado"]'::jsonb,3,'Art. 102.1 Ley 39/2015','Cabe cuando el acto no es personalísimo y otro sujeto puede realizarlo.',null),
('aux-canarias:25-10e3224300','aux-canarias',25,'Los actos administrativos serán objeto de publicación cuando:','["Lo pida cualquier ciudadano interesado en conocerlos", "Lo establezcan las normas reguladoras de cada procedimiento o lo aconsejen razones de interés público", "Sean desfavorables para el interesado, aunque la norma reguladora no lo prevea", "Lo establezcan las normas reguladoras de cada procedimiento, pero nunca por razones de interés público apreciadas por el órgano"]'::jsonb,1,'Art. 45.1 Ley 39/2015','Se publican cuando lo establezcan sus normas reguladoras o lo aconsejen razones de interés público apreciadas por el órgano competente.',null),
('aux-canarias:25-cd28f5cbed','aux-canarias',25,'La ejecución forzosa de los actos administrativos se efectuará:','["Solo con autorización judicial previa", "Siempre mediante compulsión sobre las personas", "Respetando siempre el principio de proporcionalidad y por los medios menos restrictivos de la libertad individual", "Respetando el principio de eficacia, por el medio más rápido disponible aunque no sea el menos restrictivo de la libertad individual"]'::jsonb,2,'Art. 99 Ley 39/2015','La ejecución forzosa respeta la proporcionalidad y elige el medio menos restrictivo.',null),
('aux-canarias:25-e55dcf339d','aux-canarias',25,'El apremio sobre el patrimonio procede cuando, en virtud del acto, haya de satisfacerse:','["Una obligación de no hacer", "Una cantidad líquida", "Una obligación de soportar", "Una obligación personalísima"]'::jsonb,1,'Art. 101.1 Ley 39/2015','Si hay que satisfacer cantidad líquida se sigue el procedimiento de apremio.',null),
('aux-canarias:25-891d7c92ec','aux-canarias',25,'Las Administraciones no iniciarán ninguna actuación material de ejecución que limite derechos de los particulares:','["Sin informe favorable del Consejo de Estado u órgano consultivo equivalente", "Sin el consentimiento expreso y por escrito del particular afectado por la actuación", "Sin que previamente haya sido adoptada la resolución que le sirva de fundamento jurídico", "Sin autorización judicial en todo caso"]'::jsonb,2,'Art. 97.1 Ley 39/2015','Es necesario un título previo: la resolución que sirve de fundamento jurídico.',null),
('aux-canarias:25-e0f9459ae9','aux-canarias',25,'El órgano que resuelva el recurso podrá suspender la ejecución del acto impugnado cuando:','["La impugnación se fundamente en alguna de las causas de nulidad de pleno derecho del art. 47.1", "La impugnación se fundamente en cualquier causa de anulabilidad, aunque la ejecución no cause perjuicios", "Lo pida un tercero no interesado en el procedimiento", "El acto sea favorable"]'::jsonb,0,'Art. 117.2 b) Ley 39/2015','También cuando la ejecución pueda causar perjuicios de imposible o difícil reparación.',null),
('aux-canarias:25-b14d887a54','aux-canarias',25,'La publicación sustituye a la notificación, entre otros casos, cuando el acto:','["Se dicte en un procedimiento iniciado de oficio que afecte a varios interesados identificados", "Afecte a un único interesado identificado", "Tenga por destinatario a una pluralidad indeterminada de personas", "Sea una sanción leve impuesta a un interesado identificado y con domicilio conocido"]'::jsonb,2,'Art. 45.1 a) Ley 39/2015','También en los actos de procedimientos selectivos o de concurrencia competitiva.',null),
('aux-canarias:25-fded5834a8','aux-canarias',25,'Según el art. 38, los actos de las Administraciones sujetos al Derecho Administrativo son:','["Ejecutivos solo tras su confirmación judicial", "Ejecutivos con arreglo a lo dispuesto en la Ley", "Ejecutivos solo cuando sean firmes en vía administrativa y no se haya interpuesto recurso contencioso-administrativo", "Meramente declarativos hasta que se confirmen judicialmente"]'::jsonb,1,'Art. 38 Ley 39/2015','Los actos sujetos al Derecho Administrativo serán ejecutivos con arreglo a lo dispuesto en la Ley.',null),
('aux-canarias:25-484671a12f','aux-canarias',25,'La compulsión sobre las personas procede, en los casos que la ley expresamente lo autorice, para:','["Obligaciones no personalísimas de hacer que puedan cumplirse por otro", "Cobrar cantidades líquidas", "Cualquier acto, a elección de la Administración", "Actos que impongan una obligación personalísima de no hacer o soportar"]'::jsonb,3,'Art. 104.1 Ley 39/2015','Se aplica a obligaciones personalísimas de no hacer o soportar, respetando la dignidad y los derechos constitucionales.',null),
('aux-canarias:25-6882150c37','aux-canarias',25,'Excepcionalmente, se podrá otorgar eficacia retroactiva a los actos cuando:','["Sean sanciones más favorables que las anteriores", "Se trate de actos de gravamen que restrinjan derechos individuales y así lo prevea expresamente una norma reglamentaria", "Lo solicite cualquier tercero afectado y el acto restrinja derechos individuales del destinatario", "Se dicten en sustitución de actos anulados o produzcan efectos favorables al interesado"]'::jsonb,3,'Art. 39.3 Ley 39/2015','Cabe retroactividad cuando se dicten en sustitución de actos anulados o produzcan efectos favorables, si los supuestos de hecho existían y no se lesionan derechos de terceros.',null),
('aux-canarias:25-8ab329e467','aux-canarias',25,'En la ejecución subsidiaria, el importe de los gastos podrá liquidarse:','["De forma provisional y realizarse antes de la ejecución, a reserva de la liquidación definitiva", "Por el doble de su coste, en concepto de sanción", "Nunca, porque los gastos los asume siempre la Administración que ejecuta", "Solo tras la ejecución, de forma definitiva y sin posibilidad de liquidación provisional"]'::jsonb,0,'Art. 102.4 Ley 39/2015','Cabe liquidación provisional previa a reserva de la definitiva; los gastos corren a cargo del obligado.',null),
('aux-canarias:25-b6ef5c4162','aux-canarias',25,'Si el órgano aprecia que la publicación íntegra de un acto lesiona derechos o intereses legítimos:','["Se publicará íntegramente igualmente, sin perjuicio de la responsabilidad patrimonial que proceda por los daños causados a los interesados afectados", "No se publicará ni notificará el acto, y el órgano se limitará a comunicar a los interesados que existe una resolución que les afecta", "Se enviará al Defensor del Pueblo", "Se limitará a publicar una somera indicación del contenido y del lugar donde los interesados pueden comparecer para conocerlo"]'::jsonb,3,'Art. 46 Ley 39/2015','Se publica una somera indicación del contenido y del lugar donde comparecer en el plazo que se establezca.',null),
('aux-canarias:25-d0c4924483','aux-canarias',25,'La eficacia de un acto quedará demorada cuando:','["Se haya dictado en el mes de agosto o en un periodo vacacional, salvo que el interesado solicite su eficacia inmediata", "El interesado lo solicite verbalmente", "Así lo exija su contenido o esté supeditada a su notificación, publicación o aprobación superior", "Así lo decida el funcionario instructor, aunque su contenido no lo exija ni dependa de notificación o aprobación"]'::jsonb,2,'Art. 39.2 Ley 39/2015','La eficacia se demora cuando lo exija el contenido del acto o esté supeditada a notificación, publicación o aprobación superior.',null),
('aux-canarias:25-f412b547ae','aux-canarias',25,'Si fueran varios los medios de ejecución admisibles, se elegirá:','["El más rápido para la Administración", "El que elija el interesado de entre los admisibles", "El más económico para la Administración actuante", "El menos restrictivo de la libertad individual"]'::jsonb,3,'Art. 100.2 Ley 39/2015','Se elige el menos restrictivo de la libertad individual.',null),
('aux-canarias:25-c8bfdbe6df','aux-canarias',25,'Según el art. 105, no se admitirán a trámite contra las actuaciones de los órganos administrativos realizadas en materia de su competencia y de acuerdo con el procedimiento legal:','["Los recursos contencioso-administrativos", "Las acciones posesorias", "Los recursos de alzada", "Las reclamaciones de responsabilidad"]'::jsonb,1,'Art. 105 Ley 39/2015','No se admiten acciones posesorias contra esas actuaciones.',null),
('aux-canarias:25-a43836b9f9','aux-canarias',25,'Si se trata de obligaciones personalísimas de hacer y no se realiza la prestación, el obligado deberá:','["Resarcir los daños y perjuicios, a cuya liquidación y cobro se procederá en vía administrativa", "Ser objeto de compulsión sobre su persona hasta que realice la prestación, sin resarcimiento alguno", "Nada, la obligación se extingue", "Resarcir los daños y perjuicios, cuya liquidación y cobro solo pueden exigirse en vía judicial civil"]'::jsonb,0,'Art. 104.2 Ley 39/2015','El obligado debe resarcir daños y perjuicios.',null),
('aux-canarias:25-4997af3f85','aux-canarias',25,'El órgano que ordene un acto de ejecución material de resoluciones está obligado a:','["Publicarlo en el BOE y en el boletín autonómico antes de iniciar la actuación material, sin necesidad de notificación personal", "Solicitar autorización judicial", "Esperar a que el acto sea firme en vía administrativa y solicitar autorización judicial para ejecutarlo", "Notificar al particular interesado la resolución que autorice la actuación administrativa"]'::jsonb,3,'Art. 97.2 Ley 39/2015','Debe notificar al particular la resolución que autorice la actuación.',null),
('aux-canarias:26-9f114256cd','aux-canarias',26,'La revisión de oficio de los actos nulos de pleno derecho requiere:','["Dictamen favorable previo del Consejo de Estado u órgano consultivo equivalente de la Comunidad Autónoma", "Dictamen previo, preceptivo pero no vinculante, del Consejo de Estado u órgano consultivo equivalente autonómico", "Sentencia judicial previa que declare la nulidad, a instancia de la Administración", "Informe favorable del servicio jurídico y audiencia previa de todos los interesados"]'::jsonb,0,'Art. 106.1 Ley 39/2015','Requiere dictamen favorable previo del Consejo de Estado u órgano consultivo equivalente de la Comunidad Autónoma, si lo hubiere.',null),
('aux-canarias:26-0439eebeba','aux-canarias',26,'La declaración de lesividad de un acto favorable anulable no puede adoptarse una vez transcurridos desde que se dictó:','["2 años", "4 años", "6 meses", "1 año"]'::jsonb,1,'Art. 107.2 Ley 39/2015','No puede adoptarse una vez transcurridos cuatro años desde que se dictó el acto.',null),
('aux-canarias:26-d99ec66b21','aux-canarias',26,'¿Qué actos pueden revocar las Administraciones mientras no haya transcurrido el plazo de prescripción?','["Los actos favorables", "Los actos firmes de cualquier tipo", "Los actos de gravamen o desfavorables", "Las disposiciones generales"]'::jsonb,2,'Art. 109.1 Ley 39/2015','Pueden revocar sus actos de gravamen o desfavorables mientras no haya transcurrido el plazo de prescripción.',null),
('aux-canarias:26-356f81b610','aux-canarias',26,'Los errores materiales, de hecho o aritméticos de los actos pueden rectificarse:','["En el plazo de un mes desde la notificación, de oficio o a instancia de los interesados", "Solo a instancia de los interesados, mediante el correspondiente recurso de reposición", "Solo antes de la notificación del acto, de oficio por el mismo órgano que lo dictó", "En cualquier momento, de oficio o a instancia de los interesados"]'::jsonb,3,'Art. 109.2 Ley 39/2015','Pueden rectificarse en cualquier momento, de oficio o a instancia de los interesados.',null),
('aux-canarias:26-ca88547d7a','aux-canarias',26,'¿Pueden revisarse de oficio las disposiciones administrativas nulas del art. 47.2?','["Sí, en cualquier momento y sin necesidad de dictamen del órgano consultivo", "No, la revisión de oficio solo alcanza a los actos, no a las disposiciones", "Sí, previo dictamen favorable del Consejo de Estado u órgano consultivo autonómico equivalente", "Sí, previo dictamen no vinculante del Consejo de Estado u órgano consultivo equivalente, y a instancia del interesado"]'::jsonb,2,'Art. 106.2 Ley 39/2015','Las Administraciones pueden declarar de oficio la nulidad de disposiciones del art. 47.2 previo dictamen favorable.',null),
('aux-canarias:26-d34bcc3bec','aux-canarias',26,'En la AGE, son competentes para la revisión de oficio de sus propios actos y de los dictados por los Ministros:','["El Consejo de Estado", "Los Subsecretarios", "El Presidente del Gobierno en solitario", "El Consejo de Ministros"]'::jsonb,3,'Art. 111 a) Ley 39/2015','El Consejo de Ministros revisa sus propios actos y disposiciones y los de los Ministros.',null),
('aux-canarias:26-dd173e9eab','aux-canarias',26,'Si el procedimiento de revisión de oficio se inició de oficio y transcurren seis meses sin resolución, se produce:','["La estimación por silencio", "La caducidad del mismo", "La prórroga automática del plazo", "La nulidad automática del acto"]'::jsonb,1,'Art. 106.5 Ley 39/2015','Iniciado de oficio: caducidad. Iniciado a solicitud: se podrá entender desestimada.',null),
('aux-canarias:26-9cab4b0d42','aux-canarias',26,'Transcurrido el plazo de seis meses desde la iniciación del procedimiento de lesividad sin que se haya declarado, se produce:','["La declaración automática de lesividad", "La nulidad del acto", "La estimación del interesado por silencio", "La caducidad del procedimiento"]'::jsonb,3,'Art. 107.3 Ley 39/2015','Pasados seis meses sin declaración de lesividad, el procedimiento caduca.',null),
('aux-canarias:26-654c47c1db','aux-canarias',26,'Iniciado un procedimiento de revisión de oficio o de lesividad, el órgano competente podrá suspender la ejecución del acto cuando:','["El acto sea favorable al interesado y este lo solicite antes de que se dicte la resolución", "Esta pudiera causar perjuicios de imposible o difícil reparación", "Lo solicite cualquier tercero, aunque no acredite la condición de interesado ni perjuicio alguno", "Hayan transcurrido seis meses desde que se dictó el acto"]'::jsonb,1,'Art. 108 Ley 39/2015','Puede suspenderse si la ejecución causaría perjuicios de imposible o difícil reparación.',null),
('aux-canarias:26-c68fe4b6cc','aux-canarias',26,'En las Entidades Locales, la declaración de lesividad corresponde a:','["El Pleno de la Corporación o, en su defecto, el órgano colegiado superior de la entidad", "La Junta de Gobierno Local en todo caso, previo dictamen del órgano consultivo autonómico", "El Alcalde, dando cuenta al Pleno", "El Alcalde o, en su defecto, el Secretario municipal, previo informe preceptivo del Interventor"]'::jsonb,0,'Art. 107.5 Ley 39/2015','La adopta el Pleno o, en su defecto, el órgano colegiado superior.',null),
('aux-canarias:26-228693adaa','aux-canarias',26,'Al declarar la nulidad de una disposición o acto, las Administraciones podrán:','["Establecer en la misma resolución las indemnizaciones que proceda reconocer a los interesados", "Exigir a los interesados el reintegro de lo percibido sin necesidad de procedimiento ni audiencia previa", "Imponer sanciones a los interesados que se beneficiaron del acto nulo, sin necesidad de procedimiento", "Dejar sin efecto las sentencias dictadas sobre el acto"]'::jsonb,0,'Art. 106.4 Ley 39/2015','Pueden fijar indemnizaciones si concurren los requisitos de responsabilidad patrimonial.',null),
('aux-canarias:26-0135e74543','aux-canarias',26,'El órgano competente podrá inadmitir sin dictamen las solicitudes de revisión de oficio formuladas por interesados cuando:','["Se refieran a actos favorables", "Sean formuladas por personas jurídicas", "Se presenten en papel", "Carezcan manifiestamente de fundamento"]'::jsonb,3,'Art. 106.3 Ley 39/2015','También cuando no se basen en causas de nulidad o se hayan desestimado en cuanto al fondo otras sustancialmente iguales.',null),
('aux-canarias:26-d4ce90f0be','aux-canarias',26,'Las facultades de revisión no podrán ejercerse cuando:','["Lo solicite el propio interesado", "El acto sea nulo de pleno derecho", "Por prescripción de acciones, tiempo transcurrido u otras circunstancias, su ejercicio resulte contrario a la equidad, la buena fe, el derecho de los particulares o las leyes", "Haya transcurrido un año desde la notificación del acto, cualquiera que sea el vicio que lo afecte y aunque su ejercicio no resulte contrario a la equidad, la buena fe ni el derecho de los particulares"]'::jsonb,2,'Art. 110 Ley 39/2015','Son los límites de la revisión.',null),
('aux-canarias:26-a9381448ee','aux-canarias',26,'La declaración de lesividad de los actos favorables anulables tiene como finalidad:','["Sancionar al interesado que se benefició del acto", "Convertirlos en actos nulos de pleno derecho para poder revisarlos de oficio en cualquier momento", "Su posterior impugnación ante el orden jurisdiccional contencioso-administrativo", "Anularlos directamente en vía administrativa"]'::jsonb,2,'Art. 107.1 Ley 39/2015','La Administración declara la lesividad para impugnarlos después ante la jurisdicción contencioso-administrativa.',null),
('aux-canarias:27-5c1f4f23ed','aux-canarias',27,'Cuando los plazos se señalan por días, se entiende que son:','["Naturales, salvo que una ley disponga otro cómputo", "Hábiles, excluyéndose los sábados, los domingos y los festivos", "Hábiles, excluyéndose solo los domingos y los declarados festivos", "Naturales, salvo en el mes de agosto, en que son hábiles"]'::jsonb,1,'Art. 30.2 Ley 39/2015','Los plazos por días son hábiles y se excluyen sábados, domingos y festivos.',null),
('aux-canarias:27-baf406fdbd','aux-canarias',27,'Los plazos señalados por horas no pueden tener una duración superior a:','["12 horas", "48 horas", "24 horas", "72 horas"]'::jsonb,2,'Art. 30.1 Ley 39/2015','Son hábiles todas las horas de un día hábil y no pueden superar 24 horas; si no, se expresan en días.',null),
('aux-canarias:27-27056526a4','aux-canarias',27,'Los plazos fijados en meses o años se computan:','["Por días hábiles, a partir del día siguiente a la notificación o publicación", "Por días naturales, desde el mismo día de la notificación o publicación", "Desde el mismo día de la notificación o publicación del acto", "A partir del día siguiente a la notificación o publicación del acto"]'::jsonb,3,'Art. 30.4 Ley 39/2015','Se computan a partir del día siguiente a la notificación o publicación, de fecha a fecha.',null),
('aux-canarias:27-1ab76d5b88','aux-canarias',27,'La ampliación de los plazos establecidos no puede exceder de:','["La mitad de los mismos", "El doble de los mismos", "Un mes en todo caso", "Tres meses"]'::jsonb,0,'Art. 32.1 Ley 39/2015','La ampliación no puede exceder de la mitad del plazo.',null),
('aux-canarias:27-ecf77392de','aux-canarias',27,'La presentación de un documento en el registro electrónico en un día inhábil se entiende realizada:','["En la primera hora del primer día hábil siguiente", "En la última hora del último día hábil anterior al de la presentación", "El mismo día inhábil, a la hora en que se presentó", "A las 9 horas del tercer día hábil siguiente"]'::jsonb,0,'Art. 31.2 b) Ley 39/2015','Se entiende realizada en la primera hora del primer día hábil siguiente, salvo que una norma permita la recepción en día inhábil.',null),
('aux-canarias:27-d0717f6f53','aux-canarias',27,'Cuando en una solicitud figuren varios interesados, las actuaciones se efectuarán:','["Con el que elija la Administración en cada trámite, notificando a los demás", "Con todos a la vez, de forma obligatoria y en igualdad de condiciones, salvo renuncia expresa de alguno de ellos por escrito", "Con el de mayor edad, salvo que todos hayan señalado expresamente a otro, y en su defecto con todos los interesados a la vez", "Con el representante o interesado que expresamente hayan señalado y, en su defecto, con el que figure en primer término"]'::jsonb,3,'Art. 7 Ley 39/2015','En defecto de designación, con el que figure en primer término.',null),
('aux-canarias:27-5f0119e4b7','aux-canarias',27,'Tienen la consideración de Administraciones Públicas según el art. 2.3:','["La AGE, las Administraciones de las CCAA, las Entidades de la Administración Local y los organismos públicos y entidades de derecho público del art. 2.2 a)", "La AGE, las Administraciones de las CCAA y las Entidades Locales, pero no los organismos públicos vinculados o dependientes", "La AGE, las Administraciones de las CCAA, las Entidades de la Administración Local, las universidades privadas, los colegios profesionales y todas las empresas con capital público", "Los colegios profesionales en todo caso"]'::jsonb,0,'Art. 2.3 Ley 39/2015','Son AAPP la AGE, las CCAA, las Entidades Locales y los organismos y entidades de derecho público vinculados o dependientes.',null),
('aux-canarias:27-56f3450798','aux-canarias',27,'Según su art. 1.1, la Ley 39/2015 regula, entre otros aspectos:','["El régimen jurídico de los funcionarios y del personal laboral al servicio de las Administraciones", "La jurisdicción contencioso-administrativa y sus procedimientos, así como el régimen de los recursos judiciales contra los actos de las Administraciones", "Los requisitos de validez y eficacia de los actos administrativos y el procedimiento administrativo común a todas las Administraciones", "La organización interna de la AGE y de su sector público institucional, y el régimen de los órganos colegiados de todas las Administraciones"]'::jsonb,2,'Art. 1.1 Ley 39/2015','Incluye el procedimiento sancionador, el de responsabilidad patrimonial y los principios de iniciativa legislativa y potestad reglamentaria.',null),
('aux-canarias:27-0fe34a8029','aux-canarias',27,'El registro electrónico de cada Administración permitirá la presentación de documentos:','["Solo en horario de oficina de cada órgano", "Solo de lunes a viernes, a cualquier hora", "Solo en días hábiles, durante las veinticuatro horas", "Todos los días del año durante las veinticuatro horas"]'::jsonb,3,'Art. 31.2 Ley 39/2015','El registro electrónico funciona 24 horas los 365 días.',null),
('aux-canarias:27-b7f4ac8a1e','aux-canarias',27,'La representación podrá acreditarse mediante:','["Únicamente escritura notarial de apoderamiento, que deberá presentarse en papel en el registro del órgano competente en cada uno de los procedimientos en que se actúe", "Únicamente comparecencia personal ante el órgano competente", "Cualquier medio válido en Derecho que deje constancia fidedigna, comparecencia personal o electrónica, o inscripción en el registro de apoderamientos", "Cualquier medio, incluida una llamada telefónica o un correo electrónico sin firma, siempre que el funcionario que lo recibe deje constancia escrita en el expediente"]'::jsonb,2,'Art. 5.4 Ley 39/2015','Se admite cualquier medio válido en Derecho que deje constancia fidedigna.',null),
('aux-canarias:27-b0cf1d5024','aux-canarias',27,'Si el interesado actúa por medio de representante:','["Se requiere poder notarial en todo caso", "Las actuaciones se entienden siempre con el interesado, y solo se comunican al representante a título informativo", "Solo puede actuar como representante un abogado colegiado", "Las actuaciones se entenderán con el representante, salvo manifestación expresa en contrario del interesado"]'::jsonb,3,'Art. 5.1 Ley 39/2015','Se entienden con el representante salvo manifestación expresa en contrario.',null),
('aux-canarias:27-b822fee8f6','aux-canarias',27,'Cuando el último día del plazo sea inhábil:','["Se entenderá vencido el último día hábil anterior", "Se entenderá prorrogado al primer día hábil siguiente", "Se entenderá prorrogado al tercer día hábil siguiente", "El plazo vence ese mismo día"]'::jsonb,1,'Art. 30.5 Ley 39/2015','Se prorroga al primer día hábil siguiente.',null),
('aux-canarias:27-5f6ab07445','aux-canarias',27,'Cuando la condición de interesado deriva de una relación jurídica transmisible, el derecho-habiente:','["No sucede, debiendo iniciar un nuevo procedimiento en el plazo de diez días", "Solo sucede si todavía no se ha abierto la fase de instrucción", "Sucederá en tal condición cualquiera que sea el estado del procedimiento", "Sucederá en tal condición solo si el procedimiento no ha concluido la fase de audiencia a los interesados"]'::jsonb,2,'Art. 4.3 Ley 39/2015','Sucede en la condición de interesado en cualquier estado del procedimiento.',null),
('aux-canarias:27-2a8f54d329','aux-canarias',27,'Las asociaciones y organizaciones representativas de intereses económicos y sociales son titulares de:','["Intereses individuales de cada uno de sus asociados", "Intereses legítimos colectivos en los términos que la ley reconozca", "Derechos fundamentales propios en todo procedimiento administrativo que afecte a sus asociados o al sector", "Ningún interés"]'::jsonb,1,'Art. 4.2 Ley 39/2015','Son titulares de intereses legítimos colectivos.',null),
('aux-canarias:27-530f0bdab3','aux-canarias',27,'La AGE, las CCAA y las Entidades Locales dispondrán de:','["Un registro electrónico general de apoderamientos", "Un registro de representantes en papel", "Un registro notarial propio", "Un registro único estatal compartido obligatoriamente"]'::jsonb,0,'Art. 6.1 Ley 39/2015','Cada una dispone de un registro electrónico general de apoderamientos.',null),
('aux-canarias:27-6e1ce5a8b3','aux-canarias',27,'Son interesados en el procedimiento, según el art. 4.1 a):','["Cualquier ciudadano, sin necesidad de acreditar interés alguno", "Quienes lo promuevan como titulares de derechos subjetivos, pero no de intereses legítimos colectivos", "Quienes tengan derechos que puedan resultar afectados por la decisión, aunque no se hayan personado", "Quienes lo promuevan como titulares de derechos o intereses legítimos individuales o colectivos"]'::jsonb,3,'Art. 4.1 a) Ley 39/2015','También los que tengan derechos que puedan resultar afectados y los titulares de intereses legítimos que se personen antes de la resolución definitiva.',null),
('aux-canarias:27-aad6f7d2a8','aux-canarias',27,'La ampliación de un plazo y su solicitud deberán producirse:','["Solo el último día del plazo de que se trate", "En todo caso antes del vencimiento del plazo de que se trate", "Hasta diez días después del vencimiento del plazo, si se justifica la causa", "En cualquier momento"]'::jsonb,1,'Art. 32.3 Ley 39/2015','En ningún caso podrá ampliarse un plazo ya vencido.',null),
('aux-canarias:27-6d0803f93e','aux-canarias',27,'Cuando razones de interés público lo aconsejen, podrá acordarse la tramitación de urgencia, que supone:','["Reducir todos los plazos a cinco días, incluidos los de recursos", "Suprimir los recursos administrativos", "Reducir a la mitad todos los plazos del procedimiento, incluidos los de presentación de solicitudes y recursos", "Reducir a la mitad los plazos del procedimiento ordinario, salvo los relativos a la presentación de solicitudes y recursos"]'::jsonb,3,'Art. 33.1 Ley 39/2015','Se reducen los plazos a la mitad, salvo los de solicitudes y recursos.',null),
('aux-canarias:27-cb606349d9','aux-canarias',27,'Si un plazo fijado en meses vence en un mes en el que no hay día equivalente al de la notificación:','["El plazo expira el último día del mes", "El plazo se amplía 10 días", "El plazo expira el primer día del mes siguiente", "El plazo se considera vencido el día 28"]'::jsonb,0,'Art. 30.4 Ley 39/2015','Si no hay día equivalente, el plazo expira el último día del mes.',null),
('aux-canarias:27-d41f1d39a3','aux-canarias',27,'Si durante la instrucción de un procedimiento no publicado se advierte la existencia de personas titulares de derechos o intereses legítimos que puedan resultar afectados:','["Se comunicará a dichas personas la tramitación del procedimiento", "No se les comunica nada hasta la resolución, que se les notifica", "Se suspenderá el procedimiento hasta que soliciten personarse", "Se archivará el procedimiento"]'::jsonb,0,'Art. 8 Ley 39/2015','Se les comunica la tramitación.',null),
('aux-canarias:27-b6da2dfe9a','aux-canarias',27,'Si un día es hábil en el municipio del interesado e inhábil en la sede del órgano administrativo, o a la inversa:','["Se aplica el calendario del órgano", "Se aplica el calendario del interesado", "Se considerará inhábil en todo caso", "Se considerará hábil en todo caso"]'::jsonb,2,'Art. 30.6 Ley 39/2015','En caso de discrepancia, se considera inhábil.',null),
('aux-canarias:27-4094e3e952','aux-canarias',27,'La falta o insuficiente acreditación de la representación no impedirá que se tenga por realizado el acto, siempre que se aporte o subsane en el plazo de:','["Cinco días improrrogables desde el requerimiento, sin que el órgano pueda establecer otro plazo", "Quince días hábiles", "Un mes desde el requerimiento", "Diez días, o el plazo superior que establezca el órgano cuando las circunstancias lo requieran"]'::jsonb,3,'Art. 5.6 Ley 39/2015','El plazo para subsanar es de diez días.',null),
('aux-canarias:27-0d2865180e','aux-canarias',27,'Deberá acreditarse la representación para:','["Formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar a derechos", "Pedir información general sobre los procedimientos", "Consultar el estado del expediente", "Cualquier acto de mero trámite, incluida la consulta del expediente, la obtención de copias y la petición de información general"]'::jsonb,0,'Art. 5.3 Ley 39/2015','Para los actos de mero trámite la representación se presume.',null),
('aux-canarias:27-7c924f5b9f','aux-canarias',27,'¿Cuál de las siguientes es una tipología de apoderamiento inscribible en el registro electrónico de apoderamientos?','["Un poder otorgado verbalmente ante el funcionario", "Un poder general para que el apoderado actúe en nombre del poderdante en cualquier actuación ante cualquier Administración", "Un poder especial para actuar ante los juzgados y tribunales penales en nombre del poderdante, en cualquier procedimiento", "Un poder sin identificar al apoderado"]'::jsonb,1,'Art. 6 Ley 39/2015','Las tipologías son: poder general, poder ante una Administración u Organismo concreto y poder para trámites específicos.',null),
('aux-canarias:27-941f63f6c6','aux-canarias',27,'La ampliación de plazos por el tiempo máximo permitido se aplicará en todo caso a los procedimientos tramitados por:','["Las Comunidades Autónomas cuando afecten a varias provincias", "Los órganos colegiados de cualquier Administración, y los que exijan algún trámite en otra Comunidad Autónoma", "Las misiones diplomáticas y oficinas consulares, y los que exijan algún trámite en el extranjero", "Los Ayuntamientos de municipios de gran población, y los que exijan algún trámite en otra Comunidad Autónoma"]'::jsonb,2,'Art. 32.2 Ley 39/2015','Se aplica a misiones diplomáticas, oficinas consulares y trámites en el extranjero o con interesados residentes fuera de España.',null),
('aux-canarias:27-547cf18e79','aux-canarias',27,'Los titulares de intereses legítimos que puedan resultar afectados por la resolución son interesados si:','["Se personan en el procedimiento en tanto no haya recaído resolución definitiva", "Lo solicitan antes del inicio del procedimiento", "Se personan en cualquier momento, incluso después de la resolución definitiva", "Lo autoriza el instructor"]'::jsonb,0,'Art. 4.1 c) Ley 39/2015','Deben personarse antes de la resolución definitiva.',null),
('aux-canarias:27-3188cddd31','aux-canarias',27,'Tienen capacidad de obrar ante las Administraciones Públicas:','["Solo los españoles mayores de edad", "Las personas físicas o jurídicas que la ostenten con arreglo a las normas civiles", "Solo los mayores de 21 años y las personas jurídicas inscritas en un registro público", "Las personas físicas o jurídicas con certificado digital, aunque no tengan capacidad conforme a las normas civiles"]'::jsonb,1,'Art. 3 a) Ley 39/2015','Tienen capacidad las personas que la tengan según las normas civiles.',null),
('aux-canarias:27-365c0df722','aux-canarias',27,'Según el art. 3 c), los grupos de afectados y las entidades sin personalidad jurídica tienen capacidad de obrar:','["Siempre, cualquiera que sea su número de miembros", "Cuando tengan más de 20 miembros", "Cuando la ley así lo declare expresamente", "Cuando se inscriban en el registro correspondiente de la Administración ante la que actúen"]'::jsonb,2,'Art. 3 c) Ley 39/2015','Grupos de afectados, uniones y entidades sin personalidad y patrimonios independientes tienen capacidad cuando la ley lo declare expresamente.',null),
('aux-canarias:27-6ded6e6069','aux-canarias',27,'Los términos y plazos establecidos en las leyes obligan:','["Solo a la Administración, que debe resolver en el plazo máximo", "Solo a los interesados, que pierden su derecho si no los cumplen", "A las autoridades y personal al servicio de las Administraciones competentes para la tramitación, así como a los interesados", "A las autoridades y personal de la Administración, pero no a los interesados, que pueden cumplir los trámites en cualquier momento"]'::jsonb,2,'Art. 29 Ley 39/2015','Los plazos obligan tanto a la Administración como a los interesados.',null),
('aux-canarias:27-7bcc8359f3','aux-canarias',27,'Los plazos expresados en días se contarán:','["Desde que el interesado tenga conocimiento efectivo del acto", "Desde el mismo día de la notificación o publicación del acto", "Desde el día en que se dictó el acto, aunque se notifique o publique con posterioridad a esa fecha", "A partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto"]'::jsonb,3,'Art. 30.3 Ley 39/2015','Se cuentan desde el día siguiente a la notificación o publicación.',null),
('aux-canarias:27-ded587e1fb','aux-canarias',27,'Los poderes inscritos en el registro electrónico de apoderamientos tendrán una validez máxima de:','["Diez años a contar desde la fecha de inscripción", "Un año, renovable por periodos iguales", "Cinco años a contar desde la fecha de inscripción", "Indefinida, hasta su revocación"]'::jsonb,2,'Art. 6.6 Ley 39/2015','Validez máxima de cinco años; pueden revocarse o prorrogarse, la prórroga por un máximo de cinco años.',null),
('aux-canarias:27-8264b24a20','aux-canarias',27,'Contra el acuerdo que declare la tramitación de urgencia:','["No cabrá recurso alguno, sin perjuicio del procedente contra la resolución que ponga fin al procedimiento", "Cabe recurso contencioso-administrativo inmediato", "Cabe recurso de alzada", "Cabe recurso potestativo de reposición en el plazo de un mes desde su notificación, que no suspende la tramitación"]'::jsonb,0,'Art. 33.2 Ley 39/2015','El acuerdo de urgencia no es recurrible.',null),
('aux-canarias:27-63234f99d5','aux-canarias',27,'Según el art. 1.2, solo podrán incluirse trámites adicionales o distintos de los de la Ley 39/2015:','["Mediante circular o instrucción interna", "Por decisión del órgano instructor", "Mediante reglamento, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento", "Mediante ley, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento"]'::jsonb,3,'Art. 1.2 Ley 39/2015','Solo mediante ley y de forma motivada.',null),
('aux-canarias:27-2e603c993d','aux-canarias',27,'Para los actos y gestiones de mero trámite, la representación:','["No está permitida", "Se presumirá", "Debe acreditarse ante notario", "Debe inscribirse en el registro de apoderamientos"]'::jsonb,1,'Art. 5.3 Ley 39/2015','En los actos de mero trámite se presume la representación.',null),
('aux-canarias:27-e57899eae4','aux-canarias',27,'La presentación de documentos en el registro electrónico en un día inhábil se entiende realizada:','["Al día siguiente, aunque también sea inhábil", "El último día hábil anterior", "En el mismo día inhábil, a todos los efectos", "En la primera hora del primer día hábil siguiente, salvo que una norma permita expresamente la recepción en día inhábil"]'::jsonb,3,'Art. 31.2 b) Ley 39/2015','Los documentos se consideran presentados por el orden de hora efectiva en el que lo fueron en el día inhábil.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-canarias:27-2a1fa559bb','aux-canarias',27,'El registro electrónico de cada Administración permite la presentación de documentos:','["Todos los días del año, durante las veinticuatro horas", "En días hábiles, pero durante las veinticuatro horas de cada día", "En días hábiles, de 9 a 14 horas, como las oficinas presenciales", "Todos los días del año, pero solo en el horario de atención al público"]'::jsonb,0,'Art. 31.2 a) Ley 39/2015','El cómputo de plazos se rige por la fecha y hora oficial de la sede electrónica.',null),
('aux-canarias:28-037d4630d6','aux-canarias',28,'¿Cuál de las siguientes NO es una forma de iniciación de oficio del procedimiento?','["Propia iniciativa del órgano", "Orden superior", "Solicitud del interesado", "Petición razonada de otros órganos"]'::jsonb,2,'Art. 58 Ley 39/2015','De oficio se inicia por propia iniciativa, orden superior, petición razonada de otros órganos o denuncia. La solicitud del interesado es la otra vía de inicio.',null),
('aux-canarias:28-c22c140159','aux-canarias',28,'Si la solicitud no reúne los requisitos exigidos, se requiere al interesado para que la subsane en el plazo de:','["5 días, con indicación de que si no lo hace se archivará sin más trámite", "10 días, con indicación de que si no lo hace se le tendrá por desistido", "15 días, con indicación de que si no lo hace se le tendrá por desistido", "10 días, con indicación de que si no lo hace se declarará la caducidad"]'::jsonb,1,'Art. 68.1 Ley 39/2015','Se le da un plazo de diez días, con apercibimiento de que, si no lo hace, se le tendrá por desistido.',null),
('aux-canarias:28-5ef142f74c','aux-canarias',28,'El periodo de prueba en el procedimiento administrativo tiene una duración:','["No superior a 15 días ni inferior a 5", "De 20 días exactos", "No superior a 30 días ni inferior a 10", "No superior a 2 meses"]'::jsonb,2,'Art. 77.2 Ley 39/2015','El periodo de prueba no puede ser superior a treinta días ni inferior a diez.',null),
('aux-canarias:28-2529aaea39','aux-canarias',28,'Salvo disposición expresa en contrario, los informes son:','["Preceptivos y vinculantes", "Preceptivos y no vinculantes", "Facultativos y vinculantes", "Facultativos y no vinculantes"]'::jsonb,3,'Art. 80.1 Ley 39/2015','Salvo disposición expresa, los informes son facultativos y no vinculantes.',null),
('aux-canarias:28-ea02982ce8','aux-canarias',28,'Salvo que se fije otro plazo, los informes deben emitirse en:','["10 días", "15 días", "1 mes", "3 días"]'::jsonb,0,'Art. 80.2 Ley 39/2015','Los informes se emiten en el plazo de diez días, salvo que una disposición o el cumplimiento del resto de plazos exija otro.',null),
('aux-canarias:28-1800b83496','aux-canarias',28,'En el trámite de audiencia, los interesados disponen de un plazo:','["No inferior a 5 días ni superior a 10", "No inferior a 10 días ni superior a 15", "De 20 días", "No inferior a 15 días ni superior a 30"]'::jsonb,1,'Art. 82.2 Ley 39/2015','El plazo de audiencia no puede ser inferior a diez días ni superior a quince.',null),
('aux-canarias:28-6789d2ef0c','aux-canarias',28,'El plazo del trámite de información pública no puede ser inferior a:','["10 días", "15 días", "20 días", "1 mes"]'::jsonb,2,'Art. 83.2 Ley 39/2015','El plazo de información pública no puede ser inferior a veinte días.',null),
('aux-canarias:28-e60de9c773','aux-canarias',28,'¿Cuál de las siguientes NO pone fin al procedimiento administrativo?','["La resolución", "El desistimiento", "La declaración de caducidad", "La interposición de un recurso"]'::jsonb,3,'Art. 84.1 Ley 39/2015','Ponen fin al procedimiento la resolución, el desistimiento, la renuncia y la caducidad, y también la imposibilidad material sobrevenida.',null),
('aux-canarias:28-6427b5fc7c','aux-canarias',28,'En un procedimiento iniciado a solicitud que se paraliza por causa del interesado, la Administración le advierte de que se producirá la caducidad pasados:','["3 meses", "1 mes", "6 meses", "10 días"]'::jsonb,0,'Art. 95.1 Ley 39/2015','Transcurridos tres meses tras la advertencia sin que el interesado actúe, se produce la caducidad.',null),
('aux-canarias:28-6cc35bb83d','aux-canarias',28,'Se podrá prescindir del trámite de audiencia cuando:','["Se trate de un procedimiento sancionador o de responsabilidad patrimonial", "El interesado sea una persona jurídica obligada a relacionarse electrónicamente", "No figuren ni sean tenidos en cuenta otros hechos, alegaciones o pruebas que los aducidos por el interesado", "Lo acuerde motivadamente el instructor por razones de urgencia, aunque se tengan en cuenta hechos nuevos no aportados por el interesado"]'::jsonb,2,'Art. 82.4 Ley 39/2015','Si solo se valora lo aportado por el interesado, la audiencia puede omitirse.',null),
('aux-canarias:28-7fd3dc7235','aux-canarias',28,'A los interesados que no cumplan lo dispuesto en un trámite:','["Se les tendrá por desistidos de su solicitud y se archivará el procedimiento sin más trámite", "Se les podrá declarar decaídos en su derecho al trámite correspondiente", "Se les impondrá una multa coercitiva", "Se declara la caducidad"]'::jsonb,1,'Art. 73.3 Ley 39/2015','Se admitirá su actuación si se produce antes o dentro del día en que se notifique la resolución que tenga por transcurrido el plazo.',null),
('aux-canarias:28-3bb2f8368c','aux-canarias',28,'La declaración responsable es el documento por el que el interesado manifiesta, bajo su responsabilidad:','["Que acepta cualquier sanción que se derive de la falsedad de los datos aportados", "Que cumple los requisitos de la normativa vigente, dispone de la documentación que lo acredita y la pondrá a disposición de la Administración cuando se le requiera", "Que cumple los requisitos de la normativa vigente y aporta en ese momento toda la documentación que lo acredita, sin que la Administración pueda requerírsela después", "Que pone en conocimiento de la Administración sus datos identificativos"]'::jsonb,1,'Art. 69.1 Ley 39/2015','Definición legal de la declaración responsable.',null),
('aux-canarias:28-fcff96859e','aux-canarias',28,'La petición razonada de iniciación:','["No vincula al órgano competente, que deberá comunicar los motivos por los que, en su caso, no inicia", "Equivale a una denuncia y obliga a iniciar el procedimiento", "Solo puede formularla un ciudadano afectado", "Vincula al órgano competente para iniciar, que solo puede rechazarla si concurre una causa de inadmisión prevista en la ley"]'::jsonb,0,'Art. 61.2 Ley 39/2015','No es vinculante, pero hay que comunicar los motivos de no iniciar.',null),
('aux-canarias:28-58fc71a218','aux-canarias',28,'No podrá acordarse la caducidad del procedimiento por la simple inactividad del interesado en la cumplimentación de trámites:','["En ningún caso, cualquiera que sea el trámite omitido", "Siempre que no sean indispensables para dictar resolución", "Si el interesado es persona jurídica obligada a relacionarse electrónicamente", "Aunque sean indispensables para dictar resolución, si ha transcurrido el plazo"]'::jsonb,1,'Art. 95.2 Ley 39/2015','La inactividad en trámites no indispensables no da lugar a caducidad.',null),
('aux-canarias:28-d58799a86b','aux-canarias',28,'La efectividad de las reducciones por reconocimiento o pago voluntario está condicionada a:','["El desistimiento o renuncia de cualquier acción o recurso en vía administrativa contra la sanción", "Que la sanción sea inferior a 300 euros", "El desistimiento o renuncia de cualquier acción o recurso, tanto en vía administrativa como contencioso-administrativa", "La conformidad de la víctima o del denunciante y la renuncia expresa a la vía contencioso-administrativa"]'::jsonb,0,'Art. 85.3 Ley 39/2015','El infractor debe desistir o renunciar a recursos administrativos.',null),
('aux-canarias:28-9690fe3c84','aux-canarias',28,'Los procedimientos caducados:','["Impiden iniciar uno nuevo", "Interrumpen la prescripción", "No interrumpirán el plazo de prescripción", "Producen por sí solos la prescripción de las acciones"]'::jsonb,2,'Art. 95.3 Ley 39/2015','La caducidad no produce por sí sola la prescripción, pero el procedimiento caducado no la interrumpe.',null),
('aux-canarias:28-9e8fd985a3','aux-canarias',28,'En los procedimientos de responsabilidad patrimonial es preceptivo solicitar informe al servicio cuyo funcionamiento haya ocasionado la presunta lesión, que deberá emitirse en un plazo máximo de:','["Dos meses", "Quince días", "Un mes", "Diez días"]'::jsonb,3,'Art. 81.1 Ley 39/2015','El informe del servicio no puede exceder de diez días.',null),
('aux-canarias:28-a87fa1920d','aux-canarias',28,'En los procedimientos sancionadores, los hechos declarados probados por resoluciones judiciales penales firmes:','["No vinculan a la Administración, que debe valorarlos libremente", "Solo vinculan si el interesado lo solicita expresamente en sus alegaciones al acuerdo de iniciación", "Vincularán a las Administraciones Públicas en los procedimientos sancionadores que substancien", "Vincularán a las Administraciones solo si la sentencia penal es condenatoria y se dictó antes de iniciarse el procedimiento"]'::jsonb,2,'Art. 77.4 Ley 39/2015','Los hechos probados en sentencia penal firme vinculan a la Administración.',null),
('aux-canarias:28-3286a102c3','aux-canarias',28,'La resolución del procedimiento se dictará:','["Por escrito en papel, firmado por el titular del órgano", "Electrónicamente, garantizando la identidad del órgano competente y la autenticidad e integridad del documento", "Electrónicamente o en papel, a elección del órgano, garantizando solo la identidad del firmante y no la integridad del documento", "Verbalmente, con constancia en acta"]'::jsonb,1,'Art. 88.4 Ley 39/2015','La resolución se dicta electrónicamente.',null),
('aux-canarias:28-7d26ce1d73','aux-canarias',28,'¿Quién puede acordar un período de información pública?','["El órgano al que corresponda la resolución del procedimiento, cuando su naturaleza lo requiera", "El instructor del procedimiento, a petición de cualquier interesado y siempre que lo autorice el órgano superior jerárquico", "Cualquier interesado, comunicándolo al órgano instructor, siempre que lo considere útil para su defensa", "El órgano que inició el procedimiento, solo en los procedimientos sancionadores"]'::jsonb,0,'Art. 83.1 Ley 39/2015','Lo acuerda el órgano competente para resolver.',null),
('aux-canarias:28-d798f40be0','aux-canarias',28,'Excepcionalmente, cuando al iniciar el procedimiento sancionador no existan elementos suficientes para la calificación inicial de los hechos, esta podrá realizarse en una fase posterior mediante:','["Una propuesta de resolución que deberá notificarse a los interesados", "La elaboración de un Pliego de cargos, que deberá ser notificado a los interesados", "La elaboración de un Pliego de cargos, que no se notifica a los interesados hasta la propuesta de resolución definitiva del instructor", "Un nuevo acuerdo de iniciación"]'::jsonb,1,'Art. 64.3 Ley 39/2015','Se elabora un Pliego de cargos que se notifica a los interesados.',null),
('aux-canarias:28-933212bb8f','aux-canarias',28,'Iniciado un procedimiento sancionador, si el infractor reconoce su responsabilidad:','["Se reduce la sanción a la mitad de forma automática", "Se archiva el procedimiento sin imponer sanción, si el infractor paga voluntariamente", "Se podrá resolver el procedimiento con la imposición de la sanción que proceda", "Se podrá resolver el procedimiento sin imponer sanción, salvo que la infracción sea muy grave o el infractor sea reincidente"]'::jsonb,2,'Art. 85.1 Ley 39/2015','El reconocimiento permite resolver con la sanción procedente.',null),
('aux-canarias:28-a3727e34fb','aux-canarias',28,'Si antes del vencimiento del plazo de audiencia los interesados manifiestan su decisión de no efectuar alegaciones:','["Se tendrá por decaído su derecho y se archivará el procedimiento", "Se tendrá por realizado el trámite", "Se ampliará de oficio el plazo para que puedan reconsiderar su decisión, que no será vinculante hasta su vencimiento", "Se suspenderá el procedimiento"]'::jsonb,1,'Art. 82.3 Ley 39/2015','El trámite se tiene por realizado.',null),
('aux-canarias:28-9005c7f3de','aux-canarias',28,'Si el órgano competente para resolver considera que la infracción o la sanción revisten mayor gravedad que la propuesta, se notificará al inculpado para alegaciones en un plazo de:','["Quince días", "Diez días", "Cinco días", "Un mes"]'::jsonb,0,'Art. 90.2 Ley 39/2015','El inculpado dispone de quince días para alegar.',null),
('aux-canarias:28-9ead9887e5','aux-canarias',28,'Los trámites que deban ser cumplimentados por los interesados se realizarán, salvo plazo distinto, en el plazo de:','["Diez días a partir del siguiente al de la notificación del correspondiente acto", "Cinco días a partir del siguiente al de la notificación", "Quince días a partir del siguiente al de la notificación del correspondiente acto", "Diez días a partir del mismo día de la notificación"]'::jsonb,0,'Art. 73.1 Ley 39/2015','El plazo general es de diez días.',null),
('aux-canarias:28-5ee8b78cab','aux-canarias',28,'Según el art. 54, los procedimientos podrán iniciarse:','["De oficio o a solicitud del interesado", "Solo de oficio, por propia iniciativa del órgano", "De oficio, a solicitud del interesado o por orden judicial", "Solo a solicitud"]'::jsonb,0,'Art. 54 Ley 39/2015','Las dos clases de iniciación son de oficio y a solicitud del interesado.',null),
('aux-canarias:28-d97bf8044b','aux-canarias',28,'La Administración puede abstenerse de resolver alegando silencio, oscuridad o insuficiencia de los preceptos legales:','["En ningún caso", "Sí, si lo autoriza el superior", "Sí, cuando la ley sea oscura", "Sí, en los procedimientos de oficio"]'::jsonb,0,'Art. 88.5 Ley 39/2015','Nunca puede abstenerse por esos motivos, aunque puede inadmitir solicitudes de derechos no previstos o manifiestamente carentes de fundamento.',null),
('aux-canarias:28-a53e3a1051','aux-canarias',28,'En el procedimiento sancionador se podrá adoptar la tramitación simplificada cuando:','["El infractor sea reincidente y reconozca su responsabilidad", "Existan elementos de juicio suficientes para calificar la infracción como leve", "Existan elementos de juicio suficientes para calificar la infracción como leve o grave", "La infracción sea muy grave y urgente, o lo solicite expresamente el denunciante"]'::jsonb,1,'Art. 96.5 Ley 39/2015','Procede si la infracción se califica como leve.',null),
('aux-canarias:28-1c5cd7043e','aux-canarias',28,'Las actuaciones complementarias deberán practicarse en un plazo no superior a:','["Un mes", "Quince días", "Siete días", "Tres meses"]'::jsonb,1,'Art. 87 Ley 39/2015','El plazo para resolver queda suspendido hasta su terminación.',null),
('aux-canarias:28-2723f1d6db','aux-canarias',28,'También producirá la terminación del procedimiento:','["La falta de crédito presupuestario adecuado y suficiente", "La imposibilidad material de continuarlo por causas sobrevenidas, mediante resolución motivada", "La imposibilidad material de continuarlo, que se produce automáticamente sin necesidad de resolución", "El cambio del funcionario instructor, o la falta de crédito presupuestario adecuado para continuarlo"]'::jsonb,1,'Art. 84.2 Ley 39/2015','La resolución que se dicte deberá ser motivada en todo caso.',null),
('aux-canarias:28-da633b53dc','aux-canarias',28,'Los actos de instrucción necesarios para determinar, conocer y comprobar los hechos se realizarán:','["Solo a instancia de los interesados y en papel, que deben proponer las actuaciones necesarias, sin que el órgano que tramite el procedimiento pueda acordarlas de oficio", "Por el órgano que tramite el procedimiento, en papel y sin uso de medios electrónicos, sin que los interesados puedan proponer actuaciones complementarias", "Por el instructor, a propuesta del Consejo de Estado", "De oficio y por medios electrónicos por el órgano que tramite el procedimiento, sin perjuicio del derecho de los interesados a proponer actuaciones"]'::jsonb,3,'Art. 75.1 Ley 39/2015','La instrucción se hace de oficio.',null),
('aux-canarias:28-6fb3e889b0','aux-canarias',28,'En los procedimientos de responsabilidad patrimonial, el acuerdo alcanzado entre el interesado y el órgano competente deberá fijar:','["La culpa del funcionario causante del daño", "La sanción disciplinaria del empleado público responsable", "La cuantía de la indemnización, pero no el modo, que fija después el órgano competente", "La cuantía y el modo de indemnización"]'::jsonb,3,'Art. 86.5 Ley 39/2015','El acuerdo fija la cuantía y el modo de indemnización.',null),
('aux-canarias:28-d17802a3d0','aux-canarias',28,'En los procedimientos iniciados de oficio, la Administración podrá desistir:','["Libremente y sin necesidad de motivación", "Motivadamente, en los supuestos y con los requisitos previstos en las leyes", "Solo con autorización judicial", "Motivadamente, en cualquier supuesto, sin necesidad de previsión legal"]'::jsonb,1,'Art. 93 Ley 39/2015','El desistimiento de la Administración debe ser motivado y legalmente previsto.',null),
('aux-canarias:28-f38a3d9094','aux-canarias',28,'Las Administraciones podrán celebrar acuerdos, pactos, convenios o contratos que pongan fin al procedimiento siempre que:','["El interesado sea una persona jurídica y el acuerdo se refiera a materias de contenido económico o patrimonial", "No sean contrarios al ordenamiento jurídico ni versen sobre materias no susceptibles de transacción", "Se refieran a sanciones de cuantía inferior a 3.000 euros", "Lo autorice un juez"]'::jsonb,1,'Art. 86.1 Ley 39/2015','Es la terminación convencional.',null),
('aux-canarias:28-d0cfad321a','aux-canarias',28,'El instructor solo podrá rechazar las pruebas propuestas por los interesados cuando:','["Sean costosas para la Administración, aunque sean pertinentes y necesarias, mediante resolución motivada", "Sean manifiestamente improcedentes o innecesarias, mediante resolución motivada", "Sean improcedentes a su juicio, sin necesidad de motivar el rechazo ni notificarlo a los interesados", "Se propongan fuera del plazo de diez días"]'::jsonb,1,'Art. 77.3 Ley 39/2015','El rechazo de pruebas debe ser motivado y basarse en su improcedencia o innecesariedad manifiesta.',null),
('aux-canarias:28-2e4ccc3361','aux-canarias',28,'El procedimiento está sometido al principio de:','["Rogación exclusiva del interesado, que lo impulsa en todos sus trámites mediante escritos sucesivos", "Celeridad, y se impulsará de oficio en todos sus trámites y a través de medios electrónicos", "Secreto de las actuaciones", "Oralidad, y se impulsará a instancia de los interesados en cada uno de sus trámites, en papel"]'::jsonb,1,'Art. 71.1 Ley 39/2015','El impulso es de oficio, con respeto a la transparencia y la publicidad.',null),
('aux-canarias:28-a2e70c17ba','aux-canarias',28,'En la petición de un informe se concretará:','["El plazo de tres meses para su emisión y el sentido del informe", "El extremo o extremos acerca de los que se solicita", "El sentido que debe tener el informe y el plazo para emitirlo", "El nombre del funcionario que debe emitirlo"]'::jsonb,1,'Art. 79.2 Ley 39/2015','Hay que concretar los extremos sobre los que se pide el informe.',null),
('aux-canarias:28-55feb6439f','aux-canarias',28,'La acumulación de procedimientos exige, entre otros requisitos, que:','["Lo soliciten todos los interesados por escrito", "Sea el mismo órgano quien deba tramitar y resolver el procedimiento", "Estén en la misma fase de tramitación y se refieran al mismo interesado o a interesados distintos", "Los interesados sean los mismos y los procedimientos estén en la misma fase"]'::jsonb,1,'Art. 57 Ley 39/2015','Se acumulan los que guarden identidad sustancial o íntima conexión y los tramite y resuelva el mismo órgano.',null),
('aux-canarias:28-91f643639c','aux-canarias',28,'Los interesados podrán aducir alegaciones y aportar documentos:','["En cualquier momento del procedimiento anterior al trámite de audiencia", "En cualquier momento, incluso tras la resolución", "Solo tras la propuesta de resolución", "Solo en los diez primeros días desde el inicio del procedimiento"]'::jsonb,0,'Art. 76.1 Ley 39/2015','Serán tenidos en cuenta al redactar la propuesta de resolución.',null),
('aux-canarias:28-abfbb46390','aux-canarias',28,'Si en un procedimiento simplificado el dictamen preceptivo del Consejo de Estado se manifiesta en contra del fondo de la propuesta de resolución:','["El órgano competente acordará continuar el procedimiento con arreglo a la tramitación ordinaria", "Se archiva el procedimiento", "Se resuelve igualmente según la propuesta de resolución", "El órgano competente acordará un nuevo trámite de audiencia y resolverá por la tramitación simplificada"]'::jsonb,0,'Art. 96.7 Ley 39/2015','Se pasa a la tramitación ordinaria.',null),
('aux-canarias:28-0f85aaca39','aux-canarias',28,'Cuando la sanción tenga únicamente carácter pecuniario, el reconocimiento de responsabilidad y el pago voluntario dan lugar a reducciones de:','["Exactamente el 50 % del importe de la sanción propuesta, no acumulables", "El 30 % solo por pronto pago", "El 10 %, no acumulable", "Al menos el 20 % sobre el importe de la sanción propuesta, acumulables entre sí"]'::jsonb,3,'Art. 85.3 Ley 39/2015','Las reducciones son de al menos el 20 % cada una, acumulables, y pueden incrementarse reglamentariamente.',null),
('aux-canarias:28-f340f0c841','aux-canarias',28,'Las cuestiones incidentales que se susciten en el procedimiento, incluso las que se refieran a la nulidad de actuaciones:','["Suspenden la tramitación, salvo la abstención", "Determinan el archivo provisional del procedimiento hasta su resolución por el órgano superior", "No suspenderán la tramitación del procedimiento, salvo la recusación", "Suspenden siempre la tramitación"]'::jsonb,2,'Art. 74 Ley 39/2015','Solo la recusación suspende el procedimiento.',null),
('aux-canarias:28-f807e1ef7b','aux-canarias',28,'Según el principio de simplificación administrativa, se acordarán en un solo acto:','["Todos los recursos de un mismo interesado frente a actos distintos", "La iniciación, la instrucción y la resolución, cuando el procedimiento se tramite por la vía simplificada y lo solicite el interesado", "Todos los trámites de un mismo interesado, aunque sea obligado su cumplimiento sucesivo", "Todos los trámites que, por su naturaleza, admitan un impulso simultáneo y no sea obligado su cumplimiento sucesivo"]'::jsonb,3,'Art. 72.1 Ley 39/2015','Concentración de trámites.',null),
('aux-canarias:28-0953d85d8d','aux-canarias',28,'Si la resolución va a pronunciarse sobre cuestiones conexas no planteadas por los interesados, el órgano competente debe ponerlo de manifiesto a estos por un plazo:','["De tres días", "De un mes", "No superior a quince días", "No inferior a veinte días"]'::jsonb,2,'Art. 88.1 Ley 39/2015','Se da audiencia por plazo no superior a quince días.',null),
('aux-canarias:28-2c900d826f','aux-canarias',28,'En los procedimientos sancionadores, la fase instructora y la sancionadora:','["Corresponderán al mismo órgano, salvo que la ley disponga otra cosa", "Las realiza el denunciante y el órgano competente, respectivamente", "Se tramitan como una sola fase", "Se encomendarán a órganos distintos"]'::jsonb,3,'Art. 63.1 Ley 39/2015','Los procedimientos sancionadores se inician siempre de oficio y separan instrucción y resolución.',null),
('aux-canarias:28-71fecb417b','aux-canarias',28,'En la notificación de la práctica de una prueba se consignará el lugar, fecha y hora, con la advertencia de que el interesado:','["Puede nombrar técnicos para que le asistan", "Debe comparecer acompañado de notario o de abogado colegiado", "No puede asistir a su práctica", "Debe abonar en todo caso los gastos de la prueba"]'::jsonb,0,'Art. 78.2 Ley 39/2015','Se le advierte que puede nombrar técnicos que le asistan.',null),
('aux-canarias:28-68ea7e7569','aux-canarias',28,'En los procedimientos sancionadores, la orden superior de iniciación expresará, en la medida de lo posible:','["El sentido de la resolución que deba dictarse", "La sanción que corresponda imponer, el órgano competente para resolver, el instructor designado y el plazo máximo para dictar resolución", "El nombre del abogado defensor del presunto responsable y la sanción que corresponde imponerle según la tipificación", "La persona o personas presuntamente responsables, las conductas o hechos, su tipificación y el lugar y fecha"]'::jsonb,3,'Art. 60.2 Ley 39/2015','La orden superior debe concretar responsables, hechos, tipificación, lugar y fecha.',null),
('aux-canarias:28-cdd33abd8f','aux-canarias',28,'Requerirán en todo caso la aprobación expresa del Consejo de Ministros u órgano equivalente de las CCAA:','["Todos los acuerdos convencionales que pongan fin a cualquier procedimiento", "Los acuerdos de los Ayuntamientos", "Los acuerdos que versen sobre materias de la competencia directa de dicho órgano", "Los acuerdos de cuantía superior a 6.000 €"]'::jsonb,2,'Art. 86.3 Ley 39/2015','Solo los que versen sobre materias de su competencia directa.',null),
('aux-canarias:28-3a63cd810d','aux-canarias',28,'En la AGE, los procedimientos de responsabilidad patrimonial se resolverán, como regla general, por:','["El Ministro respectivo", "El Subsecretario", "El Presidente del Gobierno", "El Delegado del Gobierno"]'::jsonb,0,'Art. 92 Ley 39/2015','Por el Consejo de Ministros en los casos del art. 32.3 LRJSP o cuando una ley lo disponga.',null),
('aux-canarias:28-e5aa83ecfd','aux-canarias',28,'En ningún caso se podrá imponer una sanción:','["Sin que se haya tramitado el oportuno procedimiento", "A una persona jurídica", "Superior a 600 euros sin autorización judicial", "Sin que el infractor esté asistido de abogado"]'::jsonb,0,'Art. 63.2 Ley 39/2015','La sanción exige siempre procedimiento previo.',null),
('aux-canarias:28-6c3a58445a','aux-canarias',28,'El acuerdo de realización de actuaciones complementarias se notificará a los interesados, concediéndoles un plazo para alegaciones tras su finalización de:','["Siete días", "Cinco días", "Quince días", "Diez días"]'::jsonb,0,'Art. 87 Ley 39/2015','Plazo de siete días para alegaciones; las actuaciones se practican en un máximo de quince días y el plazo para resolver queda suspendido.',null),
('aux-canarias:28-7430e2acda','aux-canarias',28,'La comparecencia en el trámite de información pública:','["Solo pueden hacerla los vecinos del municipio afectado", "Es obligatoria para poder recurrir después la resolución", "Convierte en interesado al compareciente", "No otorga, por sí misma, la condición de interesado"]'::jsonb,3,'Art. 83.3 Ley 39/2015','La incomparecencia tampoco impide a los interesados recurrir la resolución.',null),
('aux-canarias:28-0793046969','aux-canarias',28,'Contra el acuerdo de acumulación de procedimientos:','["No procederá recurso alguno", "Cabe recurso de reposición", "Cabe recurso extraordinario de revisión", "Cabe recurso de alzada"]'::jsonb,0,'Art. 57 Ley 39/2015','La acumulación procede si hay identidad sustancial o íntima conexión y el mismo órgano tramita y resuelve.',null),
('aux-canarias:28-41ebb84b2b','aux-canarias',28,'Si la Administración acuerda de oficio la tramitación simplificada y algún interesado manifiesta su oposición expresa:','["Se mantiene la tramitación simplificada si el órgano lo motiva por razones de interés público", "Se mantiene la tramitación simplificada", "Se mantiene la tramitación simplificada si el órgano lo motiva", "La Administración deberá seguir la tramitación ordinaria"]'::jsonb,3,'Art. 96.2 Ley 39/2015','La oposición expresa de un interesado obliga a la tramitación ordinaria.',null),
('aux-canarias:28-0d575d2ef1','aux-canarias',28,'La resolución que ponga fin al procedimiento sancionador será ejecutiva cuando:','["Lo decida motivadamente el instructor del procedimiento", "No quepa contra ella ningún recurso ordinario en vía administrativa", "Se notifique al interesado, aunque quepa contra ella recurso de alzada", "Se dicte por el órgano competente, aunque quepa contra ella recurso de alzada"]'::jsonb,1,'Art. 90.3 Ley 39/2015','Puede suspenderse cautelarmente si el interesado manifiesta que interpondrá recurso contencioso-administrativo.',null),
('aux-canarias:28-71ca7d0fd2','aux-canarias',28,'Si la cuestión suscitada entrañase interés general, la Administración ante un desistimiento o renuncia:','["Podrá limitar sus efectos al interesado y seguirá el procedimiento", "Deberá aceptarlo de plano y declarar concluso el procedimiento para todos los interesados", "Deberá archivar el procedimiento", "Deberá pedir dictamen al Consejo de Estado"]'::jsonb,0,'Art. 94.5 Ley 39/2015','El procedimiento continúa por el interés general.',null),
('aux-canarias:28-653062370c','aux-canarias',28,'Si un informe preceptivo no se emite en plazo:','["Se entiende desfavorable a la pretensión del interesado y se continúa el procedimiento hasta su resolución", "Se entiende favorable", "Se podrá suspender el transcurso del plazo máximo legal para resolver el procedimiento", "Se archiva el procedimiento"]'::jsonb,2,'Art. 80.3 Ley 39/2015','Si no es preceptivo, se pueden proseguir las actuaciones.',null),
('aux-canarias:28-136987aa2d','aux-canarias',28,'Si un interesado solicita la tramitación simplificada y el órgano considera que no procede, podrá desestimarla en el plazo de:','["Cinco días desde su presentación, sin posibilidad de recurso", "Un mes desde su presentación, con recurso de alzada", "Diez días desde su presentación, con recurso de alzada", "Cinco días desde su presentación, con recurso potestativo de reposición"]'::jsonb,0,'Art. 96.3 Ley 39/2015','Transcurrido el plazo sin resolver, se entiende desestimada.',null),
('aux-canarias:28-9b558f7b34','aux-canarias',28,'La resolución en un procedimiento de responsabilidad patrimonial deberá pronunciarse sobre:','["La responsabilidad penal del empleado público que causó el daño y la sanción disciplinaria que le corresponda imponer", "La sanción disciplinaria al funcionario responsable y la cuantía de la indemnización", "La existencia o no de relación de causalidad, la valoración del daño y la cuantía y modo de indemnización", "La existencia de culpa o dolo del empleado, que es requisito para que nazca la responsabilidad de la Administración"]'::jsonb,2,'Art. 91.2 Ley 39/2015','Son los extremos obligatorios de la resolución.',null),
('aux-canarias:28-b050ea3d82','aux-canarias',28,'No se podrán adoptar medidas provisionales que:','["Sean proporcionadas al objetivo que se pretende garantizar, aunque se adopten antes del inicio del procedimiento en casos de urgencia", "Se adopten una vez iniciado el procedimiento, sin audiencia previa del interesado", "Afecten a la actividad económica del interesado o a su patrimonio, aunque no le causen ningún perjuicio de difícil o imposible reparación ni vulneren sus derechos", "Puedan causar perjuicio de difícil o imposible reparación a los interesados o impliquen violación de derechos amparados por las leyes"]'::jsonb,3,'Art. 56.4 Ley 39/2015','Las medidas provisionales tienen ese límite.',null),
('aux-canarias:28-280ad9d0cf','aux-canarias',28,'En la tramitación simplificada, el trámite de audiencia solo se realiza cuando:','["Nunca, porque la tramitación simplificada lo suprime en todo caso", "Siempre, como en la tramitación ordinaria", "Lo pida cualquier tercero que no sea interesado", "La resolución vaya a ser desfavorable para el interesado"]'::jsonb,3,'Art. 96.6 d) Ley 39/2015','Las alegaciones al inicio se formulan en cinco días.',null),
('aux-canarias:28-a615ff11e3','aux-canarias',28,'Cuando la Administración establezca expresamente modelos específicos de presentación de solicitudes en un procedimiento concreto, estos serán:','["De uso obligatorio por los interesados", "Solo orientativos", "Exclusivos para personas jurídicas", "De uso voluntario"]'::jsonb,0,'Art. 66.6 Ley 39/2015','Los modelos específicos establecidos expresamente son de uso obligatorio.',null),
('aux-canarias:28-de0cc70d1c','aux-canarias',28,'De las solicitudes y escritos que presenten los interesados, estos podrán exigir:','["Una copia firmada por el titular del órgano destinatario", "La devolución de las tasas abonadas", "Una resolución inmediata sobre la admisión de la solicitud presentada", "El correspondiente recibo que acredite la fecha y hora de presentación"]'::jsonb,3,'Art. 66.3 Ley 39/2015','Pueden exigir recibo con fecha y hora de presentación.',null),
('aux-canarias:28-45f7b4de1a','aux-canarias',28,'La Administración aceptará de plano el desistimiento o la renuncia, salvo que terceros interesados personados insten la continuación en el plazo de:','["Cinco días desde que fueron notificados", "Un mes desde que fueron notificados", "Quince días desde que fueron notificados", "Diez días desde que fueron notificados"]'::jsonb,3,'Art. 94.4 Ley 39/2015','Los terceros tienen diez días para pedir la continuación.',null),
('aux-canarias:28-50a6960974','aux-canarias',28,'Con anterioridad al inicio del procedimiento, el órgano competente podrá abrir:','["El período de prueba", "Un período de información o actuaciones previas para conocer las circunstancias del caso y la conveniencia de iniciar", "El trámite de audiencia a los posibles interesados para que aleguen sobre la conveniencia de iniciar el procedimiento", "El trámite de información pública"]'::jsonb,1,'Art. 55.1 Ley 39/2015','Las actuaciones previas sirven para valorar si procede iniciar el procedimiento.',null),
('aux-canarias:28-f0785990a1','aux-canarias',28,'En el procedimiento sancionador, el órgano instructor resolverá la finalización con archivo de actuaciones, sin formular propuesta de resolución, cuando:','["La sanción que corresponda sea muy grave", "El denunciante lo solicite expresamente y retire la denuncia antes de la propuesta de resolución", "Los hechos probados no constituyan, de modo manifiesto, infracción administrativa", "El presunto infractor reconozca su responsabilidad y pague voluntariamente la sanción"]'::jsonb,2,'Art. 89.1 c) Ley 39/2015','También por inexistencia de los hechos, falta de prueba, falta de responsable o prescripción de la infracción.',null),
('aux-canarias:28-9ad773d817','aux-canarias',28,'Transcurridos seis meses desde el inicio de un procedimiento de responsabilidad patrimonial sin resolución ni acuerdo:','["El procedimiento caduca y se archivan las actuaciones sin pronunciamiento sobre la indemnización", "Se entiende estimada la reclamación", "Se paga automáticamente la indemnización", "Podrá entenderse que la resolución es contraria a la indemnización del particular"]'::jsonb,3,'Art. 91.3 Ley 39/2015','El silencio en responsabilidad patrimonial es desestimatorio.',null),
('aux-canarias:28-df84c21a06','aux-canarias',28,'Las medidas provisionales adoptadas antes de iniciar el procedimiento deberán ser confirmadas, modificadas o levantadas en el acuerdo de iniciación, que deberá efectuarse:','["Dentro del mes siguiente a su adopción", "Dentro de los tres meses siguientes", "Dentro de los quince días siguientes a su adopción", "Dentro de los diez días siguientes a su adopción"]'::jsonb,2,'Art. 56.2 Ley 39/2015','Si no se inicia en ese plazo o el acuerdo no se pronuncia, las medidas quedan sin efecto.',null),
('aux-canarias:28-ea278c51f3','aux-canarias',28,'Los documentos formalizados por funcionarios con la condición de autoridad en los que se recojan hechos constatados por ellos:','["Tienen valor absoluto e irrebatible", "Solo tienen valor probatorio si los ratifica un juez o el instructor del procedimiento", "No tienen valor probatorio", "Harán prueba de estos salvo que se acredite lo contrario"]'::jsonb,3,'Art. 77.5 Ley 39/2015','Gozan de presunción de veracidad salvo prueba en contrario.',null),
('aux-canarias:28-fa759d5fb6','aux-canarias',28,'Salvo que reste menos para su tramitación ordinaria, los procedimientos de tramitación simplificada deberán resolverse en:','["Tres meses desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Seis meses desde el inicio del procedimiento", "Treinta días desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Quince días desde el siguiente al que se notifique el acuerdo de tramitación simplificada"]'::jsonb,2,'Art. 96.6 Ley 39/2015','El plazo es de treinta días.',null),
('aux-canarias:28-15b792cefe','aux-canarias',28,'Se entiende por propia iniciativa:','["La petición de un órgano sin competencia de iniciación", "La denuncia de un particular que pone los hechos en conocimiento del órgano competente para iniciar, sin que este tenga conocimiento directo de las circunstancias", "La actuación derivada del conocimiento directo o indirecto de las circunstancias o hechos por el órgano que tiene la competencia de iniciación", "La orden emitida por un órgano superior jerárquico del competente para iniciar, tras conocer los hechos por una denuncia o por una petición razonada de otro órgano"]'::jsonb,2,'Art. 59 Ley 39/2015','Es el conocimiento directo o indirecto por el propio órgano competente.',null),
('aux-canarias:28-e2b5b615b3','aux-canarias',28,'En la resolución del procedimiento sancionador no se podrán aceptar hechos distintos de los determinados en el curso del procedimiento:','["Salvo que resulten más graves, en cuyo caso se notificarán al inculpado para que formule alegaciones", "Salvo en las infracciones leves, en las que sí pueden aceptarse", "Salvo que lo pida el denunciante", "Con independencia de su diferente valoración jurídica"]'::jsonb,3,'Art. 90.2 Ley 39/2015','Se protege el derecho de defensa del inculpado.',null),
('aux-canarias:28-a1b2b90e10','aux-canarias',28,'En el procedimiento de responsabilidad patrimonial iniciado de oficio, el acuerdo de iniciación se notificará a los presuntos lesionados, concediéndoles un plazo para alegaciones y pruebas de:','["Un mes", "Cinco días", "Diez días", "Quince días"]'::jsonb,2,'Art. 65.2 Ley 39/2015','Se les concede diez días para aportar alegaciones, documentos o información y proponer pruebas.',null),
('aux-canarias:28-042fd8f39b','aux-canarias',28,'En los procedimientos tramitados a solicitud del interesado, la resolución será congruente con las peticiones formuladas:','["Solo si el instructor lo propone y el interesado no se opone", "Pudiendo agravar su situación inicial si así lo exige el interés público", "Salvo que sea una persona jurídica", "Sin que en ningún caso pueda agravar su situación inicial"]'::jsonb,3,'Art. 88.2 Ley 39/2015','Sin perjuicio de la potestad de incoar de oficio un nuevo procedimiento.',null),
('aux-canarias:28-4a51a48715','aux-canarias',28,'La presentación de una denuncia:','["Convierte al denunciante en interesado en el procedimiento sancionador que se inicie", "Obliga a iniciar el procedimiento y a sancionar", "No confiere, por sí sola, la condición de interesado en el procedimiento", "Requiere asistencia de abogado"]'::jsonb,2,'Art. 62.5 Ley 39/2015','El denunciante no es interesado por el solo hecho de denunciar.',null),
('aux-canarias:28-746cf9f1cf','aux-canarias',28,'Según el art. 62.1, se entiende por denuncia:','["La solicitud de un interesado para que se inicie un procedimiento en su favor", "El acto por el que cualquier persona, en cumplimiento o no de una obligación legal, pone en conocimiento de un órgano administrativo un hecho que pudiera justificar la iniciación de oficio", "La propuesta de iniciación formulada por un órgano administrativo sin competencia para iniciar, que tiene conocimiento de los hechos por razón de sus funciones de inspección, averiguación o investigación", "La orden de un superior"]'::jsonb,1,'Art. 62.1 Ley 39/2015','Definición legal de la denuncia.',null),
('aux-canarias:28-8fd972b382','aux-canarias',28,'En los procedimientos de responsabilidad patrimonial ante la AGE, es preceptivo el dictamen del Consejo de Estado cuando la indemnización reclamada sea de cuantía igual o superior a:','["50.000 euros", "6.000 euros", "100.000 euros", "30.000 euros"]'::jsonb,0,'Art. 81.2 Ley 39/2015','Desde 50.000 € (o la cuantía fijada por la legislación autonómica) es preceptivo el dictamen.',null),
('aux-canarias:28-da6b2be28c','aux-canarias',28,'En el despacho de los expedientes se guardará:','["El orden que prefiera el funcionario responsable", "El orden alfabético de los interesados, salvo orden motivada en contrario del superior jerárquico del instructor", "El orden riguroso de incoación en asuntos de homogénea naturaleza, salvo orden motivada en contrario", "El orden de prioridad que fije cada interesado en su solicitud, o el que indique el superior jerárquico en cada caso concreto"]'::jsonb,2,'Art. 71.2 Ley 39/2015','Su incumplimiento puede dar lugar a responsabilidad disciplinaria.',null),
('aux-canarias:28-9aa0b33929','aux-canarias',28,'Las declaraciones responsables y las comunicaciones permiten el reconocimiento o ejercicio de un derecho o el inicio de una actividad:','["Tras la resolución expresa que reconozca el derecho, que deberá dictarse en un mes", "A los tres meses de su presentación si la Administración no se opone", "Desde el día de su presentación, sin perjuicio de las facultades de comprobación de la Administración", "Desde el día de su presentación, sin que la Administración pueda comprobar después lo declarado"]'::jsonb,2,'Art. 69.3 Ley 39/2015','Producen efectos desde su presentación.',null),
('aux-canarias:28-ccd8d5b87e','aux-canarias',28,'Si el escrito de iniciación se formuló por dos o más interesados, el desistimiento o la renuncia:','["No está permitido una vez iniciado el procedimiento", "Requiere el acuerdo unánime de todos los que firmaron el escrito de iniciación", "Solo afectará a aquellos que la hubiesen formulado", "Afectará a todos los interesados, salvo que alguno inste la continuación en diez días"]'::jsonb,2,'Art. 94.2 Ley 39/2015','El desistimiento solo afecta a quien lo formula.',null),
('aux-canarias:29-068c58828a','aux-canarias',29,'Contra las resoluciones y los actos de trámite cualificados caben los recursos de:','["Alzada y potestativo de reposición", "Alzada y extraordinario de revisión, únicamente", "Reposición obligatoria y alzada", "Súplica y potestativo de reposición"]'::jsonb,0,'Art. 112.1 Ley 39/2015','Caben el recurso de alzada y el potestativo de reposición.',null),
('aux-canarias:29-f229b49bef','aux-canarias',29,'Cuando hayan de tenerse en cuenta nuevos hechos o documentos no recogidos en el expediente original, se pondrán de manifiesto a los interesados para alegaciones en un plazo:','["De un mes, prorrogable por otro mes a petición del interesado", "No inferior a diez días ni superior a quince", "No inferior a cinco días ni superior a diez", "De veinte días hábiles, prorrogable por otros diez"]'::jsonb,1,'Art. 118.1 Ley 39/2015','El plazo es de 10 a 15 días.',null),
('aux-canarias:29-60e6aae613','aux-canarias',29,'La resolución de un recurso será congruente con las peticiones del recurrente:','["Salvo en materia de personal, en que puede agravarse su situación inicial", "Pudiendo agravar su situación inicial si así lo exige el interés público", "Solo si el recurrente lo autoriza expresamente", "Sin que en ningún caso pueda agravarse su situación inicial"]'::jsonb,3,'Art. 119.3 Ley 39/2015','Es la prohibición de la reformatio in peius.',null),
('aux-canarias:29-10847f75c0','aux-canarias',29,'También pone fin a la vía administrativa:','["El acuerdo de iniciación del procedimiento sancionador o de responsabilidad", "La providencia de apertura del periodo de prueba", "El informe preceptivo y vinculante emitido por un órgano consultivo", "La resolución de los procedimientos de responsabilidad patrimonial"]'::jsonb,3,'Art. 114.1 e) Ley 39/2015','Las resoluciones en materia de responsabilidad patrimonial ponen fin a la vía administrativa, cualquiera que sea el tipo de relación.',null),
('aux-canarias:29-ea15446a8d','aux-canarias',29,'Contra las disposiciones administrativas de carácter general:','["No cabe recurso en vía administrativa", "Cabe recurso de alzada", "Cabe recurso de reposición", "Cabe recurso extraordinario de revisión"]'::jsonb,0,'Art. 112.3 Ley 39/2015','Contra las disposiciones de carácter general no cabe recurso administrativo.',null),
('aux-canarias:29-0f1f28f3dd','aux-canarias',29,'Ponen fin a la vía administrativa:','["Los actos de trámite simples", "Las propuestas de resolución", "Las resoluciones de los recursos de alzada", "Los actos de órganos con superior jerárquico, como regla general"]'::jsonb,2,'Art. 114.1 a) Ley 39/2015','Las resoluciones de alzada ponen fin a la vía administrativa.',null),
('aux-canarias:29-fd6c413ca6','aux-canarias',29,'Es causa de inadmisión de un recurso:','["Que se presente en una oficina de Correos sin sello de fechas", "Que el recurrente no esté asistido de abogado", "Haber transcurrido el plazo para su interposición", "Que el recurrente haya calificado erróneamente el recurso, aunque se deduzca su verdadero carácter"]'::jsonb,2,'Art. 116 d) Ley 39/2015','Otras causas: incompetencia, falta de legitimación, acto no recurrible y carecer manifiestamente de fundamento.',null),
('aux-canarias:29-fed0a6c612','aux-canarias',29,'El error o la ausencia de calificación del recurso por parte del recurrente:','["No será obstáculo para su tramitación, siempre que se deduzca su verdadero carácter", "Obliga a presentarlo de nuevo", "Solo puede subsanarse si el recurrente está asistido de abogado", "Determina su inadmisión, salvo que el recurrente lo subsane en el plazo de diez días desde el requerimiento"]'::jsonb,0,'Art. 115.2 Ley 39/2015','Lo importante es que se deduzca el verdadero carácter del recurso.',null),
('aux-canarias:29-6a04c727cf','aux-canarias',29,'Los vicios y defectos que hagan anulable un acto:','["Solo pueden alegarse en vía judicial", "No podrán ser alegados por quienes los hubieren causado", "Determinan siempre la nulidad de pleno derecho del acto, aunque no causen indefensión", "Pueden alegarse por cualquier persona, incluidos quienes los hubieran causado"]'::jsonb,1,'Art. 115.3 Ley 39/2015','Quien causó el vicio no puede alegarlo.',null),
('aux-canarias:29-8f379f462a','aux-canarias',29,'¿Cuál de las siguientes NO es causa de inadmisión del art. 116?','["Tratarse de un acto no susceptible de recurso", "Carecer de legitimación el recurrente", "Carecer el recurso manifiestamente de fundamento", "Que el recurso se haya calificado erróneamente"]'::jsonb,3,'Art. 116 Ley 39/2015','El error en la calificación no impide la tramitación (art. 115.2).',null),
('aux-canarias:29-0d6297873a','aux-canarias',29,'Si existe vicio de forma y no se estima procedente resolver sobre el fondo, el órgano que resuelve el recurso:','["Dictará resolución favorable", "Inadmitirá el recurso", "Ordenará la retroacción del procedimiento al momento en que el vicio fue cometido", "Anulará todo el expediente y ordenará iniciar uno nuevo desde el principio"]'::jsonb,2,'Art. 119.2 Ley 39/2015','Se ordena retrotraer el procedimiento al momento del vicio.',null),
('aux-canarias:29-ca7d7904a8','aux-canarias',29,'Cuando deban resolverse una pluralidad de recursos derivados de un mismo acto y se haya interpuesto recurso judicial contra una resolución administrativa o contra el correspondiente acto presunto:','["El órgano administrativo podrá acordar la suspensión del plazo para resolver hasta que recaiga pronunciamiento judicial", "Deberá inadmitir todos los recursos pendientes", "Deberá estimar todos los recursos", "Deberá resolver todos los recursos en el plazo ordinario, sin esperar al pronunciamiento judicial, para no perjudicar a los interesados que no han acudido a los tribunales"]'::jsonb,0,'Art. 120.1 Ley 39/2015','El órgano puede suspender el plazo hasta que haya pronunciamiento judicial.',null),
('aux-canarias:29-4cdac9a687','aux-canarias',29,'El recurso extraordinario de revisión se interpone contra:','["Los actos que no ponen fin a la vía administrativa, en cualquier momento", "Los actos firmes en vía administrativa, cuando concurra alguna de las circunstancias del art. 125.1", "Cualquier acto de trámite", "Las disposiciones de carácter general, cuando concurra alguna de las circunstancias del art. 125.1"]'::jsonb,1,'Art. 113 Ley 39/2015','Procede contra actos firmes en vía administrativa en los casos del art. 125.1.',null),
('aux-canarias:30-4c76103d25','aux-canarias',30,'El recurso de alzada se interpone contra:','["Actos que ponen fin a la vía administrativa, ante el mismo órgano que los dictó", "Disposiciones de carácter general y actos que no ponen fin a la vía administrativa", "Resoluciones y actos que no ponen fin a la vía administrativa, ante el mismo órgano administrativo que los dictó", "Resoluciones y actos que no ponen fin a la vía administrativa, ante el órgano superior jerárquico"]'::jsonb,3,'Art. 121.1 Ley 39/2015','Procede contra los actos que no ponen fin a la vía administrativa y se resuelve por el superior jerárquico.',null),
('aux-canarias:30-cf29b1ed32','aux-canarias',30,'Si el acto es expreso, el plazo para interponer recurso de alzada es de:','["1 mes", "2 meses", "15 días", "3 meses"]'::jsonb,0,'Art. 122.1 Ley 39/2015','Es de un mes si el acto es expreso; si no lo es, puede interponerse en cualquier momento desde el día siguiente a los efectos del silencio.',null),
('aux-canarias:30-4cd7cdc6b8','aux-canarias',30,'¿Cuál es el plazo máximo para dictar y notificar la resolución del recurso de alzada?','["1 mes; pasado ese plazo, se podrá entender estimado", "3 meses; pasado ese plazo, se podrá entender desestimado", "6 meses; pasado ese plazo, se podrá entender desestimado", "3 meses; pasado ese plazo sin resolución expresa, se entenderá siempre estimado"]'::jsonb,1,'Art. 122.2 Ley 39/2015','El plazo es de tres meses. Transcurrido sin resolución, se podrá entender desestimado el recurso, salvo excepción.',null),
('aux-canarias:30-fe93951368','aux-canarias',30,'El recurso de reposición:','["Es obligatorio antes de acudir a los tribunales contencioso-administrativos", "Es potestativo, contra actos que no ponen fin a la vía administrativa, ante el órgano superior jerárquico del que los dictó", "Es potestativo, contra actos que ponen fin a la vía administrativa, ante el mismo órgano que los dictó", "Es obligatorio, contra actos que ponen fin a la vía administrativa, ante el mismo órgano"]'::jsonb,2,'Art. 123.1 Ley 39/2015','Es potestativo y se interpone ante el mismo órgano que dictó el acto que pone fin a la vía administrativa.',null),
('aux-canarias:30-2099f491da','aux-canarias',30,'¿Cuál es el plazo máximo para dictar y notificar la resolución del recurso de reposición?','["3 meses", "15 días", "2 meses", "1 mes"]'::jsonb,3,'Art. 124.2 Ley 39/2015','El plazo máximo es de un mes.',null),
('aux-canarias:30-c900ae190a','aux-canarias',30,'El recurso extraordinario de revisión por error de hecho que resulte de los documentos del expediente se interpone en el plazo de:','["4 años desde la notificación de la resolución", "3 meses desde la notificación de la resolución", "1 año desde la notificación de la resolución", "2 meses desde que se tuvo conocimiento del error"]'::jsonb,0,'Art. 125.2 Ley 39/2015','Cuatro años desde la notificación en la causa a); tres meses en las demás causas.',null),
('aux-canarias:30-4bffe4da87','aux-canarias',30,'Contra la resolución de un recurso de alzada:','["Cabe recurso potestativo de reposición ante el mismo órgano que resolvió la alzada", "Solo cabe el recurso extraordinario de revisión, en los casos del art. 125.1", "Cabe un nuevo recurso de alzada ante el superior jerárquico del que resolvió", "Solo cabe recurso potestativo de reposición ante el mismo órgano, en los casos del art. 125.1"]'::jsonb,1,'Art. 122.3 Ley 39/2015','No cabe ningún otro recurso administrativo, salvo el extraordinario de revisión en los casos previstos.',null),
('aux-canarias:30-8b706bfee3','aux-canarias',30,'Si el recurso de alzada se interpone ante el órgano que dictó el acto, este deberá remitirlo al competente:','["En el plazo de un mes, con su informe y una copia completa y ordenada del expediente", "En el plazo de diez días, con su informe y una copia completa y ordenada del expediente", "En el plazo de quince días, sin necesidad de informe", "En el plazo de tres días, con el expediente original"]'::jsonb,1,'Art. 121.2 Ley 39/2015','Debe remitirlo en 10 días con informe y copia del expediente.',null),
('aux-canarias:30-800241692e','aux-canarias',30,'También es causa del recurso extraordinario de revisión que la resolución se haya dictado como consecuencia de:','["Prevaricación, cohecho, violencia, maquinación fraudulenta u otra conducta punible declarada en sentencia judicial firme", "Un cambio de criterio de la Administración posterior a la resolución", "Una denuncia de un tercero por prevaricación o cohecho, aunque todavía no haya recaído sentencia judicial firme", "Un error de calificación del recurso"]'::jsonb,0,'Art. 125.1 d) Ley 39/2015','Exige que la conducta se haya declarado en sentencia judicial firme.',null),
('aux-canarias:30-33377a6405','aux-canarias',30,'Si el acto no es expreso, el recurso de alzada podrá interponerse:','["En el plazo de un mes desde el día siguiente a aquel en que se produzcan los efectos del silencio", "En el plazo de tres meses desde la presentación de la solicitud", "En el plazo de dos meses", "En cualquier momento a partir del día siguiente a aquel en que se produzcan los efectos del silencio"]'::jsonb,3,'Art. 122.1 Ley 39/2015','Contra actos presuntos, en cualquier momento desde que se producen los efectos del silencio.',null),
('aux-canarias:30-d8034aa8aa','aux-canarias',30,'Interpuesto un recurso de reposición, no se podrá interponer recurso contencioso-administrativo hasta que:','["Sea resuelto expresamente o se haya producido su desestimación presunta", "Pasen seis meses desde su interposición, aunque se haya resuelto antes", "Sea resuelto expresamente, sin que baste la desestimación presunta", "Lo autorice el órgano que dictó el acto"]'::jsonb,0,'Art. 123.2 Ley 39/2015','Hay que esperar a la resolución expresa o la desestimación presunta.',null),
('aux-canarias:30-1b4a9efa77','aux-canarias',30,'¿Ante quién se interpone el recurso extraordinario de revisión?','["Ante el Tribunal Superior de Justicia competente", "Ante el superior jerárquico del órgano que dictó el acto, que es competente para resolverlo", "Ante el órgano administrativo que dictó el acto, que también es competente para resolverlo", "Ante el superior jerárquico del órgano que dictó el acto, previo dictamen del Consejo de Estado"]'::jsonb,2,'Art. 125.1 Ley 39/2015','Se interpone y resuelve por el mismo órgano que dictó el acto.',null),
('aux-canarias:30-b56d6c2cf5','aux-canarias',30,'Contra la resolución de un recurso de reposición:','["Cabe recurso de alzada", "No puede interponerse de nuevo dicho recurso", "Cabe un segundo recurso de reposición", "Cabe recurso de reposición ante el superior"]'::jsonb,1,'Art. 124.3 Ley 39/2015','No cabe reiterar la reposición.',null),
('aux-canarias:30-3747b6e653','aux-canarias',30,'Transcurridos tres meses desde la interposición del recurso extraordinario de revisión sin resolución:','["Caducará el procedimiento", "Se entenderá desestimado, quedando expedita la vía contencioso-administrativa", "Se entenderá estimado, salvo que el recurso se base en un error de hecho resultante de los documentos del expediente", "Se prorrogará otros tres meses"]'::jsonb,1,'Art. 126.3 Ley 39/2015','El silencio en el recurso extraordinario de revisión es desestimatorio.',null),
('aux-canarias:30-a9ef9bd226','aux-canarias',30,'El recurso de alzada se interpone ante:','["El Tribunal Superior de Justicia de la Comunidad Autónoma", "El Consejo de Estado", "El órgano superior jerárquico del que dictó el acto, pudiendo presentarse ante el que lo dictó o ante el competente para resolver", "El mismo órgano que dictó el acto, que lo resuelve en el plazo de un mes, sin que pueda presentarse ante el superior jerárquico ni ante otro órgano"]'::jsonb,2,'Art. 121.1 Ley 39/2015','Lo resuelve el superior jerárquico; puede presentarse ante cualquiera de los dos.',null),
('aux-canarias:30-08d3d0594d','aux-canarias',30,'Es causa del recurso extraordinario de revisión:','["Que haya transcurrido el plazo para interponer el recurso de alzada sin haberlo hecho, por causa no imputable al interesado", "Que el interesado cambie de opinión", "Que el acto sea desfavorable y el interesado aporte cualquier documento nuevo, aunque no evidencie error alguno en la resolución", "Que aparezcan documentos de valor esencial para la resolución que evidencien el error de la resolución recurrida"]'::jsonb,3,'Art. 125.1 b) Ley 39/2015','Las causas son: error de hecho, documentos esenciales nuevos, documentos o testimonios falsos declarados en sentencia firme y conducta punible declarada en sentencia firme.',null),
('aux-canarias:31-2607adccef','aux-canarias',31,'La Ley 9/2017 de Contratos del Sector Público califica como contratos de obras, concesión de obras, concesión de servicios, suministro y servicios a:','["Los contratos que regula en su sección de calificación de contratos", "Los contratos privados de las Administraciones Públicas", "Los convenios de colaboración entre Administraciones", "Los contratos patrimoniales de compraventa y arrendamiento de bienes inmuebles"]'::jsonb,0,'Art. 12.1 LCSP','Son los contratos que se califican según las normas de esa sección: obras, concesión de obras, concesión de servicios, suministro y servicios.',null),
('aux-canarias:31-cef3327e99','aux-canarias',31,'El contrato de obras tiene por objeto, entre otros:','["La adquisición o el arrendamiento de bienes muebles necesarios para una obra", "La ejecución de una obra, aislada o conjuntamente con la redacción del proyecto", "La redacción de un proyecto de obra, sin incluir su ejecución material", "La gestión de un servicio público, con o sin ejecución previa de una obra por el contratista"]'::jsonb,1,'Art. 13.1 LCSP','Tiene por objeto la ejecución de una obra, aislada o conjuntamente con la redacción del proyecto, o los trabajos del Anexo I.',null),
('aux-canarias:31-731212a37e','aux-canarias',31,'Los contratos de suministro tienen por objeto:','["La ejecución de obras, aislada o conjuntamente con la redacción del proyecto", "La prestación de una actividad o de un resultado distinto de una obra, a cambio de un precio cierto", "La adquisición, el arrendamiento financiero o el arrendamiento de productos o bienes muebles", "La adquisición o el arrendamiento de bienes inmuebles, con o sin opción de compra, y de derechos sobre ellos"]'::jsonb,2,'Art. 16.1 LCSP','Tienen por objeto la adquisición, el arrendamiento financiero o el arrendamiento, con o sin opción de compra, de productos o bienes muebles.',null),
('aux-canarias:31-84bc9fa8c9','aux-canarias',31,'Los contratos de servicios son aquellos cuyo objeto son:','["La adquisición o el arrendamiento de bienes inmuebles, valores negociables o derechos de propiedad incorporal sobre ellos", "La adquisición, el arrendamiento financiero o el arrendamiento, con o sin opción de compra, de productos o bienes muebles", "La ejecución de obras públicas, aislada o conjuntamente con la redacción del proyecto", "Prestaciones de hacer consistentes en una actividad o dirigidas a un resultado distinto de una obra o suministro"]'::jsonb,3,'Art. 17 LCSP','Son prestaciones de hacer consistentes en el desarrollo de una actividad o dirigidas a un resultado distinto de una obra o un suministro.',null),
('aux-canarias:31-5f1e8b7f27','aux-canarias',31,'Los contratos de suministros y servicios de prestación sucesiva tienen un plazo máximo de duración de:','["Cinco años, incluidas las posibles prórrogas", "Tres años, sin posibilidad de prórroga", "Cuatro años, más dos de posibles prórrogas anuales", "Diez años, incluidas las posibles prórrogas"]'::jsonb,0,'Art. 29.4 LCSP','Cinco años, incluyendo las posibles prórrogas.',null),
('aux-canarias:31-320c82b83b','aux-canarias',31,'Los contratos menores:','["Pueden durar hasta dos años, sin posibilidad de prórroga", "No pueden durar más de un año ni ser objeto de prórroga", "No pueden durar más de un año, pero pueden prorrogarse una vez", "No pueden durar más de seis meses ni ser objeto de prórroga"]'::jsonb,1,'Art. 29.8 LCSP','No pueden tener una duración superior a un año ni ser objeto de prórroga.',null),
('aux-canarias:31-72f0418000','aux-canarias',31,'El perfil de contratante se difunde:','["Exclusivamente a través de Internet", "En el BOE", "En el tablón de anuncios del órgano", "En la prensa nacional"]'::jsonb,0,'Art. 63 LCSP','Los órganos de contratación difunden exclusivamente a través de Internet su perfil de contratante.',null),
('aux-canarias:31-df605b4cb7','aux-canarias',31,'Pueden contratar con el sector público las personas naturales o jurídicas que:','["Tengan domicilio social en España y plena capacidad de obrar, estén inscritas en el Registro Mercantil y acrediten su solvencia", "Tengan plena capacidad de obrar, no estén incursas en prohibición de contratar y acrediten su solvencia", "Tengan plena capacidad de obrar y estén inscritas en el registro mercantil desde hace al menos cinco años", "No estén incursas en prohibición de contratar y hayan contratado antes con la Administración"]'::jsonb,1,'Art. 65.1 LCSP','Se exige plena capacidad de obrar, no estar incursas en prohibición de contratar y acreditar la solvencia (o clasificación cuando se exija).',null),
('aux-canarias:31-7690354173','aux-canarias',31,'La garantía provisional, cuando se exige, no puede ser superior al:','["5 % del precio de adjudicación, IVA excluido", "10 % del presupuesto base de licitación, IVA incluido", "3 % del presupuesto base de licitación, IVA excluido", "2 % del valor estimado del contrato, IVA excluido"]'::jsonb,2,'Art. 106.2 LCSP','No puede superar el 3 % del presupuesto base de licitación, excluido el IVA.',null),
('aux-canarias:31-c287aab809','aux-canarias',31,'La garantía definitiva es, con carácter general, del:','["3 % del presupuesto base de licitación", "10 % del precio con IVA", "2 % del valor estimado", "5 % del precio final ofertado, IVA excluido"]'::jsonb,3,'Art. 107.1 LCSP','Es del 5 % del precio final ofertado, excluido el IVA.',null),
('aux-canarias:31-24cbfae18c','aux-canarias',31,'El orden jurisdiccional contencioso-administrativo es competente para resolver las cuestiones relativas a:','["Los delitos cometidos por el contratista en la ejecución", "Los efectos y extinción de los contratos privados de los poderes adjudicadores que no sean Administraciones", "La preparación, adjudicación, efectos, modificación y extinción de los contratos administrativos", "Los despidos del personal del contratista y las reclamaciones de los subcontratistas por los pagos pendientes"]'::jsonb,2,'Art. 27.1 a) LCSP','El orden civil conoce de los efectos y extinción de los contratos privados.',null),
('aux-canarias:31-f1940cceef','aux-canarias',31,'Un encargo a un medio propio personificado que cumpla los requisitos legales:','["Es un contrato menor, si no supera los 15.000 euros", "Es un contrato de servicios no armonizado", "Requiere licitación pública", "No tendrá la consideración de contrato"]'::jsonb,3,'Art. 32.1 LCSP','Requiere, entre otros, que más del 80 % de la actividad del ente se realice para el poder adjudicador que lo controla.',null),
('aux-canarias:31-0a008fca8f','aux-canarias',31,'La garantía definitiva puede constituirse, entre otras formas:','["Solo en efectivo, ingresado en la Caja General de Depósitos", "En efectivo o valores, mediante aval o mediante contrato de seguro de caución", "Mediante pagaré personal del contratista o mediante prenda sobre maquinaria, sin necesidad de aval", "Mediante hipoteca sobre bienes inmuebles del contratista o de un tercero, o mediante prenda sobre sus bienes muebles"]'::jsonb,1,'Art. 108.1 LCSP','Son las formas de constitución de la garantía.',null),
('aux-canarias:31-1dc8de3ad9','aux-canarias',31,'La información publicada en el perfil de contratante debe mantenerse durante un periodo de tiempo de, al menos:','["6 meses", "10 años", "1 año", "5 años"]'::jsonb,3,'Art. 63.1 LCSP','El acceso al perfil es libre y se difunde exclusivamente a través de Internet.',null),
('aux-canarias:31-d012828fff','aux-canarias',31,'Con carácter general, la duración de la prohibición de contratar no podrá exceder de:','["Diez años", "Cinco años", "Un año", "Tres años"]'::jsonb,3,'Art. 72.6 LCSP','Salvo que la sentencia o resolución firme establezca otro plazo.',null),
('aux-canarias:31-60048950d4','aux-canarias',31,'Según el art. 2.1 LCSP, un contrato es oneroso cuando:','["El contratista obtiene algún tipo de beneficio económico, directo o indirecto", "Supera los 15.000 euros de valor estimado, en el caso de los contratos de servicios y suministros", "Lo celebra una Administración territorial", "Se paga siempre en metálico"]'::jsonb,0,'Art. 2.1 LCSP','La ley se aplica a los contratos onerosos celebrados por las entidades del sector público.',null),
('aux-canarias:31-d22138d652','aux-canarias',31,'El valor estimado de los contratos de obras, suministros y servicios se calcula:','["Por el importe total pagadero, incluido el IVA", "Por el importe total pagadero, sin incluir el IVA", "Sin incluir las posibles prórrogas", "Solo con el precio del primer año de ejecución"]'::jsonb,1,'Art. 101.1 a) LCSP','Se tienen en cuenta las eventuales prórrogas y modificaciones previstas.',null),
('aux-canarias:31-a429b174a2','aux-canarias',31,'La publicación de la información de los contratos menores en el perfil de contratante se realizará:','["Anualmente", "Al menos trimestralmente", "Diariamente", "Solo si superan 15.000 euros"]'::jsonb,1,'Art. 63.4 LCSP','Quedan exceptuados los de valor inferior a 5.000 euros pagados mediante anticipo de caja fija o similar.',null),
('aux-canarias:31-5c1243d539','aux-canarias',31,'Los contratos de suministro de la AGE y sus organismos están sujetos a regulación armonizada cuando su valor estimado sea igual o superior a:','["750.000 euros", "40.000 euros", "5.404.000 euros", "140.000 euros"]'::jsonb,3,'Art. 21.1 LCSP','Para otras entidades el umbral es de 216.000 euros.',null),
('aux-canarias:31-ab394775bc','aux-canarias',31,'Las concesiones de obras y de servicios que comprendan la ejecución de obras tendrán un plazo de duración máximo de:','["40 años", "10 años", "25 años", "5 años"]'::jsonb,0,'Art. 29.6 a) LCSP','Las concesiones de servicios sin obras no sanitarios, 25 años; los sanitarios del art. 29.6 c), 10 años.',null),
('aux-canarias:31-c07d2b2e15','aux-canarias',31,'La prórroga de un contrato será obligatoria para el empresario siempre que su preaviso se produzca, al menos, con una antelación de:','["Quince días respecto de la finalización del plazo de duración del contrato", "Dos meses respecto de la finalización del plazo de duración del contrato", "Seis meses respecto de la finalización del plazo de duración del contrato", "Un mes"]'::jsonb,1,'Art. 29.2 LCSP','La prórroga no puede producirse por consentimiento tácito de las partes.',null),
('aux-canarias:31-3952466779','aux-canarias',31,'Los contratos de servicios sociales y otros del anexo IV están sujetos a regulación armonizada cuando su valor estimado sea igual o superior a:','["140.000 euros", "750.000 euros", "5.404.000 euros", "216.000 euros"]'::jsonb,1,'Art. 22.1 LCSP','Es un umbral específico para los servicios del anexo IV.',null),
('aux-canarias:31-65187c3f9c','aux-canarias',31,'Tanto en la concesión de obras como en la de servicios es necesaria la transferencia al concesionario de:','["La propiedad del dominio público", "La titularidad del servicio público", "El riesgo operacional", "La potestad sancionadora"]'::jsonb,2,'Arts. 14.4 y 15.2 LCSP','El concesionario asume el riesgo operacional en la explotación.',null),
('aux-canarias:31-aaa6ea3d0c','aux-canarias',31,'La inscripción en el Registro Oficial de Licitadores y Empresas Clasificadas del Sector Público acredita, salvo prueba en contrario:','["Las condiciones de aptitud del empresario frente a todos los órganos de contratación del sector público", "Que la empresa ha constituido la garantía definitiva exigida", "Las condiciones de aptitud del empresario solo frente a los órganos de contratación de la Administración General del Estado", "Las condiciones de aptitud del empresario, pero solo frente a los órganos de contratación de la Administración General del Estado"]'::jsonb,0,'Art. 96.1 LCSP','Acredita personalidad, capacidad, representación, solvencia y ausencia de prohibiciones.',null),
('aux-canarias:31-99bc66876b','aux-canarias',31,'Las entidades del sector público no podrán celebrar otros contratos que:','["Aquellos que sean necesarios para el cumplimiento y realización de sus fines institucionales", "Los que apruebe previamente el Parlamento", "Los que demanden los ciudadanos a través de los procesos de participación ciudadana y presupuestos participativos", "Los que superen 40.000 euros y estén previstos en el plan anual de contratación aprobado por el órgano"]'::jsonb,0,'Art. 28.1 LCSP','Principio de necesidad e idoneidad del contrato.',null),
('aux-canarias:31-036436e9a4','aux-canarias',31,'Están sujetos a regulación armonizada los contratos de obras y concesiones de valor estimado igual o superior a:','["5.404.000 euros", "1.000.000 euros", "750.000 euros", "216.000 euros"]'::jsonb,0,'Art. 20.1 LCSP','Umbral vigente según el texto consolidado del BOE (los umbrales se revisan periódicamente).',null),
('aux-canarias:31-9f1aae4c36','aux-canarias',31,'Para que un ente sea medio propio personificado, más del ___ de sus actividades deben llevarse a cabo en el ejercicio de los cometidos que le confíe el poder adjudicador:','["50 %", "80 %", "100 %", "20 %"]'::jsonb,1,'Art. 32.2 b) LCSP','Más del 80 % de su actividad debe dirigirse al poder adjudicador que lo controla.',null),
('aux-canarias:31-2acf909ae3','aux-canarias',31,'En la concesión de obras, la contraprestación a favor del concesionario consiste en:','["Un precio fijo pagado por adelantado por la Administración, sin derecho a explotar la obra", "Una subvención anual a cargo de la Administración concedente, sin derecho a explotar la obra", "El derecho a explotar la obra, o dicho derecho acompañado del de percibir un precio", "La propiedad de la obra"]'::jsonb,2,'Art. 14.1 LCSP','La concesión implica la transferencia del riesgo operacional al concesionario.',null),
('aux-canarias:31-1b59dd30af','aux-canarias',31,'Los órganos de contratación designarán un responsable del contrato al que corresponderá:','["Fijar el precio del contrato y resolver las reclamaciones de los licitadores sobre la adjudicación, previo informe de la mesa de contratación y de los servicios jurídicos", "Resolver el recurso especial", "Supervisar su ejecución y adoptar las decisiones y dictar las instrucciones necesarias para asegurar la correcta realización de la prestación", "Adjudicar el contrato, fijar el precio de licitación y resolver el recurso especial en materia de contratación que interpongan los licitadores excluidos"]'::jsonb,2,'Art. 62.1 LCSP','Su designación es obligatoria.',null),
('aux-canarias:31-549ab21d7e','aux-canarias',31,'La garantía complementaria que puede exigirse en casos especiales puede ser de hasta un 5 %, de modo que la garantía total pueda alcanzar:','["Un 15 % del precio del contrato", "Un 8 % del precio del contrato, IVA incluido", "Un 10 % del precio del contrato", "Un 20 % del precio del contrato"]'::jsonb,2,'Art. 107.2 LCSP','La garantía definitiva ordinaria es del 5 % y la complementaria hasta otro 5 %.',null),
('aux-canarias:31-639787d3e7','aux-canarias',31,'¿Puede prorrogarse un contrato por consentimiento tácito de las partes?','["Sí, si lo autoriza el responsable del contrato", "Sí, siempre", "Sí, si es un contrato menor", "No, en ningún caso"]'::jsonb,3,'Art. 29.2 LCSP','La prórroga la acuerda el órgano de contratación y nunca es tácita.',null),
('aux-canarias:31-d0727ef26d','aux-canarias',31,'Es una prohibición de contratar del art. 71.1:','["Haber sido adjudicatario de otro contrato con la misma Administración en los últimos tres años", "Tener menos de diez trabajadores", "Haber sido condenado mediante sentencia firme por determinados delitos, como cohecho o prevaricación", "No disponer de sede social en España"]'::jsonb,2,'Art. 71.1 a) LCSP','Otras: sanciones firmes, concurso, incumplimiento de obligaciones tributarias o de Seguridad Social…',null),
('aux-canarias:31-0506a91120','aux-canarias',31,'En los contratos de las Administraciones Públicas, el pago aplazado del precio:','["Está prohibido, salvo excepciones como el arrendamiento financiero", "Está permitido siempre que lo acepte el contratista", "Solo se permite en contratos menores y en los de suministro de bienes", "Es obligatorio en los contratos de obras de valor estimado superior a 5.000.000 de euros"]'::jsonb,0,'Art. 102.8 LCSP','Se prohíbe salvo los supuestos legalmente previstos.',null),
('aux-canarias:32-93e48857bd','aux-canarias',32,'Son contratos menores de obras los de valor estimado inferior a:','["40.000 euros", "15.000 euros", "50.000 euros", "100.000 euros"]'::jsonb,0,'Art. 118.1 LCSP','Obras: valor estimado inferior a 40.000 €. Suministro o servicios: inferior a 15.000 €.',null),
('aux-canarias:32-b5a540ed55','aux-canarias',32,'Son contratos menores de suministro o de servicios los de valor estimado inferior a:','["40.000 euros", "15.000 euros", "6.000 euros", "30.000 euros"]'::jsonb,1,'Art. 118.1 LCSP','Suministro o servicios: inferior a 15.000 €. Obras: inferior a 40.000 €.',null),
('aux-canarias:32-a7ebcdc015','aux-canarias',32,'Con carácter ordinario, la adjudicación se realiza por:','["El procedimiento negociado con publicidad, con pluralidad de criterios basados en la mejor relación calidad-precio", "El diálogo competitivo, utilizando como único criterio el precio más bajo ofertado", "El procedimiento abierto o el restringido, con pluralidad de criterios basados en la mejor relación calidad-precio", "El procedimiento abierto simplificado, con un único criterio de adjudicación"]'::jsonb,2,'Art. 131.2 LCSP','Ordinariamente por procedimiento abierto o restringido, con pluralidad de criterios basados en la mejor relación calidad-precio.',null),
('aux-canarias:32-dae5aef377','aux-canarias',32,'Los contratos se adjudican utilizando una pluralidad de criterios en base a:','["El precio más bajo ofertado", "La mayor experiencia acreditada de la empresa", "La menor huella de carbono", "La mejor relación calidad-precio"]'::jsonb,3,'Art. 145.1 LCSP','Se adjudican con pluralidad de criterios en base a la mejor relación calidad-precio.',null),
('aux-canarias:32-9d64fdfddb','aux-canarias',32,'Si el contrato no es susceptible de recurso especial, la formalización debe hacerse:','["No más tarde de los quince días hábiles siguientes a la notificación de la adjudicación", "No más tarde de un mes desde la notificación de la adjudicación a todos los licitadores participantes", "No más tarde de los quince días naturales siguientes a la publicación de la adjudicación", "No más tarde de los diez días hábiles siguientes a la notificación de la adjudicación"]'::jsonb,0,'Art. 153.3 LCSP','No más tarde de los quince días hábiles siguientes a la notificación de la adjudicación.',null),
('aux-canarias:32-3fc13b0a3b','aux-canarias',32,'En el procedimiento abierto:','["Solo pueden presentar proposición las empresas invitadas por el órgano de contratación", "Todo empresario interesado puede presentar una proposición, excluida toda negociación", "Todo empresario interesado puede presentar una proposición, que luego se negocia con él", "Solo pueden presentar proposición las empresas inscritas en el Registro Oficial de Licitadores"]'::jsonb,1,'Art. 156.1 LCSP','Todo empresario interesado puede presentar una proposición, quedando excluida toda negociación.',null),
('aux-canarias:32-39e5cf0172','aux-canarias',32,'En el procedimiento restringido pueden presentar proposiciones:','["Todos los empresarios interesados, excluida toda negociación de los términos del contrato", "Solo las pequeñas y medianas empresas que acrediten su solvencia técnica", "Solo los empresarios que, a su solicitud y en atención a su solvencia, sean seleccionados", "Solo los empresarios inscritos en el Registro Oficial de Licitadores y Empresas Clasificadas"]'::jsonb,2,'Art. 160.2 LCSP','Cualquier empresa puede solicitar participar, pero solo presentan proposiciones las seleccionadas.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-canarias:32-0a7f2cf231','aux-canarias',32,'En el procedimiento restringido, el número mínimo de empresarios invitados no puede ser inferior a:','["Tres", "Diez", "Dos", "Cinco"]'::jsonb,3,'Art. 162.2 LCSP','No puede ser inferior a cinco.',null),
('aux-canarias:32-299ad0e0a8','aux-canarias',32,'En los procedimientos con negociación, la adjudicación recae en el licitador elegido:','["Tras negociar las condiciones del contrato con uno o varios candidatos", "Por sorteo público entre los candidatos que hayan acreditado la solvencia exigida en los pliegos", "Por orden de presentación de las ofertas, sin negociación", "Atendiendo únicamente al precio más bajo, sin negociación"]'::jsonb,0,'Art. 166.1 LCSP','Recae en el licitador justificadamente elegido tras negociar las condiciones con uno o varios candidatos.',null),
('aux-canarias:32-84feda82e8','aux-canarias',32,'En la tramitación urgente del expediente, el plazo de inicio de la ejecución del contrato no podrá exceder de:','["Quince días, contados desde la formalización", "Tres meses, contados desde la adjudicación", "Una semana, contada desde la formalización", "Un mes, contado desde la formalización"]'::jsonb,3,'Art. 119.2 c) LCSP','La urgencia reduce además a la mitad los plazos de licitación, adjudicación y formalización.',null),
('aux-canarias:32-b89a6fe872','aux-canarias',32,'En el procedimiento de licitación con negociación, cuando se limite el número de candidatos, el mínimo será de:','["Cinco", "Dos", "Tres", "Diez"]'::jsonb,2,'Art. 169.2 LCSP','El número mínimo de invitados es tres.',null),
('aux-canarias:32-8939de0e28','aux-canarias',32,'En la AGE, el anuncio de licitación se publica en el perfil de contratante y, además:','["En un periódico de tirada nacional", "En el BOCM", "En el BOE", "En el tablón de anuncios del Ministerio exclusivamente"]'::jsonb,2,'Art. 135.1 LCSP','Si el contrato está sujeto a regulación armonizada, también en el DOUE.',null),
('aux-canarias:32-6a1d890f29','aux-canarias',32,'En la tramitación de emergencia:','["Hay que tramitar siempre un procedimiento abierto con plazos reducidos a la mitad, como en la tramitación urgente", "Se requiere autorización judicial", "No puede contratarse", "El órgano de contratación puede ordenar la ejecución sin obligación de tramitar expediente de contratación"]'::jsonb,3,'Art. 120.1 a) LCSP','El inicio de la ejecución no puede exceder de un mes desde el acuerdo.',null),
('aux-canarias:32-9546c372a3','aux-canarias',32,'Cuando haya varios criterios de adjudicación, el plazo máximo para adjudicar será de:','["Quince días desde la apertura de las proposiciones, sin que el pliego pueda fijar otro", "Dos meses desde la apertura de las proposiciones, salvo que el pliego indique otro", "Seis meses desde la apertura de las proposiciones", "Un mes desde la apertura de las proposiciones, salvo que el pliego indique otro"]'::jsonb,1,'Art. 158.2 LCSP','Con un único criterio (el precio), el plazo es de quince días.',null),
('aux-canarias:32-542f440ffb','aux-canarias',32,'Si el licitador propuesto no cumplimenta adecuadamente el requerimiento de documentación en plazo, se le exigirá una penalidad del:','["10 % del precio de adjudicación", "3 % del presupuesto base de licitación, IVA excluido", "1 % del valor estimado", "5 % del presupuesto base de licitación, IVA incluido"]'::jsonb,1,'Art. 150.2 LCSP','Se entiende que ha retirado su oferta.',null),
('aux-canarias:32-b691421ee8','aux-canarias',32,'El procedimiento abierto simplificado puede utilizarse en contratos de obras de valor estimado igual o inferior a:','["2.000.000 de euros", "5.538.000 euros", "500.000 euros, IVA excluido", "100.000 euros, IVA excluido"]'::jsonb,0,'Art. 159.1 LCSP','Para suministros y servicios hay un umbral inferior.',null),
('aux-canarias:32-39d09b66fd','aux-canarias',32,'En los contratos de servicios del anexo IV y en los que tengan por objeto prestaciones de carácter intelectual, los criterios relacionados con la calidad deben representar, al menos:','["El 51 % de la puntuación asignable", "El 30 % de la puntuación asignable", "El 75 % de la puntuación asignable", "El 40 % de la puntuación asignable"]'::jsonb,0,'Art. 145.4 LCSP','Garantiza que la calidad pese más que el precio en esos contratos.',null),
('aux-canarias:33-89ce4409b3','aux-canarias',33,'El recurso especial en materia de contratación tiene carácter:','["Obligatorio", "Previo al recurso de alzada", "Potestativo", "Exclusivo de las empresas adjudicatarias"]'::jsonb,2,'Art. 44.7 LCSP','Tiene carácter potestativo y es gratuito para los recurrentes.',null),
('aux-canarias:33-d884cd58bb','aux-canarias',33,'El plazo para interponer el recurso especial en materia de contratación es de:','["Un mes", "Diez días naturales", "Dos meses", "Quince días hábiles"]'::jsonb,3,'Art. 50.1 LCSP','El plazo es de quince días hábiles.',null),
('aux-canarias:33-24265313b8','aux-canarias',33,'Es causa de resolución del contrato la demora en el cumplimiento de los plazos que suponga un retraso injustificado superior a:','["La mitad del plazo de duración inicial del contrato", "Un mes, en todo caso", "Un quinto del plazo de duración inicial del contrato, sin incluir las prórrogas", "Un tercio del plazo de duración inicial del contrato, incluidas las prórrogas"]'::jsonb,3,'Art. 211.1 d) LCSP','Es una de las causas de resolución del art. 211.',null),
('aux-canarias:33-ee822e6e5e','aux-canarias',33,'En el ámbito de la AGE, el conocimiento y resolución de los recursos especiales en materia de contratación corresponde a:','["La Audiencia Nacional", "La Junta Consultiva de Contratación Pública del Estado", "El Tribunal Administrativo Central de Recursos Contractuales", "El Tribunal de Cuentas"]'::jsonb,2,'Art. 45.1 LCSP','Las CCAA pueden crear órganos propios o atribuir la competencia al Tribunal estatal por convenio.',null),
('aux-canarias:33-b43a687b8d','aux-canarias',33,'Los contratos podrán modificarse durante su vigencia, cuando así se haya advertido expresamente en el pliego, hasta un máximo del:','["50 % del precio inicial", "20 % del precio inicial", "100 % del precio inicial", "10 % del precio inicial"]'::jsonb,1,'Art. 204.1 LCSP','Para las modificaciones no previstas en el pliego rige el art. 205.',null),
('aux-canarias:33-cb58b2ed22','aux-canarias',33,'Para que el contratista pueda ceder sus derechos y obligaciones a un tercero, es requisito que el cedente tenga ejecutado al menos:','["La totalidad de la prestación", "Un 10 % del importe del contrato", "Un 20 % del importe del contrato", "Un 50 % del importe del contrato o de su duración"]'::jsonb,2,'Art. 214.2 b) LCSP','Además, se necesita autorización previa del órgano de contratación.',null),
('aux-canarias:33-fd47edd6ce','aux-canarias',33,'La duración de un acuerdo marco no podrá exceder, salvo casos excepcionales justificados, de:','["Diez años", "Cuatro años", "Dos años", "Cinco años"]'::jsonb,1,'Art. 219.2 LCSP','Es la duración máxima ordinaria de los acuerdos marco.',null),
('aux-canarias:33-1775f59c7e','aux-canarias',33,'Según el art. 197 LCSP, la ejecución del contrato se realizará:','["A riesgo y ventura del contratista", "A riesgo del responsable del contrato", "A riesgo de la Administración", "A riesgo compartido al 50 %"]'::jsonb,0,'Art. 197 LCSP','Sin perjuicio de lo previsto para el contrato de obras en el art. 239.',null),
('aux-canarias:33-32bd1d671b','aux-canarias',33,'Si transcurren dos meses desde la interposición del recurso especial sin que se notifique su resolución:','["Se prorroga otros dos meses", "El contrato se anula", "Se entiende estimado por silencio administrativo y la adjudicación queda sin efecto, debiendo el órgano de contratación adjudicar al siguiente licitador", "El interesado podrá considerarlo desestimado a efectos de interponer recurso contencioso-administrativo"]'::jsonb,3,'Art. 57.5 LCSP','El silencio en el recurso especial es desestimatorio.',null),
('aux-canarias:33-1b89bcee9d','aux-canarias',33,'Los expedientes de resolución contractual deberán ser instruidos y resueltos en el plazo máximo de:','["Ocho meses", "Tres meses", "Un año", "Seis meses"]'::jsonb,0,'Art. 212.8 LCSP','Plazo máximo de ocho meses.',null),
('aux-canarias:33-9448973d83','aux-canarias',33,'Las penalidades por demora en la ejecución, salvo que el pliego disponga otras, serán diarias en la proporción de:','["0,10 euros por cada 1.000 euros", "1 euro por cada 100 euros", "5 euros por cada 1.000 euros del precio del contrato, IVA incluido", "0,60 euros por cada 1.000 euros del precio del contrato, IVA excluido"]'::jsonb,3,'Art. 193.3 LCSP','Cada vez que las penalidades alcancen un múltiplo del 5 % del precio se puede resolver el contrato.',null),
('aux-canarias:33-21a78d000d','aux-canarias',33,'Si se interpone recurso especial contra la adjudicación, como regla general:','["El recurso no produce efectos suspensivos", "Quedará en suspenso la tramitación del procedimiento", "La adjudicación se anula automáticamente y se retrotrae el procedimiento", "El contrato se formaliza igualmente"]'::jsonb,1,'Art. 53 LCSP','Salvo en contratos basados en acuerdos marco o sistemas dinámicos de adquisición.',null),
('aux-canarias:33-2dad37de72','aux-canarias',33,'Contra la resolución del recurso especial en materia de contratación:','["Solo procederá la interposición de recurso contencioso-administrativo", "Cabe recurso de alzada ante el titular del departamento", "Cabe recurso potestativo de reposición ante el mismo tribunal administrativo, y después recurso contencioso-administrativo", "No cabe ningún recurso"]'::jsonb,0,'Art. 59.1 LCSP','La resolución es directamente ejecutiva.',null),
('aux-canarias:33-1ca2d102ff','aux-canarias',33,'NO procede el recurso especial en materia de contratación respecto de los procedimientos de adjudicación que se sigan:','["Mediante procedimiento restringido", "Mediante procedimiento abierto", "Por el trámite de emergencia", "En contratos de servicios"]'::jsonb,2,'Art. 44.4 LCSP','No cabe recurso especial en la tramitación de emergencia.',null),
('aux-canarias:33-d95fe983e5','aux-canarias',33,'Si la demora en el pago por la Administración fuese superior a seis meses, el contratista tendrá derecho a:','["Ceder el contrato a un tercero sin necesidad de autorización del órgano de contratación", "Resolver el contrato y al resarcimiento de los perjuicios", "Una prórroga del contrato por un plazo igual al de la demora", "Suspender la ejecución, pero no resolver el contrato"]'::jsonb,1,'Art. 198.6 LCSP','Si la demora supera cuatro meses puede suspender el cumplimiento del contrato.',null),
('aux-canarias:33-bb57ce606f','aux-canarias',33,'La Administración tiene la obligación de abonar el precio dentro de los ___ siguientes a la fecha de aprobación de las certificaciones o documentos de conformidad:','["Noventa días", "Quince días", "Sesenta días", "Treinta días"]'::jsonb,3,'Art. 198.4 LCSP','Si se retrasa, debe abonar intereses de demora y la indemnización por costes de cobro.',null),
('aux-canarias:33-94efac4aa1','aux-canarias',33,'Contra las actuaciones susceptibles de recurso especial en materia de contratación:','["No procederá la interposición de recursos administrativos ordinarios", "Cabe además recurso de alzada ante el titular del departamento ministerial", "Cabe recurso de reposición obligatorio, previo al recurso especial", "Cabe recurso extraordinario de revisión previo, en los supuestos del art. 125 de la Ley 39/2015"]'::jsonb,0,'Art. 44.5 LCSP','El recurso especial sustituye a los recursos ordinarios.',null),
('aux-canarias:33-b1def1ae5f','aux-canarias',33,'Cada una de las penalidades no podrá ser superior al ___ del precio del contrato, ni el total superar el 50 %:','["5 %", "20 %", "10 %", "30 %"]'::jsonb,2,'Art. 192.1 LCSP','Límites de las penalidades contractuales.',null),
('aux-canarias:34-cdb45d3304','aux-canarias',34,'Según la Ley 38/2003, General de Subvenciones, ¿cuál de los siguientes es un requisito del concepto de subvención?','["Que la entrega se formalice mediante convenio con el beneficiario", "Que el importe no supere el crédito anual del órgano concedente", "Que la entrega se realice a favor de personas privadas exclusivamente, nunca públicas", "Que la entrega se realice sin contraprestación directa de los beneficiarios"]'::jsonb,3,'Art. 2.1 Ley 38/2003','El art. 2.1 a) exige que la entrega se realice sin contraprestación directa de los beneficiarios; además, puede hacerse a personas públicas o privadas.',null),
('aux-canarias:34-b4cc37afc9','aux-canarias',34,'Según la Ley 38/2003, ¿tienen carácter de subvención los beneficios fiscales?','["Solo cuando los otorga una entidad local", "Sí, si están previstos nominativamente en los presupuestos", "Sí, cuando se conceden en concurrencia competitiva", "No, la ley los excluye expresamente"]'::jsonb,3,'Art. 2.4 Ley 38/2003','El art. 2.4 g) dice que no tienen carácter de subvenciones los beneficios fiscales ni los beneficios en la cotización a la Seguridad Social.',null),
('aux-canarias:34-6e5b6754f3','aux-canarias',34,'Según la Ley 38/2003, ¿qué deben concretar con carácter previo los órganos que propongan el establecimiento de subvenciones?','["Un programa anual de inspección financiera", "Un informe previo y favorable de la Intervención General de la Administración", "Un plan estratégico de subvenciones", "Una memoria de impacto normativo"]'::jsonb,2,'Art. 8.1 Ley 38/2003','Deberán concretar en un plan estratégico de subvenciones los objetivos y efectos, el plazo, los costes previsibles y sus fuentes de financiación.',null),
('aux-canarias:34-6b6d6f97dd','aux-canarias',34,'¿Cuál de estos principios de gestión de las subvenciones recoge expresamente el art. 8.3 de la Ley 38/2003?','["Discrecionalidad técnica del órgano concedente en la selección", "Eficiencia en la asignación y utilización de los recursos públicos", "Preferencia de las entidades sin ánimo de lucro", "Confidencialidad de los beneficiarios y de las cuantías concedidas"]'::jsonb,1,'Art. 8.3 Ley 38/2003','Los principios son publicidad, transparencia, concurrencia, objetividad, igualdad y no discriminación; eficacia en los objetivos y eficiencia en la asignación y utilización de los recursos públicos.',null),
('aux-canarias:34-5872103582','aux-canarias',34,'Según la Ley 38/2003, ¿qué debe aprobarse con carácter previo al otorgamiento de las subvenciones?','["Las normas que establezcan las bases reguladoras de concesión", "El informe del órgano colegiado de evaluación", "La resolución de concesión provisional, publicada junto con el extracto de la convocatoria", "La cuenta justificativa del ejercicio anterior presentada por los solicitantes"]'::jsonb,0,'Art. 9.2 Ley 38/2003','Con carácter previo al otorgamiento deben aprobarse las normas que establezcan las bases reguladoras de concesión.',null),
('aux-canarias:34-461af83d53','aux-canarias',34,'¿Cuál de los siguientes NO figura entre los requisitos del otorgamiento de una subvención del art. 9.4 de la Ley 38/2003?','["La aceptación previa por escrito de todos los solicitantes", "La aprobación del gasto por el órgano competente", "La competencia del órgano administrativo concedente", "La existencia de crédito adecuado y suficiente"]'::jsonb,0,'Art. 9.4 Ley 38/2003','El art. 9.4 exige competencia del órgano, crédito adecuado y suficiente, tramitación conforme a las normas, fiscalización previa y aprobación del gasto.',null),
('aux-canarias:34-1336e4d791','aux-canarias',34,'Según la Ley 38/2003, ¿quién tiene la consideración de beneficiario de subvenciones?','["La entidad colaboradora que, actuando en nombre y por cuenta del órgano concedente, entrega y distribuye los fondos públicos", "Únicamente la persona jurídica que firma la solicitud", "La persona que haya de realizar la actividad que fundamentó su otorgamiento o que se encuentre en la situación que legitima su concesión", "Cualquier persona que haya presentado una solicitud admitida a trámite en plazo, aunque no realice la actividad"]'::jsonb,2,'Art. 11.1 Ley 38/2003','Así lo define el art. 11.1 de la Ley General de Subvenciones.',null),
('aux-canarias:34-b193f0a688','aux-canarias',34,'En una agrupación de personas sin personalidad beneficiaria de una subvención, ¿hasta cuándo no puede disolverse la agrupación?','["Hasta un año después de presentar la cuenta justificativa ante el órgano concedente", "Hasta que transcurra el plazo de prescripción de los arts. 39 y 65 de la ley", "Hasta que se dicte la resolución de concesión", "Hasta que se pague la totalidad de la subvención concedida a la agrupación"]'::jsonb,1,'Art. 11.3 Ley 38/2003','No podrá disolverse la agrupación hasta que haya transcurrido el plazo de prescripción previsto en los artículos 39 y 65.',null),
('aux-canarias:34-f52664aa30','aux-canarias',34,'Según la Ley 38/2003, ¿puede obtener la condición de beneficiario quien tenga la residencia fiscal en un paraíso fiscal?','["Solo con autorización del Consejo de Ministros", "Sí, si acredita estar al corriente con la Hacienda española", "Sí, salvo en las subvenciones de concesión directa", "No, es una de las prohibiciones del art. 13.2"]'::jsonb,3,'Art. 13.2 Ley 38/2003','El art. 13.2 f) impide obtener la condición de beneficiario a quien tenga la residencia fiscal en un país o territorio calificado reglamentariamente como paraíso fiscal.',null),
('aux-canarias:34-4098a3587c','aux-canarias',34,'Si la prohibición de obtener subvenciones no deriva de sentencia firme, ¿cuál es su alcance máximo según la Ley 38/2003?','["Tres años", "Dos años", "Diez años", "Cinco años"]'::jsonb,3,'Art. 13.5 Ley 38/2003','El alcance se fija según el procedimiento reglamentario, sin que pueda exceder de cinco años cuando la prohibición no derive de sentencia firme.',null),
('aux-canarias:34-4796952e3d','aux-canarias',34,'Para subvenciones de importe superior a 30.000 euros, ¿qué deben acreditar las empresas sujetas a la Ley 3/2004 para ser beneficiarias?','["Que no han recibido otras ayudas en el mismo ejercicio", "Que cumplen los plazos de pago a proveedores de la ley de morosidad", "Que han auditado sus cuentas de los tres últimos ejercicios", "Que tienen una plantilla mínima de diez trabajadores"]'::jsonb,1,'Art. 13.3 bis Ley 38/2003','El apartado 3 bis exige acreditar el cumplimiento de los plazos de pago de la Ley 3/2004, de lucha contra la morosidad.',null),
('aux-canarias:34-ec43a524d4','aux-canarias',34,'¿Cuándo debe comunicar el beneficiario la obtención de otras subvenciones que financien la misma actividad?','["Tan pronto como se conozca y, en todo caso, antes de la justificación de los fondos", "Solo si lo pide expresamente el órgano concedente", "Al finalizar el plazo de ejecución de la actividad, junto con la memoria final de actuación", "En el plazo de un mes desde la resolución de concesión"]'::jsonb,0,'Art. 14.1 Ley 38/2003','El art. 14.1 d) obliga a comunicarlo tan pronto como se conozca y, en todo caso, con anterioridad a la justificación de la aplicación dada a los fondos percibidos.',null),
('aux-canarias:34-7d71370d22','aux-canarias',34,'En el ámbito de la Administración General del Estado, ¿cómo se aprueban las bases reguladoras de las subvenciones?','["Por real decreto del Consejo de Ministros, a propuesta del ministro de Hacienda y previo informe del Consejo de Estado", "Por resolución del secretario de Estado de Presupuestos", "Por orden ministerial, previo informe de los servicios jurídicos y de la Intervención Delegada", "Por acuerdo de la Comisión Delegada para Asuntos Económicos"]'::jsonb,2,'Art. 17.1 Ley 38/2003','Las bases se aprueban por orden ministerial, previo informe de los servicios jurídicos y de la Intervención Delegada, y se publican en el BOE.',null),
('aux-canarias:34-9f2191eaae','aux-canarias',34,'¿Cómo deben aprobar las corporaciones locales las bases reguladoras de sus subvenciones?','["Mediante resolución de la junta de gobierno local, sin necesidad de ordenanza", "Por acuerdo del pleno publicado solo en el tablón de anuncios de la corporación local", "Por decreto del alcalde o del presidente", "En el marco de las bases de ejecución del presupuesto, mediante una ordenanza general o específica"]'::jsonb,3,'Art. 17.2 Ley 38/2003','Se aprueban en el marco de las bases de ejecución del presupuesto, a través de una ordenanza general de subvenciones o una ordenanza específica.',null),
('aux-canarias:34-49c37814b2','aux-canarias',34,'Según la Ley 38/2003, ¿cuál es el procedimiento ordinario de concesión de subvenciones?','["La concurrencia competitiva", "La adjudicación por sorteo público", "La concesión por orden de presentación de solicitudes", "La concesión directa"]'::jsonb,0,'Art. 22.1 Ley 38/2003','El procedimiento ordinario se tramita en régimen de concurrencia competitiva, comparando solicitudes según criterios de valoración previamente fijados.',null),
('aux-canarias:34-50b6f984af','aux-canarias',34,'En la concurrencia competitiva, ¿quién formula la propuesta de concesión al órgano concedente?','["Una comisión formada por los propios solicitantes", "Un órgano colegiado a través del órgano instructor", "La Intervención Delegada, tras fiscalizar las solicitudes presentadas", "El órgano instructor sin intervención de ningún otro"]'::jsonb,1,'Art. 22.1 Ley 38/2003','La propuesta se formula al órgano concedente por un órgano colegiado a través del órgano instructor; su composición la fijan las bases.',null),
('aux-canarias:34-bee133bf4b','aux-canarias',34,'¿Cuál de estas subvenciones puede concederse de forma directa según la Ley 38/2003?','["Las solicitadas fuera de plazo por causa justificada", "Todas las que conceda una entidad local", "Las previstas nominativamente en los presupuestos", "Las de importe inferior a 3.000 euros"]'::jsonb,2,'Art. 22.2 Ley 38/2003','Pueden concederse de forma directa las nominativas, las impuestas por norma con rango de ley y, excepcionalmente, las que acrediten razones de interés público, social, económico o humanitario.',null),
('aux-canarias:34-1b56a5ac65','aux-canarias',34,'Durante la instrucción, ¿cuál es el plazo general para emitir los informes que pida el órgano instructor?','["15 días", "5 días", "10 días", "Un mes"]'::jsonb,2,'Art. 24.3 Ley 38/2003','El plazo es de 10 días, salvo que el instructor pida un plazo menor o mayor, que en este caso no puede exceder de dos meses.',null),
('aux-canarias:34-788e28fc59','aux-canarias',34,'Notificada la propuesta de resolución provisional, ¿de qué plazo disponen los interesados para presentar alegaciones?','["5 días", "10 días", "20 días", "15 días"]'::jsonb,1,'Art. 24.4 Ley 38/2003','La propuesta de resolución provisional se notifica a los interesados y se concede un plazo de 10 días para presentar alegaciones.',null),
('aux-canarias:34-5ad1f56258','aux-canarias',34,'¿Crean derecho a favor del beneficiario las propuestas de resolución provisional y definitiva?','["No, mientras no se le haya notificado la resolución de concesión", "Sí, si el beneficiario ya ha comunicado su aceptación de la propuesta en el plazo previsto", "Sí, desde que se notifica la propuesta definitiva, aunque aún no se haya dictado la resolución", "Solo la definitiva, cuando no hubo trámite de audiencia"]'::jsonb,0,'Art. 24.6 Ley 38/2003','Las propuestas no crean derecho alguno frente a la Administración mientras no se haya notificado la resolución de concesión.',null),
('aux-canarias:34-ff9aeab599','aux-canarias',34,'Salvo norma con rango de ley o normativa de la UE, ¿cuál es el plazo máximo para resolver y notificar el procedimiento de concesión?','["Tres meses", "Cuatro meses", "Un año", "Seis meses"]'::jsonb,3,'Art. 25.4 Ley 38/2003','El plazo máximo no puede exceder de seis meses y se computa desde la publicación de la convocatoria, salvo que esta posponga sus efectos.',null),
('aux-canarias:34-416ae9f984','aux-canarias',34,'Si vence el plazo máximo sin notificar la resolución de concesión, ¿cómo puede entenderse la solicitud?','["Estimada por silencio administrativo", "Caducada, con archivo de las actuaciones", "Estimada solo si la convocatoria lo prevé", "Desestimada por silencio administrativo"]'::jsonb,3,'Art. 25.5 Ley 38/2003','El vencimiento del plazo legitima a los interesados para entender desestimada por silencio administrativo la solicitud de concesión.',null),
('aux-canarias:34-58a1e59917','aux-canarias',34,'A falta de previsión en las bases reguladoras, ¿en qué plazo máximo debe presentarse la cuenta justificativa?','["Tres meses desde la finalización del plazo para realizar la actividad", "Un mes desde la notificación de la resolución de concesión", "Dos meses desde la finalización de la actividad", "Seis meses desde el cobro efectivo de la subvención"]'::jsonb,0,'Art. 30.2 Ley 38/2003','La cuenta se presentará, como máximo, en el plazo de tres meses desde la finalización del plazo para la realización de la actividad.',null),
('aux-canarias:34-199a7d505b','aux-canarias',34,'En la adquisición de bienes inmuebles con una subvención, ¿qué debe aportarse además de las facturas?','["Nota simple del Catastro", "Escritura pública inscrita en el Registro de la Propiedad del lugar donde radique el inmueble", "Certificado de tasador independiente inscrito en el registro oficial", "Informe del arquitecto municipal"]'::jsonb,2,'Art. 30.5 Ley 38/2003','Debe aportarse certificado de tasador independiente debidamente acreditado e inscrito en el correspondiente registro oficial.',null),
('aux-canarias:34-42df755cfd','aux-canarias',34,'Según la Ley 38/2003, ¿cuál es una causa de nulidad de la resolución de concesión, además de las generales del procedimiento administrativo?','["La justificación insuficiente de la subvención", "La carencia o insuficiencia de crédito", "El incumplimiento de las medidas de difusión", "La obtención de otras ayudas, ingresos o recursos para la misma finalidad"]'::jsonb,1,'Art. 36.1 Ley 38/2003','Son causas de nulidad las generales de la ley de procedimiento y la carencia o insuficiencia de crédito.',null),
('aux-canarias:34-46eb60acf7','aux-canarias',34,'¿Cuál de las siguientes es una causa de reintegro según la Ley 38/2003?','["El incumplimiento de la obligación de justificación o la justificación insuficiente", "La carencia o insuficiencia de crédito", "La anulación de la convocatoria por defecto de forma en la publicación del extracto", "La falta de competencia del órgano concedente que dictó la resolución"]'::jsonb,0,'Art. 37.1 Ley 38/2003','El art. 37.1 c) incluye el incumplimiento de la obligación de justificación o la justificación insuficiente; la falta de crédito es causa de nulidad.',null),
('aux-canarias:34-1de8aab7de','aux-canarias',34,'¿En qué plazo prescribe el derecho de la Administración a reconocer o liquidar el reintegro de una subvención?','["Cinco años", "Cuatro años", "Tres años", "Dos años"]'::jsonb,1,'Art. 39.1 Ley 38/2003','Prescribe a los cuatro años el derecho de la Administración a reconocer o liquidar el reintegro.',null),
('aux-canarias:34-94c177a8fc','aux-canarias',34,'En las subvenciones concedidas por la concurrencia de una situación en el perceptor, ¿desde cuándo se computa la prescripción del reintegro?','["Desde la publicación de la convocatoria", "Desde el pago de la subvención", "Desde que venció el plazo de justificación", "Desde el momento de la concesión"]'::jsonb,3,'Art. 39.2 Ley 38/2003','En el supuesto del art. 30.7 el plazo se computa desde el momento de la concesión.',null),
('aux-canarias:35-fc71d10122','aux-canarias',35,'Se entiende por actuación administrativa automatizada la realizada íntegramente por medios electrónicos y:','["En la que un empleado público valide y firme cada acto con su certificado personal", "En la que no haya intervenido de forma directa un empleado público", "En la que intervenga un empleado público solo en la fase de notificación", "Que se publique en la sede electrónica"]'::jsonb,1,'Art. 41.1 Ley 40/2015','Es la realizada íntegramente por medios electrónicos en un procedimiento y sin intervención directa de un empleado público.',null),
('aux-canarias:35-e1d0a31eb3','aux-canarias',35,'En la actuación administrativa automatizada, cada Administración puede determinar como sistema de firma:','["El certificado de autenticación de sitio web de la sede electrónica", "Solo la firma electrónica cualificada de la persona titular del órgano", "La firma manuscrita digitalizada del empleado que supervisa el sistema", "Un sello electrónico o un código seguro de verificación vinculado a la Administración"]'::jsonb,3,'Art. 42 Ley 40/2015','El art. 42 permite el sello electrónico de Administración, órgano u organismo, o el código seguro de verificación.',null),
('aux-canarias:35-a3307e28f2','aux-canarias',35,'El código seguro de verificación (CSV) permite en todo caso:','["Prorrogar durante cinco años la validez del documento al que se vincula", "Comprobar la integridad del documento mediante el acceso a la sede electrónica correspondiente", "Identificar al empleado público que tramitó el expediente, su puesto de trabajo y el órgano al que está adscrito", "Sustituir la firma del interesado en las solicitudes que presente por registro"]'::jsonb,1,'Art. 42 b) Ley 40/2015','El CSV vinculado a la Administración permite en todo caso la comprobación de la integridad del documento accediendo a la sede.',null),
('aux-canarias:35-1d1276e3e7','aux-canarias',35,'Por razones de seguridad pública, los sistemas de firma electrónica del personal al servicio de la Administración:','["Podrán referirse solo al número de identificación profesional del empleado público", "Solo podrán utilizarse previa autorización judicial en cada procedimiento", "Podrán omitir cualquier dato que identifique al empleado público y a su órgano", "Deberán incluir siempre el nombre, los apellidos y el número del DNI del empleado público que firma la actuación"]'::jsonb,0,'Art. 43.2 Ley 40/2015','Por razones de seguridad pública, los sistemas de firma pueden referirse solo al número de identificación profesional del empleado.',null),
('aux-canarias:35-2847797009','aux-canarias',35,'Si los participantes en un entorno cerrado de comunicación pertenecen a distintas Administraciones, las condiciones y garantías se fijan:','["Por orden del ministerio competente en materia de función pública", "Mediante real decreto aprobado por el Consejo de Ministros", "Mediante convenio", "Por decisión del órgano emisor de los datos, sin más requisitos"]'::jsonb,2,'Art. 44.3 Ley 40/2015','Entre distintas Administraciones, las condiciones y garantías del entorno cerrado se establecen mediante convenio.',null),
('aux-canarias:35-2a56f067a6','aux-canarias',35,'Según el art. 46 de la Ley 40/2015, los documentos utilizados en las actuaciones administrativas se almacenan:','["En soporte electrónico solo si lo solicita el interesado", "En papel y en soporte electrónico, siempre por duplicado", "Por medios electrónicos durante cinco años y después en papel", "Por medios electrónicos, salvo cuando no sea posible"]'::jsonb,3,'Art. 46.1 Ley 40/2015','Todos los documentos utilizados en las actuaciones administrativas se almacenan por medios electrónicos, salvo cuando no sea posible.',null),
('aux-canarias:35-6df7682625','aux-canarias',35,'Según la Ley 40/2015, la actuación administrativa automatizada es:','["Cualquier acto dictado por un funcionario usando un ordenador", "El envío de avisos por SMS a los interesados", "Cualquier acto o actuación realizada íntegramente a través de medios electrónicos por una Administración en el marco de un procedimiento, sin intervención directa de un empleado público", "La digitalización de documentos en papel"]'::jsonb,2,'Art. 41.1 Ley 40/2015','Debe establecerse previamente el órgano u órganos competentes para definir las especificaciones, programación, mantenimiento, supervisión y control de calidad y auditoría del sistema.',null),
('aux-canarias:35-4005dde4f1','aux-canarias',35,'En la actuación administrativa automatizada, ¿qué sistema de firma puede utilizar cada Administración?','["Sello electrónico de órgano o código seguro de verificación", "El certificado electrónico personal del ciudadano que inició el procedimiento", "La clave concertada del interesado, comunicada previamente por SMS", "La firma manuscrita del titular del órgano, digitalizada mediante escáner"]'::jsonb,0,'Art. 42 Ley 40/2015','El código seguro de verificación permite comprobar la integridad del documento mediante el acceso a la sede electrónica correspondiente.',null),
('aux-canarias:35-1463a739aa','aux-canarias',35,'El código seguro de verificación (CSV) permite:','["Cifrar el documento para que solo pueda leerlo el destinatario que disponga de la clave privada correspondiente", "Firmar documentos en papel con valor de original", "Identificar al ciudadano ante cualquier Administración sin necesidad de disponer de un certificado electrónico", "Comprobar la integridad y autenticidad de un documento accediendo a la sede electrónica correspondiente"]'::jsonb,3,'Art. 42 b) Ley 40/2015','Se vincula a la Administración, órgano u organismo y, en su caso, a la persona firmante del documento.',null),
('aux-canarias:36-b3e413d299','aux-canarias',36,'Según la Ley 39/2015, cada Administración dispondrá de:','["Un Registro Electrónico General", "Un registro en papel por cada órgano", "Un registro único estatal", "Ningún registro propio"]'::jsonb,0,'Art. 16.1 Ley 39/2015','Cada Administración dispondrá de un Registro Electrónico General.',null),
('aux-canarias:36-973257e5bc','aux-canarias',36,'¿Dónde NO se pueden presentar documentos dirigidos a las Administraciones según el art. 16.4 de la Ley 39/2015?','["En las oficinas de Correos", "En las representaciones diplomáticas u oficinas consulares", "En las oficinas de asistencia en materia de registros", "En cualquier comercio colaborador"]'::jsonb,3,'Art. 16.4 Ley 39/2015','Se pueden presentar en los registros electrónicos, en Correos, en representaciones diplomáticas u oficinas consulares, en las oficinas de asistencia en materia de registros y donde establezcan las disposiciones vigentes.',null),
('aux-canarias:36-170629b97b','aux-canarias',36,'¿Cuál es uno de los requisitos de validez de los documentos administrativos electrónicos?','["Estar impresos y llevar el sello del órgano que los emite", "Llevar firma manuscrita escaneada y el sello del órgano emisor en cada página", "Incorporar la fecha de emisión y los metadatos mínimos exigidos", "Incorporar la fecha de emisión y estar disponibles en papel, con la firma original del titular del órgano"]'::jsonb,2,'Art. 26.2 Ley 39/2015','Deben contener información en soporte electrónico, datos de identificación, firmas electrónicas, fecha de emisión y metadatos mínimos.',null),
('aux-canarias:36-716e9cf73f','aux-canarias',36,'Los interesados, ¿están obligados a aportar documentos elaborados por cualquier Administración?','["Sí, siempre", "Sí, si son originales", "Solo en papel", "No"]'::jsonb,3,'Art. 28.2 Ley 39/2015','No están obligados a aportar documentos elaborados por cualquier Administración; esta puede consultarlos salvo oposición del interesado.',null),
('aux-canarias:36-24ad73d39b','aux-canarias',36,'¿Quién determina los órganos que tienen atribuidas las competencias de expedición de copias auténticas?','["Cada Administración Pública", "El Consejo de Estado", "El Ministerio de Justicia para todas", "Los notarios"]'::jsonb,0,'Art. 27.1 Ley 39/2015','Cada Administración determina los órganos competentes para expedir copias auténticas.',null),
('aux-canarias:36-7ff72f7d66','aux-canarias',36,'Los documentos presentados de manera presencial ante las Administraciones deberán ser:','["Archivados en papel sin digitalizar en la oficina que los recibió", "Digitalizados por la oficina de registro, conservándose los originales en el expediente", "Enviados por correo postal al órgano competente para su digitalización en destino, junto con el resto del expediente", "Digitalizados por la oficina de asistencia en materia de registros, devolviéndose los originales al interesado"]'::jsonb,3,'Art. 16.5 Ley 39/2015','Se digitalizan y se devuelven los originales, salvo que la norma determine la custodia obligatoria.',null),
('aux-canarias:36-c6c315e0f1','aux-canarias',36,'Las copias auténticas de documentos realizadas por los órganos competentes:','["Solo tienen validez dentro del mismo procedimiento en el que se expidieron", "Caducan a los seis meses de su expedición", "Tienen menos valor probatorio que el original, salvo que se compulsen ante notario", "Tendrán la misma validez y eficacia que los documentos originales"]'::jsonb,3,'Art. 27.2 Ley 39/2015','Las copias auténticas tienen la misma validez y eficacia que los originales.',null),
('aux-canarias:36-4e5c1be725','aux-canarias',36,'Se entiende por documentos públicos administrativos:','["Los documentos privados presentados en un registro público", "Los documentos autorizados por notario, exclusivamente", "Los válidamente emitidos por los órganos de las Administraciones Públicas", "Cualquier documento firmado electrónicamente por un ciudadano y presentado en la sede electrónica de una Administración"]'::jsonb,2,'Art. 26.1 Ley 39/2015','Se emiten por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma.',null),
('aux-canarias:36-d62a5dfbd3','aux-canarias',36,'Las Administraciones no exigirán a los interesados la presentación de documentos originales:','["Salvo en los procedimientos iniciados de oficio", "Salvo que, con carácter excepcional, la normativa reguladora aplicable establezca lo contrario", "En ningún caso, sin excepciones", "Salvo que el funcionario que tramite el procedimiento lo considere oportuno para comprobar su autenticidad"]'::jsonb,1,'Art. 28.3 Ley 39/2015','La regla es no exigir originales; solo excepcionalmente por normativa.',null),
('aux-canarias:36-37c2922713','aux-canarias',36,'Los expedientes tendrán formato electrónico y se formarán mediante la agregación ordenada de documentos, con:','["Un sello en papel en cada documento", "Un resumen elaborado por el instructor con la relación de los interesados y de los trámites realizados", "La firma de todos los interesados en cada uno de los documentos que contenga", "Un índice numerado de todos los documentos que contenga cuando se remita"]'::jsonb,3,'Art. 70.2 Ley 39/2015','Deben incluir un índice numerado de todos los documentos.',null),
('aux-canarias:36-597e4ba83d','aux-canarias',36,'En el asiento de registro debe constar, entre otros datos:','["La firma del superior jerárquico del órgano destinatario y el sello de la oficina que lo recibe", "Un número, epígrafe expresivo de su naturaleza, fecha y hora de presentación, identificación del interesado y referencia al contenido", "Un número, fecha de presentación, identificación del interesado y del órgano destinatario, pero no la hora de presentación ni ninguna referencia a su contenido", "El sentido previsible de la resolución"]'::jsonb,1,'Art. 16.2 Ley 39/2015','Se emite recibo con copia autenticada del documento, fecha y hora de presentación y número de entrada.',null),
('aux-canarias:36-c51f24e4a4','aux-canarias',36,'No se tendrán por presentados en el registro:','["Aquellos documentos e información cuyo régimen especial establezca otra forma de presentación", "Los presentados por un representante cuya representación no esté inscrita", "Los presentados en día inhábil, que se tendrán por no presentados hasta el siguiente hábil", "Los presentados en las oficinas de Correos sin sello de fechas"]'::jsonb,0,'Art. 16.8 Ley 39/2015','No se tienen por presentados los que tengan un régimen especial con otra forma de presentación.',null),
('aux-canarias:36-28bfbcd323','aux-canarias',36,'NO forma parte del expediente administrativo:','["La información auxiliar o de apoyo, como notas, borradores u opiniones, salvo los informes solicitados antes de la resolución", "Las notificaciones practicadas", "Las pruebas practicadas", "Los informes preceptivos, que se incorporan a un expediente auxiliar distinto del principal y no se remiten al juzgado"]'::jsonb,0,'Art. 70.4 Ley 39/2015','Notas, borradores, opiniones, resúmenes y comunicaciones internas no forman parte del expediente.',null),
('aux-canarias:36-bf89e6c0f5','aux-canarias',36,'Tras presentar un documento en el registro electrónico se emite automáticamente:','["Un recibo con copia autenticada del documento, fecha y hora de presentación y número de entrada", "Una resolución de admisión a trámite firmada por el órgano competente para resolver, con indicación del plazo máximo para hacerlo", "Un justificante sin fecha, que se completa el primer día hábil siguiente", "Un código para consultar el expediente, sin copia del documento presentado"]'::jsonb,0,'Art. 16.3 Ley 39/2015','El registro emite automáticamente un recibo consistente en una copia autenticada del documento, con fecha, hora y número de entrada.',null),
('aux-canarias:36-7565f3d867','aux-canarias',36,'Una vez digitalizados por la oficina de asistencia, los documentos originales presentados presencialmente:','["Se remiten siempre al archivo central de la consejería que tramita el expediente, para su custodia hasta que se dicte la resolución", "Se destruyen una vez transcurridos quince días hábiles desde su presentación", "Se conservan en la oficina de asistencia durante un año y después se devuelven", "Se devuelven al interesado, salvo que una norma determine su custodia por la Administración"]'::jsonb,3,'Art. 16.5 Ley 39/2015','Los originales se devuelven al interesado, sin perjuicio de los supuestos en que la norma determine la custodia por la Administración.',null),
('aux-canarias:36-b176c20c66','aux-canarias',36,'Las Administraciones deben hacer pública y mantener actualizada:','["La lista de los funcionarios que digitalizan documentos en cada oficina", "La lista de los interesados que han presentado documentos en papel durante el último año", "Una relación de las oficinas en las que se presta asistencia para la presentación electrónica de documentos", "Una relación de los documentos que no pueden presentarse en el registro electrónico"]'::jsonb,2,'Art. 16.7 Ley 39/2015','El art. 16.7 obliga a publicar y actualizar la relación de oficinas de asistencia en materia de registros.',null),
('aux-canarias:36-b64dc40178','aux-canarias',36,'Con carácter general, ¿pueden las Administraciones exigir a los interesados la presentación de documentos originales?','["Sí, siempre que el procedimiento se haya iniciado a solicitud del interesado", "Sí, en todo caso, cuando se trate de documentos de carácter público", "No, en ningún caso, ni siquiera cuando lo establezca una norma reguladora", "No, salvo que excepcionalmente la normativa reguladora aplicable establezca lo contrario"]'::jsonb,3,'Art. 28.3 Ley 39/2015','Las Administraciones no exigen originales, salvo que con carácter excepcional la normativa aplicable establezca lo contrario.',null),
('aux-canarias:36-f89e1f10f0','aux-canarias',36,'Si existen dudas derivadas de la calidad de la copia aportada por el interesado, la Administración puede:','["Tener la copia por no presentada y archivar el procedimiento de oficio", "Exigir que el interesado aporte en el plazo de un mes una copia compulsada por notario o por el secretario de un ayuntamiento", "Solicitar de manera motivada el cotejo de la copia, requiriendo la exhibición del original", "Inadmitir la solicitud sin más trámite, por falta de un requisito esencial"]'::jsonb,2,'Art. 28.5 Ley 39/2015','Excepcionalmente, la Administración puede solicitar motivadamente el cotejo y requerir la exhibición del documento original.',null),
('aux-canarias:36-3e7b06a64c','aux-canarias',36,'Según el art. 28.7 de la Ley 39/2015, de la veracidad de los documentos que presentan responden:','["El funcionario que digitaliza los documentos", "Los interesados", "El órgano instructor del procedimiento", "La oficina de asistencia que los registra"]'::jsonb,1,'Art. 28.7 Ley 39/2015','Los interesados se responsabilizarán de la veracidad de los documentos que presenten.',null),
('aux-canarias:36-b4040238a2','aux-canarias',36,'Según el Real Decreto 1708/2011, ¿en qué cuatro tipos se clasifican los archivos del Sistema de Archivos de la AGE según el ciclo vital de los documentos?','["Activos, pasivos, temporales y definitivos de cada Ministerio", "Físicos, electrónicos, mixtos y digitalizados", "De oficina o gestión, centrales, intermedio e históricos", "Generales, especiales, provinciales y municipales"]'::jsonb,2,'Art. 8 RD 1708/2011','Los documentos pasan del archivo de oficina al central, de este al intermedio y, si tienen valor histórico, al histórico.',null),
('aux-canarias:36-62c3dd9db0','aux-canarias',36,'¿Qué archivo actúa como archivo intermedio de la Administración General del Estado?','["El Archivo de la Corona de Aragón, en Barcelona", "El Archivo General de la Administración", "El Archivo General de Simancas, en Valladolid", "El Archivo Histórico Nacional, en Madrid"]'::jsonb,1,'Art. 11 RD 1708/2011','El Archivo Histórico Nacional actúa como archivo histórico de la AGE.',null),
('aux-canarias:36-c5f283fbc7','aux-canarias',36,'El Archivo Histórico Nacional cumple, en el Sistema de Archivos de la AGE, la función de:','["Archivo histórico", "Archivo intermedio", "Archivo central del Ministerio de Cultura", "Archivo electrónico único"]'::jsonb,0,'Art. 12 RD 1708/2011','Custodia documentos de valor patrimonial que reflejan la historia de la Administración del Estado.',null),
('aux-canarias:36-1818f19ded','aux-canarias',36,'En los archivos de oficina o de gestión se conservan los documentos:','["Una vez finalizada su tramitación y transcurridos quince años", "Que la Comisión Superior Calificadora ha propuesto eliminar", "Mientras están en tramitación o sometidos a uso administrativo continuo", "Que han sido declarados de conservación permanente por su valor histórico"]'::jsonb,2,'Art. 9 RD 1708/2011','Cuando termina ese uso, se transfieren al archivo central del departamento.',null),
('aux-canarias:36-100fef3daa','aux-canarias',36,'¿Qué instrumento fija, para cada serie documental, los plazos de permanencia de los documentos en cada tipo de archivo?','["El calendario de conservación", "La relación de puestos de trabajo", "El inventario", "El cuadro de clasificación"]'::jsonb,0,'Art. 15.3 RD 1708/2011','Determina las fases activa, semiactiva e inactiva de cada serie.',null),
('aux-canarias:36-21e80bd45a','aux-canarias',36,'¿Qué órgano debe dictaminar con carácter preceptivo las propuestas de eliminación o de conservación permanente de documentos de la AGE?','["La Agencia Española de Protección de Datos", "La Comisión Superior Calificadora de Documentos Administrativos", "La Comisión General de Secretarios de Estado y Subsecretarios del Gobierno", "El Consejo de Transparencia y Buen Gobierno, como autoridad independiente"]'::jsonb,1,'Art. 15.1 RD 1708/2011','Se rige por el Real Decreto 1401/2007.',null),
('aux-canarias:36-6e4c087f60','aux-canarias',36,'Según el Real Decreto 1708/2011, la eliminación de documentos es:','["La digitalización de los documentos en papel y su incorporación al expediente electrónico", "La destrucción física de unidades o series documentales por el órgano responsable, con métodos que impidan su reconstrucción", "El traslado de los documentos del archivo central al archivo intermedio", "El borrado de los datos personales de un documento para permitir su consulta pública"]'::jsonb,1,'Art. 2 RD 1708/2011','Solo puede hacerse tras el dictamen de la Comisión Superior Calificadora.',null),
('aux-canarias:36-04a49eede6','aux-canarias',36,'La valoración documental consiste en:','["La firma electrónica del documento por el órgano competente", "La asignación de un número de registro de entrada a cada documento", "El estudio de los valores administrativos, jurídicos, fiscales, informativos e históricos de los documentos", "El cálculo del coste económico que supone conservar un documento en el archivo durante todo su ciclo de vida"]'::jsonb,2,'Art. 2 RD 1708/2011','Sirve para decidir los plazos de conservación, el acceso y, en su caso, la eliminación.',null),
('aux-canarias:36-3aa4640d8d','aux-canarias',36,'Según la Ley 39/2015, el expediente administrativo es:','["La carpeta física en la que se archivan los escritos de los interesados", "El acto administrativo que pone fin al procedimiento", "Cualquier documento que se presente en un registro electrónico", "El conjunto ordenado de documentos y actuaciones que sirven de antecedente y fundamento a la resolución administrativa, y las diligencias encaminadas a ejecutarla"]'::jsonb,3,'Art. 70.1 Ley 39/2015','Los expedientes tienen formato electrónico.',null),
('aux-canarias:36-fac6b32067','aux-canarias',36,'¿Forman parte del expediente administrativo las notas, borradores y opiniones de carácter auxiliar?','["Sí, todos ellos, porque reflejan la actividad del órgano", "No, y además deben destruirse al terminar el procedimiento", "No, salvo que se trate de informes preceptivos o facultativos solicitados antes de la resolución", "Sí, todos ellos, porque reflejan la actividad interna del órgano y deben estar a disposición de los interesados"]'::jsonb,2,'Art. 70.4 Ley 39/2015','Tampoco forman parte las comunicaciones e informes internos o entre órganos o entidades administrativas, ni los juicios de valor emitidos por las Administraciones.',null),
('aux-canarias:36-64e8a7e5b6','aux-canarias',36,'Al remitir un expediente electrónico, este debe ir acompañado de:','["El original en papel de cada uno de los documentos que lo integran", "La firma manuscrita del jefe de la unidad que lo tramita y lo remite", "Una copia completa en soporte óptico, como un CD o un DVD", "Un índice numerado de todos los documentos que contenga"]'::jsonb,3,'Art. 70.2 Ley 39/2015','El índice garantiza la integridad del expediente y permite su recuperación.',null),
('aux-canarias:36-e740a4a89f','aux-canarias',36,'Los asientos en el registro electrónico se anotan:','["Agrupados por procedimientos administrativos al final de cada jornada de trabajo", "Respetando el orden temporal de recepción o salida de los documentos", "Por orden alfabético del apellido del interesado", "Por orden de importancia del asunto, según decida el responsable del registro"]'::jsonb,1,'Art. 16.2 Ley 39/2015','Indican la fecha del día en que se producen.',null),
('aux-canarias:36-824d704054','aux-canarias',36,'Los documentos que los interesados presenten en papel en las oficinas de asistencia en materia de registros:','["Se destruyen tras su presentación para evitar duplicidades", "Se archivan en papel en la oficina, sin digitalizarlos", "Se digitalizan para incorporarlos al expediente electrónico y se devuelven los originales al interesado", "Se remiten por valija a la unidad tramitadora, que los conserva en papel junto con el resto del expediente"]'::jsonb,2,'Art. 16.5 Ley 39/2015','Salvo que la norma determine la custodia de los documentos por la Administración o que se trate de objetos o documentos en un soporte específico no susceptibles de digitalización.',null),
('aux-canarias:36-bf1970481c','aux-canarias',36,'Las copias auténticas de documentos públicos administrativos o privados realizadas por las Administraciones:','["Tienen valor informativo y no pueden aportarse a otros procedimientos", "Valen durante seis meses desde su expedición", "Son válidas dentro de la Administración que las expide y en sus organismos públicos", "Tienen la misma validez y eficacia que los documentos originales"]'::jsonb,3,'Art. 27.2 Ley 39/2015','Pueden expedirse en papel o en soporte electrónico.',null),
('aux-canarias:36-06b522bd2b','aux-canarias',36,'El documento de archivo, según el RD 1708/2011, es:','["La relación de expedientes que se transfieren a otro archivo", "El ejemplar en cualquier soporte que refleja las actividades y funciones de personas físicas o jurídicas, públicas o privadas", "Cualquier libro o publicación editada por la Administración", "Solo el documento en papel firmado de forma manuscrita"]'::jsonb,1,'Art. 2 RD 1708/2011','Puede estar en papel o en formato electrónico.',null),
('aux-canarias:36-edf1e877fb','aux-canarias',36,'Según la Ley 39/2015, los interesados no estarán obligados a aportar documentos que:','["Tengan una antigüedad inferior a cinco años desde su expedición, salvo que el órgano competente los requiera por resolución motivada", "Hayan sido elaborados por cualquier Administración o que hayan sido aportados anteriormente por el interesado a cualquier Administración", "Estén redactados en una lengua cooficial distinta del castellano", "Hayan sido firmados electrónicamente por el propio interesado o por su representante con un certificado cualificado expedido por un prestador de confianza"]'::jsonb,1,'Art. 28.2 y 28.3 Ley 39/2015','La Administración los consultará o recabará, salvo oposición expresa del interesado o que una ley especial exija su consentimiento expreso.',null),
('aux-canarias:37-69576bd868','aux-canarias',37,'La combinación Tecla Windows + V en Windows 11 abre:','["El historial del portapapeles", "La configuración de vídeo y pantalla", "El panel de widgets con noticias y tiempo", "El Explorador de archivos"]'::jsonb,0,'Windows 11 · Portapapeles','Permite pegar elementos copiados anteriormente, si el historial está activado.',null),
('aux-canarias:37-37bffa0327','aux-canarias',37,'En Windows 11, ¿qué combinación de teclas abre el Explorador de archivos?','["Tecla Windows + E", "Tecla Windows + I", "Tecla Windows + L", "Tecla Windows + D"]'::jsonb,0,'Windows 11 · Atajos','Win+D muestra el escritorio, Win+L bloquea el equipo y Win+I abre Configuración.',null),
('aux-canarias:37-31f7dfee24','aux-canarias',37,'La combinación Tecla Windows + I abre:','["El Explorador de archivos", "La aplicación Configuración", "La búsqueda", "El Centro de notificaciones"]'::jsonb,1,'Windows 11 · Atajos','Configuración sustituye a gran parte del antiguo Panel de control.',null),
('aux-canarias:37-8983918cee','aux-canarias',37,'¿Qué combinación abre la herramienta Recortes para capturar una parte de la pantalla?','["Ctrl + Mayús + C", "Tecla Windows + S", "Tecla Windows + Mayús + S", "Tecla Windows + Impr Pant"]'::jsonb,2,'Windows 11 · Capturas','Win+S abre la búsqueda.',null),
('aux-canarias:37-7192137e38','aux-canarias',37,'La función de ajuste de ventanas de Windows 11 que permite elegir una distribución de pantalla al pasar el ratón por el botón Maximizar se llama:','["Diseños de acoplamiento (Snap layouts)", "Escritorio remoto (Remote Desktop)", "Vista de tareas (Task view)", "Modo de concentración (Focus)"]'::jsonb,0,'Windows 11 · Ventanas','También se abre con Tecla Windows + Z.',null),
('aux-canarias:37-29df8ddd28','aux-canarias',37,'¿Qué combinación de teclas bloquea el equipo en Windows 11?','["Alt + F4", "Tecla Windows + L", "Tecla Windows + B", "Ctrl + L"]'::jsonb,1,'Windows 11 · Atajos','Bloquea la sesión sin cerrar las aplicaciones abiertas.',null),
('aux-canarias:37-ef5d9b23a5','aux-canarias',37,'La combinación Tecla Windows + D:','["Abre el Explorador de archivos en la carpeta Escritorio del usuario", "Muestra el escritorio, y al pulsarla de nuevo restaura las ventanas", "Duplica la pantalla en un segundo monitor conectado", "Abre el dictado por voz en el campo de texto activo, si hay micrófono"]'::jsonb,1,'Windows 11 · Atajos','Minimiza todas las ventanas para ver el escritorio.',null),
('aux-canarias:37-bdc8e11c4e','aux-canarias',37,'¿Qué combinación crea un nuevo escritorio virtual en Windows 11?','["Tecla Windows + Tab + N", "Tecla Windows + D", "Tecla Windows + Ctrl + D", "Ctrl + Alt + D"]'::jsonb,2,'Windows 11 · Escritorios virtuales','Win+Tab abre la Vista de tareas con los escritorios.',null),
('aux-canarias:37-2758a7f135','aux-canarias',37,'En Windows 11, Alt + Tab sirve para:','["Crear un escritorio virtual", "Cerrar la ventana activa sin guardar", "Abrir el menú Inicio con las aplicaciones ancladas", "Cambiar entre las ventanas abiertas"]'::jsonb,3,'Windows 11 · Ventanas','Alt+F4 cierra la ventana activa.',null),
('aux-canarias:37-6b78ae478e','aux-canarias',37,'¿Qué hace la combinación Ctrl + Mayús + Esc en Windows 11?','["Abre el Explorador de archivos", "Bloquea el equipo", "Cierra la sesión", "Abre el Administrador de tareas"]'::jsonb,3,'Windows 11 · Atajos','Permite ver y finalizar procesos y aplicaciones.',null),
('aux-canarias:37-39e2f2263e','aux-canarias',37,'En Windows 11, ¿qué combinación de teclas muestra u oculta el escritorio?','["Windows + L", "Windows + D", "Windows + M + Mayús", "Windows + E"]'::jsonb,1,'Atajos de Windows','Windows + E abre el Explorador de archivos y Windows + L bloquea el equipo.',null),
('aux-canarias:37-96f2f3d519','aux-canarias',37,'En Windows 11, la combinación Windows + L sirve para:','["Abrir el Explorador de archivos", "Cerrar la sesión y apagar el equipo", "Bloquear el equipo", "Abrir la configuración de idioma"]'::jsonb,2,'Atajos de Windows','Para volver a entrar hay que identificarse (contraseña, PIN o Windows Hello).',null),
('aux-canarias:37-1d7279c315','aux-canarias',37,'¿Qué combinación de teclas abre el historial del portapapeles en Windows 11?','["Windows + V", "Ctrl + V", "Ctrl + Mayús + V", "Windows + C"]'::jsonb,0,'Atajos de Windows','Ctrl + V pega el último elemento copiado. El historial debe estar activado en Configuración.',null),
('aux-canarias:37-91dc6df800','aux-canarias',37,'En Windows 11, Windows + Mayús + S permite:','["Abrir el menú de apagado, reinicio y suspensión del sistema operativo", "Capturar una parte de la pantalla con la herramienta Recortes", "Cambiar entre los distintos escritorios virtuales creados por el usuario", "Guardar el documento que está abierto con otro nombre o en otra carpeta"]'::jsonb,1,'Atajos de Windows','La captura se copia en el portapapeles y puede editarse en Recortes.',null),
('aux-canarias:37-675a0aac77','aux-canarias',37,'¿Qué combinación abre directamente el Administrador de tareas?','["Windows + Ctrl + Esc", "Ctrl + Mayús + Esc", "Windows + Tab", "Alt + F4"]'::jsonb,1,'Atajos de Windows','Ctrl + Alt + Supr muestra una pantalla desde la que también puede abrirse.',null),
('aux-canarias:37-fc00c89604','aux-canarias',37,'En Windows 11, la combinación Windows + Tab abre:','["El menú Inicio con las aplicaciones ancladas y los archivos recomendados recientemente", "El centro de notificaciones", "El cuadro Ejecutar para escribir el nombre de un programa, carpeta o comando", "La vista de tareas, con las ventanas abiertas y los escritorios virtuales"]'::jsonb,3,'Atajos de Windows','Alt + Tab permite cambiar rápidamente entre ventanas abiertas.',null),
('aux-canarias:37-9839a1d93e','aux-canarias',37,'En Windows 11, la combinación Windows + I abre:','["Configuración", "El Explorador de archivos", "El Panel de control", "La búsqueda de Windows"]'::jsonb,0,'Atajos de Windows','La aplicación Configuración sustituye progresivamente al Panel de control.',null),
('aux-canarias:37-f91c2d1587','aux-canarias',37,'¿Qué combinación de teclas abre el cuadro de diálogo Ejecutar?','["Windows + E", "Ctrl + R", "Windows + R", "Alt + R"]'::jsonb,2,'Atajos de Windows','Permite abrir programas, carpetas o comandos escribiendo su nombre, por ejemplo «cmd».',null),
('aux-canarias:37-ecd0911510','aux-canarias',37,'¿Qué combinación abre el menú de vínculo rápido (clic derecho del botón Inicio) en Windows 11?','["Windows + X", "Windows + Q", "Alt + Inicio", "Ctrl + X"]'::jsonb,0,'Atajos de Windows','Da acceso a herramientas como el Administrador de dispositivos, la Administración de discos o Terminal.',null),
('aux-canarias:37-01aba4e1a6','aux-canarias',37,'¿Qué combinación abre el panel de emojis en Windows 11?','["Windows + punto (.)", "Windows + E", "Alt + punto (.)", "Ctrl + Mayús + E"]'::jsonb,0,'Atajos de Windows','También permite insertar símbolos y GIF.',null),
('aux-canarias:37-39e166720b','aux-canarias',37,'En Windows 11, Windows + A abre:','["Las aplicaciones ancladas en el menú Inicio del usuario", "El asistente de accesibilidad con la lupa y el narrador", "La Configuración rápida (wifi, volumen, brillo, etc.)", "El Administrador de tareas con los procesos en ejecución"]'::jsonb,2,'Atajos de Windows','Windows + N abre el centro de notificaciones y el calendario.',null),
('aux-canarias:37-dd89f34e50','aux-canarias',37,'En Windows 11, la combinación Windows + E abre:','["El Administrador de tareas", "El menú Inicio", "La Configuración", "El Explorador de archivos"]'::jsonb,3,'Atajos de Windows','Windows + E abre el Explorador de archivos.',null),
('aux-canarias:37-481947e295','aux-canarias',37,'En Windows, Alt + Tab sirve para:','["Minimizar todas las ventanas", "Cerrar la ventana activa", "Abrir la vista de tareas y los escritorios", "Cambiar entre las ventanas abiertas"]'::jsonb,3,'Atajos de Windows','Alt + Tab cambia entre ventanas; Alt + F4 cierra y Windows + Tab abre la vista de tareas.',null),
('aux-canarias:37-9805bd9f0b','aux-canarias',37,'En Windows, Alt + F4 sirve para:','["Bloquear el equipo", "Cerrar la ventana o aplicación activa", "Abrir el Explorador de archivos", "Cambiar entre las ventanas abiertas"]'::jsonb,1,'Atajos de Windows','Alt + F4 cierra el elemento activo; en el escritorio, abre el cuadro de apagado.',null),
('aux-canarias:37-20c44bd424','aux-canarias',37,'En Windows 11, Windows + M:','["Abre el Explorador de archivos", "Muestra el centro de notificaciones", "Minimiza todas las ventanas abiertas", "Abre el menú Inicio"]'::jsonb,2,'Atajos de Windows','Windows + M minimiza todas las ventanas.',null),
('aux-canarias:37-5e92cff221','aux-canarias',37,'En Windows 11, Windows + H abre:','["El historial del portapapeles", "La pantalla de inicio", "El dictado o escritura por voz", "La ayuda de Windows"]'::jsonb,2,'Atajos de Windows','Windows + H activa la escritura por voz.',null),
('aux-canarias:38-336cacca00','aux-canarias',38,'En Windows 11, ¿cómo se crea un archivo comprimido ZIP desde el Explorador?','["Arrastrándolos a la Papelera", "Clic derecho sobre los elementos > Comprimir en > Archivo ZIP", "Desde el Administrador de tareas > Archivo > Nueva tarea", "Con la tecla F12"]'::jsonb,1,'Explorador · Comprimir','Windows incluye la compresión ZIP sin programas adicionales.',null),
('aux-canarias:38-2a1e494cea','aux-canarias',38,'¿Qué vista del Explorador muestra en columnas el nombre, la fecha de modificación, el tipo y el tamaño de los archivos?','["Contenido", "Iconos grandes", "Detalles", "Mosaicos"]'::jsonb,2,'Explorador · Vistas','La vista Detalles permite además ordenar haciendo clic en el encabezado de cada columna.',null),
('aux-canarias:38-9152a39a8c','aux-canarias',38,'Si arrastras un archivo a una carpeta situada en otra unidad, por defecto el archivo:','["Se convierte en acceso directo", "Se mueve", "Se copia", "Se elimina del origen sin copiarse"]'::jsonb,2,'Explorador · Arrastrar y soltar','Para moverlo entre unidades se puede mantener pulsada la tecla Mayús al arrastrar.',null),
('aux-canarias:38-db5374c1b5','aux-canarias',38,'¿Qué combinación muestra u oculta el panel de vista previa en el Explorador de archivos?','["Alt + P", "F11", "Ctrl + P", "Alt + D"]'::jsonb,0,'Explorador · Paneles','Alt+Mayús+P muestra u oculta el panel de detalles.',null),
('aux-canarias:38-ed1cfe4072','aux-canarias',38,'En el Explorador de archivos, la tecla F2 sirve para:','["Abrir el cuadro de propiedades del elemento seleccionado", "Eliminar el archivo", "Actualizar la ventana", "Cambiar el nombre del elemento seleccionado"]'::jsonb,3,'Explorador · Atajos','F5 actualiza la ventana; Alt+Entrar abre las propiedades.',null),
('aux-canarias:38-512faa1689','aux-canarias',38,'En el Explorador de archivos, ¿qué combinación crea una carpeta nueva en la ubicación actual?','["Ctrl + N", "Ctrl + Mayús + N", "Alt + N", "Ctrl + Alt + N"]'::jsonb,1,'Explorador · Atajos','Ctrl+N abre una nueva ventana del Explorador.',null),
('aux-canarias:38-76d8cb842e','aux-canarias',38,'En el Explorador de archivos, Alt + Entrar sobre un elemento seleccionado:','["Lo renombra", "Abre sus propiedades", "Lo abre en una ventana nueva", "Lo envía a la Papelera"]'::jsonb,1,'Explorador · Atajos','Muestra el cuadro de diálogo Propiedades.',null),
('aux-canarias:38-d43a8f9b32','aux-canarias',38,'Si arrastras con el ratón un archivo a otra carpeta de la misma unidad, por defecto el archivo:','["Se mueve", "Se comprime", "Se copia", "Se elimina"]'::jsonb,0,'Explorador · Arrastrar y soltar','Si la carpeta de destino está en otra unidad, por defecto se copia.',null),
('aux-canarias:38-05c2db16cd','aux-canarias',38,'Desde la versión 22H2, el Explorador de archivos de Windows 11 permite abrir varias carpetas en la misma ventana mediante:','["Escritorios virtuales", "Accesos directos", "Bibliotecas", "Pestañas"]'::jsonb,3,'Explorador · Pestañas','Se puede abrir una pestaña nueva con Ctrl+T.',null),
('aux-canarias:38-2c2e326f5f','aux-canarias',38,'¿Qué ocurre al pulsar Mayús + Supr sobre un archivo de una unidad local?','["Se copia al portapapeles", "Se crea un acceso directo", "Se elimina definitivamente sin pasar por la Papelera de reciclaje", "Se envía a la Papelera de reciclaje y se vacía la Papelera al cerrar la sesión"]'::jsonb,2,'Explorador · Eliminar','Con Supr solo, el archivo va a la Papelera y puede restaurarse.',null),
('aux-canarias:38-d48d4c2e25','aux-canarias',38,'¿Qué es OneDrive dentro del Explorador de archivos de Windows 11?','["Una unidad física interna", "Una ubicación que sincroniza archivos con el almacenamiento en la nube de Microsoft", "Un antivirus en la nube que analiza los archivos antes de abrirlos y los pone en cuarentena", "Una carpeta temporal que se borra al apagar el equipo y que no se sincroniza con ningún servicio en la nube"]'::jsonb,1,'Explorador · OneDrive','Con Archivos a petición, los archivos pueden estar solo en la nube hasta que se abren.',null),
('aux-canarias:38-312d202568','aux-canarias',38,'Por defecto, en Windows 11 el Explorador de archivos muestra las extensiones de los tipos de archivo conocidos:','["Sí, siempre y no se pueden ocultar", "Solo las de los archivos de Office, mientras que las del resto de tipos de archivo están ocultas y no pueden mostrarse", "Solo en la vista Detalles", "No, están ocultas, pero puede activarse su visualización desde el menú Ver > Mostrar"]'::jsonb,3,'Explorador · Opciones','Se activan con Ver > Mostrar > Extensiones de nombre de archivo.',null),
('aux-canarias:38-e2f2bfb700','aux-canarias',38,'En OneDrive, un archivo marcado como «Mantener siempre en este dispositivo»:','["Se elimina del ordenador y solo se conserva en la nube", "Se comparte públicamente", "Solo existe en la nube y se descarga cuando se abre", "Se descarga y queda disponible sin conexión"]'::jsonb,3,'Explorador · OneDrive','«Liberar espacio» deja el archivo solo en la nube.',null),
('aux-canarias:38-82108b9b1f','aux-canarias',38,'Un acceso directo en Windows es:','["Una copia completa del archivo original, que se actualiza al modificarlo", "Un archivo comprimido", "Un archivo que apunta a otro elemento; si se borra el acceso directo, el original se conserva", "Un archivo que apunta a otro elemento; si se elimina el acceso directo, también se borra el archivo original al que apunta"]'::jsonb,2,'Explorador · Accesos directos','Se crea, por ejemplo, arrastrando con Alt pulsada.',null),
('aux-canarias:38-537dff317b','aux-canarias',38,'En el Explorador de archivos, Alt + flecha arriba:','["Sube a la carpeta que contiene la carpeta actual", "Abre el menú Inicio con la lista de carpetas ancladas", "Vuelve a la última carpeta visitada en el historial de navegación", "Maximiza la ventana"]'::jsonb,0,'Explorador · Navegación','Alt+flecha izquierda vuelve a la ubicación anterior.',null),
('aux-canarias:38-e569d26168','aux-canarias',38,'Para seleccionar varios archivos no contiguos en el Explorador, se hace clic en cada uno manteniendo pulsada la tecla:','["Ctrl", "Alt", "Mayús", "Tab"]'::jsonb,0,'Explorador · Selección','Con Mayús se selecciona un rango continuo entre dos archivos.',null),
('aux-canarias:38-8481f4a419','aux-canarias',38,'¿Qué tecla se mantiene pulsada al arrastrar un archivo para copiarlo, aunque el destino esté en la misma unidad?','["Tecla Windows", "Alt", "Mayús", "Ctrl"]'::jsonb,3,'Explorador · Arrastrar y soltar','Ctrl fuerza la copia; Mayús fuerza el movimiento; Alt crea un acceso directo.',null),
('aux-canarias:38-05e97feb55','aux-canarias',38,'Marcar un archivo con el atributo «Solo lectura» en sus propiedades:','["Impide modificarlo, sobrescribirlo y eliminarlo, incluso para el administrador", "Lo oculta en el Explorador de archivos y en los resultados de búsqueda", "Evita que se modifique por accidente, pero no impide eliminarlo", "Impide compartirlo en red"]'::jsonb,2,'Explorador · Propiedades','Para impedir el borrado hacen falta permisos.',null),
('aux-canarias:38-78ae6781db','aux-canarias',38,'El panel de vista previa del Explorador permite:','["Ver solo imágenes JPG y PNG", "Ver las propiedades de seguridad", "Editar los archivos directamente en el panel sin abrir la aplicación asociada", "Ver el contenido de muchos tipos de archivo sin abrirlos"]'::jsonb,3,'Explorador · Paneles','Funciona con documentos, imágenes, PDF y otros tipos compatibles.',null),
('aux-canarias:38-8ad3535d34','aux-canarias',38,'En el Explorador, una carpeta anclada en el acceso rápido se diferencia de una carpeta frecuente en que:','["La frecuente solo la ve el administrador", "No se pueden anclar carpetas en el acceso rápido, solo archivos, mientras que las frecuentes aparecen según el uso", "La anclada se sincroniza siempre con OneDrive y está disponible sin conexión, mientras que la frecuente solo existe en el equipo local", "La anclada permanece hasta que la desancles, mientras que las frecuentes cambian según el uso reciente"]'::jsonb,3,'Explorador · Acceso rápido','En Windows 11 el acceso rápido aparece en la sección Inicio del Explorador.',null),
('aux-canarias:38-1bcc17f84d','aux-canarias',38,'Si en el cuadro de búsqueda del Explorador escribes un texto entre comillas, por ejemplo "informe anual", Windows busca:','["Esa frase exacta, con las palabras en ese orden", "Cualquiera de las dos palabras", "Solo archivos cuyo nombre empiece por la primera palabra", "Las dos palabras en cualquier orden"]'::jsonb,0,'Explorador · Búsqueda','Las comillas indican frase exacta.',null),
('aux-canarias:38-bea4857564','aux-canarias',38,'Para ver el espacio libre de una unidad de disco, lo más directo es:','["Abrir las propiedades de la unidad desde «Este equipo»", "No es posible ver el espacio por unidad", "Abrir las propiedades de un archivo de la unidad", "Mirar el panel de vista previa"]'::jsonb,0,'Explorador · Unidades','También se ve con la barra de capacidad en «Este equipo».',null),
('aux-canarias:38-60db95fc9d','aux-canarias',38,'Al agrupar archivos por tipo en el Explorador, el número que aparece entre paréntesis junto a cada grupo indica:','["Cuántos archivos hay en ese grupo", "Cuántas aplicaciones pueden abrirlos", "El orden del grupo", "Cuántos archivos están duplicados"]'::jsonb,0,'Explorador · Vistas','Por ejemplo, «Documento de Microsoft Word (12)».',null),
('aux-canarias:38-e8e44bcc03','aux-canarias',38,'En el Explorador de archivos, la ruta completa de la carpeta en la que estás se ve en:','["El panel de vista previa", "La barra de estado", "La barra de direcciones", "La cinta de opciones"]'::jsonb,2,'Explorador · Navegación','Al hacer clic en ella se muestra la ruta como texto.',null);
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-canarias:38-c44d68dcfb','aux-canarias',38,'En el Explorador de archivos de Windows 11, Ctrl + Mayús + N:','["Crea una carpeta nueva", "Cambia el nombre de la carpeta", "Crea un acceso directo", "Abre una nueva ventana del Explorador"]'::jsonb,0,'Explorador de archivos','Ctrl + Mayús + N crea una carpeta nueva; Ctrl + N abre una nueva ventana.',null),
('aux-canarias:39-7e53e43713','aux-canarias',39,'¿En qué plazo debe cursarse la notificación de un acto administrativo?','["5 días desde que el acto se dictó", "15 días hábiles desde que el acto se dictó o se firmó", "1 mes desde que el acto se dictó", "10 días desde que el acto se dictó"]'::jsonb,3,'Art. 40.2 Ley 39/2015','La notificación debe cursarse dentro de los diez días siguientes a la fecha en que el acto se dictó.',null),
('aux-canarias:39-d7517910ca','aux-canarias',39,'Una notificación que contenga el texto íntegro del acto pero omita otro requisito surte efecto:','["A los seis meses de su práctica, si el interesado no ha reclamado", "Desde que el interesado realice actuaciones que supongan el conocimiento del contenido o interponga el recurso procedente", "Inmediatamente desde su envío, aunque el interesado no haya realizado ninguna actuación ni interpuesto recurso", "Nunca"]'::jsonb,1,'Art. 40.3 Ley 39/2015','Surte efecto desde que el interesado realiza actuaciones que suponen conocer su contenido e alcance o interpone recurso.',null),
('aux-canarias:39-a5976805dc','aux-canarias',39,'A efectos de entender cumplida la obligación de notificar dentro del plazo máximo, basta:','["Con firmar la resolución dentro del plazo máximo, aunque su notificación se intente después de vencido ese plazo legal", "Con remitir un aviso por SMS o correo electrónico", "La notificación que contenga el texto íntegro de la resolución y el intento de notificación debidamente acreditado", "Con publicar un anuncio en el tablón de edictos de la sede electrónica, aunque no se haya intentado la notificación personal"]'::jsonb,2,'Art. 40.4 Ley 39/2015','Es suficiente la notificación con el texto íntegro y el intento de notificación debidamente acreditado.',null),
('aux-canarias:39-8ceb4660cf','aux-canarias',39,'¿A quién debe notificar el órgano que dicte una resolución?','["A los interesados cuyos derechos e intereses sean afectados por ella", "A todos los vecinos del municipio afectado", "Solo al solicitante, aunque haya otros interesados afectados", "Al superior jerárquico, que da traslado a los interesados"]'::jsonb,0,'Art. 40.1 Ley 39/2015','Se notifica a los interesados cuyos derechos e intereses sean afectados por las resoluciones y actos.',null),
('aux-canarias:39-e8294cfaee','aux-canarias',39,'Según la Ley 39/2015, toda notificación debe cursarse dentro del plazo de:','["Tres días a partir de la fecha en que el acto haya adquirido firmeza", "Un mes a partir de la fecha en que el acto haya sido dictado y firmado", "Diez días a partir de la fecha en que el acto haya sido dictado", "Quince días a partir de la fecha en que el acto haya sido publicado"]'::jsonb,2,'Art. 40.2 Ley 39/2015','Debe contener el texto íntegro de la resolución, si pone fin o no a la vía administrativa y los recursos que procedan.',null),
('aux-canarias:40-a4ec8f64f5','aux-canarias',40,'¿Qué norma aprueba el Reglamento del Sistema de gestión documental y organización de los archivos dependientes de la Administración de la Comunidad Autónoma de Canarias?','["El Decreto 76/2003, de 12 de mayo", "El Decreto 160/2006, de 8 de noviembre", "El Decreto 212/1991, de 11 de septiembre", "La Ley 3/1990, de 22 de febrero"]'::jsonb,1,'Decreto 160/2006','El Decreto 160/2006 aprueba el Reglamento y deroga expresamente el Decreto 76/2003; la Ley 3/1990 es la de Patrimonio Documental y Archivos de Canarias.',null),
('aux-canarias:40-6bedfd83ab','aux-canarias',40,'Según el Decreto 160/2006, ¿a quién se aplica el Reglamento del sistema de archivos?','["A la Administración autonómica y a los ayuntamientos de más de 20.000 habitantes", "Solo a las consejerías del Gobierno de Canarias y a la Presidencia, con exclusión de los organismos autónomos y de las empresas públicas", "A la Administración autonómica, sus organismos autónomos, entes públicos y empresas públicas con capital mayoritario autonómico", "A todas las Administraciones públicas radicadas en Canarias, incluidos los cabildos insulares y los ayuntamientos de la comunidad"]'::jsonb,2,'Art. 2 Decreto 160/2006','El art. 2 incluye la Administración autonómica, sus organismos autónomos, entes públicos y empresas públicas con participación de capital mayoritario autonómico.',null),
('aux-canarias:40-a50bae85f0','aux-canarias',40,'¿Por qué normativa se rigen los documentos de la historia clínica de los centros hospitalarios según el Decreto 160/2006?','["Por el Reglamento del sistema de archivos sin excepción", "Por las tablas de valoración de la Comisión General", "Por la Ley 3/1990 exclusivamente", "Por su normativa específica"]'::jsonb,3,'Art. 2 Decreto 160/2006','El art. 2 dispone que los documentos que conforman la historia clínica se regirán por su normativa específica.',null),
('aux-canarias:40-8db3d37e98','aux-canarias',40,'Según el Decreto 160/2006, ¿cuál es la unidad archivística más utilizada?','["El expediente administrativo", "El acta de órgano colegiado", "La correspondencia", "El libro de registro"]'::jsonb,0,'Art. 4 Decreto 160/2006','La unidad archivística más utilizada es el expediente administrativo; también lo son el libro de registro, el acta, el informe y la correspondencia.',null),
('aux-canarias:40-07198f00d7','aux-canarias',40,'Según el Decreto 160/2006, ¿cómo se define la serie documental?','["Agrupación orgánica de documentos generados por una institución o persona física o jurídica en el ejercicio de sus funciones", "Conjunto de unidades archivísticas producidas en una función o actividad regulada por una misma norma de procedimiento", "Reunión de documentos sin carácter orgánico que responde a criterios subjetivos", "Conjunto de ejemplares múltiples que ayudan a la gestión"]'::jsonb,1,'Art. 4 Decreto 160/2006','Así la define el art. 4 e); la agrupación orgánica de una institución es el fondo documental y la reunión sin carácter orgánico, la colección.',null),
('aux-canarias:40-3ad069e630','aux-canarias',40,'¿Qué son las series documentales comunes según el Decreto 160/2006?','["Las que ya tienen carácter histórico", "Las propias de cada departamento, reguladas por una norma de procedimiento específica de esa consejería", "Las producidas en una función regulada por una misma norma y común a todos los departamentos", "Las que se conservan solo en los archivos de oficina hasta que finaliza su tramitación administrativa"]'::jsonb,2,'Art. 4 Decreto 160/2006','Las comunes son comunes a todos los departamentos; las específicas, propias de cada departamento.',null),
('aux-canarias:40-ef4e8a876f','aux-canarias',40,'Según el Decreto 160/2006, ¿qué es el fondo documental?','["La reunión de documentos que, sin poseer carácter orgánico, responde a criterios subjetivos o de conservación", "El lugar donde se custodian, organizan y sirven los documentos", "El conjunto de copias y fotocopias que apoyan la gestión", "La agrupación orgánica de documentos generados por una institución o persona en el ejercicio de sus funciones"]'::jsonb,3,'Art. 4 Decreto 160/2006','El art. 4 f) define el fondo documental como la agrupación orgánica de documentos generados por una institución o persona física o jurídica en el ejercicio de sus funciones.',null),
('aux-canarias:40-5c433c6f81','aux-canarias',40,'Según el Decreto 160/2006, ¿qué valores establece la valoración documental?','["Primarios, por necesidades administrativas, fiscales o legales, y secundarios, por su importancia para la investigación", "Primarios, por su importancia para la investigación histórica, y secundarios, por su uso administrativo, fiscal o legal", "Económicos y patrimoniales", "Jurídicos y estadísticos, únicamente"]'::jsonb,0,'Art. 4 Decreto 160/2006','La valoración analiza los valores primarios (administrativos, fiscales o legales) y secundarios (investigación).',null),
('aux-canarias:40-7f59374352','aux-canarias',40,'Según el Decreto 160/2006, ¿qué determinan las tablas de valoración documental?','["La ubicación física de cada caja en el depósito", "El código, la denominación, el órgano productor, la función y los plazos de transferencia, conservación y eliminación de cada serie", "Las personas autorizadas a consultar cada expediente y los motivos concretos de restricción del acceso a cada uno de ellos", "El presupuesto anual de cada archivo central"]'::jsonb,1,'Art. 4 Decreto 160/2006','Así lo establece el art. 4 k).',null),
('aux-canarias:40-de4d2abf7c','aux-canarias',40,'¿Cómo distingue el Decreto 160/2006 el expurgo de la eliminación?','["El expurgo es la destrucción física y la eliminación, la baja en el inventario", "El expurgo afecta solo a las copias de apoyo informativo y la eliminación, a los originales de cualquier serie documental", "El expurgo es la selección de los documentos que se van a destruir y la eliminación es su destrucción física", "Son sinónimos en el Reglamento"]'::jsonb,2,'Art. 4 Decreto 160/2006','El expurgo es la selección de documentos que van a destruirse según la tabla de valoración; la eliminación, el acto físico de destrucción.',null),
('aux-canarias:40-6c223d2e38','aux-canarias',40,'¿Qué carácter tiene la Comisión General de Valoración Documental según el Decreto 160/2006?','["Órgano colegiado de carácter técnico", "Unidad administrativa de la secretaría general técnica", "Órgano consultivo del Parlamento de Canarias", "Órgano directivo del sistema"]'::jsonb,0,'Art. 6 Decreto 160/2006','Es un órgano colegiado de carácter técnico para establecer los valores primarios y secundarios de los documentos y valorar las series.',null),
('aux-canarias:40-452e75e9b2','aux-canarias',40,'¿Cuáles son los centros de archivo del sistema según el Decreto 160/2006?','["El Archivo General y los archivos de los cabildos insulares, coordinados por la Comisión General de Valoración", "Los archivos de oficina, los archivos insulares de cada cabildo y el Archivo Histórico Provincial", "Los archivos centrales, los intermedios y los históricos de cada isla", "Los archivos de oficina, los archivos centrales de las consejerías y el Archivo General"]'::jsonb,3,'Art. 7 Decreto 160/2006','El art. 7.1 enumera los archivos de oficina, los archivos centrales de las consejerías y el Archivo General.',null),
('aux-canarias:40-0faeb0e38e','aux-canarias',40,'Según el Decreto 160/2006, ¿dónde se integran, como regla general, los archivos de los organismos autónomos?','["En el archivo central de la consejería de la que dependan", "En el archivo de oficina de su gerencia", "En un archivo propio, obligatorio para todos ellos con independencia de su tamaño", "En el Archivo General directamente, sin pasar por el archivo central de ninguna consejería"]'::jsonb,0,'Art. 7 Decreto 160/2006','Quedan integrados en el archivo central de la consejería de la que dependan, aunque por orden departamental pueden crearse archivos centrales propios.',null),
('aux-canarias:40-73b1341ee8','aux-canarias',40,'¿Con qué criterio se organizan los centros de archivo según el Decreto 160/2006?','["Según la isla en que se producen", "Según el soporte de los documentos", "Según la materia de los documentos", "Según la antigüedad de los fondos que conservan"]'::jsonb,3,'Art. 8 Decreto 160/2006','El art. 8 dispone que se organizan según la antigüedad de los fondos de archivo que conservan y gestionan.',null),
('aux-canarias:40-1f2afd2aa4','aux-canarias',40,'¿Qué documentos se custodian en los archivos de oficina según el Decreto 160/2006?','["Los que tienen valor histórico", "Los que tienen más de cinco años", "Los que están en trámite o son de uso muy frecuente", "Solo los que contienen datos personales"]'::jsonb,2,'Art. 9 Decreto 160/2006','Se custodian los documentos en tanto se encuentren en trámite o su uso sea muy frecuente; el plazo de transferencia lo fija la tabla de valoración.',null),
('aux-canarias:40-dd66fd8075','aux-canarias',40,'Según el Decreto 160/2006, ¿qué expedientes deben transferir las oficinas al archivo central?','["Todos los expedientes al año de su apertura", "Los resueltos con actos firmes cuya ejecución se ha completado", "Los expedientes en trámite cuyos plazos estén suspendidos o pendientes de informe", "Solo los que tengan valor histórico"]'::jsonb,1,'Art. 10 Decreto 160/2006','Se transfieren los expedientes con actos de resolución firmes y totalmente ejecutados, y los estudios e informes que hayan producido todos sus efectos.',null),
('aux-canarias:40-1d79fdd344','aux-canarias',40,'Según el Decreto 160/2006, ¿qué documentos permanecen en el Archivo General como parte del patrimonio histórico?','["Los que tengan veinticinco años desde su producción, sea cual sea su valor", "Los que tengan cincuenta años desde su producción", "Los que tengan treinta años desde su producción y valor informativo, histórico y cultural", "Todos los transferidos por los archivos centrales"]'::jsonb,2,'Art. 12 Decreto 160/2006','Tras el periodo de archivo intermedio, permanecen los documentos con treinta años desde su producción y valor informativo, histórico y cultural.',null),
('aux-canarias:40-80b9dceaf4','aux-canarias',40,'Según el Decreto 160/2006, ¿a qué órgano está adscrito el archivo central de cada departamento?','["A la viceconsejería del departamento", "A la secretaría general técnica o al órgano horizontal de coordinación que fije el reglamento orgánico", "Al Archivo General, como sección territorial dependiente de la consejería competente en materia de archivos", "A la dirección general competente en materia de patrimonio de la comunidad autónoma, en todo caso y sin excepción"]'::jsonb,1,'Art. 13 Decreto 160/2006','El art. 13.2 lo adscribe a la secretaría general técnica o, en su caso, al órgano horizontal de coordinación administrativa que determine el reglamento orgánico.',null),
('aux-canarias:40-120a56294c','aux-canarias',40,'¿Quién identifica y valora las series documentales específicas de cada departamento según el Decreto 160/2006?','["El Archivo General", "El archivo de oficina que las produce", "La Comisión General de Valoración Documental", "El archivo central del departamento"]'::jsonb,3,'Art. 14 Decreto 160/2006','El archivo central identifica y valora las series específicas (anexo II); el Archivo General, las comunes (anexo I).',null),
('aux-canarias:40-07193a58b3','aux-canarias',40,'¿Cómo se configura el Archivo General de la Administración de la Comunidad Autónoma de Canarias según el Decreto 160/2006?','["Como unidad administrativa integrada en la consejería competente en materia de archivos", "Como órgano colegiado de carácter técnico, presidido por el titular de la consejería competente en archivos", "Como centro directivo con rango de dirección general", "Como organismo autónomo con personalidad jurídica propia adscrito a la Presidencia del Gobierno"]'::jsonb,0,'Art. 15 Decreto 160/2006','El art. 15 lo configura como unidad administrativa; el decreto derogado lo configuraba como centro directivo.',null),
('aux-canarias:40-ef3665a91c','aux-canarias',40,'Según el Decreto 160/2006, ¿qué doble función realiza el Archivo General?','["Archivo central e intermedio", "Archivo de oficina y central", "Archivo de gestión y de seguridad", "Archivo intermedio e histórico"]'::jsonb,3,'Art. 16 Decreto 160/2006','El Archivo General realiza la doble función de archivo intermedio e histórico de la Administración autonómica.',null),
('aux-canarias:40-7243f53701','aux-canarias',40,'Según el Decreto 160/2006, ¿cómo se formaliza el ingreso extraordinario de documentos en el Archivo General?','["Mediante una hoja de remisión de fondos", "Mediante resolución de la secretaría general técnica", "Mediante un acta de recepción", "Mediante una relación de entrega"]'::jsonb,2,'Art. 18 Decreto 160/2006','El ingreso ordinario se formaliza con relación de entrega; el extraordinario (compra, donación, depósito…), con acta de recepción.',null),
('aux-canarias:40-74ab79abe7','aux-canarias',40,'Según el Decreto 160/2006, ¿qué criterios sigue la clasificación de los documentos?','["De procedencia, funcional y orgánico", "Alfabético, cronológico y geográfico", "Por valor económico y por antigüedad", "Por materias y por soportes"]'::jsonb,0,'Art. 19 Decreto 160/2006','La clasificación obedece a los criterios de procedencia, funcional y orgánico y se refleja en el cuadro de clasificación.',null),
('aux-canarias:40-3a90a9c35c','aux-canarias',40,'¿Dónde se publican las tablas de valoración documental una vez aprobadas según el Decreto 160/2006?','["Solo en la intranet del Gobierno de Canarias", "En el Boletín Oficial de Canarias", "En el tablón del Archivo General", "En el Boletín Oficial del Estado"]'::jsonb,1,'Art. 20 Decreto 160/2006','Las tablas de valoración documental, tras ser aprobadas, se publican en el Boletín Oficial de Canarias.',null),
('aux-canarias:40-7e3b3c25d9','aux-canarias',40,'¿Qué constancia queda de los documentos eliminados según el Decreto 160/2006?','["Un informe anual al Parlamento de Canarias y a la Audiencia de Cuentas sobre los documentos destruidos", "Una diligencia en el expediente, sin más trámite", "Un acta de eliminación, de la que se da cuenta a la Comisión General de Valoración Documental", "Una anotación en el registro general de salida"]'::jsonb,2,'Art. 20 Decreto 160/2006','Todos los documentos eliminados quedan reflejados en el acta de eliminación, de la que se da cuenta a la Comisión.',null),
('aux-canarias:40-fcebe5c005','aux-canarias',40,'Según el Decreto 160/2006, ¿cómo es el acceso de los ciudadanos a los centros de archivo?','["Libre y gratuito, sin perjuicio de las restricciones legales o de conservación", "Sujeto a tasa en todos los casos", "Gratuito solo para investigadores acreditados", "Libre solo para documentos con más de treinta años"]'::jsonb,0,'Art. 23 Decreto 160/2006','La Administración garantiza el acceso libre y gratuito a los centros de archivo, con las restricciones legales o por la conservación de los documentos.',null),
('aux-canarias:40-7a99dbc078','aux-canarias',40,'Según el Decreto 160/2006, ¿quién organiza los archivos de oficina?','["Una empresa externa de gestión documental", "El Archivo General directamente, con su propio personal técnico especializado en gestión documental", "Personal de la escala de archiveros del Cuerpo Superior Facultativo destinado en cada unidad administrativa", "El personal administrativo y auxiliar de la unidad, siguiendo las directrices del archivo central"]'::jsonb,3,'Art. 24 Decreto 160/2006','Los archivos de oficina los organiza el personal administrativo y auxiliar de la unidad, siguiendo las directrices técnicas del archivo central.',null),
('aux-canarias:40-71f1de986b','aux-canarias',40,'Según el Decreto 160/2006, ¿qué obligación tiene el personal que entra en contacto con los documentos de un archivo?','["Pedir autorización del consejero para cada acceso", "Guardar secreto profesional sobre su contenido", "Ser funcionario del cuerpo de archiveros", "Firmar cada consulta en el libro de registro"]'::jsonb,1,'Art. 24 Decreto 160/2006','El art. 24.4 obliga a guardar secreto profesional del contenido de los documentos.',null),
('aux-canarias:40-7560194ee6','aux-canarias',40,'¿Cuál de estos documentos NO puede eliminarse según el art. 28 del Decreto 160/2006?','["Los borradores sin valor administrativo", "Los que permitan conocer los procesos de elaboración de leyes y reglamentos", "Las fotocopias de apoyo informativo", "Los duplicados de expedientes ya transferidos"]'::jsonb,1,'Art. 28 Decreto 160/2006','No pueden eliminarse, entre otros, los que expliquen el origen de un organismo, los procesos de elaboración de normas o los que tengan carácter histórico.',null);
